(window.QUIZ_DIFF_PACKS = window.QUIZ_DIFF_PACKS || []).push({"chapters":[{"id":1,"name":"驾驶证和机动车管理规定","exam":1,"count":15},{"id":2,"name":"道路交通标志及信号","exam":1,"count":11},{"id":3,"name":"道路通行条件及通行规定","exam":1,"count":110},{"id":4,"name":"道路交通安全违法行为及处罚","exam":1,"count":10},{"id":5,"name":"道路交通事故处理相关规定","exam":1,"count":3},{"id":6,"name":"机动车基础知识","exam":1,"count":2},{"id":7,"name":"货车制动系统与安全装置知识","exam":1,"count":14},{"id":8,"name":"客车制动系统与安全装置知识地","exam":1,"count":18},{"id":9,"name":"科目一摩托车相关试题","exam":1,"count":14},{"id":10,"name":"方性题库","exam":1,"count":423},{"id":17,"name":"满分题库","exam":1,"count":6},{"id":301,"name":"安全行车常识","exam":4,"count":40},{"id":302,"name":"文明行车常识","exam":4,"count":3},{"id":303,"name":"道路交通信号在交通场景中的综合应用","exam":4,"count":14},{"id":304,"name":"恶劣气象和复杂道路条件下安全驾驶知识","exam":4,"count":83},{"id":305,"name":"紧急情况下避险常识","exam":4,"count":26},{"id":307,"name":"交通事故救护及常见危险化学品处置常识","exam":4,"count":6},{"id":308,"name":"科目四摩托车相关试题","exam":4,"count":52},{"id":309,"name":"地方性题库","exam":4,"count":81},{"id":310,"name":"货车从业资格题库","exam":4,"count":1}],"questions":[{"i":9010016,"c":1,"x":1,"y":1,"q":"长期服用依赖性精神药品成瘾尚未戒除的，不得申请机动车驾驶证。","o":["正确","错误"],"a":"A","e":"《机动车驾驶证申领和使用规定》第十五条，有下列情形之一的，不得申领机动车驾驶证：（二）三年内有吸食、注射毒品行为或者解除强制戒毒隔离措施未满三年，以及长期服用依赖性精神药品成瘾尚未戒除的。","k":"题目看到“不得申请”，直接答正确。","p":"","j":""},{"i":9010017,"c":1,"x":1,"y":1,"q":"年龄在70周岁以上的驾驶人，可以驾驶小型汽车。","o":["正确","错误"],"a":"A","e":"年龄在70周岁以上的驾驶人，在满足每年提交身体条件证明并通过“三力测试”（记忆力、判断力、反应力）的前提下，可以合法驾驶小型汽车‌或小型自动挡汽车。","k":"关于年龄的判断题中只有“70周岁以上”、“18周岁”答对。其它的答错。","p":"","j":""},{"i":9010019,"c":1,"x":1,"y":1,"q":"驾车追逐竞驶，构成犯罪依法被吊销机动车驾驶证未满5年的，不得申请机动车驾驶证。","o":["正确","错误"],"a":"A","e":"《机动车驾驶证申领和使用规定》第十五条，有下列情形之一的，不得申请机动车驾驶证:（七）驾驶机动车追逐竞驶、超员、超速、违反危险化学品安全管理规定运输危险化学品构成犯罪依法被吊销机动车驾驶证未满五年的；","k":"题目看到“不得申请”，直接答正确。","p":"","j":""},{"i":9010020,"c":1,"x":1,"y":1,"q":"在学习驾驶证明有效期内，可以预约5次科目二考试。","o":["正确","错误"],"a":"A","e":"科目二、科目三道路驾驶技能考试各有5次预约机会，只要有一个科目预约超过5次都不合格，以前通过的考试科目也会作废。","k":"判断题中看到，“预约5次”答对，“预约6次”答错。","p":"","j":""},{"i":9010021,"c":1,"x":1,"y":1,"q":"在学习驾驶证明有效期内，第5次科目二考试仍不合格的，已考试合格的其他科目成绩作废。","o":["正确","错误"],"a":"A","e":"科目二、科目三道路驾驶技能考试各有5次预约机会，只要有一个科目预约超过5次都不合格，以前通过的考试科目也会作废。","k":"判断题出现“作废”都是对的。","p":"","j":""},{"i":9010022,"c":1,"x":1,"y":1,"q":"持有C1驾驶证可以驾驶小型汽车。","o":["正确","错误"],"a":"A","e":"C1驾驶证的准驾车型包括小型、微型载客汽车和轻型及小型的载货汽车。轻型载货汽车的身长度小于6米，总质量小于等于4.5吨。另外C1驾照还可以驾驶C2、C3及C4的准驾车型。","k":"常识：小型汽车简称C1。","p":"","j":""},{"i":9010023,"c":1,"x":1,"y":1,"q":"在学习驾驶证明有效期内，可以预约6次科目三道路驾驶技能考试。","o":["正确","错误"],"a":"B","e":"科目二、科目三道路驾驶技能考试各有5次预约机会，只要有一个科目预约超过5次都不合格，以前通过的考试科目也会作废。","k":"判断题中看到，“预约5次”答对，“预约6次”答错。","p":"","j":""},{"i":9010024,"c":1,"x":1,"y":2,"q":"驾驶人第一次取得汽车类准驾车型后的实习期是（ ）个月。","o":["6","12","16","18"],"a":"B","e":"实习期是一年，也就是12个月。","k":"答案有‘12个月’直接选。","p":"","j":""},{"i":9010025,"c":1,"x":1,"y":1,"q":"持有C2驾驶证可以驾驶三轮汽车。","o":["正确","错误"],"a":"B","e":"C2的准驾车型是：小型、微型自动挡载客汽车以及轻型、微型自动挡载货汽车","k":"常识：小型自动挡汽车简称C2，不可以驾驶三轮汽车。","p":"","j":""},{"i":9010026,"c":1,"x":1,"y":1,"q":"年龄在70周岁以上的驾驶人，可以驾驶小型自动挡汽车。","o":["正确","错误"],"a":"A","e":"年龄在70周岁以上的驾驶人，在满足每年提交身体条件证明并通过“三力测试”（记忆力、判断力、反应力）的前提下，可以合法驾驶小型汽车‌或小型自动挡汽车。","k":"关于年龄的判断题中只有“70周岁以上”、“18周岁”答对。其它的答错。","p":"","j":""},{"i":9010027,"c":1,"x":1,"y":1,"q":"在考试过程中有贿赂、舞弊行为的，已经通过考试的其他科目成绩无效，且申请人在1年内不得再次申领驾驶证。","o":["正确","错误"],"a":"A","e":"1、隐瞒有关情况或者提供虚假材料申领机动车驾驶证的——罚500元以下，一年内不能申请驾驶证。2、考试过程中贿赂、舞弊行为的，取消考试资格，已通过的科目作废——罚2000元以下，一年内不能申请驾驶证。3、以欺骗、贿赂等不正当手段取得驾驶证的，收缴驾驶证——罚2000元以下，三年内不能申请驾驶证。","k":"“舞弊”找“1年”。简单记作：五（舞）一劳动节。","p":"","j":""},{"i":9010028,"c":1,"x":1,"y":1,"q":"小型汽车驾驶人发生交通事故造成人员死亡，承担同等以上责任未被吊销驾驶证的，不需要接受审验。","o":["正确","错误"],"a":"B","e":"《机动车驾驶证申领和使用规定》第七十二条，持有小型汽车准驾车型驾驶证的驾驶人，发生交通事故造成人员死亡承担同等以上责任未被吊销机动车驾驶证的，应当在本记分周期结束后三十日内到公安机关交通管理部门接受审验。","k":"判断题出现“不需”、“无需” 都是错的。","p":"","j":""},{"i":9010029,"c":1,"x":1,"y":1,"q":"申请人在考试过程中有舞弊行为的，取消考试资格，在一年内不得再次申领驾驶证。","o":["正确","错误"],"a":"A","e":"1、隐瞒有关情况或者提供虚假材料申领机动车驾驶证的——罚500元以下，一年内不能申请驾驶证。2、考试过程中贿赂、舞弊行为的，取消考试资格，已通过的科目作废——罚2000元以下，一年内不能申请驾驶证。3、以欺骗、贿赂等不正当手段取得驾驶证的，收缴驾驶证——罚2000元以下，三年内不能申请驾驶证。","k":"“舞弊”找“1年”。简单记作：五（舞）一劳动节。","p":"","j":""},{"i":9010030,"c":1,"x":1,"y":1,"q":"组织他人参加审验教育时，在签注学习记录、学习过程中弄虚作假的，有违法所得的，处违法所得3倍以下罚款，但最高不超过2万元。","o":["正确","错误"],"a":"A","e":"1、驾驶人参加审验教育时弄虚作假，罚一千元以下；2、代替他人参加审验教育，罚二千元以下；3、组织他人弄虚作假或组织其他人代替他人参加的“有违法所得”的，处违法所得三倍罚款但不得超过二万；“没有违法所得”的，处二万以下。","k":"判断题里看到“万”字，直接答正确。","p":"","j":""},{"i":9010031,"c":1,"x":1,"y":1,"q":"驾驶证有效期满需换领驾驶证时，应到医疗机构进行体检。","o":["正确","错误"],"a":"A","e":"办理机动车驾驶证业务时，提交的身体条件证明应当由县级、部队团级以上医疗机构，或者经地市级以上卫生健康行政部门认定的具有健康体检资质的二级以上医院、乡镇卫生院、社区卫生服务中心、健康体检中心等医疗机构出具。","k":"题目看到“医疗机构”，直接答正确。","p":"","j":""},{"i":9020005,"c":2,"x":1,"y":2,"q":"遇到这种情形时，应如何行驶（ ）。","o":["靠左侧直行通过","遵守交通信号灯","停车等待","靠右侧直行通过"],"a":"C","e":"交警此时是在指挥左侧车道的车辆右转弯。抬起的手掌心朝向我方车辆，说明是禁止通行，让我方车辆停车等待。","k":"场景手势题，答案找四个字的，没有四个字的选“转弯”。","p":"40387.jpg","j":""},{"i":9020006,"c":2,"x":1,"y":1,"q":"如图所示，驾车通过有这个标志的交叉路口可以不减速。","o":["正确","错误"],"a":"B","e":"图中右侧有减速让行的标志，行驶至此处时应慢行或停车观察，确保干道车优先通行。","k":"判断题里有‘可不’、‘可以不’、‘可在’、‘可以在’的都是错的。（只有‘可以在虚线处掉头’的答对）。","p":"11130.jpg","j":""},{"i":9020007,"c":2,"x":1,"y":1,"q":"驾车在隧道内通行时不得超车。","o":["正确","错误"],"a":"A","e":"隧道内是禁止停车、超车、倒车、掉头的。","k":"判断题中“不得超车”的都对；“可以超车”的都错。","p":"","j":""},{"i":9020008,"c":2,"x":1,"y":1,"q":"非机动车不得驶入高速公路。","o":["正确","错误"],"a":"A","e":"第六十七条,行人、非机动车、拖拉机、轮式专用机械车、铰接式客车、全挂拖斗车以及其他设计最高时速低于七十公里的机动车，不得进入高速公路。","k":"在小型车试题里出现“不得”而且没有图片的判断题直接答对。例外情况：与 “只需、小于100米 、120公里 、一天 、精神病， 上高速”同时出现答错 。","p":"","j":""},{"i":9020009,"c":2,"x":1,"y":2,"q":"在高速公路遇恶劣天气能见度小于50米时，以下哪种做法正确？","o":["开启远光灯","在应急车道停车等待","加速行驶，但车速不得超过100km/h","车速不得超过20km/h，并从最近的出口尽快驶离"],"a":"D","e":"法律明文规定：1.能见度200米--60公里--100米；2.能见度100米--40公里--50米；3.能见度50米--20公里--离开高速。","k":"能见度题口诀：记住2-6-1，1-4-5，5-2-离。","p":"","j":""},{"i":9020010,"c":2,"x":1,"y":2,"q":"行车中遇抢救伤员的救护车从本车道后方驶来时，以下哪种做法正确？","o":["靠边减速或停车让行","占用其他车道行驶","加速变更车道避让","继续占原车道行驶"],"a":"A","e":"遇到正在执行任务的特种车辆，都应当予以让行。","k":"答案里有“减速或停车”的，直接选。","p":"2025081802.jpg","j":""},{"i":9020011,"c":2,"x":1,"y":1,"q":"驾驶车辆在高速公路发生故障后，应当立即开启危险报警闪光灯，按规定放置警告标志，将车内人员转移至安全位置。","o":["正确","错误"],"a":"A","e":"驾驶机动车在高速公路发生故障后，首先开启危险报警闪光灯，将车辆移至不妨碍交通的位置；然后在来车方向150米以外放置警告标志，转移乘车人员至安全处，迅速报警，等待救援。","k":"题目中有按规定意思的都是对的。","p":"","j":""},{"i":9020012,"c":2,"x":1,"y":1,"q":"如图所示，驾驶车辆遇到漫水桥时应加速冲过漫水路段。","o":["正确","错误"],"a":"B","e":"机动车行经漫水路或者漫水桥时，应当停车察明水情，确认安全后，低速通过。","k":"题目中出现“加速”意思的都是错的。","p":"40224.jpg","j":""},{"i":9020013,"c":2,"x":1,"y":1,"q":"在图中路段禁止鸣喇叭。","o":["正确","错误"],"a":"A","e":"图中右侧是禁令标志：禁止鸣喇叭，行使至此路段时不能使用喇叭。","k":"图中有“禁止鸣喇叭”标志，题目和图片一致答对。","p":"2025081901.jpg","j":""},{"i":9020014,"c":2,"x":1,"y":1,"q":"图中A车可沿箭头方向驶离高速公路。","o":["正确","错误"],"a":"B","e":"图中A车如果想驶离高速，应提前在虚线处进入减速车道，减速后经匝道驶离。图中A车已经错过虚线，直接进入匝道会压实线，是错误的。","k":"图中箭头压实线，答错。","p":"2025081804.jpg","j":""},{"i":9030052,"c":2,"x":1,"y":1,"q":"驾车通过有这个标志的交叉路口要停车让行。","o":["正确","错误"],"a":"A","e":"图中右侧有停车让行的标志，行驶至此处时应停车瞭望，确认安全后才可以通行。","k":"题目里有‘停车让行’并且图片上有人或车的都对。","p":"11131.jpg","j":""},{"i":170133,"c":3,"x":1,"y":1,"q":"在没有中心线的窄路与非机动车会车时，使用近光灯。","o":["正确","错误"],"a":"A","e":"夜间会车时，一律近光灯。使用远光灯会干扰对向驾驶员的视线，很容易发生危险。","k":"跟车、会车一律近光。","p":"","j":""},{"i":9030006,"c":3,"x":1,"y":1,"q":"行经没有火车通过的铁路道口时，可以超车。","o":["正确","错误"],"a":"B","e":"铁路道口，经常有火车经过，属于危险路段，禁止超车、掉头、倒车、停车。","k":"判断题中看到“可以超车”，直接答错误。","p":"","j":""},{"i":9030007,"c":3,"x":1,"y":2,"q":"在没有划分机动车道、非机动车道和人行道的道路行驶时，以下说法错误的是（ ）。","o":["非机动车在道路两侧通行","机动车在道路左侧通行","机动车在道路中间通行","行人在道路两侧通行"],"a":"B","e":"驾驶机动车经过无划分车道的道路时，机动车在道路中间通行，非机动车和行人在道路两侧通行。","k":"没有中心线道路通行原则：车中间，人两边。题目让选错误的，找“车左侧”。","p":"11121.jpg","j":""},{"i":9030008,"c":3,"x":1,"y":2,"q":"进入图中弯道时，最高车速是（ ）。","o":["70km/h","50km/h","30km/h","40km/h"],"a":"C","e":"最高行驶速度不得超过每小时30公里：1进出非机动车道，通过铁路道口、急弯路、窄路、窄桥时；2掉头、转弯、下陡坡时；3遇雾、雨、雪、沙尘、冰雹，能见度在50米以内时；4在冰雪、泥泞的道路上行驶时。","k":"特殊危险路段，车速都不得超30km/h。","p":"40129.jpg","j":""},{"i":9030009,"c":3,"x":1,"y":2,"q":"通过铁路道口，最高车速是（ ）。","o":["40km/h","20km/h","30km/h","50km/h"],"a":"C","e":"最高行驶速度不得超过每小时30公里：1进出非机动车道，通过铁路道口、急弯路、窄路、窄桥时；2掉头、转弯、下陡坡时；3遇雾、雨、雪、沙尘、冰雹，能见度在50米以内时；4在冰雪、泥泞的道路上行驶时。","k":"特殊危险路段，车速都不得超30km/h。","p":"40225.jpg","j":""},{"i":9030010,"c":3,"x":1,"y":1,"q":"在隧道内通行时不得超车。","o":["正确","错误"],"a":"A","e":"隧道内禁止超车、掉头、倒车、停车。","k":"判断题中看到“不能超车”、“不得超车”，直接答正确。","p":"","j":""},{"i":9030011,"c":3,"x":1,"y":1,"q":"左转弯车辆在任何情况下都可进入交叉路口左转弯待转区。","o":["正确","错误"],"a":"B","e":"左转弯待转区，只有直行是绿灯时才可以进入待转区等待左转，左转灯变绿时方可左转。","k":"题目中有“任何”的都是错的。","p":"","j":""},{"i":9030012,"c":3,"x":1,"y":1,"q":"图中己车遇右侧车辆强行变道，可加速，阻止其变道。","o":["正确","错误"],"a":"B","e":"文明驾驶，礼貌让行。驾驶机动车遇到强行变道的，应减速慢行，如都互不相让，就会造成交通事故。","k":"题目中出现“加速”意思的都是错的。","p":"60029.jpg","j":""},{"i":9030013,"c":3,"x":1,"y":1,"q":"在没有划分车道、非机动车道和人行道的道路行驶时，应降低车速靠右通行。","o":["正确","错误"],"a":"B","e":"驾驶机动车经过无划分车道的道路时，机动车在道路中间通行，非机动车和行人在道路两侧通行。","k":"没有中心线道路通行原则：车中间，人两边。","p":"picture_26.jpg","j":""},{"i":9030014,"c":3,"x":1,"y":1,"q":"行经陡坡时不得超车。","o":["正确","错误"],"a":"A","e":"容易发生危险的路段（弯道、陡坡、铁路口、隧道、桥梁、雪地、泥泞地）都不能掉头、超车、停车。车速不能超过30公里每小时。","k":"判断题中看到“不能超车”、“不得超车”，直接答正确。","p":"","j":""},{"i":9030015,"c":3,"x":1,"y":1,"q":"在没有交通信号的交叉路口应降低车速安全通过。","o":["正确","错误"],"a":"A","e":"通过路口都应该减速慢行，礼让行人和非机动车。","k":"判断题出现“安全通过”都是对的。","p":"","j":""},{"i":9030016,"c":3,"x":1,"y":1,"q":"图中两车追尾，是因为后车未注意观察，跟车距离过近。","o":["正确","错误"],"a":"A","e":"前方是人行横道，应保持安全距离，提前减速。后车很明显，没有与前车保持安全距离，才导致追尾事故。追尾一律后车的责任。","k":"判断题中出现“注意观察”的都是对的。（行人标志的题除外）","p":"picture_32.jpg","j":""},{"i":9030017,"c":3,"x":1,"y":1,"q":"在没有交通信号的路口应加速通过。","o":["正确","错误"],"a":"B","e":"通过路口都应该减速慢行，礼让行人和非机动车。","k":"题目中有‘加速通过’的都是错的，只有‘不可加速通过’是对的。","p":"","j":""},{"i":9030018,"c":3,"x":1,"y":1,"q":"驾车遇右侧车辆变更车道时，己车应提高车速，尽快超越。","o":["正确","错误"],"a":"B","e":"前方车辆已经开启左转向灯，说明他要向左变更车道。此时后车应适当减速，保持安全距离，防止两车追尾。","k":"题目里有“提高车速”的都是错的。","p":"11156.jpg","j":""},{"i":9030019,"c":3,"x":1,"y":1,"q":"机动车行经人行横道时不得超车。","o":["正确","错误"],"a":"A","e":"人行横道内禁止超车、停车、倒车、掉头。","k":"判断题中“不得超车”的都对；“可以超车”的都错。","p":"","j":""},{"i":9030020,"c":3,"x":1,"y":1,"q":"驾车变更车道应提前开启转向灯。","o":["正确","错误"],"a":"A","e":"变更车道应该提前开启相应方向转向灯，提醒其他车辆注意，不得影响正常行驶车辆，确认安全后再变更车道。","k":"题目里有‘提前’的都是对的，只有和“加速’、‘不受’同时出现答错。","p":"","j":""},{"i":9030021,"c":3,"x":1,"y":2,"q":"如图所示，夜间驾车在窄桥会车时应怎样使用灯光？","o":["开启危险报警闪光灯","开启近光灯","关闭前照灯","开启远光灯"],"a":"B","e":"夜间会车时，一律近光灯。使用远光灯会干扰对向驾驶员的视线，很容易发生危险。","k":"跟车、会车一律开“近光灯”。","p":"2025070716.jpg","j":""},{"i":9030022,"c":3,"x":1,"y":1,"q":"超车时，遇前车未减速让行，可加速超越。","o":["正确","错误"],"a":"B","e":"超车时，前方车辆不减速不让路，应该主动放弃超车，保持距离行驶，等下次超车机会。","k":"题目中出现“加速超越”的，直接答错。","p":"","j":""},{"i":9030023,"c":3,"x":1,"y":1,"q":"在没有中心标线的窄路与自行车会车时，使用远光灯。","o":["正确","错误"],"a":"B","e":"夜间会车时，一律近光灯。使用远光灯会干扰对向驾驶员的视线，很容易发生危险。","k":"使用远光灯的都是错的。","p":"","j":""},{"i":9030024,"c":3,"x":1,"y":1,"q":"驾车变更车道时无需观察，开启转向灯同时驶入相应车道。","o":["正确","错误"],"a":"B","e":"变更车道应该提前开启相应方向转向灯，提醒其他车辆注意，不得影响正常行驶车辆，确认安全后再变更车道。","k":"判断题出现“不需”、“无需” 都是错的。","p":"","j":""},{"i":9030025,"c":3,"x":1,"y":1,"q":"驾车在车道减少的路口、路段行驶时，遇有前方机动车停车排队等候或缓慢行驶的，应当尽快穿插驶入。","o":["正确","错误"],"a":"B","e":"车道减少停车排队时，应该排队依次行驶。强行穿插、加塞只会加重拥堵情况。","k":"题目里有“穿插”的，直接答错误。","p":"","j":""},{"i":9030026,"c":3,"x":1,"y":1,"q":"准备超车时，应提前打开左转向灯。","o":["正确","错误"],"a":"A","e":"超车前应该提前开启左转灯，同时可以切换远、近光灯或适当鸣喇叭提醒被超车辆，超车后应与后车拉开距离再开右转灯驶回原车道。","k":"题目里有‘提前’的都是对的，只有和“加速’、‘不受’同时出现答错。","p":"","j":""},{"i":9030027,"c":3,"x":1,"y":1,"q":"在没有中心标线的窄路与自行车会车时，使用近光灯。","o":["正确","错误"],"a":"A","e":"夜间会车时，一律近光灯。使用远光灯会干扰对向驾驶员的视线，很容易发生危险。","k":"判断题中用“近光灯”、“远近光”的，都是对的。（图片题除外）","p":"","j":""},{"i":9030028,"c":3,"x":1,"y":1,"q":"在禁止鸣喇叭的区域行驶时，不得鸣喇叭。","o":["正确","错误"],"a":"A","e":"行驶至禁止鸣喇叭的区域，是不可以鸣喇叭的。","k":"在小型车试题里出现“不得”而且没有图片的判断题直接答对。例外情况：与 “只需、小于100米 、120公里 、一天 、精神病， 上高速”同时出现答错 。","p":"","j":""},{"i":9030029,"c":3,"x":1,"y":1,"q":"驾车进入交叉路口实线导向车道后，可变更车道。","o":["正确","错误"],"a":"B","e":"进入实线导向车道的车辆，应按导向箭头指示行驶，不得变更车道或压线行驶。","k":"虚可实禁。（虚线可以跨越。实线禁止跨越）。","p":"","j":""},{"i":9030030,"c":3,"x":1,"y":1,"q":"驾驶机动车在车道减少的路段，遇有前方机动车缓慢行驶的，应当每车道一辆依次交替驶入车道减少后的路段。","o":["正确","错误"],"a":"A","e":"车道减少停车排队时，应该排队依次行驶。强行穿插、加塞只会加重拥堵情况。","k":"判断题里有“依次”的直接答对。","p":"","j":""},{"i":9030031,"c":3,"x":1,"y":1,"q":"超车时提前打开左转向灯、变换使用远近光灯或者鸣喇叭，是为了提醒周边车辆和行人。","o":["正确","错误"],"a":"A","e":"超车前应该提前开启左转灯，同时可以切换远、近光灯或适当鸣喇叭提醒被超车辆，超车后应与后车拉开距离再开右转灯驶回原车道。","k":"题目里有‘提前’的都是对的，只有和“加速’、‘不受’同时出现答错。","p":"","j":""},{"i":9030032,"c":3,"x":1,"y":1,"q":"如果无法保证与被超车辆间的安全车距，应放弃超车。","o":["正确","错误"],"a":"A","e":"安全第一，超车无法保持安全距离说明不具备超车条件，应该放弃超车。","k":"题目看到“放弃”，直接答对。","p":"","j":""},{"i":9030033,"c":3,"x":1,"y":1,"q":"夜晚在照明不良路段跟车较近时，应打开近光灯。","o":["正确","错误"],"a":"A","e":"跟车行驶一律近光，远光灯会影响前车的视线，特别是夜晚跟车、会车一定不要用远光灯。","k":"判断题中用“近光灯”、“远近光”的，都是对的。（图片题除外）","p":"2025070713.jpg","j":""},{"i":9030034,"c":3,"x":1,"y":1,"q":"发生图中交通事故，A车负次要责任。","o":["正确","错误"],"a":"B","e":"进入环岛应让环岛内的车辆先行，明显B车行驶在环岛内，A车没有让B车，才引发的事故，所以A车负全责。","k":"判断题中有“次要责任”的，直接答错误。","p":"2025070714.jpg","j":""},{"i":9030035,"c":3,"x":1,"y":1,"q":"驾驶车辆在高速路上遇前方拥堵时，可尽快超车通过。","o":["正确","错误"],"a":"B","e":"何路段交通拥堵，都应该依次排队行驶，防止拥堵情况加重。","k":"题目里有“尽快”都是错的，只有和“减少”、“60”同时出现答对。","p":"","j":""},{"i":9030036,"c":3,"x":1,"y":1,"q":"图中左侧蓝车超车时，己车应该减速让行。","o":["正确","错误"],"a":"A","e":"行驶中遇前车正在超车，应减速让行。","k":"礼让通行的都是对的。","p":"60018.jpg","j":""},{"i":9030037,"c":3,"x":1,"y":1,"q":"雾天驾驶车辆可打开远光灯。","o":["正确","错误"],"a":"B","e":"雾天要用雾灯，雾灯穿透力强，开远光灯会出现漫反射造成驾驶人视线受阻，影响驾驶安全。","k":"使用远光灯的都是错的。","p":"","j":""},{"i":9030038,"c":3,"x":1,"y":1,"q":"驾车应当紧跟前车行驶。","o":["正确","错误"],"a":"B","e":"在路上行驶应该与前车保持安全距离，紧跟容易引发追尾事故。","k":"题目中有“紧跟”都是错的。","p":"","j":""},{"i":9030039,"c":3,"x":1,"y":1,"q":"机动车向右变更车道开启右转向灯。","o":["正确","错误"],"a":"A","e":"变更车道应该提前开启相应方向转向灯，提醒其他车辆注意，不得影响正常行驶车辆，确认安全后再变更车道。","k":"常识，向右变道开右转灯。","p":"","j":""},{"i":9030040,"c":3,"x":1,"y":2,"q":"前方遇有下列哪种车辆可以超车？","o":["执行任务的消防车","执行任务的警车","执行任务的救护车","出租汽车"],"a":"D","e":"遇执行任务的警车、消防车、救护车等，不能超越。","k":"常识，执行任务的车辆不能超越，所以选“出租汽车”。","p":"","j":""},{"i":9030041,"c":3,"x":1,"y":1,"q":"后方无来车时，己车可以不开转向灯变道。","o":["正确","错误"],"a":"B","e":"变更车道应该提前开启相应方向转向灯，提醒其他车辆注意，不得影响正常行驶车辆，确认安全后再变更车道。","k":"判断题里有‘可不’、‘可以不’、‘可在’、‘可以在’的都是错的。（只有‘可以在虚线处掉头’的答对）。","p":"","j":""},{"i":9030042,"c":3,"x":1,"y":1,"q":"驾车应当与前车保持安全距离。","o":["正确","错误"],"a":"A","e":"在路上行驶应该与前车保持安全距离，紧跟容易引发追尾事故。","k":"题目有‘安全距离’或加大车距意思的都是对的。","p":"","j":""},{"i":9030043,"c":3,"x":1,"y":1,"q":"驾车上坡将要到达坡顶时，不可鸣喇叭示意。","o":["正确","错误"],"a":"B","e":"驾车抵达坡顶时，会影响驾驶员的视距，所以此时应该减速慢行并鸣喇叭示意，安全驾驶。","k":"转弯、陂路等视线受阻的路段行驶原则：减速、靠右、鸣喇叭。","p":"","j":""},{"i":9030044,"c":3,"x":1,"y":2,"q":"以下哪种情形可以超车？","o":["前车减速让行","前车正在掉头","前车正在超车","前车正在左转弯"],"a":"A","e":"前车正在超车、左转弯、掉头、变道，后车都不能超越前车。","k":"前车有向左的行为都不可以超车，所以选“减速让行”。","p":"","j":""},{"i":9030045,"c":3,"x":1,"y":1,"q":"夜晚在照明不良路段跟车较近时，应打开远光灯。","o":["正确","错误"],"a":"B","e":"夜间通过照明不好的路段跟车、会车必须开启近光灯。","k":"使用远光灯的都是错的。","p":"2025070713.jpg","j":""},{"i":9030046,"c":3,"x":1,"y":1,"q":"冰雪道路行驶的最高车速是50km/h。","o":["正确","错误"],"a":"B","e":"最高行驶速度不得超过每小时30公里情况：1、进出非机动车道，通过铁路道口、急弯路、窄路、窄桥时；2、掉头、转弯、下陡坡时；3、遇雾、雨、雪、沙尘、冰雹，能见度在50米以内时；4、在冰雪、泥泞的道路上行驶时。","k":"判断题中只有30公里和100公里是对的，其他公里的全部是错的。","p":"42493.jpg","j":""},{"i":9030047,"c":3,"x":1,"y":1,"q":"驾车行经桥梁、隧道和陡坡不得超车。","o":["正确","错误"],"a":"A","e":"容易发生危险的路段（弯道、陡坡、铁路口、隧道、桥梁、雪地、泥泞地）都不能掉头、超车、停车。车速不能超过30公里每小时。","k":"判断题中看到“不能超车”、“不得超车”，直接答正确。","p":"","j":""},{"i":9030048,"c":3,"x":1,"y":2,"q":"行经下列哪些地点可以超车？","o":["交叉路口","隧道","窄桥","城市快速路"],"a":"D","e":"容易发生危险的路段（交叉路口、弯道、陡坡、铁路口、隧道、桥梁、雪地、泥泞地）都不能掉头、超车、停车。","k":"特殊危险路段禁止超车，所以只能选“城市快速路”。","p":"","j":""},{"i":9030049,"c":3,"x":1,"y":1,"q":"夜晚在急弯驾驶车辆时，使用远光灯。","o":["正确","错误"],"a":"B","e":"机动车在夜间通过急弯、坡路、拱桥、人行横道或者没有交通信号灯控制的路口时，应当交替使用远近光灯示意，用以提醒其他车辆。","k":"使用远光灯的都是错的。","p":"picture_24.jpg","j":""},{"i":9030050,"c":3,"x":1,"y":1,"q":"超车时应确认具备充足的横向距离，不可越实线超车。","o":["正确","错误"],"a":"A","e":"超车时，要与前车加大横向距离，但是不可以越实线超车。","k":"题目里看到“实线超车”的答错；“不可实线超车”的答对。","p":"","j":""},{"i":9030051,"c":3,"x":1,"y":2,"q":"雨天跟车行驶时，不能使用的灯光是（ ）。","o":["远光灯","后位灯","近光灯","示廓灯"],"a":"A","e":"跟车行驶时不能使用远光灯,主要是因为这会导致前车司机的后视镜受到影响,形成局部盲区,增加发生交通事故的风险。","k":"题目问“不能使用”，使用远光灯的都是错的，所以选“远光灯”。","p":"70104.jpg","j":""},{"i":9030053,"c":3,"x":1,"y":1,"q":"在进入交叉路口实线导向车道前，变更车道要在虚线路段完成。","o":["正确","错误"],"a":"A","e":"车辆进入实线导向车道前，应在虚线区域变更到想去的车道，一旦进入实线区域，不得变更车道或压线行驶。","k":"实线不可压，所以变道在虚线路段是对的。","p":"","j":""},{"i":9030054,"c":3,"x":1,"y":1,"q":"如图所示，夜间驾车在窄桥会车时应当使用远光灯。","o":["正确","错误"],"a":"B","e":"夜间会车时，一律近光灯。使用远光灯会干扰对向驾驶员的视线，很容易发生危险。","k":"使用远光灯的都是错的。","p":"2025070716.jpg","j":""},{"i":9030055,"c":3,"x":1,"y":1,"q":"机动车行经交叉路口时不得超车。","o":["正确","错误"],"a":"A","e":"铁道路口、交叉路口、窄桥、窄路、弯道、坡道、隧道、人行横道以及交通流量大的路段等特殊危险路段，禁止超车。","k":"判断题中“不得超车”的都对；“可以超车”的都错。","p":"","j":""},{"i":9030056,"c":3,"x":1,"y":1,"q":"图中A车在这种情况下，可适当加速。","o":["正确","错误"],"a":"B","e":"图中，B车已经开启右转向灯准备要右转，因此A车应适当的减速，加速可能发生追尾。","k":"判断题中看到“适当减速”的答对；“适当加速”的答错。","p":"2025070719.jpg","j":""},{"i":9030057,"c":3,"x":1,"y":1,"q":"驾车在交叉路口右转弯时，应提前开启右转向灯，根据交通信号的指示，降低车速安全通过。","o":["正确","错误"],"a":"A","e":"交叉路口右转弯应提前开启右转向灯，根据信号灯指示，确认安全后通过路口。","k":"题目里有‘提前’的都是对的，只有和“加速’、‘不受’同时出现答错。","p":"","j":""},{"i":9030058,"c":3,"x":1,"y":1,"q":"图中己车准备进入环形路口时，应当让红车先行，依次进入路口。","o":["正确","错误"],"a":"A","e":"在进出环形路口或路口变更车道时，都必须让在原车道内行驶的车辆(包括非机动车)先行，以保证安全。","k":"判断题里有“依次”的直接答对。","p":"11187.jpg","j":""},{"i":9030059,"c":3,"x":1,"y":1,"q":"驾车遇沙尘、冰雹、雨、雾、结冰等气象条件时，应当提高行驶速度，迅速通过。","o":["正确","错误"],"a":"B","e":"特殊天气条件下行车，应减速慢行。","k":"题目里有“迅速”的都错。（只有迅速报警和降低车速意思的是对的）","p":"","j":""},{"i":9030060,"c":3,"x":1,"y":1,"q":"驾车通过有交通信号灯控制的路口，遇停止信号时，依次停在停止线以外。","o":["正确","错误"],"a":"A","e":"行驶至路口遇红灯时，应该依次在停止线外等候。","k":"判断题里有“依次”的直接答对。","p":"","j":""},{"i":9030061,"c":3,"x":1,"y":1,"q":"雾天通过交叉路口时，要开灯、鸣喇叭、减速慢行。","o":["正确","错误"],"a":"A","e":"雾天通过交叉路口，应开启雾灯，鸣喇叭警示后减速慢行通过。","k":"判断题看到“减速慢行”都是对的，只有标志里有车和“不用减速慢行”是错的。","p":"","j":""},{"i":9030062,"c":3,"x":1,"y":1,"q":"驾车进入交叉路口前，应注意观察、提高车速。","o":["正确","错误"],"a":"B","e":"进入交叉路口前应注意观察路口内情况，确认安全后减速通过。","k":"判断题中有“提高车速”的都是错的。","p":"","j":""},{"i":9030063,"c":3,"x":1,"y":2,"q":"夜晚驾驶车辆在道路发生事故妨碍交通又难以移动时，不应该打开的灯光是（ ）。","o":["危险报警闪光灯","示廓灯","后位灯","远光灯"],"a":"D","e":"机动车在道路上发生故障或者交通事故，妨碍交通又难以移动时，应当在车后50米至100米处设置警告标志，并按照规定开启危险报警闪光灯，夜间还应当同时开启示廓灯和后位灯。","k":"使用远光灯的都是错的，题目问不应该，答案选“远光灯”。","p":"2025070724.jpg","j":""},{"i":9030064,"c":3,"x":1,"y":1,"q":"驶离高速路时，可不打开转向灯。","o":["正确","错误"],"a":"B","e":"驶入高速公路是提前开左转向灯；驶离高速公路是提前开右转向灯。","k":"判断题里有‘可不’、‘可以不’、‘可在’、‘可以在’的都是错的。（只有‘可以在虚线处掉头’的答对）。","p":"","j":""},{"i":9030065,"c":3,"x":1,"y":2,"q":"前方遇有下列哪种车辆可以超车？","o":["执行任务的警车","执行任务的救护车","执行任务的消防车","城市公交车"],"a":"D","e":"遇执行任务的警车、消防车、救护车等，不能超越。","k":"常识，执行任务的车辆不能超越，所以选“公交车”。","p":"","j":""},{"i":9030066,"c":3,"x":1,"y":2,"q":"如图所示，夜间会车时，应距对向来车（ ）将远光灯改为近光灯。","o":["150米以内","150米以外","100米以内","50米以内"],"a":"B","e":"夜间会车如果开远光灯，会造成驾驶员看不清周围情况，所以夜间遇到对向来车，应该距离对面来车150米以外，将远光灯换成近光灯。","k":"答案里看到“150”或“150米以外”，直接选。(题目里有“100”的和错误的不选)","p":"2025070716.jpg","j":""},{"i":9030067,"c":3,"x":1,"y":2,"q":"机动车在没有划分机动车道、非机动车道和人行道的道路行驶时，以下说法正确的是（ ）。","o":["在道路两侧通行","在道路中间通行","在道路右侧通行","可随意通行"],"a":"B","e":"驾驶机动车经过无划分车道的道路时，机动车在道路中间通行，非机动车和行人在道路两侧通行。","k":"没有中心线道路通行原则：车中间，人两边。","p":"60032.jpg","j":""},{"i":9030068,"c":3,"x":1,"y":2,"q":"有关在道路同方向划有2条以上车道的，以下说法错误的是（ ）。","o":["左侧为快车道","右侧为慢车道","未达到快速车道限速规定的，可在快速车道行驶","在慢速车道超车时可借用快速车道"],"a":"C","e":"同方向划有2条以上车道的道路，左侧为快车道，右侧为慢车道，在慢车道的车辆可以借用快车道超车，未达到快速车道限速规定的，不可在快速车道行驶。","k":"题目问错误的，答案找“可在”。","p":"","j":""},{"i":9030069,"c":3,"x":1,"y":1,"q":"人行横道禁止掉头。","o":["正确","错误"],"a":"A","e":"人行横道内禁止超车、停车、倒车、掉头。","k":"常识，记住就好！","p":"","j":""},{"i":9030070,"c":3,"x":1,"y":2,"q":"在高速公路遇图中所示情况时，以下哪种做法正确？","o":["增大跟车距离","紧跟前车","停在应急车道","加速行驶"],"a":"A","e":"这种雾天在高速公路行驶，应该打开雾灯和危险报警闪光灯，注意与前车保持距离，减速行驶，避免发生追尾事故。","k":"答案中有保持车距意思的 ，看到\"距离\" 直接选。","p":"21238.jpg","j":""},{"i":9030071,"c":3,"x":1,"y":1,"q":"图中灰色车辆驶离高速公路时，应开启右转向灯，驶入减速车道。","o":["正确","错误"],"a":"A","e":"图中车辆想驶离高速公路，应提前开启右转向灯，从虚线处进入减速车道，准备进入匝道口。","k":"进出高速路灯光口诀：左灯进，右灯出。","p":"picture_92.jpg","j":""},{"i":9030072,"c":3,"x":1,"y":1,"q":"在距离图中路段50米内不得停放机动车。","o":["正确","错误"],"a":"A","e":"以下路段30米内不能停车：公交车站、急救站、加油站、消防站等；以下路段50米内不能停车：桥梁、隧道口、急弯路、窄路、交叉路口等。","k":"口诀：站三口五。（有站、队30米内不能停车；路口50米内不能停车。）","p":"picture_79.jpg","j":""},{"i":9030073,"c":3,"x":1,"y":2,"q":"驾驶机动车遇图中前方交叉路口交通阻塞时怎样行驶？","o":["依次停在路口外等候","可以对向车道通过","从前车两侧穿插通过","进入路口内等候"],"a":"A","e":"交叉路口交通阻塞，机动车此时进入路口的话，可能会造成更严重的堵塞，正确的做法应依次停在路口以外等候。","k":"答案中看到“依次”，直接选。","p":"picture_56.jpg","j":""},{"i":9030074,"c":3,"x":1,"y":1,"q":"图中路段不允许掉头。","o":["正确","错误"],"a":"B","e":"虚线可以掉头，实线不可以掉头。","k":"虚可实禁。图中是虚线“可以掉头”，题目说“不允许掉头”，题目和图片不一致答错。","p":"11196.jpg","j":""},{"i":9030075,"c":3,"x":1,"y":1,"q":"机动车载物应当符合核定的载质量，严禁超载，载物的长、宽、高不得违反装载要求，不得遗洒、飘散载运物。","o":["正确","错误"],"a":"A","e":"《道路交通安全法》第四十八条规定：机动车载物应当符合核定的载质量，严禁超载；载物的长、宽、高不得违反装载要求，不得遗洒、飘散载运物。","k":"在小型车试题里出现“不得”而且没有图片的判断题直接答对。例外情况：与 “只需、小于100米 、120公里 、一天 、精神病， 上高速”同时出现答错 。","p":"","j":""},{"i":9030076,"c":3,"x":1,"y":1,"q":"车辆在高速公路上发生故障停在应急车道后，可以不开启危险报警闪光灯。","o":["正确","错误"],"a":"B","e":"发生故障、交通事故必须打开危险报警灯，在车后设置警告标志。（普通路是50米以外100米以内；高速路上是150米以外。）","k":"判断题里有‘可不’、‘可以不’、‘可以在’的都是错的。（‘可以在虚线处掉头’的除外）","p":"","j":""},{"i":9030077,"c":3,"x":1,"y":2,"q":"如图所示，驾车在路口遇到这种信号灯时，以下说法正确的是（ ）。","o":["可以向左或向右转弯","可以直行或向左转弯","可以向左转弯","可以直行或向右转弯"],"a":"D","e":"图中信号灯，红箭头代表禁止通行，绿箭头代表准许通行，所以此时只能直行或右转弯，不能左转弯。","k":"图中绿色箭头一个是直的，一个是向右的，答案找“可以直行或向右”。","p":"2025081806.jpg","j":""},{"i":9030078,"c":3,"x":1,"y":2,"q":"如图所示，以下做法正确的是（ ）。","o":["鸣笛催促","保持速度通过","减速避让","加速通过"],"a":"C","e":"图中左右两侧都有人正在通过人行横道，应减速避让，必要时停车让行。","k":"答案中有“减速避让”、“停车避让”的直接选。","p":"picture_41.jpg","j":""},{"i":9030079,"c":3,"x":1,"y":1,"q":"在高速公路车流量较小时，可以长时间骑、轧车行道分界线行驶。","o":["正确","错误"],"a":"B","e":"任何路上骑线行驶，都会影响正常通行，不能一车占两道，压线行驶易引发危险。","k":"骑轧分界线行驶容易发生危险。","p":"","j":""},{"i":9030080,"c":3,"x":1,"y":1,"q":"驾车时不得向道路上抛撒物品。","o":["正确","错误"],"a":"A","e":"道路上随便抛洒物品，对其他车辆来说是很危险的，这是违法行为。","k":"在小型车试题里出现“不得”而且没有图片的判断题直接答对。例外情况：与 “只需、小于100米 、120公里 、一天 、精神病， 上高速”同时出现答错 。","p":"","j":""},{"i":9030081,"c":3,"x":1,"y":1,"q":"为了车辆美观，可以在驾驶室前后窗范围内悬挂和放置妨碍驾驶人视线的物品。","o":["正确","错误"],"a":"B","e":"物品干扰开车视线增大了行车危险，容易引发交通事故。","k":"判断题里有‘可不’、‘可以不’、‘可以在’的都是错的。（‘可以在虚线处掉头’的除外）。","p":"","j":""},{"i":9030082,"c":3,"x":1,"y":2,"q":"在高速公路发生车辆故障必须停车排查时，应将车辆停在（ ）。","o":["应急车道","最左侧车道","中间车道","最右侧车道"],"a":"A","e":"高速路最右侧就是紧急停车道，也就是应急车道。应急车道就是专门在车子发生故障或事故时停靠的。","k":"题目有“故障”，答案找“报警”或“应急”。","p":"","j":""},{"i":9030083,"c":3,"x":1,"y":2,"q":"以下哪些地点允许倒车？","o":["隧道","高速公路","停车场","立交匝道"],"a":"C","e":"交叉路口、隧道、急弯、陡坡、铁路道口、匝道、宽度不足4米的窄路、窄桥等特殊危险路段等以上路段均不得超车、掉头、倒车、停车。（以上路段车速均不能超过30km/h）。","k":"常识：停车场内是可以倒车的。","p":"","j":""},{"i":9030084,"c":3,"x":1,"y":2,"q":"图中黄车驶入减速车道时，以下灯光操作正确的是（ ）。","o":["开启远光灯","开启右转向灯","开启危险报警闪光灯","开启近光灯"],"a":"B","e":"图中黄车想要驶离高速，应提前开启右转向灯驶入减速车道，降到规定时速后安全驶离。","k":"图中减速车道在黄车的右侧，答案找“右”。","p":"2025081807.jpg","j":""},{"i":9030085,"c":3,"x":1,"y":2,"q":"如图所示，驾车在路口遇到这种信号灯时，以下说法正确的是（ ）。","o":["可以直行","可以向右转弯","可以直行或向左转弯","可以向左转弯"],"a":"B","e":"图中信号灯，红箭头代表禁止通行，绿箭头代表准许通行，所以此时只能右转弯，不能左转弯或直行。","k":"图中绿色箭头向右，答案找“可以向右”。","p":"2025081808.jpg","j":""},{"i":9030086,"c":3,"x":1,"y":1,"q":"在路边临时停车时应顺向停放车辆。","o":["正确","错误"],"a":"A","e":"为了确保道路的安全和顺畅，临时停车时应顺向停车，即按照道路的行驶方向，将车辆停靠在道路的右侧。","k":"题目里看到“顺向”，直接答正确。","p":"","j":""},{"i":9030087,"c":3,"x":1,"y":1,"q":"如图所示，车辆可在行人未通过前加速通过。","o":["正确","错误"],"a":"B","e":"图中有行人横过要停车让行，待行人通过后再起步。","k":"题目中有‘加速通过’的都是错的，只有‘不可加速通过’是对的。","p":"11179.jpg","j":""},{"i":9030088,"c":3,"x":1,"y":1,"q":"牵引发生故障的车辆时，最高车速不得超过30km/h。","o":["正确","错误"],"a":"A","e":"遇有下列情形之一的，最高速度不得超过每小时30公里：进出非机动车道，通过铁路道口、急弯路、窄路、窄桥时；掉头、转弯、下陡坡时；遇雾、雨、雪、沙尘、冰雹，能见度在50米以内时；在冰雪、泥泞的道路上行驶时；牵引发生故障的机动车时。","k":"判断题中只有30公里和100公里是对的，其他公里的全部是错的。","p":"","j":""},{"i":9030089,"c":3,"x":1,"y":1,"q":"在高速公路遇恶劣天气能见度小于100米时，应与同车道前车保持50米以上的距离。","o":["正确","错误"],"a":"A","e":"1.能见度200米--60公里--100米；2.能见度100米--40公里--50米；3.能见度50米--20公里--离开高速。","k":"能见度的题记住2-6-1，1-4-5，5-2-离。","p":"","j":""},{"i":9030090,"c":3,"x":1,"y":1,"q":"在高速公路驾车，应根据个人驾驶经验确认车速。","o":["正确","错误"],"a":"B","e":"高速公路每个车道都有限速标准，应该按限速标志确认车速，不可以根据经验确认。","k":"题目中看到“经验”二字，直接答错误。","p":"","j":""},{"i":9030091,"c":3,"x":1,"y":1,"q":"从高速公路进入减速车道后，应通过观察与前后车的距离控制车速，不能单纯凭感觉。","o":["正确","错误"],"a":"A","e":"进入减速车道后，根据限速标志规定，通过观察与前后车的距离控制车速。","k":"判断题中“凭感觉”的都是错的，只有“不凭感觉”是对的。","p":"","j":""},{"i":9030092,"c":3,"x":1,"y":1,"q":"在高速公路上发生故障后，应将车上人员迅速转移至车辆前方等待救援。","o":["正确","错误"],"a":"B","e":"高速公路上车辆故障时，应逐渐向右变更车道，停在应急车道内，车上人员应当迅速转移到应急车道或路肩，并立刻报警处理。车辆附近都很危险。","k":"题目里有“迅速”的都错。（只有迅速报警和降低车速意思的是对的）","p":"","j":""},{"i":9030093,"c":3,"x":1,"y":1,"q":"在交叉路口、铁路道口内可以临时停车。","o":["正确","错误"],"a":"B","e":"以下路段30米内不能停车：公交车站、急救站、加油站、消防站等；以下路段50米内不能停车：桥梁、隧道口、急弯路、窄路、交叉路口等。","k":"特殊危险路段禁止掉头、超车、停车、倒车。","p":"","j":""},{"i":9030094,"c":3,"x":1,"y":1,"q":"图中路段允许倒车。","o":["正确","错误"],"a":"B","e":"图上右侧是蓝色的指示标志：直行单行路。这种路段是禁止掉头、倒车的。","k":"图中是“单行路”，箭头向前，只能向前走，不可以倒车。","p":"2025081813.jpg","j":""},{"i":9030095,"c":3,"x":1,"y":1,"q":"图中路段不允许掉头。","o":["正确","错误"],"a":"A","e":"图中道路中间是黄实线，实线禁止跨越，所以不能掉头。","k":"虚可实禁。图中是实线，“不能掉头”，题目和图片一致答对。","p":"60039.jpg","j":""},{"i":9030096,"c":3,"x":1,"y":2,"q":"图中车辆在高速公路上因故障停车，以下哪种说法正确？","o":["该车未开启危险报警闪光灯","警告标志设置距离不足","该车骑轧应急车道分界线","警告标志设置方向错误"],"a":"B","e":"高速公路因故障停车，首先应该开启危险报警闪光灯，图片中车灯亮着这说明已开启。然后在来车方向150米以外设置警告标志。图中标的距离是100米，肯定不对。应规范停车，不能骑轧实线，图中故障车左侧车轮明显已经压在实线边缘，也是不对的。","k":"","p":"20200332.jpg","j":""},{"i":9030097,"c":3,"x":1,"y":1,"q":"车辆在高速公路发生故障后，只需开启危险报警闪光灯，无需设置警告标志。","o":["正确","错误"],"a":"B","e":"驾驶机动车在高速公路发生故障，首先开启危险报警闪光灯，将车辆移至不妨碍交通的位置；然后在车后150米以外放置警告标志，转移乘车人员至安全处，迅速报警，等待救援。","k":"判断题出现“不需”、“无需” 都是错的。","p":"","j":""},{"i":9030098,"c":3,"x":1,"y":1,"q":"驾驶车辆遇图中所示情况时，应主动让行左侧灰色车辆。","o":["正确","错误"],"a":"A","e":"图上明显是汇入主车道，应减速慢行，在不影响正常行驶车辆情况下汇入。所以应减速让灰色车通过后再汇入车流。","k":"判断题中有‘主动’二字的，都是对的。","p":"picture_57.jpg","j":""},{"i":9030099,"c":3,"x":1,"y":1,"q":"驶入高速公路后应直接进入最左侧车道行驶。","o":["正确","错误"],"a":"B","e":"进入高速，应经加速车道加速后，开启左转向灯，观察后面无来车再驶入行车道，想驶入最左侧车道应每次变更一条车道，直到变更至最左侧。。","k":"题目出现“直接”的都是错的，只有“直接影响”是对的。","p":"","j":""},{"i":9030100,"c":3,"x":1,"y":1,"q":"驾驶车辆遇到图中这种情形时应连续大声鸣笛催促前方行人。","o":["正确","错误"],"a":"B","e":"图中车辆前方有横过道路的行人，应减速避让，必要时停车让行。","k":"题目里有“催促”二字的直接判错误。","p":"picture_64.jpg","j":""},{"i":9030101,"c":3,"x":1,"y":1,"q":"在没有道路中心标线的道路行驶时，应在道路中间通行。","o":["正确","错误"],"a":"A","e":"没有中心线的路上，机动车要在路中间行驶，给两侧的行人让出足够的空间。","k":"没有中心线的道路通行原则，车中间，人两边。","p":"","j":""},{"i":9030102,"c":3,"x":1,"y":1,"q":"驾驶车辆经图中漫水路时，应当停车察明水情，确认安全后，低速通过。","o":["正确","错误"],"a":"A","e":"机动车行经漫水路或者漫水桥时，应当首先停车察明水情，确认安全后，低速通过。如果不查明水情，冒然行驶的话，水过深，会导致发动机进水，损坏车辆。","k":"判断题中有“确认安全”的都对。","p":"2025081812.jpg","j":""},{"i":9030103,"c":3,"x":1,"y":1,"q":"在高速公路匝道，加速车道或者减速车道内禁止超车。","o":["正确","错误"],"a":"A","e":"高速公路的加速车道、减速车道和匝道都是禁止停车、倒车、掉头、超车的。","k":"判断题中看到“禁止超车”的，直接答正确。","p":"","j":""},{"i":9030104,"c":3,"x":1,"y":1,"q":"机动车向右变更车道开启左转向灯。","o":["正确","错误"],"a":"B","e":"变更车道应该提前开启相应方向转向灯，提醒其他车辆注意，不得影响正常行驶车辆，确认安全后再变更车道。","k":"常识，向右变道开右转灯。","p":"","j":""},{"i":9030105,"c":3,"x":1,"y":1,"q":"当驾驶车辆遇到前方交叉路口交通拥堵时，应按顺序停在路口外等候，严禁驶入路口。","o":["正确","错误"],"a":"A","e":"遇到车辆停车排队等候或者缓慢行驶时，应依次行驶，不要超车、占道，贸然进入路口，避免造成更大的拥堵。","k":"判断题里有“依次”、“按顺序”的直接答对。","p":"","j":""},{"i":9030106,"c":3,"x":1,"y":1,"q":"最高设计时速低于70公里的机动车不得进入高速公路行驶。","o":["正确","错误"],"a":"A","e":"第六十七条,行人、非机动车、拖拉机、轮式专用机械车、铰接式客车、全挂拖斗车以及其他设计最高时速低于七十公里的机动车,不得进入高速公路。","k":"在小型车试题里出现“不得”而且没有图片的判断题直接答对。例外情况：与 “只需、小于100米 、120公里 、一天 、精神病， 上高速”同时出现答错 。","p":"","j":""},{"i":9030107,"c":3,"x":1,"y":1,"q":"驾车在没有中心线的城市道路行驶时，最高车速是30km/h。","o":["正确","错误"],"a":"A","e":"交通安全法规定：没有中心线的城市道路最高行驶速度为30km/h，乡村道路行驶速度最高为40km/h。有中心线的城市道路最高行驶速度为50km/h，乡村道路行驶速度最高为70km/h。","k":"判断题中只有30公里和100公里是对的，其他公里数都是错误的。","p":"","j":""},{"i":9030108,"c":3,"x":1,"y":2,"q":"如图所示，校车在最右侧车道停靠上下学生时，以下哪辆车可以通行？","o":["①","②","③","②③"],"a":"A","e":"校车在路右侧车道上下学生，同向有一条车道或两条车道的，后方的车辆都应该停车等待。同向有三条车道的，中间车道也必须停车等待，只有最左侧车道，利于观察情况，可以减速通过。","k":"校车停车上下学生只有最左侧车道车辆可以通行，所以选①。","p":"2025081818.jpg","j":""},{"i":9030109,"c":3,"x":1,"y":1,"q":"图中白色车辆可以在该路段练车。","o":["正确","错误"],"a":"B","e":"由路边的绿色路牌可知，这是高速公路。白色车的车牌显示XX学并且写着教练车，教练车是不能上高速的。","k":"判断题里有‘可不’、‘可以不’、‘可以在’的都是错的，只有一题‘可以在虚线处掉头’是对的。","p":"2025070717.jpg","j":""},{"i":9030110,"c":3,"x":1,"y":1,"q":"驾驶机动车遇到后方有执行任务的紧急车辆时，可以借用无人通行的非机动车道让行。","o":["正确","错误"],"a":"A","e":"机动车遇有执行任务的紧急车辆时，在不影响其他车道行驶情况下，可以暂时借用，以保证执行任务的紧急车辆顺利通过。","k":"判断题里有“借”字的都是错的。（只有和“执行任务”同时出现时答对）","p":"","j":""},{"i":9030111,"c":3,"x":1,"y":1,"q":"车辆应靠高速公路右侧的路肩上行驶。","o":["正确","错误"],"a":"B","e":"《道路交通安全法实施条例》第八十二条规定，机动车在高速公路行驶，不得有下列行为：（三）骑、轧车行道分界线或者在路肩上行驶。","k":"看到“路肩行驶”的，直接答错误。","p":"","j":""},{"i":9030112,"c":3,"x":1,"y":2,"q":"图中车辆因故障在应急车道内停车，以下哪种做法正确？","o":["不用开启危险报警闪光灯","警告标志放置距离为50米","在来车方向设置警告标志","人员坐在车内等待"],"a":"C","e":"高速公路因故障在应急车道停车，首先应开启危险报警闪光灯，图中未开启灯光。然后在来车方向150米以外设置警告标志，图中标的距离是50米。驾乘人员应撤离到安全区域等待救援，车内等待非常危险。","k":"题目问正确的，不开灯、警告标50米、车内等都是错的，只能选“来车方向”。","p":"2025081821.jpg","j":""},{"i":9030113,"c":3,"x":1,"y":1,"q":"图中红车不得在此处停放。","o":["正确","错误"],"a":"A","e":"图中红车停在了人行横道线上，属于违法行为。","k":"人行横道上禁止停车，题目说“不得停放”，答对。","p":"2025081822.jpg","j":""},{"i":9030114,"c":3,"x":1,"y":1,"q":"如图所示，A车可以在此处停车。","o":["正确","错误"],"a":"B","e":"图中车辆临时停放的地点在公共汽车站10米以外，是不可以临时停放的。（公交车站30米内不得停车）","k":"站三口五。公交站30米内不能停车，图中车辆停在路口10米答错。","p":"2025090801.jpg","j":""},{"i":9030115,"c":3,"x":1,"y":1,"q":"道路划设专用车道的，只准许规定的车辆通行，其他车辆不得进入。","o":["正确","错误"],"a":"A","e":"专用车道内，其他车辆如果进入可能会影响车道内正常通行，所以规定其他车辆不得进入专用车道内行驶。","k":"题目看到“只准”，直接答正确。","p":"","j":""},{"i":9040003,"c":4,"x":1,"y":2,"q":"以下不属于依法扣留车辆情形的是（ ）。","o":["未携带机动车登记证书","伪造机动车号牌","变造机动车行驶证","未投保机动车交通事故责任强制保险"],"a":"A","e":"使用其他车辆的、伪造、变造机动车登记证书、号牌、行驶证、检验合格标志、保险标志的，交警可以扣留机动车。","k":"题目问不属于，未带登记证书不会被扣车。","p":"","j":""},{"i":9040004,"c":4,"x":1,"y":2,"q":"以下属于依法扣留车辆情形的是（ ）。","o":["连续驾车超过4小时未停车休息","在高速公路低于规定最低时速行驶","驾驶人未按规定系安全带","未投保机动车交通事故责任强制保险"],"a":"D","e":"使用其他车辆的、伪造、变造机动车登记证书、号牌、行驶证、检验合格标志、保险标志的，交警可以扣留机动车。","k":"题目问“扣留车辆”的，答案里出现“号牌”、“驾驶证”、“行驶证”、“检验合格标志”、“保险标志”的，直接选。","p":"","j":""},{"i":9040005,"c":4,"x":1,"y":1,"q":"公路客运车辆载客超过额定乘员的，由公安交管部门扣留机动车至违法状态消除。","o":["正确","错误"],"a":"A","e":"公路客运车辆载客超过额定成员将处二百元以上五百元以下罚款;超过额定乘员百分之二十或者违反规定载货的，处五百元以上二千元以下罚款，由公安机关交通管理部门扣留机动车至违法状态消除。","k":"题目中有‘扣留’的都是对的，只有‘扣留行驶证’和‘未携带身份证’是错的。","p":"","j":""},{"i":9040006,"c":4,"x":1,"y":2,"q":"下列交通违法行为，一次记12分的是（ ）。","o":["驾车不按交通信号灯指示通行的","驾车运载超限的不可解体的物品，未按指示时间、路线行驶的","驾驶小型客车在高速公路上行驶超过规定时速30%的","驾车在高速公路上倒车的"],"a":"D","e":"不按交通信号灯指示通行的扣6分；运载超限的不可解体的物品，未按指示时间、路线行驶的扣6分；小型客车在高速公路上行驶超过规定时速30%的扣6分；在高速公路上倒车的扣12分。","k":"倒车、掉头、逆行没有“以外”的，找12分；有“以外”的，倒车，掉头找1分，逆行找3分。","p":"","j":""},{"i":9040007,"c":4,"x":1,"y":2,"q":"下列交通违法行为，一次记12分的是（ ）。","o":["在高速公路上逆行的","在高速公路上违法停车的","在城市快速路上违法占用应急车道行驶的","行经人行横道不按规定减速、停车、避让行人的"],"a":"A","e":"高速公路逆行会被扣12分；高速公路违法停车会被扣9分；城市快速路占用应急车道会被扣6分；不按规定减速、停车、避让行人的会被扣3分。","k":"倒车、掉头、逆行没有“以外”的，找12分；有“以外”的，倒车、掉头找1分，逆行找3分。","p":"","j":""},{"i":9040008,"c":4,"x":1,"y":1,"q":"饮酒后驾驶车辆，除罚款外，将暂扣驾驶证6个月。","o":["正确","错误"],"a":"A","e":"饮酒驾驶机动车辆，罚款1000元-2000元、记12分并暂扣驾照6个月；饮酒驾驶营运机动车，罚款5000元，记12分，处以15日以下拘留，并且5年内不得重新获得驾照。","k":"常识，饮酒驾车不但会被扣分罚款，还会被暂扣6个月驾驶证。","p":"","j":""},{"i":9040009,"c":4,"x":1,"y":1,"q":"醉酒驾车的，由公安交管部门约束至酒醒，吊销其驾驶证，依法追究刑事责任，5年内不得重新取得驾驶证。","o":["正确","错误"],"a":"A","e":"《道路交通安全法》第九十一条:醉酒驾驶机动车的，由公安机关交通管理部门约束至酒醒，吊销机动车驾驶证，依法追究刑事责任;五年内不得重新取得机动车驾驶证。","k":"题目里看到“追究”的答对，只有“不追究”和“追究10年”的答错。","p":"","j":""},{"i":9040010,"c":4,"x":1,"y":1,"q":"饮酒后不得驾驶机动车。","o":["正确","错误"],"a":"A","e":"开车不喝酒，喝酒不开车，饮酒驾车和醉酒驾车都属于严重的交通违法行为。","k":"在小型车试题里出现“不得”而且没有图片的判断题直接答对。例外情况：与 “只需、小于100米 、120公里 、一天 、精神病， 上高速”同时出现答错 。","p":"","j":""},{"i":9040011,"c":4,"x":1,"y":1,"q":"隐瞒有关情况申领机动车驾驶证的，申请人一年内不得再次申领驾驶证。","o":["正确","错误"],"a":"A","e":"1、隐瞒有关情况或者提供虚假材料申领机动车驾驶证的——罚500元以下，一年内不能申请驾驶证。2、考试过程中贿赂、舞弊行为的，取消考试资格，已通过的科目作废——罚2000元以下，一年内不能申请驾驶证。3、以欺骗、贿赂等不正当手段取得驾驶证的，收缴驾驶证——罚2000元以下，三年内不能申请驾驶证。","k":"在小型车试题里出现“不得”而且没有图片的判断题直接答对。例外情况：与 “只需、小于100米 、120公里 、一天 、精神病， 上高速”同时出现答错 。","p":"","j":""},{"i":9040012,"c":4,"x":1,"y":2,"q":"将机动车交由未取得驾驶证的人驾驶的，除罚款外，可并处（ ）。","o":["拘留","吊销驾驶证","扣留车辆","暂扣驾驶证"],"a":"B","e":"规定：驾驶人将机动车交给驾驶证被吊销的人驾驶的将被处200元以上2000元以下罚款，可以并处吊销机动车驾驶证。","k":"处罚题选项里单独出现“罚款”二字首选，没有的选“吊销”。","p":"","j":""},{"i":9050004,"c":5,"x":1,"y":1,"q":"驾车遇其他车辆发生交通事故受伤者需要抢救时，应予以协助。","o":["正确","错误"],"a":"A","e":"遇其他车辆发生交通事故，要尽可能地将伤害降到最低，及时送伤者去医院。","k":"题目里有“抢救”的，直接答对。","p":"","j":""},{"i":9050005,"c":5,"x":1,"y":1,"q":"发生仅有轻微财产损失的事故可以适用简易处理程序，但有交通肇事、危险驾驶犯罪嫌疑的除外。","o":["正确","错误"],"a":"A","e":"根据《道路交通事故处理程序规定》，公安机关交通管理部门可以适用简易程序处理以下道路交通事故，但有交通肇事、危险驾驶犯罪嫌疑的除外：财产损失事故；受伤当事人伤势轻微，各方当事人一致同意适用简易程序处理的伤人事故。因此，如果交通事故涉及到交通肇事或危险驾驶犯罪嫌疑，就不能使用简易程序处理了。","k":"题目看到“除外”的，直接答正确。","p":"","j":""},{"i":9050007,"c":5,"x":1,"y":1,"q":"如图所示，驾驶车辆撞毁道路隔离护栏后抓紧时间报警。","o":["正确","错误"],"a":"A","e":"撞坏隔离带，属于损坏公共财物，所以需要先报警，由交警队对交通事故责任进行认定。先由保险公司在交强险的范围内承担赔偿责任，超过部分，按照责任比例进行划分。","k":"题目中有“报警”行为的都对。","p":"21244.jpg","j":""},{"i":9050006,"c":6,"x":1,"y":2,"q":"红圈内的符号表示（）。","o":["后风窗玻璃除霜","前风窗玻璃除霜","后风窗玻璃刮水器","前风窗玻璃刮水器"],"a":"D","e":"车的前车窗是（扇形），后车窗是（矩形）。图中红圈处是扇形且有个指针像是车窗上的刮水器，就是前风窗玻璃刮水器。","k":"指针代表刮水，扇形是前窗，矩形（方形）是后窗。","p":"2025070726.jpg","j":""},{"i":9060015,"c":6,"x":1,"y":1,"q":"新能源汽车充电时应选择使用符合国家标准的充电桩。","o":["正确","错误"],"a":"A","e":"新能源汽车充电时，选用符合国家标准的充电桩是安全充电的基本要求。国家标准充电桩经过严格的安全检测，具备过载保护、漏电保护、接地保护等功能，可有效降低充电过程中因设备不合格导致的短路、起火、触电等风险。使用非国标充电桩可能因参数不匹配、保护功能缺失等问题损坏车辆电池，甚至引发安全事故。","k":"符合国家标准的都是对的。","p":"","j":""},{"i":9070001,"c":7,"x":1,"y":2,"q":"以下交通违法行为，一次记12分的是（ ）。","o":["饮酒后驾车的","未取得校车驾驶资格驾驶校车的","驾驶校车在一般城市道路上行驶超过规定时速50%以上的","驾车运输危险化学品，未经批准进入危险化学品运输车辆限制通行区域的"],"a":"A","e":"饮酒后驾车的扣12分；未取得校车驾驶资格驾驶校车的扣9分；驾驶校车在一般城市道路上行驶超过规定时速50%以上的扣9分；驾车运输危险化学品，未经批准进入危险化学品运输车辆限制通行区域的扣6分。","k":"扣12分的：伪、变、代、酒、死、高快超速50%以上、百分之百（口诀：伪变代酒死一生，高速快速路上超速50%以上，百分百会被扣12分。）","p":"","j":""},{"i":9070002,"c":7,"x":1,"y":1,"q":"如图所示，驾驶机动车行驶至有中心黄色虚实线的路段时，可以借用对向车道超越前车。","o":["正确","错误"],"a":"B","e":"图中的中心黄色虚实线，靠近车辆一侧为实线，实线一侧禁止跨越，所以不可借道超车。","k":"判断题里有“借”字的都是错的。（只有和“执行任务”同时出现时答对）","p":"2025071903.jpg","j":""},{"i":9070003,"c":7,"x":1,"y":2,"q":"以下交通违法行为，一次记12分的是（ ）。","o":["驾驶7座以上载客汽车载人超过核定人数50%以上未达到100%的","在高速公路上倒车、逆行的","在高速公路上违法停车的","驾驶旅游客运汽车载人超过核定人数10%的"],"a":"B","e":"驾驶7座以上载客汽车载人超过核定人数50%以上未达到100%的扣9分；在高速公路上倒车、逆行的扣12分；在高速公路上违法停车的扣9分；驾驶旅游客运汽车载人超过核定人数10%的扣6分。","k":"倒车、掉头、逆行没有“以外”的，找12分；有“以外”的，倒车、掉头找1分，逆行找3分。","p":"","j":""},{"i":9070004,"c":7,"x":1,"y":1,"q":"机动车驾驶人驾驶擅自改变已登记的结构、构造的载货汽车上道路行驶的，一次记1分。","o":["正确","错误"],"a":"A","e":"《道路交通安全违法行为记分管理办法》第十二条，机动车驾驶人有下列交通违法行为之一，一次记1分：（八）驾驶擅自改变已登记的结构、构造或者特征的载货汽车上道路行驶的；","k":"“擅自”找1分。","p":"","j":""},{"i":9070005,"c":7,"x":1,"y":2,"q":"以下交通违法行为，一次记12分的是（ ）。","o":["饮酒后驾车的","未取得校车驾驶资格驾驶校车的","驾驶校车在一般城市道路上行驶超过规定时速50%以上的","驾车运输危险化学品，未经批准进入危险化学品运输车辆限制通行区域的"],"a":"A","e":"饮酒后驾车的扣12分；未取得校车驾驶资格驾驶校车的扣9分；驾驶校车在一般城市道路上行驶超过规定时速50%以上的扣9分；驾车运输危险化学品，未经批准进入危险化学品运输车辆限制通行区域的扣6分。","k":"扣12分的：伪、变、代、酒、死、高快超速50%以上、百分之百（口诀：伪变代酒死一生，高速快速路上超速50%以上，百分百会被扣12分。）","p":"","j":""},{"i":9070006,"c":7,"x":1,"y":1,"q":"机动车驾驶人驾驶载货汽车载物超过最大允许总质量50%以上的，一次记6分。","o":["正确","错误"],"a":"A","e":"《道路交通安全违法行为记分管理办法》第十条，机动车驾驶人有下列交通违法行为之一，一次记6分：（四）驾驶载货汽车载物超过最大允许总质量百分之五十以上的；","k":"判断题看到小写“50%\"，答错。“50%以上”，答对。","p":"","j":""},{"i":9070007,"c":7,"x":1,"y":1,"q":"持有大型客车、重型牵引车、城市公交车、中型客车、大型货车驾驶证的驾驶人联系电话、从业单位等信息发生变化未及时申报变更信息的，处20元以上200元以下罚款。","o":["正确","错误"],"a":"A","e":"按照规定，信息变化，就应该去及时登记。未及时变更信息的，公安机关交通管理部门处二十元以上二百元以下罚款。","k":"题目里有“200”或“二百”的都是对的。（只有和“二千”同时出现时答错。）","p":"","j":""},{"i":9070008,"c":7,"x":1,"y":1,"q":"重型牵引挂车、大型货车、大型客车驾驶人在一个记分周期内累积记分满12分的，应当参加为期30天的道路交通安全法律、法规和相关知识学习。","o":["正确","错误"],"a":"A","e":"《道路交通安全违法行为记分管理办法》第十八条，机动车驾驶人在一个记分周期内累积记分满12分的，应当参加为期七天的道路交通安全法律、法规和相关知识学习。其中，大型客车、重型牵引挂车、城市公交车、中型客车、大型货车驾驶人应当参加为期三十天的道路交通安全法律、法规和相关知识学习。","k":"判断题里有“三十天”或“30天”的，直接答正确。","p":"","j":""},{"i":9070009,"c":7,"x":1,"y":1,"q":"机动车驾驶人驾驶未按规定定期进行安全技术检验的危险物品运输车辆上道路行驶的，一次记3分。","o":["正确","错误"],"a":"A","e":"《道路交通安全违法行为记分管理办法》第十一条机动车驾驶人有下列交通违法行为之一，一次记3分：（十二）驾驶未按规定定期进行安全技术检验的公路客运汽车、旅游客运汽车、危险物品运输车辆上道路行驶的；","k":"扣分题：看到“检验”、“检查”，找3分；“检验……以外”找1分。","p":"","j":""},{"i":9070010,"c":7,"x":1,"y":1,"q":"驾驶校车上道路行驶前，未对校车车况是否符合安全技术要求进行检查的，一次记3分。","o":["正确","错误"],"a":"A","e":"道路交通安全违法行为记分管理办法》第十一条，机动车驾驶人有下列交通违法行为之一，一次记3分：（十三）驾驶校车上道路行驶前，未对校车车况是否符合安全技术要求进行检查，或者驾驶存在安全隐患的校车上道路行驶的；","k":"扣分题：看到“检验”、“检查”，找3分；“检验……以外”找1分。","p":"","j":""},{"i":9070011,"c":7,"x":1,"y":2,"q":"驾驶机动车在高速公路出口时，以下说法正确的是什么？","o":["白色导流线处可以临时停车休息","不确定出口时应立即停车确认","此时可以超越前方车辆","进入匝道应提前减速"],"a":"D","e":"在图中这种高速出口，应提前减速，确定好方向后，从虚线处驶入匝道。禁止停车休息和超车。","k":"答案里有“提前减速”的，直接选。","p":"2025071902.jpg","j":""},{"i":9070012,"c":7,"x":1,"y":2,"q":"机动车驾驶人驾驶危险物品运输车在一般城市道路上行驶超过规定时速20%以上未达到50%的，一次记（ ）分。","o":["3","6","9","12"],"a":"B","e":"《道路交通安全违法行为记分管理办法》第十条，机动车驾驶人有下列交通违法行为之一，一次记6分：（二）驾驶校车、中型以上载客载货汽车、危险物品运输车辆在高速公路、城市快速路上行驶超过规定时速未达到百分之二十，或者在高速公路、城市快速路以外的道路上行驶超过规定时速百分之二十以上未达到百分之五十的；","k":"题目中看到“五十”或者“50%”，答案找“6分”。","p":"","j":""},{"i":9070013,"c":7,"x":1,"y":1,"q":"运输危险化学品，未经批准进入危险化学品运输车辆限制通行的区域的，一次记6分。","o":["正确","错误"],"a":"A","e":"《道路交通安全违法行为记分管理办法》第十条，机动车驾驶人有下列交通违法行为之一，一次记6分：（七）驾驶机动车运输危险化学品，未经批准进入危险化学品运输车辆限制通行的区域的；","k":"题目里看到“物品”、“化学品”的，找“6分”。","p":"","j":""},{"i":9070014,"c":7,"x":1,"y":1,"q":"驾驶人在实习期内可以驾驶大型营运客车。","o":["正确","错误"],"a":"B","e":"机动车驾驶人在实习期内不得驾驶公共汽车、营运客车或者执行任务的警车、消防车、救护车、工程救险车以及载有爆炸物品、易燃易爆化学物品、剧毒或者放射性等危险物品的机动车；","k":"“实习期……可以”的答错；“实习期……不可以” 的答对。","p":"","j":""},{"i":9080001,"c":8,"x":1,"y":1,"q":"如图所示，驾驶机动车行驶至有中心黄色虚实线的路段时，可以借用对向车道超越前车。","o":["正确","错误"],"a":"B","e":"图中的中心黄色虚实线，靠近车辆一侧为实线，实线一侧禁止跨越，所以不可借道超车。","k":"判断题里有“借”字的都是错的。（只有和“执行任务”同时出现时答对）","p":"2025071903.jpg","j":""},{"i":9080002,"c":8,"x":1,"y":1,"q":"图中标志的含义是禁止小型载客汽车驶入。","o":["正确","错误"],"a":"B","e":"禁止大型客车驶入：表示前方路段禁止大型客车驶入。","k":"图中是大客车，题目说小型客车，不一致答错。","p":"2023051574065.jpg","j":""},{"i":9080003,"c":8,"x":1,"y":2,"q":"以下交通违法行为，一次记12分的是（ ）。","o":["驾驶7座以上载客汽车载人超过核定人数50%以上未达到100%的","在高速公路上倒车、逆行的","在高速公路上违法停车的","驾驶旅游客运汽车载人超过核定人数10%的"],"a":"B","e":"驾驶7座以上载客汽车载人超过核定人数50%以上未达到100%的扣9分；在高速公路上倒车、逆行的扣12分；在高速公路上违法停车的扣9分；驾驶旅游客运汽车载人超过核定人数10%的扣6分。","k":"倒车、掉头、逆行没有“以外”的，找12分；有“以外”的，倒车、掉头找1分，逆行找3分。","p":"","j":""},{"i":9080004,"c":8,"x":1,"y":1,"q":"机动车驾驶人驾驶擅自改变已登记的结构、构造的载货汽车上道路行驶的，一次记1分。","o":["正确","错误"],"a":"A","e":"《道路交通安全违法行为记分管理办法》第十二条，机动车驾驶人有下列交通违法行为之一，一次记1分：（八）驾驶擅自改变已登记的结构、构造或者特征的载货汽车上道路行驶的；","k":"“擅自”找1分。","p":"","j":""},{"i":9080005,"c":8,"x":1,"y":2,"q":"以下交通违法行为，一次记12分的是（ ）。","o":["饮酒后驾车的","未取得校车驾驶资格驾驶校车的","驾驶校车在一般城市道路上行驶超过规定时速50%以上的","驾车运输危险化学品，未经批准进入危险化学品运输车辆限制通行区域的"],"a":"A","e":"饮酒后驾车的扣12分；未取得校车驾驶资格驾驶校车的扣9分；驾驶校车在一般城市道路上行驶超过规定时速50%以上的扣9分；驾车运输危险化学品，未经批准进入危险化学品运输车辆限制通行区域的扣6分。","k":"扣12分的：伪、变、代、酒、死、高快超速50%以上、百分之百（口诀：伪变代酒死一生，高速快速路上超速50%以上，百分百会被扣12分。）","p":"","j":""},{"i":9080006,"c":8,"x":1,"y":1,"q":"机动车驾驶人驾驶载货汽车载物超过最大允许总质量50%以上的，一次记6分。","o":["正确","错误"],"a":"A","e":"《道路交通安全违法行为记分管理办法》第十条，机动车驾驶人有下列交通违法行为之一，一次记6分：（四）驾驶载货汽车载物超过最大允许总质量百分之五十以上的；","k":"判断题看到小写“50%\"，答错。“50%以上”，答对。","p":"","j":""},{"i":9080007,"c":8,"x":1,"y":1,"q":"持有大型客车、重型牵引车、城市公交车、中型客车、大型货车驾驶证的驾驶人联系电话、从业单位等信息发生变化未及时申报变更信息的，处20元以上200元以下罚款。","o":["正确","错误"],"a":"A","e":"按照规定，信息变化，就应该去及时登记。未及时变更信息的，公安机关交通管理部门处二十元以上二百元以下罚款。","k":"题目里有“200”或“二百”的都是对的。（只有和“二千”同时出现时答错。）","p":"","j":""},{"i":9080008,"c":8,"x":1,"y":1,"q":"重型牵引挂车、大型货车、大型客车驾驶人在一个记分周期内累积记分满12分的，应当参加为期30天的道路交通安全法律、法规和相关知识学习。","o":["正确","错误"],"a":"A","e":"《道路交通安全违法行为记分管理办法》第十八条，机动车驾驶人在一个记分周期内累积记分满12分的，应当参加为期七天的道路交通安全法律、法规和相关知识学习。其中，大型客车、重型牵引挂车、城市公交车、中型客车、大型货车驾驶人应当参加为期三十天的道路交通安全法律、法规和相关知识学习。","k":"判断题里有“三十天”或“30天”的，直接答正确。","p":"","j":""},{"i":9080009,"c":8,"x":1,"y":1,"q":"在造成人员死亡的交通事故中承担主要责任的，不得申请增加大型货车、重型牵引挂车、城市公交车准驾车型。","o":["正确","错误"],"a":"A","e":"有下列情形之一的，不得申请大型客车、重型牵引挂车、城市公交车、中型客车、大型货车准驾车型：（一）发生交通事故造成人员死亡，承担同等以上责任的；","k":"题目看到“不得申请”，直接答正确。（只有与“但可以”同时出现答错。）","p":"","j":""},{"i":9080010,"c":8,"x":1,"y":1,"q":"机动车驾驶人驾驶未按规定定期进行安全技术检验的危险物品运输车辆上道路行驶的，一次记3分。","o":["正确","错误"],"a":"A","e":"《道路交通安全违法行为记分管理办法》第十一条机动车驾驶人有下列交通违法行为之一，一次记3分：（十二）驾驶未按规定定期进行安全技术检验的公路客运汽车、旅游客运汽车、危险物品运输车辆上道路行驶的；","k":"扣分题：看到“检验”、“检查”，找3分；“检验……以外”找1分。","p":"","j":""},{"i":9080011,"c":8,"x":1,"y":1,"q":"驾驶校车上道路行驶前，未对校车车况是否符合安全技术要求进行检查的，一次记3分。","o":["正确","错误"],"a":"A","e":"《道路交通安全违法行为记分管理办法》第十一条，机动车驾驶人有下列交通违法行为之一，一次记3分：（十三）驾驶校车上道路行驶前，未对校车车况是否符合安全技术要求进行检查，或者驾驶存在安全隐患的校车上道路行驶的；","k":"扣分题：看到“检验”、“检查”，找3分；“检验……以外”找1分。","p":"","j":""},{"i":9080012,"c":8,"x":1,"y":2,"q":"驾驶重型、中型载货汽车，半挂车载物，高度从地面起不得超过多少米？","o":["3","4","5","6"],"a":"B","e":"重型、中型载货汽车，半挂车载物，高度从地面起不得超过4米，载运集装箱的车辆不得超过4.2米。","k":"关于高度的题，“载物”找栏板，没有的找4米；“集装箱”找4.2米。","p":"","j":""},{"i":9080013,"c":8,"x":1,"y":2,"q":"驾驶机动车在高速公路出口时，以下说法正确的是什么？","o":["白色导流线处可以临时停车休息","不确定出口时应立即停车确认","此时可以超越前方车辆","进入匝道应提前减速"],"a":"D","e":"在图中这种高速出口，应提前减速，确定好方向后，从虚线处驶入匝道。禁止停车休息和超车。","k":"答案里有“提前减速”的，直接选。","p":"2025071902.jpg","j":""},{"i":9080014,"c":8,"x":1,"y":2,"q":"机动车驾驶人驾驶危险物品运输车在一般城市道路上行驶超过规定时速20%以上未达到50%的，一次记（ ）分。","o":["3","6","9","12"],"a":"B","e":"《道路交通安全违法行为记分管理办法》第十条，机动车驾驶人有下列交通违法行为之一，一次记6分：（二）驾驶校车、中型以上载客载货汽车、危险物品运输车辆在高速公路、城市快速路上行驶超过规定时速未达到百分之二十，或者在高速公路、城市快速路以外的道路上行驶超过规定时速百分之二十以上未达到百分之五十的；","k":"题目中看到“五十”或者“50%”，答案找“6分”。","p":"","j":""},{"i":9080015,"c":8,"x":1,"y":1,"q":"重型牵引挂车、大型货车、大型客车驾驶人在一个记分周期内参加满分教育的次数每增加一次，道路交通安全法律、法规和相关知识的学习时间增加30天，每次满分学习的天数最多120天。","o":["正确","错误"],"a":"A","e":"《道路交通安全违法行为记分管理办法》第十八条，机动车驾驶人在一个记分周期内参加满分教育的次数每增加一次或者累积记分每增加12分，道路交通安全法律、法规和相关知识的学习时间增加七天，每次满分学习的天数最多六十天。其中，大型客车、重型牵引挂车、城市公交车、中型客车、大型货车驾驶人在一个记分周期内参加满分教育的次数每增加一次或者累积记分每增加12分，道路交通安全法律、法规和相关知识的学习时间增加三十天，每次满分学习的天数最多一百二十天。","k":"判断题里有“三十天”或“30天”的，直接答正确。","p":"","j":""},{"i":9080016,"c":8,"x":1,"y":1,"q":"运输危险化学品，未经批准进入危险化学品运输车辆限制通行的区域的，一次记6分。","o":["正确","错误"],"a":"A","e":"《道路交通安全违法行为记分管理办法》第十条，机动车驾驶人有下列交通违法行为之一，一次记6分：（七）驾驶机动车运输危险化学品，未经批准进入危险化学品运输车辆限制通行的区域的；","k":"题目里看到“物品”、“化学品”的，找“6分”。","p":"","j":""},{"i":9080017,"c":8,"x":1,"y":1,"q":"驾驶人在实习期内可以驾驶大型营运客车。","o":["正确","错误"],"a":"B","e":"机动车驾驶人在实习期内不得驾驶公共汽车、营运客车或者执行任务的警车、消防车、救护车、工程救险车以及载有爆炸物品、易燃易爆化学物品、剧毒或者放射性等危险物品的机动车；","k":"“实习期……可以”的答错；“实习期……不可以” 的答对。","p":"","j":""},{"i":9080018,"c":8,"x":1,"y":1,"q":"醉酒驾驶营运机动车，被吊销驾驶证的，重新取得驾驶证后，不得驾驶营运机动车。","o":["正确","错误"],"a":"A","e":"根据《中华人民共和国道路交通安全法》第九十一条规定，醉酒驾驶营运机动车的，由公安机关交通管理部门约束至酒醒，吊销机动车驾驶证，依法追究刑事责任；十年内不得重新取得机动车驾驶证，重新取得机动车驾驶证后，不得驾驶营运机动车。","k":"判断题看到“吊销”都是对的，只有和“90日”同时出现时答错。","p":"","j":""},{"i":900023,"c":9,"x":1,"y":2,"q":"以下交通标志中表示注意落石的是（ ）。","o":["图3","图1","图2","图4"],"a":"C","e":"图1是村庄或集镇；图2是注意落石；图3是隧道；图4是傍山险路","k":"题目问“注意落石”，找图中有“落石”的。","p":"MT2025061201.jpg","j":""},{"i":900024,"c":9,"x":1,"y":2,"q":"图中红色圈内的交通标线表示减速让行线的是（ ）。","o":["图4","图3","图2","图1"],"a":"C","e":"图1是停止线；图2是减速让行线；图3是人行横道线；图4是停车让行线。","k":"题目问“减速让行线”，找图中有“让”字的。","p":"MT2025062501.jpg","j":""},{"i":900025,"c":9,"x":1,"y":2,"q":"图中红色圈内的交通标线表示停车让行线的是（ ）。","o":["图2","图1","图3","图4"],"a":"D","e":"图1是停止线；图2是减速让行线；图3是人行横道线；图4是停车让行线。","k":"题目问“停车让行线”，找图中有“停”字的。","p":"MT2025062501.jpg","j":""},{"i":900026,"c":9,"x":1,"y":2,"q":"图中红色圈内的交通标线表示停止线的是（ ）。","o":["图2","图4","图1","图3"],"a":"C","e":"图1是停止线；图2是减速让行线；图3是人行横道线；图4是停车让行线。","k":"题目问“停止线”，找图中红圈内是横着的“单实线”。","p":"MT2025062501.jpg","j":""},{"i":900027,"c":9,"x":1,"y":2,"q":"图中红色圈内的交通标线允许车辆跨越行驶的是（ ）。","o":["图4","图2","图3","图1"],"a":"B","e":"图1和图3都是双黄实线，禁止跨越；图2是虚线，可以跨越；图4是单实线，禁止跨越。","k":"虚可实禁。题目问“允许车辆跨越”，找图中红圈内是“虚线”的。","p":"MT2025062502.jpg","j":""},{"i":900028,"c":9,"x":1,"y":2,"q":"以下交通标志中表示前方为连续下坡的是（ ）。","o":["图4","图3","图2","图1"],"a":"D","e":"图1是连续下坡；图2是窄路；图3是窄桥；图4是连续弯路。","k":"题目问“连续下坡”，找图中有两个向下的箭头的。","p":"MT2025061206.jpg","j":""},{"i":900029,"c":9,"x":1,"y":2,"q":"以下交通标志中表示前方有反向弯路的是（ ）。","o":["图3","图4","图2","图1"],"a":"B","e":"图1是上陡坡；图2是向左急转弯；图3是十字交叉路口；图4是反向弯路。","k":"题目问“反向弯路”，找图中有“Z”字型的（谐音：反贼）。","p":"MT2025061207.jpg","j":""},{"i":900030,"c":9,"x":1,"y":2,"q":"以下交通标志中表示禁止摩托车行驶的是（ ）。","o":["图1","图3","图2","图4"],"a":"B","e":"图1是禁止人力客运三轮车进入；图2是禁止三轮车驶入；图3是禁止摩托车驶入；图4是禁止电动自行车进入。","k":"题目问“摩托车”，找图中有人骑摩托车的。","p":"MT2025061208.jpg","j":""},{"i":900031,"c":9,"x":1,"y":2,"q":"以下交通标志中表示禁止超车的是（ ）。","o":["图2","图1","图3","图4"],"a":"B","e":"图1是禁止超车；图2是禁止驶入；图3是禁止通行；图4是禁止直行和向右转弯。","k":"题目问“禁止超车”，找图中有一个箭头超过另一个箭头的。","p":"MT2025061203.jpg","j":""},{"i":900032,"c":9,"x":1,"y":2,"q":"以下交通标志中表示该车道仅供公交车辆、通勤班车等大型载客汽车通行的是（ ）。","o":["图2","图1","图4","图3"],"a":"B","e":"图1是公交线路专用车道；图2是小型载客汽车车道；图3是机动车车道；图4是非机动车车道。","k":"题目中有“公交”，找图中有公交的。","p":"MT2025061209.jpg","j":""},{"i":900033,"c":9,"x":1,"y":2,"q":"以下交通标志中表示该路段仅供行人步行，任何车辆不准进入的是（ ）。","o":["图4","图3","图2","图1"],"a":"C","e":"图1是施工；图2是行人步行；图3是应急避难设施；图4是注意行人。","k":"题目问“行人步行”，找圆形图中只有一个人的。","p":"MT2025061210.jpg","j":""},{"i":900034,"c":9,"x":1,"y":2,"q":"以下交通标志中表示注意儿童的是（ ）。","o":["图3","图2","图4","图1"],"a":"A","e":"图1是注意行人；图2是注意残疾人；图3是注意儿童；图4是施工。","k":"题目问“注意儿童”，找图中有两个小孩的。","p":"MT2025061211.jpg","j":""},{"i":900035,"c":9,"x":1,"y":2,"q":"以下交通标志中表示注意前方路段设有减速丘的是（ ）。","o":["图2","图4","图1","图3"],"a":"A","e":"图1是隧道；图2是减速丘；图3是驼峰桥；图4是有人看守铁路道口。","k":"题目问“减速丘”，找图中有“凸起”且没有洞的。","p":"MT2025061212.jpg","j":""},{"i":900036,"c":9,"x":1,"y":2,"q":"这个标志是何含义？","o":["禁止在路口掉头","禁止向左和向右转弯","禁止车辆直行","禁止向左向右变道"],"a":"B","e":"图中标志为：禁止向左和向右转弯。表示前方路口禁止一切车辆向左向右转弯。","k":"标志里有两个转弯的箭头，答案就找“转弯”。","p":"2023051574010.jpg","j":""},{"i":100518,"c":10,"x":1,"y":1,"q":"在江苏省内机动车交通事故视频快处，可以通过“交管12123”APP或“江苏交警”微信公众号操作。","o":["正确","错误","仅适用于高速公路的事故处理模式","现场交警处理的事故快处方式"],"a":"A","e":"轻微道路交通事故视频快处”操作步骤：（1）如何报警方法一：通过“江苏交警”微信公众号或者各地公安交管部门微信公众号点击“视频快处”；方法二：手机下载“交管12123”APP，点击“事故视频快处”；方法三：拨打110报警后，点击110推送的视频报警短信链接。","k":"","p":"","j":""},{"i":100519,"c":10,"x":1,"y":1,"q":"“轻微道路交通事故视频快处”报警视频接入后，现场取证应由后台坐席操作。","o":["正确","错误"],"a":"A","e":"轻微道路交通事故视频快处”操作步骤：（2）报警视频接入后如何操作报警接通后，后台座席人员会与当事人视频通话协助开展调查取证。在处理过程中，当事人只需手持手机切换前后摄像头，现场配合取证即可，所有取证均由坐席人员操作。远程调查取证接收后，民警在远端完成事故定责，并通过手机短信告知当事人。","k":"","p":"","j":""},{"i":100520,"c":10,"x":1,"y":2,"q":"事故视频快处的处理时间一般为？","o":["仅限白天晴天","每天7：00—19：00","全天24小时","工作日7：00—19：00"],"a":"B","e":"“轻微道路交通事故视频快处”方式处理交通事故时间是每天7时至19时。","k":"","p":"","j":""},{"i":100521,"c":10,"x":1,"y":2,"q":"视频快处中，后台坐席认定事故责任后，当事人应在多久内完成定损理赔？","o":["3日内","7日内","无时间限制","24小时内"],"a":"B","e":"新规要求，责任认定后需在7日内完成定损理赔，逾期可能影响处理效率。","k":"","p":"","j":""},{"i":100522,"c":10,"x":1,"y":1,"q":"“轻微道路交通事故视频快处”需要事故双方当事人同时到交警大队现场处理才能完成调查取证定责。","o":["正确","错误"],"a":"B","e":"“轻微道路交通事故视频快处” 是“交管12123”APP事故处理业务单元中新增模块，是基于视频通话服务研发的事故视频远程快处系统。事故任何一方当事人只需一键报警，建立视频“线上见面”配合现场取证即可完成交通事故调查取证定责。","k":"","p":"","j":""},{"i":100523,"c":10,"x":1,"y":2,"q":"当事人发起视频快处后，因特殊情况需取消申请，正确的做法是？","o":["拨打122说明情况","等待系统自动取消","通过原申请渠道提交取消申请","直接驶离现场即可"],"a":"C","e":"官方规定，取消视频快处申请需通过原发起渠道（如交管12123APP）提交，确保流程可追溯。","k":"","p":"","j":""},{"i":100524,"c":10,"x":1,"y":1,"q":"机动车与非机动车发生仅造成车辆损失和人员轻微伤，且非机动车方承担事故责任的，可适用“轻微道路交通事故视频快处”。","o":["正确","错误"],"a":"B","e":"在驾驶人及车辆证件合法有效，机动车投保交通事故责任强制保险，驾驶人无饮酒、吸毒、逃逸等严重违法行为的情况下，发生下列交通事故：（1）机动车与机动车发生仅造成车辆损失的道路交通事故，且当事人能够自行移动车辆的；（2）机动车与非机动车（行人）发生仅造成车辆损失和人员轻微伤的，机动车方应当承担事故责任的；（3）机动车发生单方事故造成他方财产损失，有物损负责人在现场的。","k":"","p":"","j":""},{"i":100525,"c":10,"x":1,"y":2,"q":"以下哪些区域可以适用“轻微道路交通事故视频快处”？","o":["省内城市道路","省外郊区道路","高速公路","高架公路"],"a":"A","e":"省内全部城市道路、国省道普通公路和县乡道路可以适用“轻微道路交通事故视频快处”。高速公路、高架道路根据所在设区市实际情况视情推广应用。","k":"","p":"","j":""},{"i":100526,"c":10,"x":1,"y":1,"q":"“轻微道路交通事故视频快处”是基于视频通话服务研发的事故视频远程快处系统。事故任何一方当事人只需一键报警，建立视频“线上见面”配合现场取证即可完成交通事故调查取证定责。","o":["正确","错误"],"a":"A","e":"“轻微道路交通事故视频快处” 是“交管12123”APP事故处理业务单元中新增模块，是基于视频通话服务研发的事故视频远程快处系统。事故任何一方当事人只需一键报警，建立视频“线上见面”配合现场取证即可完成交通事故调查取证定责。","k":"","p":"","j":""},{"i":100527,"c":10,"x":1,"y":2,"q":"在驾驶人及车辆证件合法有效等前提下，下列哪种事故不适合用“轻微道路交通事故视频快处”？","o":["机动车与机动车发生仅造成车辆损失的，且当事人能够自行移动车辆的事故","机动车发生单方事故造成他方财产损失的，且有物损负责人在现场的事故","机动车与机动车发生仅造成车辆损失的，且当事人能够自行移动车辆的事故，但驾驶人存在饮酒的行为","机动车与非机动车（行人）发生仅造成车辆损失和人员轻微伤的，机动车方应当承担事故责任的事故"],"a":"C","e":"在驾驶人及车辆证件合法有效，机动车投保交通事故责任强制保险，驾驶人无饮酒、吸毒、逃逸等严重违法行为的情况下，发生下列交通事故：（1）机动车与机动车发生仅造成车辆损失的道路交通事故，且当事人能够自行移动车辆的；（2）机动车与非机动车（行人）发生仅造成车辆损失和人员轻微伤的，机动车方应当承担事故责任的；（3）机动车发生单方事故造成他方财产损失，有物损负责人在现场的。","k":"","p":"","j":""},{"i":100528,"c":10,"x":1,"y":1,"q":"仅造成车辆轻微剐蹭，且双方对责任无争议的事故，不可使用视频快处。","o":["正确","错误"],"a":"B","e":"新规明确，此类轻微且责任无争议的事故属于视频快处适用范围。","k":"","p":"","j":""},{"i":100529,"c":10,"x":1,"y":2,"q":"以下哪类区域不必然适用“轻微道路交通事故视频快处”？","o":["省内城市道路","国省道普通公路","高速公路","县乡道路"],"a":"C","e":"省内全部城市道路、国省道普通公路和县乡道路可以适用“轻微道路交通事故视频快处”。高速公路、高架道路根据所在设区市实际情况视情推广应用。","k":"","p":"","j":""},{"i":100530,"c":10,"x":1,"y":2,"q":"事故视频快处过程中，当事人需提供的基本信息应是（ ）。","o":["车辆购买价格","家庭住址，工作单位","身份证号，车牌号，联系方式","以上都是"],"a":"C","e":"事故视频快处需要提供当事人的身份证号，车牌号，联系方式。","k":"","p":"","j":""},{"i":100531,"c":10,"x":1,"y":2,"q":"事故视频快处时，当事人应站在哪里进行视频通话（ ）。","o":["必须站在车辆前方","确保自身安全的地方","必须站在道路中间","必须站在车辆后方"],"a":"B","e":"处理事故时，应首先保证自己的安全，所以应站在能确保自身安全的地方。","k":"","p":"","j":""},{"i":100532,"c":10,"x":1,"y":1,"q":"事故中有人员伤亡、无牌（含临牌）或无证或无本市保单、涉酒涉毒，车辆无法移动情形之一的，不适合“快处易赔”。","o":["正确","错误"],"a":"A","e":"下列4种情形不适用“快处易赔”：1、交通事故中有人员伤亡；2、无牌（含临牌）或无证或无本市保单；3、涉酒涉毒；4、车辆无法移动的。","k":"","p":"","j":""},{"i":100533,"c":10,"x":1,"y":1,"q":"事故视频快处受理时间全国统一为24小时。","o":["正确","错误"],"a":"B","e":"各省因作息差异受理时间会有差异，江苏省的“轻微道路交通事故视频快处”方式处理交通事故时间是每天7时至19时。","k":"","p":"","j":""},{"i":100534,"c":10,"x":1,"y":2,"q":"事故视频快处的主要目的是（ ）。","o":["提高处理效率","降低处罚力度","减少保险理赔","增加监控设备"],"a":"A","e":"事故视频快处是为了提高处理事故的效率。","k":"","p":"","j":""},{"i":100535,"c":10,"x":1,"y":1,"q":"通过“轻微道路交通事故视频快处”报警后，当事人可以通过“交管12123”APP【网办进度】查看事故处理进度、事故责任及电子文书。","o":["正确","错误"],"a":"A","e":"轻微道路交通事故视频快处”操作步骤：（3）如何查看事故处理流程，领取电子责任认定书。当事人可以通过“交管12123”APP【网办进度】查看事故处理进度、事故责任及电子文书。","k":"","p":"","j":""},{"i":100536,"c":10,"x":1,"y":1,"q":"通过“轻微道路交通事故视频快处”交通事故，在完成信息采集后，当事人应即刻撤离。","o":["正确","错误"],"a":"A","e":"事故发生后，当事人在事故现场需要立即开启车辆双闪灯，在后方来车方向放好三角警告牌做好警示提醒，防止发生二次事故。在完成信息采集后，当事人即刻撤离，避免造成大面积交通拥堵。","k":"","p":"","j":""},{"i":100537,"c":10,"x":1,"y":2,"q":"以下哪种天气条件下，轻微事故不建议使用视频快处？","o":["阴天","晴天","小雨","能见度不足50米的雾天"],"a":"D","e":"浓雾等低能见度天气可能会影响现场拍摄清晰度，官方建议此类情况优先报警等待现场处理。","k":"","p":"","j":""},{"i":100538,"c":10,"x":1,"y":1,"q":"视频快处的电子认定书与纸质认定书具有同等法律效力。","o":["正确","错误"],"a":"A","e":"电子认定书经系统签章后，与纸质版具有同等法律效力，可用于保险理赔。","k":"","p":"","j":""},{"i":100539,"c":10,"x":1,"y":1,"q":"现场急救应遵循先止后包、先重后轻、先救后送等原则。","o":["正确","错误"],"a":"A","e":"现场急救应遵循先止后包、先重后轻、先救后送等原则。","k":"","p":"","j":""},{"i":100540,"c":10,"x":1,"y":2,"q":"呼吸、心跳停止后，急救的黄金时间是多久？","o":["3分钟","4分钟","5分钟","6分钟"],"a":"B","e":"呼吸、心脏骤停后，急救越早，存活率越高，医学上急救黄金时间为4分钟。","k":"","p":"","j":""},{"i":100541,"c":10,"x":1,"y":2,"q":"最快、最简单地判断昏迷伤员是否心脏骤停的指标是（ ）。","o":["无意识并且摸不到脉搏","检查是否有呼吸","血压很低","瞳孔变得散大"],"a":"A","e":"简单而迅速地确定心脏骤停的指标是病人意识消失，无大动脉搏动，不能仅凭呼吸停止、瞳孔散大等症状判断。","k":"","p":"","j":""},{"i":100542,"c":10,"x":1,"y":2,"q":"遇有昏迷不醒，没心跳没呼吸的人，应当立即（ ）。","o":["掐人中使其清醒","扇耳光使其清醒","就地实施心肺复苏","大声呼叫引起周围人员注意"],"a":"C","e":"呼吸、心脏骤停后，急救越早，存活率越高，医学上急救黄金时间为4分钟。对心跳、呼吸停止的伤员，应就地实施心肺复苏。","k":"","p":"","j":""},{"i":100543,"c":10,"x":1,"y":2,"q":"对成人实施胸外心脏按压时，正确的按压位置是？","o":["胸骨上段","胸骨中段","胸骨中下1/3交界处","心前区"],"a":"C","e":"成人心肺复苏时，胸外心脏按压的正确位置是胸骨中下1/3交界处，按压的深度至少5厘米，按压频率为每分钟100-120次，按压中断时间应尽可能控制在10秒以内。","k":"","p":"","j":""},{"i":100544,"c":10,"x":1,"y":2,"q":"成人心肺复苏时，胸外心脏按压与人工呼吸的配合比例是（ ）。","o":["15∶2","5∶1","30∶2","20∶3"],"a":"C","e":"心脏按压与人工呼吸配合同时进行时，使用的按压与通气的比例为30:2。","k":"","p":"","j":""},{"i":100545,"c":10,"x":1,"y":2,"q":"成人心肺复苏时，打开气道最常用的方法是什么？","o":["仰头举颏法","仰头抬颈法","低头抬颏法","双手托颌法"],"a":"A","e":"成人心肺复苏时打开气道的最常用方式是仰头举颏法。这种操作方法是抢救者将一手掌小拇指侧置于患者前额，然后下压使其头部后仰，另一手的食指和中指置于靠近颏部的下颌骨下方，将颏部向前抬起，帮助患者头部后仰，将其气道开放。","k":"","p":"","j":""},{"i":100546,"c":10,"x":1,"y":2,"q":"成人心肺复苏时，胸外心脏按压的频率应为每分钟多少次？","o":["80—100次","100—120次","60—80次","120—140次"],"a":"B","e":"成人心肺复苏时，胸外心脏按压的正确位置是胸骨中下1/3交界处，按压的深度至少5厘米，按压频率为每分钟100-120次，按压中断时间应尽可能控制在10秒以内。","k":"","p":"","j":""},{"i":100547,"c":10,"x":1,"y":2,"q":"成人心肺复苏时，胸外按压的深度至少应为多少？","o":["9厘米","3厘米","5厘米","7厘米"],"a":"C","e":"成人心肺复苏时，胸外心脏按压的正确位置是胸骨中下1/3交界处，按压的深度至少5厘米，按压频率为每分钟100-120次，按压中断时间应尽可能控制在10秒以内。","k":"","p":"","j":""},{"i":100548,"c":10,"x":1,"y":2,"q":"对1岁至青春期的儿童实施心肺复苏时，胸外按压的深度应为多少？","o":["约2厘米","约3厘米","约5厘米（胸廓厚度1/3）","约7厘米"],"a":"C","e":"儿童心肺复苏时，1岁至青春期儿童按压深度为胸廓厚度的1/3（约5厘米），1岁以下婴儿按压深度应为4厘米。","k":"","p":"","j":""},{"i":100549,"c":10,"x":1,"y":2,"q":"对1岁以下的婴儿实施心肺复苏时，胸外按压的深度应为多少？","o":["约2厘米","约4厘米","约5厘米（胸廓厚度1/3）","约6厘米"],"a":"B","e":"儿童心肺复苏时，1岁至青春期儿童按压深度为胸廓厚度的1/3（约5厘米），1岁以下婴儿按压深度应为5厘米。","k":"","p":"","j":""},{"i":100550,"c":10,"x":1,"y":1,"q":"包扎止血时，可以使用麻绳代替止血带。","o":["正确","错误"],"a":"B","e":"包扎止血法可以采用绷带、三角巾、止血带等物品，不能使用麻绳包扎。加压包扎止血法，主要用于四肢损伤时的较小血管出血或渗血。","k":"","p":"","j":""},{"i":100551,"c":10,"x":1,"y":1,"q":"在对儿童（婴儿）实施心肺复苏时，胸外按压深度与成人一致。","o":["正确","错误"],"a":"B","e":"成人心肺复苏时，胸外心脏按压的正确位置是胸骨中下1/3交界处，按压的深度至少5厘米；儿童心肺复苏时，1岁至青春期儿童按压深度为胸廓厚度的1/3（约5厘米），1岁以下婴儿按压深度应为4厘米。","k":"","p":"","j":""},{"i":100552,"c":10,"x":1,"y":1,"q":"固定四肢骨折时，应将趾指末端露出，以便观察血液循环情况。","o":["正确","错误"],"a":"A","e":"四肢骨折的病人，固定时应将趾指末端露出，通过观察趾指末端的颜色、温度和肿胀情况，及时判断肢体血液循环情况。","k":"","p":"","j":""},{"i":100553,"c":10,"x":1,"y":1,"q":"对脊柱损伤的伤员，可以让其尝试站起或坐立，以检查伤情。","o":["正确","错误"],"a":"B","e":"救护员在现场对伤病员进行救护之前，首先要考虑现场环境是否安全。对意识不清的伤病员，检查脉搏常用颈动脉；对伤员鼻出血，应先给与干净布擦血；对疑似颈椎骨折时，尽量不移动伤病员，拨打急救电话；对异物插入体内的，现场不能拔除异物,应采取简单固定包扎措施后送往医院。","k":"","p":"","j":""},{"i":100554,"c":10,"x":1,"y":2,"q":"搬运昏迷或有呕吐风险的伤员时，应采取何种体位？","o":["平卧位","俯卧位","侧卧位，头偏向一侧","坐位"],"a":"C","e":"搬运昏迷伤员时应采取侧卧位，头偏向一侧；搬运昏迷患者时，应采取平卧位头偏向一侧，侧卧位防止误吸。","k":"","p":"","j":""},{"i":100555,"c":10,"x":1,"y":1,"q":"骨折固定时，夹板或绷带只需固定骨折处即可。","o":["正确","错误"],"a":"B","e":"骨折固定时，应超过骨折处的上、下关节。","k":"","p":"","j":""},{"i":100556,"c":10,"x":1,"y":2,"q":"伤病员同时出现心跳骤停和骨折时，应遵循什么原则？","o":["先救命后治伤","先固定后救命","同时进行","等待专业医护人员"],"a":"A","e":"伤病员心跳、呼吸骤停同时又伴有骨折时，应遵循先救命后治伤的原则，采取先心肺复苏术，后固定骨折的顺序开展施救。","k":"","p":"","j":""},{"i":100557,"c":10,"x":1,"y":1,"q":"海姆立克法通过冲击腹部产生气流排出异物。","o":["正确","错误"],"a":"A","e":"海姆立克急救法的原理主要是通过冲击腹部，产生气流，排出异物，使气道通畅，从而达到急救的目的。","k":"","p":"","j":""},{"i":100558,"c":10,"x":1,"y":1,"q":"对于异物插入体内的伤员，现场应尝试将异物拔除。","o":["正确","错误"],"a":"B","e":"救护员在现场对伤病员进行救护之前，首先要考虑现场环境是否安全。对意识不清的伤病员，检查脉搏常用颈动脉；对伤员鼻出血，应先给与干净布擦血；对疑似颈椎骨折时，尽量不移动伤病员，拨打急救电话；对异物插入体内的，现场不能拔除异物,应采取简单固定包扎措施后送往医院。","k":"","p":"","j":""},{"i":100559,"c":10,"x":1,"y":2,"q":"现场存在多名伤员，确无法同时救治时，应优先救治（ ）。","o":["未成年伤员","因疼痛不停喊叫的伤员","有其他疾病的伤员","已昏迷的伤员"],"a":"D","e":"多名伤员，确无法同时救治，应优先救治伤势可能危及生命伤员，所以选“已昏迷的伤员”。","k":"","p":"","j":""},{"i":100560,"c":10,"x":1,"y":1,"q":"动脉出血可以采用直接加压包扎法完全止住。","o":["正确","错误"],"a":"B","e":"动脉出血时，血液随脉搏节律间歇状向外喷射，出血颜色鲜红，应采取指压止血法止血，直接加压无法完全止血。指压止血部位包括桡动脉、股动脉和肱动脉。","k":"","p":"","j":""},{"i":100561,"c":10,"x":1,"y":2,"q":"加压包扎止血法主要用于什么情况？","o":["内脏出血","四肢损伤时的较小血管出血或渗血","头部动脉出血","动脉喷射性出血"],"a":"B","e":"包扎止血法可以采用绷带、三角巾、止血带等物品，不能使用麻绳包扎。加压包扎止血法，主要用于四肢损伤时的较小血管出血或渗血。","k":"","p":"","j":""},{"i":100562,"c":10,"x":1,"y":1,"q":"实施填塞止血时，应用敷料紧密压实伤口，压力越大效果越好。","o":["正确","错误"],"a":"B","e":"填塞止血时，应适度压力，不能将敷料紧密压实伤口，过度加压可能损伤组织或加重出血；直接加压止血时，应持续按压10-15分钟后检查是否止血，过早松开会再次出血。","k":"","p":"","j":""},{"i":100563,"c":10,"x":1,"y":2,"q":"止血带的使用范围是？","o":["仅限四肢","仅用于头部","可用于儿童前臂浅表划伤","所有部位均可"],"a":"A","e":"止血带仅限四肢，不能用于头部出血和儿童的前臂浅表划伤出血。救治四肢动脉喷射性出血伤员时，应记录使用时间，每1小时要放松1次。","k":"","p":"","j":""},{"i":100564,"c":10,"x":1,"y":1,"q":"对开放性骨折外露的骨端，应立即将其复位回伤口内再进行包扎。","o":["正确","错误"],"a":"B","e":"对开放性骨折外露的骨端，不能立即复位，应原位覆盖敷料固定。","k":"","p":"","j":""},{"i":100565,"c":10,"x":1,"y":2,"q":"包扎开放性腹部损伤（脏器外漏）时，以下哪种做法是正确的？","o":["将脏器直接塞回腹腔","不予处理立即送医","用无菌湿纱布覆盖，并用碗状物扣住伤口后压迫","用干纱布擦拭后包扎"],"a":"C","e":"包扎开放性腹部损伤（脏器外露）伤员时，用无菌湿纱布覆盖外露脏器，并用碗状物扣住伤口避免压迫，包扎后让患者平卧屈膝。","k":"","p":"","j":""},{"i":100566,"c":10,"x":1,"y":3,"q":"搬运脊柱损伤患者时，可采用哪些方法？","o":["使用木板运送","一人背驮","二人抬肢","轴线翻身或脊柱板固定"],"a":"AD","e":"搬运脊柱损伤患者时，可采用“轴线翻身”或脊柱板固定；骨盆骨折患者搬运时，可用宽布带固定骨盆减少移位；运送脊椎骨折的病人应选用木板。","k":"","p":"","j":""},{"i":100567,"c":10,"x":1,"y":1,"q":"骨盆骨折患者搬运时，可用宽布带固定骨盆以减少移位。","o":["正确","错误"],"a":"A","e":"骨盆骨折患者搬运时，可用宽布带固定骨盆减少移位。","k":"","p":"","j":""},{"i":100568,"c":10,"x":1,"y":2,"q":"对意识不清的伤病员，检查脉搏常用的动脉是？","o":["桡动脉","股动脉","足背动脉","颈动脉"],"a":"D","e":"对意识不清的伤病员，检查脉搏常用颈动脉。","k":"","p":"","j":""},{"i":100569,"c":10,"x":1,"y":3,"q":"拨打120急救电话时，需要向调度员提供哪些信息？","o":["患者当前意识和呼吸状态","患者详细描述患者症状（如胸痛、呕吐物颜色）","现场是否存在危险因素（如火灾、漏电）","精确的地址（附近标志性建筑或门牌号）"],"a":"ABCD","e":"拨打120报警时，要保持冷静，语速清晰，详细描述患者症状（如胸痛、呕吐物颜色）、患者当前意识和呼吸状态，附近标志性建筑（精确到门牌号），以及现场是否有危险因素（如火灾、漏电）。","k":"","p":"","j":""},{"i":100570,"c":10,"x":1,"y":2,"q":"一侧头顶部出血时，应采用下列哪种指压止血法？","o":["压迫同侧颈总动脉","压迫对侧面动脉","在同侧耳前，对准耳屏上前方1.5厘米处压迫颞浅动脉","压迫手腕处的桡动脉"],"a":"C","e":"一侧头顶部出血时，在同侧耳前,对准耳屏上前方1.5厘米血管搏动处，用拇指压迫颞浅动脉止血。","k":"","p":"","j":""},{"i":100571,"c":10,"x":1,"y":2,"q":"小腿骨折只有一块夹板时，夹板应放在什么位置？","o":["小腿外侧","小腿内侧","小腿前侧","小腿后侧"],"a":"D","e":"当小腿骨折，只有一块夹板时，夹板应放在小腿的后侧。","k":"","p":"","j":""},{"i":100572,"c":10,"x":1,"y":2,"q":"对于四肢动脉喷射性出血的伤员，使用止血带后应怎么做？","o":["一直紧缚直到医院","每1小时要放松1次，并记录时间","每30分钟放松一次","不需要放松"],"a":"B","e":"止血带仅限四肢，不能用于头部出血和儿童的前臂浅表划伤出血。救治四肢动脉喷射性出血伤员时，应记录使用时间，每1小时要放松1次。","k":"","p":"","j":""},{"i":100573,"c":10,"x":1,"y":2,"q":"根据《民法典》第184条，因自愿实施紧急救助行为造成受助人损害的，救助人承担何种责任？","o":["重大过失责任","部分责任","不承担责任","全部责任"],"a":"C","e":"发现多人急需救治时，或自己无法完成救治时，应立即呼救。对急需救治的患者，应根据现场情况将病人移出危险区，或消除引起危害的因素。根据《民法典》第184条，因紧急搬运导致患者颈椎二次损伤，施救者无需担责；施救者因使用止血带导致患者截肢无需担责。","k":"","p":"","j":""},{"i":100574,"c":10,"x":1,"y":2,"q":"动脉出血的特征是什么？","o":["血液呈鲜红色，缓慢渗出","血液呈暗红色，缓慢流出","血液呈鲜红色，随脉搏节律喷射而出","血液呈暗红色，点滴状流出"],"a":"C","e":"动脉出血时，血液随脉搏节律间歇状向外喷射，出血颜色鲜红，应采取指压止血法止血，直接加压无法完全止血。指压止血部位包括桡动脉、股动脉和肱动脉。","k":"","p":"","j":""},{"i":100575,"c":10,"x":1,"y":2,"q":"用干净敷料压迫伤口止血时，敷料范围应超出伤口多大？","o":["1—2厘米","5—10厘米","3—4厘米","越大越好"],"a":"B","e":"用干净敷料压迫伤口止血时，放置敷料范围要大，超出伤口5-10厘米。","k":"","p":"","j":""},{"i":100576,"c":10,"x":1,"y":3,"q":"处理清醒成人的气道完全异物梗阻时，可采取哪些方法？","o":["鼓励患者用力咳嗽","立即用手指伸入口腔掏取","拍击患者背部肩胛区5次","实施海姆立克急救法"],"a":"ACD","e":"处理清醒的成人气道异物梗阻（完全梗阻）时，应鼓励患者用力咳嗽，或拍击患者背部肩胛区5次，必要时可以站在患者身后实施海姆立克法。","k":"","p":"","j":""},{"i":100577,"c":10,"x":1,"y":2,"q":"采用直接加压法止血时，应持续按压多久再检查是否止血？","o":["10—15分钟","5—6分钟","1—2分钟","20分钟以上"],"a":"A","e":"直接加压止血时，应持续按压10-15分钟后检查是否止血，过早松开会再次出血。","k":"","p":"","j":""},{"i":100578,"c":10,"x":1,"y":2,"q":"《江西省非机动车管理办法》规定电动自行车、残疾人机动轮椅车在非机动车道内行驶时，最高时速不得超过多少公里?","o":["25","20","15","30"],"a":"C","e":"《江西省非机动车管理办法》第十七条:电动自行车、残疾人机动轮椅车在非机动车道内行驶时，最高时速不得超过15公里。","k":"","p":"","j":""},{"i":100579,"c":10,"x":1,"y":2,"q":"大雨天在高速公路行车时，怎样避免发生“水滑”现象?","o":["安装防滑装置","提高车速行驶","降低车速行驶","断续使用制动"],"a":"C","e":"水滑就是因为雨天雨水多了，使轮胎与路面的摩擦系数变小，就容易侧滑。因此降低车速就能减少水滑发生的可能。","k":"","p":"","j":""},{"i":100580,"c":10,"x":1,"y":2,"q":"道路与铁路平面交叉道口有两个红灯交替闪烁时，表示什么?","o":["允许车辆、行人通行","提示车辆、行人注意瞭望，确认安全后通过","禁止车辆、行人通行","火车通行的指示灯"],"a":"C","e":"红灯闪烁是在说明有列车接近，表示禁止车辆、行人通行，即任何人员与车辆不得通过。","k":"","p":"","j":""},{"i":100581,"c":10,"x":1,"y":2,"q":"对一个记分周期内记分达到新规题()分的，由公安交通管理部门扣留其机动车驾驶证，机动车驾驶人应参加交通安全法律法规学习并接受考试。","o":["3分","6分","12分","24分"],"a":"C","e":"《道路交通安全法实施条例》规定:对在一个记分周期内记分达到12分的，由公安机关交通管理部门扣留其机动车驾驶证，该机动车驾驶人应当按照规定参加道路交通安全法律、法规的学习并接受考试。考试合格的，记分予以清除，发还机动车驾驶证:考试不合格的，继续参加学习和考试。","k":"","p":"","j":""},{"i":100582,"c":10,"x":1,"y":2,"q":"发动机着火后怎么处置?","o":["迅速关闭发动机","用水进行灭火","开启发动机罩灭火","站在下风处灭火"],"a":"A","e":"发动机着火，首先要关闭发动机，阻止发动机运行再进行其他的灭火措施。","k":"","p":"","j":""},{"i":100583,"c":10,"x":1,"y":2,"q":"高速公路上行车，如果因疏忽驶过出口且下一出口距离较远时，要怎样做?","o":["沿路肩倒车驶回","继续向前行驶","立即停车","在原地掉头"],"a":"B","e":"高速公路不能掉头、停车，错过出口，只能继续行驶寻找下个出口。","k":"","p":"","j":""},{"i":100584,"c":10,"x":1,"y":2,"q":"高速行车时，车辆受了()的影响转向盘会有突然“被夺”的感觉时，驾驶人应握紧转向盘，减速行驶。","o":["冰雪","侧风","大雨","大雾"],"a":"B","e":"注意题目是“在高速行车时”，选项中只有侧风是车辆到高速了，才可以感受到的气候条件。所以选侧风。","k":"","p":"","j":""},{"i":100585,"c":10,"x":1,"y":2,"q":"高速行驶的车辆，在转向失控的情况下使用紧急制动，很容易造成什么后果?","o":["侧滑","翻车","车厢前移","爆胎"],"a":"B","e":"车辆在高速行驶状态下使用紧急制动，是很容易翻车的。这种情况下，应该先松油门，轻点刹车，慢慢把车速降下来，然后再想办法把车辆移到不妨碍交通的地方等待救援。","k":"","p":"","j":""},{"i":100586,"c":10,"x":1,"y":2,"q":"高速行驶中制动突然失灵，驾驶人要如何制动?","o":["连续踩踏制动踏板","抢挂低速挡，使用驻车制动","迅速踏下离合器踏板","迅速拉紧驻车制动器操纵杆"],"a":"B","e":"行车制动=制动踏板=刹车。刹车失灵，应抢挂低速挡减速后，使用驻车制动。","k":"","p":"","j":""},{"i":100587,"c":10,"x":1,"y":2,"q":"根据江西省实施《中华人民共和国道路交通安全法》办法规定，公路客运车辆驾驶人二十四小时内累计驾驶时间不得超过()小时。","o":["6","8","10","12"],"a":"B","e":"江西省实施《中华人民共和国道路交通安全法》办法第四十一条:公路客运车辆驾驶人二十四小时内累计驾驶时间不得超过八小时，日间连续驾驶不得超过四小时，夜间连续驾驶不得超过两小时，每次停车休息时间不得少于二十分钟。","k":"","p":"","j":""},{"i":100588,"c":10,"x":1,"y":2,"q":"根据《中华人民共和国道路交通安全法实施条例》，高速公路同方向有2条车道的，左侧车道为快车道，最低车速为()公里/小时。","o":["80","100","110","120"],"a":"B","e":"《中华人民共和国道路交通安全法实施条例》第七十八条:同方向有2条车道的，左侧车道的最低车速为每小时100公里:同方向有3条以上车道的，最左侧车道的最低车速为每小时110公里，中间车道的最低车速为每小时90公里。道路限速标志标明的车速与上述车道行驶车速的规定不一致的，按照道路限速标志标明的车速行驶。","k":"","p":"","j":""},{"i":100589,"c":10,"x":1,"y":2,"q":"行车中发动机突然熄火怎样处置?","o":["紧急制动停车","缓慢减速停车","挂空挡滑行","关闭点火开关"],"a":"B","e":"行车中发动机突然熄火，由于惯性，车不会立刻停下来，此时应立刻开启右转向灯，缓慢减速停车到路边，取出警告标志放置在车后50米外，打电话等待救援。","k":"","p":"","j":""},{"i":100590,"c":10,"x":1,"y":2,"q":"行车中发现右侧轮胎漏气时怎样处置?","o":["迅速制动减速","慢慢制动减速","迅速向左转向","采取紧急制动"],"a":"B","e":"当车辆漏气时，会引起轮胎不正常工作，因此此时应该减速并找安全的地方停车。迅速向左转向或是紧急制动都有可能造成爆胎等状况的发生，因此不可行。迅速制动减速和慢慢制动减速的差别在于是快还是要慢，若是动作过快也有可能造成爆胎，因此应该慢慢制动减速。","k":"","p":"","j":""},{"i":100591,"c":10,"x":1,"y":2,"q":"行车中发现左侧轮胎漏气时怎样处置?","o":["慢慢制动减速","迅速制动减速","迅速向右转向","采取紧急制动"],"a":"A","e":"当车辆漏气时，会引起轮胎不正常工作，因此此时应该减速并找安全的地方停车。迅速向左转向或是紧急制动都有可能造成爆胎等状况的发生，因此不可行。迅速制动减速和慢慢制动减速的差别在于是快还是要慢，若是动作过快也有可能造成爆胎，因此应该慢慢制动减速。","k":"","p":"","j":""},{"i":100592,"c":10,"x":1,"y":2,"q":"行车中与其他机动车发生正面碰撞已不可避免时怎样处置?","o":["变正面碰撞为侧面碰撞","向右急转转向盘躲避","迅速采取紧急制动","向左急转转向盘躲避"],"a":"C","e":"正面碰撞已不可避免时应该采取紧急制动，以减少碰撞力度。这时动方向盘避让会造成翻车等更严重的伤害。","k":"","p":"","j":""},{"i":100593,"c":10,"x":1,"y":2,"q":"行车中遇醉酒的行人时应怎么做?","o":["鸣喇叭警告","迅速从一侧绕过","减速慢行，保持足够的横向间距","紧随其后行驶"],"a":"C","e":"醉酒的人往往走路东倒西歪，驾驶人要减速慢行并保持距离。","k":"","p":"","j":""},{"i":100594,"c":10,"x":1,"y":2,"q":"行车中制动突然失灵时，驾驶人要怎样进行减速？","o":["连续踩踏制动踏板","利用“抢挡”或驻车制动","迅速踏下离合器踏板","迅速拉紧驻车制动器操纵杆"],"a":"B","e":"没有刹车首先做的是减挡，这是一个需要练习才可以完成的动作。第一，减到2挡或者是3挡;第二慢慢拉起手刹，不可拉死，后轮拉死会甩尾，事故更大;第三，抓好方向，抓住一切可以减速的机会减挡成功后不可踩离合器。因此本题的正确做法是利用“抢挡”或驻车制动。","k":"","p":"","j":""},{"i":100595,"c":10,"x":1,"y":2,"q":"机动车白天在道路上发生故障，妨碍交通又难以移动的，应当按照规定先开启危险报警闪光灯并在车后多少米放置警告标志?","o":["10米至20米","20米至30米","50米至100米","緘怀鄑傢扪0米至150米"],"a":"C","e":"机动车在道路上发生故障或者发生交通事故，妨碍交通又难以移动的，应当按照规定开启危险报警闪光灯并在车后50米至100米处放置警告标志，夜间还应当同时开启示廓灯和后位灯。","k":"","p":"","j":""},{"i":100596,"c":10,"x":1,"y":2,"q":"机动车不慎落水,车门无法开启时可选择自救的方法是什么?","o":["敲碎侧窗玻璃","关闭车窗","打电话求救","用工具撬开车门"],"a":"A","e":"这种情况下应敲碎侧窗玻璃，然后逃生。这时，打电话等比较耗时的方法是行不通的。","k":"","p":"","j":""},{"i":100597,"c":10,"x":1,"y":2,"q":"机动车从匝道驶入高速公路，应当开启什么灯?","o":["左转向灯","右转向灯","危险报警闪光灯","前照灯"],"a":"A","e":"从匝道驶入高速公路，是由右边向左驶入，因此需开启左转向灯。","k":"","p":"","j":""},{"i":100598,"c":10,"x":1,"y":2,"q":"机动车发生撞击的位置不在驾驶人一侧或撞击力量较小时，驾驶人不正确的做法是什么?","o":["紧握转向盘","两腿向前蹬","从一侧跳车","身体向后紧靠座椅"],"a":"C","e":"撞击位置不在驾驶人一侧或撞击力量较小时，说明没有跳车的必要。此时在车内比跳车安全得多。除此之外，大家要记住不是万不得已都不要选择跳车。","k":"","p":"","j":""},{"i":100599,"c":10,"x":1,"y":2,"q":"机动车行驶中遇见施工路段要注意什么?","o":["靠路右侧缓速通过","按照路标和指示牌通行","靠路左侧缓慢通过","左右均可，快速通过"],"a":"B","e":"《中华人民共和国道路交通安全法实施条例》第八十四条:机动车通过施工作业路段时，应当注意警示标志，减速行驶。","k":"","p":"","j":""},{"i":100600,"c":10,"x":1,"y":2,"q":"机动车行经人行横道时，应当()。","o":["减速让行","停车观察","正常通行","加速通行"],"a":"A","e":"《中华人民共和国道路交通安全法》第四十七条:机动车行经人行横道时，应当减速行驶;遇行人正在通过人行横道，应当停车让行。","k":"","p":"","j":""},{"i":100601,"c":10,"x":1,"y":2,"q":"机动车喷涂、粘贴标识或车身广告影响安全驾驶的，可以()。","o":["限令车主改正，不受处罚","处50元罚款","处100元罚款","处200元罚款"],"a":"D","e":"机动车喷涂、粘贴标识或车身广告影响安全驾驶的处以警告或者两百元罚款。","k":"","p":"","j":""},{"i":100602,"c":10,"x":1,"y":2,"q":"机动车上高速公路，以下哪种说法是正确的?","o":["可在匝道、加速车道、减速车道上超车","不准倒车、逆行、穿越中央分隔带掉头","非紧急情况时可以在应急车道行驶","可以试车或学习驾驶"],"a":"B","e":"《中华人民共和国道路交通安全法实施条例》第八十二条:机动车在高速公路上行驶，不得有下列行为:倒车、逆行、穿越中央分隔带掉头或者在车道内停车;在匝道、加速车道或者减速车道上超车;骑、轧车行道分界线或者在路肩上行驶;非紧急情况时在应急车道行驶或者停车;试车或者学习驾驶机动车","k":"","p":"","j":""},{"i":100603,"c":10,"x":1,"y":2,"q":"机动车驶离高速公路时，应当开启什么灯?","o":["左转向灯","右转向灯","危险报警闪光灯","前照灯"],"a":"B","e":"驶离高速公路，就是靠右侧驶离，因此要开启的应该是右转向灯。此情况下与危险报警闪光灯或是前照灯无关。","k":"","p":"","j":""},{"i":100604,"c":10,"x":1,"y":2,"q":"机动车因故障或者事故在高速公路行车道上紧急停车时，驾乘人员怎么办?","o":["站在机动车左侧","留在车上等待救援","在机动车前方放置警告标志","迅速转移至右侧路肩上或应急车道内"],"a":"D","e":"当车辆发生故障时，打开危险报警闪光灯，将车辆停放在最右侧的应急车道或紧急停车带内，夜间还应打开示廓灯和后位灯。司乘人员应立即下车，迅速转移至右侧路肩上或应急车道内(尽量远离高速公路路面、护栏)等候救援车辆、人员来。由一个人在车辆尾部150米左右放置三角警示牌或警示物(最好隔十米左右放置一个警示物)，切记不能在高速公路内走动、追逐、等候!不能在故障车辆内等候!一般情况禁止在高速公路上修理车辆。","k":"","p":"","j":""},{"i":100605,"c":10,"x":1,"y":2,"q":"机动车因故障在高速公路停车时在后方多远距离放置故障警告标志?","o":["150米以内","150米以外","100米以内","50米以内"],"a":"B","e":"车辆因故障必须在高速公路停车时，应在车后方150米处设置故障警告标志，夜间还需开启示廓灯和后位灯。","k":"","p":"","j":""},{"i":100606,"c":10,"x":1,"y":2,"q":"机动车在单位院内、居民居住区内最高时速为()。","o":["10公里","20公里","30公里","40公里"],"a":"B","e":"江西省实施《中华人民共和国道路交通安全法》办法第四十二条:在单位院内、居民居住区内，最高时速为二十公里。","k":"","p":"","j":""},{"i":100607,"c":10,"x":1,"y":2,"q":"机动车在高速公路发生故障需停车检查时，要在什么地方停车?","o":["最外侧行车道上","内侧行车道上","应急车道","匝道口"],"a":"C","e":"高速公路最右侧的道路就是紧急停车道，也就是应急车道，供车辆发生故障或事故时停靠。","k":"","p":"","j":""},{"i":100608,"c":10,"x":1,"y":2,"q":"机动车在高速公路行驶，以下哪种说法是正确的？","o":["可在应急车道停车上下人员","可在紧急停车带停车装卸货物","可在减速或加速车道上超车、停车","非紧急情况时不得在应急车道行驶或者停务"],"a":"D","e":"在高速公路上，除了遇到障碍、发生故障等必须停车的情况外，不准随意停车、停车上下人员或者装卸货物，也不准掉头、转弯、逆行、倒车。","k":"","p":"","j":""},{"i":100609,"c":10,"x":1,"y":2,"q":"机动车在高速公路上超车，车速为每小时100公里时，最小横向间距应为多少?","o":["0.8米","1.0米","1.2米","1.5米"],"a":"D","e":"横向间距就是两车的横向距离，最小横向间距应为1.5米。","k":"","p":"","j":""},{"i":100610,"c":10,"x":1,"y":2,"q":"机动车在夜间通行经公路的弯道时，最安全的做法是?","o":["使用远光灯","使用近光灯","减速慢行并交替使用远近光灯示意","使用危险报警闪光灯"],"a":"C","e":"夜间行经公路的弯道时，应减速慢行并交通使用远近光灯示意。通过连续急弯路时，要注意靠右侧减速慢行，不要占对向车道。","k":"","p":"","j":""},{"i":100611,"c":10,"x":1,"y":2,"q":"驾驶车辆过程中，与其他车辆发生矛盾时，应该（）","o":["进行谩骂","耐心分辨是非，有礼让精神，向对方赔礼道歉","开赌气车，超过后猛转方向盘报复","耐心分辨是非，保持冷静，不要把情绪带到悭劼蘖垬窦率阻鉆托菴坠雉伍膻徫穵笸媲氧中"],"a":"D","e":"驾驶车辆时，要安全行车，文明礼让，友好驾驶。","k":"","p":"","j":""},{"i":100612,"c":10,"x":1,"y":2,"q":"驾驶机动车在高速公路上以每小时100公里的速度行驶，与前车的安全距离是多少?","o":["50米","60米","80米","100米"],"a":"D","e":"《中华人民共和国道路交通安全法实施条例》第八十条:机动车在高速公路上行驶，车速超过每小时100公里时，应当与同车道前车保持100米以上的距离车速低于每小时100公里时，与同车道前车距离可以适当缩短，但最小距离不得少于50米","k":"","p":"","j":""},{"i":100613,"c":10,"x":1,"y":2,"q":"驾驶人发现转向不灵活时，错误的做法是什么？","o":["应尽快减速停车","在安全地点停车","继续驾驶","停车查明原因"],"a":"C","e":"发现转向不灵活时若是继续驾驶，而不是停车找原因的话，很可能会发生状况。","k":"","p":"","j":""},{"i":100614,"c":10,"x":1,"y":2,"q":"江西省实施《中华人民共和国道路交通安全法》办法规定，货运机动车违反规定载客的，可以处()罚款。","o":["2000元以上5000元以下罚款","1000元以上2000元以下罚款","500元以上1000元以下罚款","1000元以上5000元以下罚款"],"a":"B","e":"江西省实施《中华人民共和国道路交通安全法》办法第九十六条:货运机动车违反规定载客的，处一千元以上二千元以下罚款。","k":"","p":"","j":""},{"i":100615,"c":10,"x":1,"y":2,"q":"江西省实施《中华人民共和国道路交通安全法》办法规定，驾驶拼装或者已达到报废标准的机动车上道路行驶的，可以处()罚款。","o":["200元以上500元以下罚款","500元以上1000元以下罚款","500元以上2000元以下罚款","1000元以上2000元以下罚款"],"a":"B","e":"江西省实施《中华人民共和国道路交通安全法》办法第九十九条:驾驶拼装或者已达到报废标准的机动车上道路行驶的，处五百元以上一千元以下罚款。\n注意题干中前提是江西省，与道路交通安全法中的规定并不冲突。","k":"","p":"","j":""},{"i":100616,"c":10,"x":1,"y":2,"q":"客车在行驶中遇险时，驾驶人要怎么做?","o":["优先保护乘客人身安全","先抢救财产","根据情况进行抢救","蓽跛釀「覽抢救贵重物品"],"a":"A","e":"乘客人身安全是第一重要的，以人为本。","k":"","p":"","j":""},{"i":100617,"c":10,"x":1,"y":2,"q":"老张发现自己车辆在省内高速公路上有一条罚款30元的违法记录，有可能是以下哪种行为导致的?","o":["向车外抛撒物品","乘车人不按规定使用安全带","驾驶人不按规定使用安全带","非紧急情况在应急车道行驶或路肩上行驶"],"a":"B","e":"江西省实施《中华人民共和国道路交通安全法》办法第七十七条:乘车人在高速公路上不按规定使用安全带的，处三十元罚款。","k":"","p":"","j":""},{"i":100618,"c":10,"x":1,"y":2,"q":"轮胎气压过低时，高速行驶可能导致什么结果?","o":["侧滑","翻车","车厢前移","爆胎"],"a":"D","e":"轮胎气压过低和过高都会导致爆胎。轮胎气压过低在车辆行驶过程中，会让轮胎不正常工作，若是高速行驶的话，产生摩擦之后就很容易发生爆胎。","k":"","p":"","j":""},{"i":100619,"c":10,"x":1,"y":2,"q":"抢救昏迷失去知觉的伤员要在抢救前检查什么?","o":["呼吸","伤口","面部","四周环境"],"a":"A","e":"抢救昏迷的伤员时，应先确认伤员的生命体征，也就是先检查呼吸，然后再根据情况进行施救。","k":"","p":"","j":""},{"i":100620,"c":10,"x":1,"y":2,"q":"如果在夜间行车中，发现后车开启左转向灯，并变换使用远、近光灯，有可能后车要做出以下哪种行为?","o":["求救","靠边停车","掉头","超车"],"a":"D","e":"开启左转向灯，是变道的要求，是后方的车给你发出的超车信号。变换远、近光灯，是为了提醒前车注意。","k":"","p":"","j":""},{"i":100621,"c":10,"x":1,"y":2,"q":"擅自改变机动车外形、外廓尺寸座椅、品牌标识等已登记的有关技术数据的由公安交通管理部门责令恢复原状，并处()罚款。","o":["100元以上300元以下","200元以上400元以下","300元以上500元以下","400元以上600元以下"],"a":"C","e":"江西省实施《中华人民共和国道路交通安全法》办法第九十八条:擅自改变机动车外形、外廓尺寸、座椅、品牌标识等已登记的有关技术数据的，由公安机关交通管理部门责令恢复原状，并处三百元以上五百元以下罚款。","k":"","p":"","j":""},{"i":100622,"c":10,"x":1,"y":2,"q":"申请人在申领机动车驾驶证考试过程中有贿赂、舞弊行为的，取消考试资格，已通过考试的其他科目成绩无效;申请人在()年内不得再次申领机动车驾驶证。","o":["一","二","三","十"],"a":"A","e":"《机动车驾驶证申领和使用规定》规定:申请人在考试过程中有贿赂、舞弊行为的，取消考试资格，已经通过考试的其他科目成绩无效，公安机关交通管理部门处二千元以下罚款;申请人在一年内不得再次申领机动车驾驶证。","k":"","p":"","j":""},{"i":100623,"c":10,"x":1,"y":2,"q":"事故现场抢救伤员的基本要求是什么？","o":["先治伤，后救命","先救命，后治伤","先帮助轻伤","后救助重伤员"],"a":"B","e":"事故现场必须先救人，否则很有可能因为送医不及时而造成伤者死亡，而受伤的人员没有生命危险可以暂缓一下。","k":"","p":"","j":""},{"i":100624,"c":10,"x":1,"y":2,"q":"同方向有3条车道的高速公路上大中型客货车在没有限速标志标线的情况下行驶时，以下哪种做法是正确的?","o":["车速达到110公里/小时以上时，在最左侧车道行驶","车速达到100公里/小时以下时，在最左侧车道行驶","车速达到80公里/小时，在中间车道行驶","车速达到60公里/小时，在最右侧车道行驶"],"a":"D","e":"同向3车道最左侧行驶最低速度为110km/h，中间车道最低行驶速度90km/h，最右侧车道最低车速60km/h。大中型客货车在高速公路允许行驶的速度区间是60km/h-100km/h。所以车速达到60km/h或80km/h都只能在最右侧车道行驶，因此本题选择'车速达到60公里/小时，在最右侧车道行驶”","k":"","p":"","j":""},{"i":100625,"c":10,"x":1,"y":2,"q":"下列属于危险化学品易燃固体的是什么?","o":["火柴","烟花","电石","炸药"],"a":"A","e":"易燃固体是指在常温下以固态形式存在，燃点较低，遇火受热、撞击、摩擦或接触氧化剂能引起燃烧的物质。根据本题的四个选项，只有火柴是符合的，而其他则是爆炸物。","k":"","p":"","j":""},{"i":100626,"c":10,"x":1,"y":2,"q":"下坡路行车中制动突然失效怎么办？","o":["可利用避险车道减速停车","越二级挡位减挡","挂倒挡迫使停车","拉紧驻车制动器减速"],"a":"A","e":"在下坡路行车中制动突然失效，车速肯定会越来越快，越二级挡位减挡、挂倒挡迫使停车，是都不能让车停下来的;如果拉紧驻车制动器减速，容易造成汽车翻车。最有效安全的办法,是开到避险车道内，利用车前保险杠、车厢等钢性部位与路边岩石、大树或土坡摩擦、碰撞，在不威胁乘车人安全的情况下强行停车。","k":"","p":"","j":""},{"i":100627,"c":10,"x":1,"y":2,"q":"下坡路行车中制动突然失效后，不可采用的办法是什么?","o":["将车辆向上坡道方向行驶","用车身靠向路旁的岩石或树林碰擦","利用道路边专设的避险车道停车","拉紧驻车制动器操纵杆或越二级挡位减挡"],"a":"D","e":"题目要选的是不可取的办法，而且要看清是下坡路。拉紧驻车制动器操纵杆是指把手刹拉死，突发状况中突然拉死手刹会造成翻车，这种做法是不可取的。","k":"","p":"","j":""},{"i":100628,"c":10,"x":1,"y":2,"q":"小型汽车驾驶人在实习期内可以驾驶以下哪种车辆?","o":["小型汽车","公交汽车","营运客车","牵引挂车"],"a":"A","e":"考什么证，开什么车。","k":"","p":"","j":""},{"i":100629,"c":10,"x":1,"y":2,"q":"需要在高速公路停车时，要选择在什么地方停车？","o":["匝道","加速车道","减速车道","服务区"],"a":"D","e":"在高速公路的匝道、加速车道和减速车道不能停车因为不仅会影响正常交通，还容易引发事故。因此选服务区。","k":"","p":"","j":""},{"i":100630,"c":10,"x":1,"y":2,"q":"夜间会车，应当在对方来车()米以外，将远光灯变为近光灯。","o":["50","100","150","200"],"a":"C","e":"在没有中心隔离设施或者没有中心线的道路上，夜间会车应当在距相对方向来车150米以外改用近光灯，在窄路、窄桥与非机动车会车时应当使用近光灯。","k":"","p":"","j":""},{"i":100631,"c":10,"x":1,"y":2,"q":"液化石油气罐车在运输途中发生大量泄漏时，下列措施错误的是什么?","o":["切断一切电源","戴好防护面罩和手套","关闭阀门制止渗漏","组织人员向下风方向疏散"],"a":"D","e":"为了防止泄漏事件造成更大的伤害和损失，因此采取的措施应该是戴好防护面具和手套、切断一切电源、关闭阀门制止渗漏,并组织人员向上风方向疏散。选项中说下风方向，错误。","k":"","p":"","j":""},{"i":100632,"c":10,"x":1,"y":2,"q":"已经安全技术检验合格的机动车超过多久未办理注册登记的，应当重新进行安全技术检验?","o":["三个月","六个月","一年","二年"],"a":"C","e":"已经安全技术检验合格的机动车，超过一年未办理注册登记的，应当重新进行安全技术检验。","k":"","p":"","j":""},{"i":100633,"c":10,"x":1,"y":2,"q":"饮酒后驾驶营运机动车的，处十五日拘留，并处5000元罚款，吊销机动车驾驶证，()年内不得重新取得机动车驾驶证。","o":["1","20","5","10"],"a":"C","e":"《中华人民共和国道路交通安全法实施条例》第九十一条:饮酒后驾驶营运机动车的，处15日拘留，并处5000元罚款，吊销机动车驾驶证，5年内不得重新取得机动车驾驶证。","k":"","p":"","j":""},{"i":100634,"c":10,"x":1,"y":2,"q":"饮酒后驾驶营运机动车的，处十五日拘留，并处()罚款。","o":["2000元","5000元","10000元","20000元"],"a":"B","e":"《中华人民共和国道路交通安全法》第九十一条:饮酒后驾驶营运机动车的，处15日拘留，并处5000元罚款，吊销机动车驾驶证，5年内不得重新取得机动车驾驶证。","k":"","p":"","j":""},{"i":100635,"c":10,"x":1,"y":2,"q":"遇紧急情况避险时，要沉着冷静坚持什么样的处理原则?","o":["先避人后避物","先避物","先避车后避人","先避物后避人"],"a":"A","e":"以人为本，所以首先要避人。","k":"","p":"","j":""},{"i":100636,"c":10,"x":1,"y":2,"q":"在车速较高可能与前方机动车发生碰撞时，驾驶人采取什么措施?","o":["先制动减速，后转向避让","急转方向向左避让","急打方向，向右避让","先转向避让，后制动减速"],"a":"A","e":"注意是车速较高的情况下，因此若是直接转向，很有可能发生侧翻，所以应该先减速后转向避让。","k":"","p":"","j":""},{"i":100637,"c":10,"x":1,"y":2,"q":"在高速公路驾驶机动车意外碰撞护栏时采取什么保护措施?","o":["适量修正转向盘","迅速向相反方向转向","迅速采取紧急制动","迅速向碰撞一侧转向"],"a":"A","e":"车辆在高速公路以外碰撞护栏时，如果驾驶人迅速采取紧急制动，或向相反方向大幅度转向，或迅速向碰撞一侧转向，都会造成车辆严重失控，会发生连续碰撞护栏、倾翻、飞过护栏等重大交通事故。因此，车辆在高速公路意外撞击护栏的瞬间，驾驶人应握紧转向盘稳住方向，适当修正，极力控制车辆反弹;切忌紧急制动、猛转转向盘或迅速向相反方向转向躲避，以免扩大事故。","k":"","p":"","j":""},{"i":100638,"c":10,"x":1,"y":2,"q":"在同向3车道高速公路上行车，车速高于每小时90公里低于每小时110公里的机动车，应该在哪条车道上行驶?","o":["最左侧","中间","最右侧","任意"],"a":"B","e":"《中华人民共和国道路交通安全法实施条例》第七十八条:同方向有3条以上车道的，最左侧车道的最低车速为每小时110公里，中间车道的最低车速为每小时90公里。根据题意，选择中间车道。","k":"","p":"","j":""},{"i":100639,"c":10,"x":1,"y":2,"q":"怎样使用灭火器灭火?","o":["人要站在下风处","灭火器瞄准火源","尽量靠近火源","灭火器瞄准火苗"],"a":"B","e":"常识题。使用灭火器的方法:1、把灭火器罐上下晃动三次以上;2、将安全销拉开;3、握住出粉皮管，将皮管朝向火点;4、距着火点4-6米处用力压下把手，选择上风位置或者侧风方向接近火点，将干粉射入火焰基部;5、熄灭后用水冷却除烟防止复燃。","k":"","p":"","j":""},{"i":100640,"c":10,"x":1,"y":2,"q":"正常情况下，高速公路同方向有两条车道的，大型货车应当在()侧车道内行驶。","o":["左侧","右侧","中间","随意"],"a":"B","e":"正常情况下，高速公路同方向有两条车道的，大型货车应当在右侧车道内行驶。","k":"","p":"","j":""},{"i":100641,"c":10,"x":1,"y":2,"q":"转向失控后，若车辆偏离直线行驶方向，应怎样使车辆尽快减速停车?","o":["轻踏制动踏板","拉紧驻车制动器操纵杆","迅速降挡减速","果断地连续踩踏、放松制动踏板"],"a":"D","e":"果断地连续踩踏、放松制动踏板，也就是连续点刹车如果直接踩死的话轮胎会抱死，而且不是直线行驶车就会旋转，高速的话车就会翻车，是很危险的，所以要连续点刹车","k":"","p":"","j":""},{"i":100642,"c":10,"x":1,"y":2,"q":"准许机动车掉头的地方是()。","o":["桥梁","铁路道口","隧道","环岛"],"a":"D","e":"环岛可以掉头，其他选项都不行。","k":"","p":"","j":""},{"i":100643,"c":10,"x":1,"y":2,"q":"醉酒驾驶营运机动车的，由公安机关交通管理部门约束至酒醒，()，依法追究刑事责任。","o":["暂扣机动车","暂扣行驶证","吊销机动车驾驶证","终生禁驾"],"a":"C","e":"《中华人民共和国道路交通安全法》第九十一条:醉酒驾驶营运机动车的，由公安机关交通管理部门约束至酒醒，吊销机动车驾驶证，依法追究刑事责任:10年内不得重新取得机动车驾驶证，重新取得机动车驾驶证后，不得驾驶营运机动车，","k":"","p":"","j":""},{"i":100644,"c":10,"x":1,"y":3,"q":"《江西省非机动车管理办法》规本市考题定，驾驶非机动车应当遵守下列哪些规定?","o":["有非机动车道的，在非机动车道内行驶。没有非机动车道的，靠车行道的右侧行驶","电动自行车、残疾人机动轮椅车在非机动车道内行驶时，最高时速不得超过30公里","未锼载12周岁的未成年人不得在道路上驾驶非机动车，未满16周岁的未成年人不得在道路上驾驶电动自行车、残疾人机动轮椅车和畜力车","自行车、电动自行车限载一名16周岁以下未成年人，搭载学龄前儿童的，应当使用安全座椅"],"a":"AC","e":"《江西省非机动车管理办法》第十七条:电动自行车，残疾人机动轮椅车在非机动车道内行驶时，最高时速不得超过15公里。自行车、电动自行车限载一名12周岁以下未成年人;搭载学龄前儿童的，应当使用安全座椅。","k":"","p":"","j":""},{"i":100645,"c":10,"x":1,"y":3,"q":"《江西省非机动车管理办法》规定下列非机动车经县(市、区)公安机关交通管理部门登记，可上道路行驶。","o":["电动自行车","残疾人机动轮椅车","省人民政府确定的其他非机动车","变速自行车"],"a":"ABC","e":"《江西省非机动车管理办法》第八条:下列非机动车经县(市、区)公安机关交通管理部门登记后，方可上道路行驶:(一)电动自行车;(二)残疾人机动轮椅车;(三)省人民政府确定的其他非机动车。本省对以人力或者畜力驱动的非机动车不实行登记制度包括自行车、三轮车等。","k":"","p":"","j":""},{"i":100646,"c":10,"x":1,"y":3,"q":"超车时应注意()。","o":["紧急情况下可以从右侧超车","超车时应通过内外后视镜观察后方和左侧的交通情况","超车时应与被超车辆保持安全距离","超车后不得急转向驶回本车道，不得妨碍被超车辆正常行驶"],"a":"BCD","e":"紧急情况下，也不可以从右侧超车。","k":"","p":"","j":""},{"i":100647,"c":10,"x":1,"y":3,"q":"车辆行车中遇火灾应注意哪些事项？","o":["不得开启车罩灭火","车辆燃油着火时，不能用水进行灭火","使用灭火器灭火时应将灭火器瞄准火源","含酒精的防冻液着火时，可立即用水泼着火部位"],"a":"ABCD","e":"车辆着火时的注意事项:1、发动机着火时应迅速停熄发动机用灭火器或覆盖法灭火;不得开启发动机罩后灭火，因为这样做可能会因大量空气进入而加大火势;2、车辆燃油着火时，应当使用灭火器或路边砂土:棉衣等覆盖法灭火，不能使用水灭火;3、使用灭火器救火时，人要站在上风处，灭火器瞄准火源;4、含酒精的防冻液着火时，可立即用水浇泼着火部位，以冲淡酒精防冻液的浓度。","k":"","p":"","j":""},{"i":100648,"c":10,"x":1,"y":3,"q":"大雾天在高速公路遇事故不能继续行驶时，应当()?","o":["开启危险报警闪光灯和尾灯","按规定设置警告标志","驾乘人尽快从右侧离开车辆并转移到防护栏外","不随意在高速公路上行走"],"a":"ABCD","e":"当车辆发生故障时，打开危险报警闪光灯，将车辆停放在最右侧的应急车道或紧急停车带内，夜间还应打开示廓灯和后位灯。司乘人员应立即下车，迅速转移至右侧路肩上或应急车道内(尽量远离高速公路路面、护栏)等候救援车辆、人员。由一个人在车辆尾部150米左右放置三角警示牌或警示物(最好隔十米左右放置一个警示物)，切记不能在高速公路内走动、追逐、等候!不能在故障车辆内等候!","k":"","p":"","j":""},{"i":100649,"c":10,"x":1,"y":3,"q":"对道路交通安全违法行为的处罚种类有（）。","o":["警告","罚款","暂扣或者吊销驾驶证","行政拘留"],"a":"ABCD","e":"《中华人民共和国道路交通安全法》第八十八条:对道路交通安全违法行为的处罚种类包括:警告、罚款、暂扣或者吊销机动车驾驶证、拘留。","k":"","p":"","j":""},{"i":100650,"c":10,"x":1,"y":3,"q":"发生交通事故后，防止二次事故的有效措施是什么?","o":["疏散人员","开启危险报警闪光灯","标记伤员原始位置","正确放置危险警告标志"],"a":"ABD","e":"选项“疏散人员”、“开启危险报警闪光灯”“正确放置危险警告标志”都是防止二次事故的有效措施，而选项“标记伤员原始位置”的主要作用是事后判责，而不能够起到防止二次事故的作用。","k":"","p":"","j":""},{"i":100651,"c":10,"x":1,"y":3,"q":"高速行驶中出现转向失控时，驾驶人要如何处置?","o":["紧急制动","抢挂低速挡","合理使用行车制动和驻车制动，避免紧急制动","开启危险报警闪光灯"],"a":"BCD","e":"车辆在高速行驶的状态下，使用紧急制动很容易翻车。因此发生转向失控时，应当要减速，并开启危险报警闪光灯，并注意制动的使用。","k":"","p":"","j":""},{"i":100652,"c":10,"x":1,"y":3,"q":"机动车避免爆胎的正确做法是什么?","o":["降低轮胎气压","定期检查轮胎","及时清理轮胎沟槽的异物","更换有裂纹或损伤的轮胎"],"a":"BCD","e":"若是降低轮胎气压会导致爆胎，因此降低轮胎气压这一招不安全。","k":"","p":"","j":""},{"i":100653,"c":10,"x":1,"y":3,"q":"机动车发生侧滑时要如何调整方向?","o":["前轮侧滑，向侧滑方向转动转向盘","前轮侧滑，向侧滑相反方向转动转向盘","后轮侧滑，向侧滑方向转动转向盘","后轮侧滑，向侧滑相反方向转动转向盘"],"a":"BC","e":"前轮侧滑，向侧滑相反方向转动转向盘;后轮侧滑向侧滑方向转动转向盘。","k":"","p":"","j":""},{"i":100654,"c":10,"x":1,"y":3,"q":"机动车行驶时突然发生自燃，驾驶人采取以下紧急避险措施中，正确做法是什么?","o":["用清水喷洒扑灭","及时报警","使用车内备用的灭火器灭火","在来车方向设置警告标志"],"a":"BCD","e":"水的密度比油大，不能用来灭火，因此“用清水喷酒扑灭”首先排除。“报警”与“设置警告标志”是用来告知自燃地点，而“使用灭火器”选项则是进行灭火。","k":"","p":"","j":""},{"i":100655,"c":10,"x":1,"y":3,"q":"机动车因故障必须在高速公路上停车时，要采取的正确做法是什么?","o":["在车后150米处设置故障警告标志","在车后100米处设置故障警告标志","夜间要开启示廓灯和后位灯","要开启危险报警闪光灯"],"a":"ACD","e":"机动车因故障必须在高速公路上停车时，要开启危险报警闪光灯，夜间还要开启示廓灯和后位灯，在应急车道内停车，并在来车方向(车后)150米处设置警告标志。","k":"","p":"","j":""},{"i":100656,"c":10,"x":1,"y":3,"q":"机动车与非机动车、行人之间发生交通事故造成人身伤亡、财产损失的，在以下哪种情况下，机动车不用承担赔偿责任?","o":["交通事故损失是由非机动车驾驶人、行人故意碰撞机动车造成的","非机动车驾驶人、行人一方负全部责任的","非机动车驾驶人、行人一方负主要责任的","非机动车驾驶人、行人与处于合法停放状态的机动车发生交通事故，机动车一方无交通事故责任的"],"a":"AD","e":"交通事故的损失是由非机动车驾驶人、行人造成的机动车一方分担责任;损失是由非机动车驾驶人、行人故意造成的，机动车一方不承担责任。","k":"","p":"","j":""},{"i":100657,"c":10,"x":1,"y":3,"q":"机动车在高速公路上行驶,遇有雾雨、雪鞧且能见度在100米至200米之间时，应该怎么做?","o":["开启雾灯、近光灯、示廓灯、前后位灯","车速不超过60公里/小时","与同车道前车保持100米以上的距离","从最近的出口尽快驶离高速公路"],"a":"ABC","e":"(一)能见度小于200米时，开启雾灯、近光灯、示廓灯和前后位灯，车速不得超过每小时60公里，与同车道前车保持100米以上的距离;(二)能见度小于100米时，开启雾灯、近光灯、示廓灯、前后位灯和危险报警闪光灯，车速不得超过每小时40公里，与同车道前车保持50米以上的距离(三)能见度小于50米时,开启雾灯、近光灯、示廓灯前后位灯和危险报警闪光灯，车速不得超过每小时20公里，并从最近的出口尽快驶离高速公路。","k":"","p":"","j":""},{"i":100658,"c":10,"x":1,"y":3,"q":"机动车在高速行驶中突然爆胎，要采取的安全措施是什么?","o":["紧急制动，靠边停车","牢牢地握住转向盘，保持直行","立即松开加速踏板","轻踏制动踏板"],"a":"BCD","e":"如果采取紧急制动的方法，很容易出现侧翻事故因此正确的做法应该是握紧转向盘，同时松开加速踏板、轻踩制动踏板控制车速。","k":"","p":"","j":""},{"i":100659,"c":10,"x":1,"y":3,"q":"机动车在行驶中突遇制动失灵时驾驶人要采取什么措施?","o":["握稳转向盘","使用驻车制动器减速","抢挂低速挡减速","开启危险报警闪光灯"],"a":"ABCD","e":"机动车在行驶中突遇制动失灵时，应当握稳转向盘并开启危险报警闪光灯，并使用抢挂低速挡的方式或使用驻车制动器来减速。要先控制方向保持直线行驶，然后开启危险报警闪光灯(提示其他车辆我方车辆出现故障或紧急情况)，减速停车。","k":"","p":"","j":""},{"i":100660,"c":10,"x":1,"y":3,"q":"驾驶机动车遇有漫水路时，要采取的正确做法是什么?","o":["停车察明水情","确认安全，低速通过","机动车涉水后，间断轻踏制动踏板","机动车涉水后，持续轻踏制动踏板"],"a":"ABC","e":"《中华人民共和国道路交通安全法实施条例》第六十四条:机动车行经漫水路或者漫水桥时，应当停车察明水情，确认安全后，低速通过。另外，机动车涉水后，制动器效果会受影响，所以要间断轻踏制动:恢复制动效果。","k":"","p":"","j":""},{"i":100661,"c":10,"x":1,"y":3,"q":"驾驶伪造号牌的机动车上路行驶有可能受到公安交通管理部门以下哪种处罚?","o":["处二千元以上五千元以下罚款","收缴伪造机动车号牌，扣留该车辆","处十五日以下拘留","构成犯罪的，依法追究刑事责任"],"a":"ABCD","e":"《中华人民共和国道路交通安全法》第九十六条:伪造、变造或者使用伪造、变造的机动车登记证书、号牌、行驶证、驾驶证的，由公安机关交通管理部门予以收缴，扣留该机动车，处15日以下拘留，并处2000元以上5000元以下罚款;构成犯罪的，依法追究刑事责任。","k":"","p":"","j":""},{"i":100662,"c":10,"x":1,"y":3,"q":"江西省实施《道路交通安3新規題全法》办法规定，对公路客运车辆载客超过额定人员处罚，下列说法哪些是正确的?","o":["超员百分之二十以下的，处二百元以上四百元以下罚款","超员百分之二十的，处五百元罚款","超员百分之二十以上，每增加百分之十加处二百元罚款","超员罚款最高数额不得超过五千"],"a":"ABC","e":"江西省实施《中华人民共和国道路交通安全法》规定:公路客运车辆载客超过额定乘员百分之二十以下的，处二百元以上四百元以下罚款;超过额定乘员百分之二十的，处五百元罚款;超过额定乘员百分之二十以上,每增加百分之十的,加处二百元罚款，但最高罚款数额不得超过二千元。情节严重的，公安机关交通管理部门可以依法扣留机动车。","k":"","p":"","j":""},{"i":100663,"c":10,"x":1,"y":3,"q":"江西省实施《道路交通安全法》办法规定，对饮酒后驾驶机动车，哪些处罚是正确的?","o":["饮酒后驾驶机动车的，处一千五百元罚款","因饮酒后驾驶机动车被处罚，再次饮酒后驾驶机动车的，处二千元罚款","饮酒后驾驶营运机动车的，处五千元罚款","饮酒后驾驶机动车的，终生禁驾"],"a":"ABC","e":"江西省实施《中华人民共和国道路交通安全法》办法第九十二条:饮酒后驾驶机动车的，处一千五百元罚款;因饮酒后驾驶机动车被处罚，再次饮酒后驾驶机动车的，处二千元罚款;饮酒后驾驶营运机动车的，处五千元罚款。","k":"","p":"","j":""},{"i":100664,"c":10,"x":1,"y":3,"q":"江西省实施《道路交通安全法》办法规定，行人有下列哪些行为处50元罚款?","o":["跨越或者倚坐道路隔离设施的","在道路上使用滑板、旱冰鞋等滑行工具的","扒车、强行拦车、追车、抛物击车的","进入高速公路、城市快速路的"],"a":"ACD","e":"江西省实施《中华人民共和国道路交通安全法》办法第七十四条:行人有下列行为之一的，处五十元罚款:(一)跨越或者倚坐道路隔离设施的;(二)不给执行紧急任务的警车、消防车、救护车、工程救险车让行的;(三)扒车、强行拦车、追车、抛物击车的;(四)进入高速公路、城市快速路的。","k":"","p":"","j":""},{"i":100665,"c":10,"x":1,"y":3,"q":"江西省实施《道路交通安全法》办法规定，下列机动车在道路上行驶，应当遵守相应的哪些限速规定?","o":["手扶拖拉机最高时速为20公里，其他拖拉机最高时速为40公里","三轮汽车、轮式专用机械车、轻便摩托车最高时速为40公里","全挂拖斗车、低速载货汽车、摩托车和公交车最高时速为60公里","运载危险物品的机动车在高速公路上行驶时最高时速为80公里，在其他公路上行驶时最高时速为60公里"],"a":"ABCD","e":"江西省实施《中华人民共和国道路交通安全法》办法第四十三条:下列机动车在道路上行驶，应当遵守相应的限速规定:(一)手扶拖拉机最高时速为二十公里，其他拖拉机最高时速为四十公里;(二)三轮汽车、轮式专用机械车、轻便摩托车最高时速为四十公里:(三)全挂拖斗车、低速载货汽车、摩托车和公交车最高时速为六十公里;(四)运载危险物品的机动车在高速公路上行驶时最高时速为八十公里在其他公路上行驶时最高时速为六十公里。前款规定的机动车限速高于道路实际限速的，按照道路实际限速规定行驶;低于道路实际限速的，按照前款规定的限速行驶。","k":"","p":"","j":""},{"i":100666,"c":10,"x":1,"y":3,"q":"江西省实施《道路交通安全法》办法规定，机动车变更车道时，应当遵守下列哪些规定?","o":["提前100米至50米开启转向灯，在高速公路上提前150米至100米开启转向灯","同方向行驶左右两侧车道的车辆向中间车道变更时，左侧车道的车辆让右侧车道的车辆先行","可以一次性变更两条以上机动车道，但必须符合交通信号要求","不得一次性变更两条以上机动车道，但符緱爵験铃犋禇鹈交通信号要求的除外"],"a":"ABD","e":"江西省实施《中华人民共和国道路交通安全法》办法第三十七条:机动车变更车道时，应当遵守下列规定:(一)提前一百米至五十米开启转向灯，在高速公路上提前一百五十米至一百米开启转向灯;(二)不得一次性变更两条以上机动车道，但符合交通信号要求的除外;(三)同方向行驶左右两侧车道的车辆向中间车道变更时，左侧车道的车辆让右侧车道的车辆先行。","k":"","p":"","j":""},{"i":100667,"c":10,"x":1,"y":3,"q":"江西省实施《道路交通安全法》办法规定，在高速公路或者城市快速路上，机动车驾驶人有下列行为之一的，处200元罚款。","o":["驾驶拖拉机、轮式专用机械车、铰接式客车、全挂拖斗车、低速载货汽车、三轮汽车以及其他设计最高时速低于70公里的机动车进入高速公路的","发生故障或者交通事故，不按法律、法规规定处置的","遇有低能见度气象条件时，不遵守法律法规规定行驶的","倒车、逆行、穿越中央分隔带掉头或者在车道内停车的"],"a":"ABCD","e":"江西省实施《中华人民共和国道路交通安全法》办法第八十九条:在高速公路或者城市快速路上，机动车驾驶人有下列行为之一的，处二百元罚款:(一)驾驶拖拉机、轮式专用机械车、铰接式客车、全挂拖斗车、低速载货汽车、三轮汽车以及其他设计最高时速低于七十公里的机动车进入高速公路的;(二)发生故障或者交通事故，不按规定使用危险报警闪光灯、设置警告标志的;(三)遇有低能见度气象条件时，不遵守法律、法规规定行驶的;(四)倒车，逆行、穿越中央分隔带掉头或者在车道内停车的:(五)在匝道、加速车道或者减速车道上超车的;(六)骑、轧车行道分界线或者在路肩上行驶的;(七)非紧急情况时在应急车道行驶或者停车的;(八)试车或者学习驾驶机动车的;(九)在高速公路上驾驶的载货汽车车厢载人的。","k":"","p":"","j":""},{"i":100668,"c":10,"x":1,"y":3,"q":"江西省实施《道路交通安全法》办法规定，在高速公路或者城市快速路上，有下列情形之一的，对机动车驾驶人处100元罚款。","o":["不按规定使用安全带的","车速低于法律规定的最低限速的","不按法律、法规规定驶入或者驶离高速公路的","机动车在高速公路上遇交通阻塞停车时车上人员在行驶车道内活动、逗留，或者驾驶人在夜间未开启危险报警闪光灯、示廓灯和前后位灯"],"a":"ABCD","e":"江西省实施《中华人民共和国道路交通安全法》办法第八十八条:在高速公路或者城市快速路上，机动车驾驶人有下列行为之一的，处一百元罚款:(一)不按规定使用安全带的;(二)车速低于法律规定的最低限速的;(三)不按法律、法规规定驶入或者驶离高速公路的;(四)不按法律、法规规定与同车道前车保持距离的;(五)通过施工作业路段，不减速行驶的;(六)机动车在高速公路上遇交通阻塞停车时，车上人员在行驶车道内活动、逗留，或者驾驶人在夜间未开启危险报警闪光灯、示廓灯和前后位灯。","k":"","p":"","j":""},{"i":100669,"c":10,"x":1,"y":3,"q":"哪几种情况不宜超车?","o":["有限速标志时","在超车区域内能见度不佳","在狭窄地带或陡坡道上","在繁华的街道和铁路道口"],"a":"BCD","e":"在超车区域内能见度不佳、在狭窄地带或陡坡道上、在繁华的街道和铁路道口、视野或路况不好等没有超车的条件时，不宜超车。","k":"","p":"","j":""},{"i":100670,"c":10,"x":1,"y":3,"q":"申请机动车注册登记应当提交的证明和凭证包括?","o":["机动车所有人的身份证明","机动车来历证明","机动车整车出厂合格证明或者进口机动车凭证","车辆购置税的完税凭证或者免税凭证"],"a":"ABCD","e":"《中华人民共和国道路交通安全法实施条例》第五条申请机动车注册登记，应当交验机动车，并提交以下证明、凭证:机动车所有人的身份证明:购车发票等机动车来历证明;机动车整车出厂合格证明或者进口机动车进口凭证;车辆购置税完税证明或者免税凭证;机动车第三者责任强制保险凭证;法律行政法规规定应当在机动车注册登记时提交的其他证明、凭证。不属于国务院机动车产品主管部门规定免予安全技术检验的车型的，还应当提供机动车安全技术检验合格证明。","k":"","p":"","j":""},{"i":100671,"c":10,"x":1,"y":3,"q":"为确保机动车在高速公路安全行驶，不得有下列哪些行为?","o":["倒车、逆行、穿越中央分隔带掉头或者在车道内停车","骑、轧车行道分界线或者在路肩上行驶","在匝道、加速车道或者减速车道上超车","试车或者学习驾驶机动车"],"a":"ABCD","e":"《道路交通安全法实施条例》规定，机动车在高速公路上行驶，不得有下列行为:倒车、逆行、穿越中央分隔带掉头或者在车道内停车;在匝道、加速车道或者减速车道上超车；骑、轧车行道分界线或者在路肩上行驶;非紧急情况时在应急车道行驶或者停车；试车或者学习驾驶机动车。","k":"","p":"","j":""},{"i":100672,"c":10,"x":1,"y":3,"q":"下坡路行驶，制动突然失效后，采用的减速方法是什么?","o":["利用道路边专设的避险车道停车","用车身靠向路旁的岩石或树林碰擦","首先拉紧驻车制动","抢挂低速挡"],"a":"ABD","e":"这四个选项中，除了首先拉紧驻车制动可能会造成车辆侧滑等状况外，都是可以让机动车减速的有效措施。","k":"","p":"","j":""},{"i":100673,"c":10,"x":1,"y":3,"q":"以下哪几种情况需要对车辆强制报废？","o":["未按规定进行机动车安全技术检验被扣留的","机动车安全技术检验不合格，经修理和调整仍不符合机动车安全技术国家标准对在用车有关要求的","在检验有效期届满后连续三个机动车检验周期内未取得机动车检验合格标志的","使用超过20年的"],"a":"BC","e":"江西省实施《中华人民共和国道路交通安全法》办法第十八条:机动车安全技术检验不合格，经修理和调整仍不符合机动车安全技术国家标准对在用车有关要求的，或者在检验有效期届满后连续三个机动车检验周期内未取得机动车检验合格标志的，应当强制报废。","k":"","p":"","j":""},{"i":100674,"c":10,"x":1,"y":3,"q":"以下哪些行为是影响驾驶安全的不文明行为？","o":["在驾驶室内放置车载香水","在驾驶室内悬挂、放置妨碍驾驶人视线的物品","下陡坡时熄火或者空挡滑行","在禁止鸣喇叭的路段鸣喇叭"],"a":"BCD","e":"影响到别人的行为，就是不文明行为。","k":"","p":"","j":""},{"i":100675,"c":10,"x":1,"y":3,"q":"以下说法正确的是?","o":["车辆通过没有交通信号灯的交叉路口时转弯的机动车应该让直行的车辆先行","车辆通过没有交通信号灯的交叉路口遇放行信号时，应当让先于本放行信号的车辆先行","车辆通过环形路口，应该按照逆时针方向行驶","车辆通过交叉路口右转弯，应当让同方向左转弯或者直行的行人和非机动车先行"],"a":"ABD","e":"车辆通过环形路口，应当按照导向箭头所示方向行驶。其他选项说法正确。","k":"","p":"","j":""},{"i":100676,"c":10,"x":1,"y":3,"q":"有效预防机动车发生制动失效的措施是什么？","o":["定期维护制动系统","行车前检查制动踏板的自由行程","正确使用制动，防止热衰退","行车前检查制动液是否有滴漏"],"a":"ABCD","e":"四个选项都是对制动系统等的检查，通过检查，可以预防机动车制动失效的发生。","k":"","p":"","j":""},{"i":100677,"c":10,"x":1,"y":3,"q":"与对向来车发生正面碰撞且碰撞位置在驾驶人正前方时，驾驶人正确的急救姿势是什么?","o":["迅速躲离转向盘","往副驾驶座位躲避","迅速将两腿抬起","两脚蹬直"],"a":"ABC","e":"两脚蹬直会让驾驶人受到更大的伤害，其他三个选项的用意是为了不让身体被卡住。因此两脚蹬直不选，选其余三个选项。","k":"","p":"","j":""},{"i":100678,"c":10,"x":1,"y":3,"q":"在城市道路驾驶尽量不要尾随公共汽车，原因是?","o":["公共汽车见站就停，尾随其后会影响正常通行","公共汽车外形较大，尾随其后不便观察前方交通情况","公共汽车到站后会有行人突然横穿，易造成危险","公共汽车易造成拥堵"],"a":"ABC","e":"在城市道路驾驶尽量不要尾随公共汽车，原因是公共汽车见站就停，尾随其后会影响正常通行;公共汽车外形较大，尾随其后不便观察前方交通情况;公共汽车到站后会有行人突然横穿，易造成危险。","k":"","p":"","j":""},{"i":100679,"c":10,"x":1,"y":1,"q":"搬运昏迷失去知觉的伤员要采取俯卧位。","o":["正确","错误"],"a":"B","e":"对于昏迷、失去知觉患者的搬运，要保持患者是侧卧位，尽量头偏向一侧，使得口腔内的液体分泌时直接从口腔分泌出来。","k":"","p":"","j":""},{"i":100680,"c":10,"x":1,"y":1,"q":"避免机动车爆胎的正确做法是降低轮胎气压。","o":["正确","错误"],"a":"B","e":"轮胎气压过低会导致爆胎，轮胎缺气行驶是爆胎的祸根。车辆在缺气(轮胎胎压低于标准胎压)行驶时，随着胎压的下降，轮胎与地面的摩擦成倍增加，胎温急剧升高,轮胎变软，强度急剧下降。这种情况下，如果车辆高速行驶，就可能导致爆胎。因此本题错误。","k":"","p":"","j":""},{"i":100681,"c":10,"x":1,"y":1,"q":"车辆发生爆胎后，驾驶人在尚未控制住车速前，不要冒险使用行车制动器停车以避免车辆横甩发生更大的险情。","o":["正确","错误"],"a":"A","e":"爆胎后，驾驶人在尚未控制住车速的时候，是不能急踩刹车的，此举极易导致翻车，甚至与后面来车追尾。正确的做法应该是紧握方向盘，控制方向，极力保持直线行驶，利用发动机制动，减挡或抢挡减速度，轻踏制动踏板缓慢减速，平稳靠边停车。","k":"","p":"","j":""},{"i":100682,"c":10,"x":1,"y":1,"q":"车辆行驶中(特别在高速公路上)一侧发生爆胎时，转向盘随之以极大的力量蒈窠翀粳贖殮稟力镙斯誣畦另一侧急转。","o":["正确","错误"],"a":"B","e":"车辆行驶靠轮胎提供驱动力，当一边爆胎时，此处不能提供驱动力，就造成了车辆两侧受力不均衡，非爆胎侧受力大，故促使车辆向爆胎一侧转动。","k":"","p":"","j":""},{"i":100683,"c":10,"x":1,"y":1,"q":"车辆后轮爆裂，车尾摇摆不定，驾驶人应双手紧握转向盘，控制车辆保持直线行驶，减速停车。","o":["正确","错误"],"a":"A","e":"爆胎后，首先要控制方向，保持直线行驶，再减速停车。因为如果突然爆胎，车辆瞬间靠右会导致与后方来车相撞，所以应该先保持直线行驶，再减速停车。","k":"","p":"","j":""},{"i":100684,"c":10,"x":1,"y":1,"q":"车辆前轮爆裂，危险较大，方向会立刻向爆胎车辆一侧跑偏，直接影响驾驶人对转向盘的控制。","o":["正确","错误"],"a":"A","e":"爆胎后，车辆整体平衡会受到影响，会向爆胎的一侧跑偏，直接影响到驾驶人对转向盘的控制。","k":"","p":"","j":""},{"i":100685,"c":10,"x":1,"y":1,"q":"车辆通过交叉路口同时被放行或者没有交通信号时，右转弯机动车应当让后方向左转弯或者直行的行人和非机动车先行。","o":["正确","错误"],"a":"A","e":"江西省实施《中华人民共和国道路交通安全法》办法第四十四条:车辆通过交叉路口同时被放行或者没有交通信号时，右转弯的机动车应当让同方向左转弯或者直行的行人和非机动车先行。","k":"","p":"","j":""},{"i":100686,"c":10,"x":1,"y":1,"q":"道路危险货物运输驾驶人、装卸人员和押运人员必须了解所运载的危险化学品的性质、危害特性、包装容器的使用特性和发生意外时的应急措施。","o":["正确","错误"],"a":"A","e":"《危险化学品安全管理条例》第四十五条:运输危险化学品的驾驶人员、船员、装卸管理人员、押运人员申报人员、集装箱装箱现场检查员，应当了解所运输的危险化学品的危险特性及其包装物、容器的使用要求和出现危险情况时的应急处置方法。","k":"","p":"","j":""},{"i":100687,"c":10,"x":1,"y":1,"q":"发动机着火时,要迅速关闭发动机开启发动机罩进行灭火。","o":["正确","错误"],"a":"B","e":"打开发动机罩后氧气会迅速涌入，引起更大的火灾，所以本题错误。","k":"","p":"","j":""},{"i":100688,"c":10,"x":1,"y":1,"q":"公路客运车辆驾驶人二十四小时内累计驾驶时间不得超过八小时，日间连续驾驶不得超过四小时，夜间连续驾驶不得超过两小时，每次停车休息时间不得少于二十分钟。","o":["正确","错误"],"a":"A","e":"江西省实施《中华人民共和国道路交通安全法》办法第四十一条:公路客运车辆驾驶人二十四小时内累计驾驶时间不得超过八小时，日间连续驾驶不得超过四小时，夜间连续驾驶不得超过两小时，每次停车休息时间不得少于二十分钟。严禁公路客运车辆夜间通行达不到安全通行条件的三级以下山区公路。","k":"","p":"","j":""},{"i":100689,"c":10,"x":1,"y":1,"q":"行车的速度越快，驾驶人越看不到近处周围的情况，而且单位时间内遇到的情况越多，行驶的危险性越大。","o":["正确","错误"],"a":"A","e":"车速越快，驾驶人越看不到近处周围的情况，而且单位时间内遇到的情况越多，行驶的危险性越大。","k":"","p":"","j":""},{"i":100690,"c":10,"x":1,"y":1,"q":"行车途中发动机突然熄火，不能继续启动时要采取紧急制动措施，迫使机动车迅速停住。","o":["正确","错误"],"a":"B","e":"若是采取紧急制动的话，很有可能造成机动车侧滑或侧翻，引发事故，因此正确的做法应当是缓慢减速停车。","k":"","p":"","j":""},{"i":100691,"c":10,"x":1,"y":1,"q":"行车中发动机突然熄火后不能启动时，及时靠边停车检查熄火原因。","o":["正确","错误"],"a":"A","e":"行车中发动机突然熄火，极有可能是车辆某个部件出现了故障。为了安全，应该及时靠边停车检查熄火原因，因此本题正确。","k":"","p":"","j":""},{"i":100692,"c":10,"x":1,"y":1,"q":"行车中发生爆胎后，驾驶人可迅速使用行车制动器减速停车。","o":["正确","错误"],"a":"B","e":"爆胎后，驾驶人在尚未控制住车速的时候，是不能急踩刹车的，此举极易导致翻车，甚至与后面来车追尾。正确的做法应该是紧握方向盘，控制方向极力保持直线行驶，利用发动机制动，减挡或抢挡减速度，轻踏制动踏板缓慢减速，平稳靠边停车。","k":"","p":"","j":""},{"i":100693,"c":10,"x":1,"y":1,"q":"行车中遇突然爆胎时，驾驶人要急踏制动踏板减速停车。","o":["正确","错误"],"a":"B","e":"机动车爆胎时，紧急制动的话很容易造成车辆侧翻要轻踏制动踏板慢慢减速停车，因此本题错误。","k":"","p":"","j":""},{"i":100694,"c":10,"x":1,"y":1,"q":"机动车安全技术检验不合格，经修理和调整仍不符合机动车安全技术国家标准对在用车有关要求的，或者在检验有效期届满后连续三个机动车检验周期内未取得机动车检验合格标志的，应当强制报废。","o":["正确","错误"],"a":"A","e":"江西省实施《中华人民共和国道路交通安全法》办法第十八条:机动车安全技术检验不合格，经修理和调整仍不符合机动车安全技术国家标准对在用车有关要求的，或者在检验有效期届满后连续三个机动车检验周期内未取得机动车检验合格标志的，应当强制报废。","k":"","p":"","j":""},{"i":100695,"c":10,"x":1,"y":1,"q":"机动车变更车道时，应当提前一百米至五十米开启转向灯，在高速公路上提前一百五十米至一百米开启转向灯。","o":["正确","错误"],"a":"A","e":"江西省实施《中华人民共和国道路交通安全法》办法第三十七条:机动车变更车道时，应当提前一百米至五十米开启转向灯，在高速公路上提前一百五十米至一百米开启转向灯。","k":"","p":"","j":""},{"i":100696,"c":10,"x":1,"y":1,"q":"机动车电器、汽油着火时可用水来熄灭。","o":["正确","错误"],"a":"B","e":"水的密度比油大，不能用来灭火。电器着火，如用水熄灭的话，很容易导电。因此本题错误。","k":"","p":"","j":""},{"i":100697,"c":10,"x":1,"y":1,"q":"机动车驾驶人故意遮挡、污损、不按规定安装机动车号牌的，处五百元罚款。","o":["正确","错误"],"a":"B","e":"江西省实施《中华人民共和国道路交通安全法》办法第八十七条:机动车驾驶人故意遮挡、污损、不按规定安装机动车号牌的，或者在机动车号牌上喷涂粘贴影响交通技术监控信息接收的材料的，处二百元罚款。","k":"","p":"","j":""},{"i":100699,"c":10,"x":1,"y":1,"q":"机动车在高速公路意外撞击护栏时，有效的保护措施是向相反方向大幅度转向。","o":["正确","错误"],"a":"B","e":"向相反方向大幅度转向很容易造成车辆侧翻或倾翻因此本题错误。正确的做法是握紧方向盘，适当修正。","k":"","p":"","j":""},{"i":100700,"c":10,"x":1,"y":1,"q":"驾驶客车遇非常情况或发生事故时，要力所能及的将损失降到最低限度，决不能因紧急避险造成二次事故或更大损失。","o":["正确","错误"],"a":"A","e":"要以人为本，秉承着将伤害和损失降到最低的原则。","k":"","p":"","j":""},{"i":100701,"c":10,"x":1,"y":1,"q":"驾驶人行车中意识到爆胎时，要轻踏制动踏板，缓慢减速停车。","o":["正确","错误"],"a":"A","e":"意识到爆胎，要紧握转向盘，掌握好方向，轻踩制动踏板，缓慢减速停车。汽车爆胎重心会偏向爆胎的一侧，这时千万不能紧急制动，会造成侧翻。因此本题正确。","k":"","p":"","j":""},{"i":100702,"c":10,"x":1,"y":1,"q":"扑救易散发腐蚀性蒸汽或有毒气体的火灾时，扑救人员应穿戴防毒面具和相应的防护用品，站在上风处施救。","o":["正确","错误"],"a":"A","e":"由于是扑救易散发腐蚀性蒸汽或有毒气体的火灾那么既要做到不中毒，也要做到不被烫伤等。因此在扑救时，要穿戴防毒面具和相应的防护用品，这是为了防止中毒;而站在上风处施救，是因为不会因火势被烧伤。因此本题是正确的。","k":"","p":"","j":""},{"i":100703,"c":10,"x":1,"y":1,"q":"使用备胎时，行驶速度可以与正常轮胎一样。","o":["正确","错误"],"a":"B","e":"备胎不能当正常轮胎使用，所以行驶速度也与正常轮胎不一样。","k":"","p":"","j":""},{"i":100704,"c":10,"x":1,"y":1,"q":"伪造、变造或者使用伪造、变造的机动车登记证书、号牌、行驶证、驾驶证的由公安机关交通管理部门处二千元以上五千元以下罚款。","o":["正确","错误"],"a":"A","e":"《中华人民共和国道路交通安全法》第九十六条:伪造、变造或者使用伪造、变造的机动车登记证书、号牌、行驶证、驾驶证的，由公安机关交通管理部门予以收缴，扣留该机动车，处15日以下拘留，并处2000元以上5000元以下罚款;构成犯罪的，依法追究刑事责任。","k":"","p":"","j":""},{"i":100705,"c":10,"x":1,"y":1,"q":"雾天在高速公路发生事故后，车上人员不要随便下车行走。","o":["正确","错误"],"a":"B","e":"注意题目中说的是雾天发生事故后，为了避免二次事故的发生，车上人员要转移到高速公路护栏外等候，避免二次伤害。","k":"","p":"","j":""},{"i":100706,"c":10,"x":1,"y":1,"q":"因醉酒后驾驶机动车被吊销驾驶证的，终生禁驾。","o":["正确","错误"],"a":"B","e":"《中华人民共和国道路交通安全法》第九十一条:醉酒驾驶机动车的，由公安机关交通管理部门约束至酒醒，吊销机动车驾驶证，依法追究刑事责任;5年内不得重新取得机动车驾驶证。","k":"","p":"","j":""},{"i":100707,"c":10,"x":1,"y":1,"q":"用于公路营运的载客汽车、重型载货汽车、半挂牵引车、危险物品运输车和校车应当安装、使用符合国家标准的行驶记录仪或者全球定位系统，卧铺客车应当同时安装车载视频装置。","o":["正确","错误"],"a":"A","e":"江西省实施《中华人民共和国道路交通安全法》办法第二十条:用于公路营运的载客汽车、重型载货汽车、半挂牵引车、危险物品运输车和校车应当安装使用符合国家标准的行驶记录仪或者全球定位系统卧铺客车应当同时安装车载视频装置。运输企业或者相关单位应当落实安全监控主体责任，加强对所属车辆和驾驶人的动态监管。机动车驾驶人应当保持行驶记录仪或者全球定位系统的正常运行。","k":"","p":"","j":""},{"i":100708,"c":10,"x":1,"y":1,"q":"遇高速公路发生事故造成堵塞时可以使用右侧紧急停车带。","o":["正确","错误"],"a":"B","e":"右侧紧急停车带一般用于高速公路发生车祸等事故以后，警车、救护车、消防车等救援车辆的紧急通行车道。其他车辆除特殊情况下，严禁占用该车道行驶或长时间停车。","k":"","p":"","j":""},{"i":100709,"c":10,"x":1,"y":1,"q":"在道路与铁路道口遇到红灯亮时要尽快通过路口。","o":["正确","错误"],"a":"B","e":"在铁路道口遇到红灯亮，表示火车要来，禁止通行需要停车等待。","k":"","p":"","j":""},{"i":100710,"c":10,"x":1,"y":1,"q":"在浓雾中行车，可以以前车尾灯作为1安全距离的依据。","o":["正确","错误"],"a":"B","e":"雾天行车很容易将前面停驶车辆的尾灯误认为是行驶车辆的尾灯，进而引起追撞，因此，一定要密切注意前车动态，严格控制车速，加大行车安全距离千万不能以前车尾灯作为1安全距离的依据。","k":"","p":"","j":""},{"i":100711,"c":10,"x":1,"y":1,"q":"在狭窄的坡道上会车时，驾驶人应做到下坡车让上坡车先行，避免在坡道上会车。","o":["正确","错误"],"a":"A","e":"《中华人民共和国道路交通安全法实施条例》第四十八条:在狭窄的坡路，上坡的一方先行;但下坡的一方已行至中途而上坡的一方未上坡时，下坡的一方先行。","k":"","p":"","j":""},{"i":100712,"c":10,"x":1,"y":1,"q":"醉酒驾驶营运机动车的，只处二千元罚款。","o":["正确","错误"],"a":"B","e":"《中华人民共和国道路交通安全法》第九十一条:醉酒驾驶营运机动车的，由公安机关交通管理部门约束至酒醒，吊销机动车驾驶证，依法追究刑事责任:10年内不得重新取得机动车驾驶证，重新取得机动车驾驶证后，不得驾驶营运机动车。","k":"","p":"","j":""},{"i":100713,"c":10,"x":1,"y":1,"q":"机动车发生爆胎后，驾驶人在没有控制住车速前，可以使用行车制动器停车。","o":["正确","错误"],"a":"B","e":"本题主要考察轮胎常识。爆胎后一定要先稳住方向盘，做适度修正，尽快平稳减速停车。车速还没降下来前，不要冒险使用行车制动器停车，以免造成翻车。因此选择“错误”。","k":"","p":"","j":""},{"i":100715,"c":10,"x":1,"y":1,"q":"抢救失血伤员时要先止血。","o":["正确","错误"],"a":"A","e":"本题主要考察失血伤员的急救。在抢救失血伤员时必须尽快采取措施来制止出血，并防止进一步失血因此选择“正确”。","k":"","p":"","j":""},{"i":100716,"c":10,"x":1,"y":1,"q":"抢救骨折伤员时为了避免二次伤害，尽量不要移动身体骨折部位。","o":["正确","错误"],"a":"A","e":"本题主要考察骨折伤员的处置常识。骨折是肉眼看不到的伤害，随意碰触很有可能造成第二次伤害所以为了不让骨折情况变严重或恶化，尽量不要去触碰，不要移动身体骨折部位。因此选择“正确”。","k":"","p":"","j":""},{"i":100717,"c":10,"x":1,"y":1,"q":"救助有害气体中毒伤员，首先采取的措施是将伤员移到有新鲜空气的地方。","o":["正确","错误"],"a":"A","e":"本题主要考察有害气体中毒伤员急救。抢救有害气体中毒伤员，首先将这类伤员转移到有新鲜空气的地方，让伤员呼吸新鲜空气，减少有害气体的伤害再采取其他措施。因此选择“正确”。\n相关内容拓展:救助有害气体中毒伤员，要在第一时间迅速将伤员转移到有新鲜空气的地方，以防止继续中毒。","k":"","p":"","j":""},{"i":100718,"c":10,"x":1,"y":2,"q":"符合以下哪项情况的，当事人应当先撤离现场，将车辆移至不妨碍交通的地点再协商处理损害赔偿事宜?","o":["未造成人身伤亡且车辆能够移动的交通事故","造成人身伤亡且车辆能够移动的交通事故","未造成人身伤亡但车辆不能移动的交通事故","造成人身伤亡且车辆不能移动的交通事故"],"a":"A","e":"根据《重庆市道路交通安全条例》第六十条:未造成人身伤亡且车辆能够移动的交通事故，当事人应当先撤离现场，将车辆移至不妨碍交通的地点，再协商处理损害赔偿事宜。","k":"","p":"","j":""},{"i":100719,"c":10,"x":1,"y":2,"q":"机动车进入()划分车道的路段后，以及进入导向车道后，不得变更车道。","o":["实线标线","禁停黄色标线","虚线标线","禁停黄色虚线"],"a":"A","e":"根据《重庆市道路交通安全条例》第三十八条:机动车进入实线标线划分车道的路段后，以及进入导向车道后，不得变更车道。","k":"","p":"","j":""},{"i":100720,"c":10,"x":1,"y":2,"q":"公安机关交通管理部门及其交通警2察发现机动车有未处理的道路交通安全违法行为记录的，可扣留()。","o":["机动车行驶证","机动车","以上全部可以扣留","机动车驾驶证"],"a":"A","e":"根据《重庆市道路交通安全条例》第九十条 公安机关交通管理部门及其交通警察发现机动车有未处理的道路交通安全违法行为记录的，可扣留机动车行驶证，并书面通知机动车所有人、管理人或者驾驶人及时接受处理，处理完毕后，立即发还机动车行驶证。","k":"","p":"","j":""},{"i":100721,"c":10,"x":1,"y":2,"q":"发生道路交通事故导致1人死亡驾驶人承担事故()，应当依法追究刑事责任。","o":["主要以上责任","次要责任","无责任","同等责任"],"a":"A","e":"根据《刑法》133条与《最高人民法院关于审理交通肇事刑事案件具体应用法律若干问题的解释》第2条第一项规定，交通肇事具有死亡一人或者重伤三人以上，负事故全部或者主要责任的，构成交通肇事罪，应处三年以下有期徒刑或者拘役。再根据《道路交通安全法》第101条规定，构成交通肇事罪的，依法追究刑事责任，并由公安机关交通管理部门吊销机动车驾驶证。","k":"","p":"","j":""},{"i":100722,"c":10,"x":1,"y":2,"q":"对符合12123事故快处范围的财损交通事故，均要求当事人拍照取证后，先撤离现场再协商损害赔偿事宜，如当事人未自行撤离现场或者阻止他方当事人撤离现场的依据《重庆市道路交通安全条例》第八十七条规定，处以罚款()。","o":["300元以下","100元以上200元以下","400元以下","500元以下"],"a":"B","e":"根据《重庆市道路交通安全条例》第八十七条 发生交通事故，当事人未按本条例第六十条第一、二款规定撤离现场或者阻止他方当事人撤离现场的，处一百元以上二百元以下罚款。造成交通堵塞的，可以并处暂扣一个月机动车驾驶证。","k":"","p":"","j":""},{"i":100723,"c":10,"x":1,"y":2,"q":"明明在晚自习课后骑自行车回家途中,迎面遇到一辆驶来的汽车,灯光非常耀眼,为了安全，明明应该()。","o":["用手遮挡灯光","下车靠边避让","闭目缓慢行驶","迎着灯光行驶"],"a":"B","e":"骑自行车时要双手握住车把，选择中只有下车靠边避让是正确的做法。","k":"","p":"","j":""},{"i":100724,"c":10,"x":1,"y":2,"q":"公安机关交通管理部门现场查获道路交通安全违法行为，并出具道路交通安全违法行为处理通知书的，违法行为人应当在接到通知书之日起十五日内到公安机关交通管理部门接受调查、处理。无正当理由逾期不接受调查、处理的，公安机关交通管理部门可以()其机动车驾驶证。","o":["撤销","注销","吊销","暂扣"],"a":"C","e":"根据《重庆市道路交通安全条例》第八十八条公安机关交通管理部门现场查获道路交通安全违法行为并出具道路交通安全违法行为处理通知书的，违法行为人应当在接到通知书之日起十五日内到公安机关交通管理部门接受调查、处理。无正当理由逾期不接受调查、处理的，公安机关交通管理部门可以吊销其机动车驾驶证。","k":"","p":"","j":""},{"i":100725,"c":10,"x":1,"y":2,"q":"发生交通事故，符合自行撤离法定情形未撤离造成交通堵塞的，可以()。","o":["并处暂扣二个月机动车驾驶证","并处暂扣三个月机动车驾驶证","并处暂扣四个月机动车驾驶证","并处暂扣一个月机动车驾驶证"],"a":"D","e":"根据《重庆市道路交通安全条例》八十七条规定:发生交通事故，当事人未按本条例第六十条第一、二款规定撤离现场或者阻止他方当事人撤离现场的处一百元以上二百元以下罚款。造成交通堵塞的可以并处暂扣一个月机动车驾驶证。第六十条第一二款:未造成人身伤亡且车辆能够移动的交通事故当事人应当先撤离现场，将车辆移至不妨碍交通的地点，再协商处理损害赔偿事宜。发生道路、供电、通讯等设施损坏的交通事故，机动车可以移动的驾驶人应当将机动车移至不妨碍交通的地点，报警等候处理。","k":"","p":"","j":""},{"i":100726,"c":10,"x":1,"y":2,"q":"《道路交通安全法》施行日期是()。","o":["38322","38261","37987","38108"],"a":"D","e":"2003年10月28日，第十届全国人民代表大会常务委员会第五次会议通过，2003年10月28日中华人民共和国主席令第八号公布，自2004年5月1日起施行。2007年12月29日，第十届全国人民代表大会常务委员会第三十一次会议通过《关于修改(中华人民共和国道路交通安全法》的决定》，自2008年5月1日起施行。2011年4月22日，第十一届全国人民代表大会常务委员会第二十次会议通过《全国人民代表大会常务委员会关于修改的决定》，自2011年5月1日起施行。","k":"","p":"","j":""},{"i":100727,"c":10,"x":1,"y":2,"q":"王某夜间驾驶机动车去送货，途中2遇到对面来车未关闭远光灯，他也变换远近光灯示意，对方仍不关闭远光灯，此时王某应当()。","o":["靠左停车","开启近光灯","减速靠右或停车让行","向左行驶"],"a":"C","e":"夜间会车对方若一直使用远光灯，为了保证安全要注意避免直视灯光，减速靠右行驶。","k":"","p":"","j":""},{"i":100728,"c":10,"x":1,"y":2,"q":"驾驶营运机动车的驾驶人应当参加交通安全教育培训，每年不少于()学时，","o":["12","48","24","6"],"a":"C","e":"根据《重庆市道路交通安全条例》第二十四条:驾驶营运机动车的驾驶人应当参加交通安全教育培训，每年不少于二十四学时。","k":"","p":"","j":""},{"i":100729,"c":10,"x":1,"y":2,"q":"为减少奥运会期间交通拥堵，提高城市空气质量，您最好乘坐()前往观看奥运体育比赛。","o":["摩托车","出租车","公交车","私家车"],"a":"C","e":"奥运期间本就交通拥堵，乘坐公交车是最好的选择还可以节能减排。","k":"","p":"","j":""},{"i":100730,"c":10,"x":1,"y":2,"q":"机动车与非机动车驾驶人、行人之间发生交通事故，由保险公司在机动车第三者责任强制保险责任限额范围内予以赔偿不足的部分，非机动车驾驶人、行人的过错在交通事故中起主要作用,机动车一方承担()的赔偿责任。","o":["40%至50%","35%至45%","45%至55%","50%至60%"],"a":"A","e":"根据《重庆市道路交通安全条例》第六十七条 机动车与非机动车驾驶人、行人之间发生交通事故，由保险公司在机动车第三者责任强制保险责任限额范围内予以赔偿;不足的部分，机动车一方按照下列规定承担赔偿责任:(一)机动车一方没有过错的，机动车一方承担不超过百分之十的赔偿责任;(二)非机动车驾驶人、行人的过错在交通事故中起主要作用的，机动车一方承担百分之四十至百分之五十的赔偿责任;(三)非机动车驾驶人、行人与机动车一方的过错在交通事故中作用相当的，机动车一方承担百分之六十至百分之七十的赔偿责任;(四)非机动车驾驶人、行人的过错在交通事故中起次要作用的，机动车一方承担百分之八十至百分之九十的赔偿责任;(五)非机动车驾驶人、行人无过错的，机动车一方承担百分之百的赔偿责任。","k":"","p":"","j":""},{"i":100731,"c":10,"x":1,"y":2,"q":"没有非机动车道的，残疾人机动轮椅车、人力车、三轮车、畜力车在距道路右侧边缘()米的范围内行驶。","o":["二","二点二","二点五","一点五"],"a":"C","e":"根据《重庆市道路交通安全条例》第五十四条非机动车在道路上行驶应当遵守下列规定:(一)有非机动车道的，在非机动车道内行驶;没有非机动车道的自行车、电动自行车在距道路右侧边缘两米的范围内行驶，残疾人机动轮椅车、人力车、三轮车、畜力车在距道路右侧边缘二点五米的范围内行驶。","k":"","p":"","j":""},{"i":100732,"c":10,"x":1,"y":2,"q":"牵引车辆应当遵守哪些规定，以下说法错误的是?","o":["牵引载运危险品的车辆应当由专业人员操作","使用软连接牵引的，应该设置示警标识","重型货车、拖拉机、载运危险品的车辆不得牵引车辆","不得牵引轮式专用机械车及其他轮式机械"],"a":"C","e":"根据《重庆市道路交通安全条例》第四十四条牵引车辆应当遵守下列规定:(一)使用软连接牵引的，应当设置示警标识;(二)牵引载运危险品的车辆应当由专业人员操作;(三)挂车、拖拉机、载运危险品的车辆不得牵引车辆;(四)不得牵引轮式专用机械车及其他轮式机械。","k":"","p":"","j":""},{"i":100733,"c":10,"x":1,"y":2,"q":"以下哪种非机动车不需经过公安交通管理部门登记并领取牌证?","o":["自行车","残疾人机动轮椅车","人力车","电动自行车"],"a":"A","e":"根据《重庆市道路交通安全条例》十六条规定:电动自行车、残疾人机动轮椅车、人力车、三轮车、畜力车，经公安机关交通管理部门登记并领取牌证后方可在允许其通行的道路上行驶。自行车不实行登记。非机动车登记工本费标准由市价格主管部门规定。","k":"","p":"","j":""},{"i":100734,"c":10,"x":1,"y":2,"q":"路权按照类型可分为空间路权和()。","o":["通行路权","时间路权","先行路权","占道路权"],"a":"B","e":"路权是指道路交通主管部门为了提升道路使用效率、确保道路使用者的安全，根据道路交通工程与管理的原理，由道路交通法规、交通控制设施，在一定空间、时间内，规范道路使用者使用道路的权利。按照类型可分为空间路权和时间路权。","k":"","p":"","j":""},{"i":100735,"c":10,"x":1,"y":2,"q":"车辆、行人应当按照交通信号通行在交通信号中应当最先遵守的是()。","o":["交通警察的指挥","交通信号灯","交通标志","交通标线"],"a":"A","e":"根据《中华人民共和国道路交通安全法》第三十八条规定:车辆、行人应当按照交通信号通行;遇有交通警察现场指挥时，应当按照交通警察的指挥通行:在没有交通信号的道路上，应当在确保安全、畅通的原则下通行。","k":"","p":"","j":""},{"i":100736,"c":10,"x":1,"y":2,"q":"机动车通过没有交通信号灯控制也没有交通警察指挥的交叉路口，有让行交通标志、标线控制的，让()通行的一方先行。","o":["优先","右侧","左侧","直行"],"a":"A","e":"根据《中华人民共和国道路交通安全法实施条例》五十二条规定:机动车通过没有交通信号灯控制也没有交通警察指挥的交叉路口，除应当遵守第五十一条第(二)项、第(三)项的规定外，还应当遵守下列规定:有交通标志、标线控制的，让优先通行的一方先行;没有交通标志、标线控制的，在进入路口前停车瞭望，让右方道路的来车先行;支路让主路先行;转弯的机动车让直行的车辆先行;相对方向行驶的右转弯的机动车让左转弯的车辆先行。","k":"","p":"","j":""},{"i":100737,"c":10,"x":1,"y":2,"q":"交通事故处理中，当事人或代理人可以申请()回避。","o":["办案民警","办案单位领导","对方代理人","车辆所有人"],"a":"A","e":"《道路交通安全法》第八十三条，交通警察调查处理道路交通安全违法行为和交通事故，有下列情形之一的，应当回避:(一)是本案的当事人或者当事人的近亲属;(二)本人或者其近亲属与本案有利害关系;(三)与本案当事人有其他关系，可能影响案件的公正处理。","k":"","p":"","j":""},{"i":100738,"c":10,"x":1,"y":2,"q":"任何人不得强迫、指使、纵容驾驶人违反道路交通安全法律、法规和机动车驾驶要求驾驶()。","o":["非机动车","机动车","自行车","滑板车"],"a":"B","e":"根据《中华人民共和国道路交通安全法》二十二条规定:任何人不得强迫、指使、纵容驾驶人违反道路交通安全法律、法规和机动车安全驾驶要求驾驶机动车。","k":"","p":"","j":""},{"i":100739,"c":10,"x":1,"y":2,"q":"饮酒后不得驾驶()。","o":["非机动车","滑板车","自行车","机动车"],"a":"D","e":"根据《中华人民共和国道路交通安全法》二十二条规定:饮酒、服用国家管制的精神药品或者麻醉药品，或者患有妨碍安全驾驶机动车的疾病，或者过度疲劳影响安全驾驶的，不得驾驶机动车。","k":"","p":"","j":""},{"i":100740,"c":10,"x":1,"y":2,"q":"道路交通安全管理是为了保障道路交通()、有序、畅通。","o":["可用","美观","安全","可行"],"a":"C","e":"《道路交通安全法》第三条规定，道路交通安全工作，应当遵循依法管理、方便群众的原则，保障道路交通有序、安全、畅通。","k":"","p":"","j":""},{"i":100741,"c":10,"x":1,"y":2,"q":"符合以下哪项情形的，车辆驾驶人应当保护现场，立即抢救受伤人员，并迅速报告执勤的交通警察或者公安机关交通管理部门?","o":["发生人身伤亡的交通事故","未造成人身伤亡但车辆不能移动的交通事故","发生道路、供电、通讯等设施损坏的交通事故","未造成人身伤亡且车辆能够移动的交通事投"],"a":"A","e":"根据《中华人民共和国道路交通安全法》第七十条明确规定，在道路上发生交通事故，车辆驾驶人应当立即停车，保护现场;造成人身伤亡的，车辆驾驶人应当立即抢救受伤人员，并迅速报告执勤的交通警察或者公安机关交通管理部门。因抢救受伤人员变动现场的，应当标明位置。乘车人、过往车辆驾驶人、过往行人应当予以协助。","k":"","p":"","j":""},{"i":100742,"c":10,"x":1,"y":2,"q":"禁令标志的颜色为()。","o":["白底、红圈、红杠、黑图案","白底、黑边、红杠、黑图案","白底、黑边、红杠、红图案","黄底、红边、红杠、黑图案"],"a":"A","e":"禁令标志的颜色为白底、红圈、红杠、黑图案。","k":"","p":"","j":""},{"i":100743,"c":10,"x":1,"y":2,"q":"指示标志的颜色为()。","o":["白底、红图案","蓝底、白图案","白底、黑图案","黑底黑图案"],"a":"B","e":"指示标志的颜色为蓝底、白图案。","k":"","p":"","j":""},{"i":100744,"c":10,"x":1,"y":2,"q":"警告标志的颜色为()。","o":["黄底、红边、白图案","白底、黑边、黑图案","白底、黑边、红图案","黄底、黑边、黑图案"],"a":"D","e":"警告标志的颜色为黄底、黑边、黑图案。","k":"","p":"","j":""},{"i":100745,"c":10,"x":1,"y":1,"q":"单位和个人不得在城市道路、公路上组织开展体育锻炼、商业宣传、文艺表演等集体活动。但经公安机关批准的大型群众性活动除外。","o":["正确","错误"],"a":"A","e":"根据《重庆市道路交通安全条例》第五十五条 单位和个人不得在城市道路、公路上组织开展体育锻炼、商业宣传、文艺表演等集体活动。但经公安机关批准的大型群众性活动除外。","k":"","p":"","j":""},{"i":100746,"c":10,"x":1,"y":1,"q":"道路交通标志标线应与交通信号灯统筹考虑，所表达的内容不应发生相互矛盾不应产生歧义。","o":["正确","错误"],"a":"A","e":"交通信号灯应与道路的交通组织方式、交通标志标线的设置等统筹考虑，所表达的内容不能发生相互矛盾、不应产生歧义，否则将误导驾驶人，降低路口通行效率，甚至引发交通事故。","k":"","p":"","j":""},{"i":100747,"c":10,"x":1,"y":1,"q":"取得本市核发的行驶证的机动车产国国应当到公安机关交通管理部门领取交通信息卡，上道路行驶时应随车携带。","o":["正确","错误"],"a":"A","e":"根据《重庆市道路交通安全条例》第九条 取得本市核发的行驶证的机动车，应到公安机关交通管理部门领取交通信息卡，上道路行驶时应随车携带。","k":"","p":"","j":""},{"i":100748,"c":10,"x":1,"y":1,"q":"在不影响车辆、行人通行与安全的路段，市政等行政主管部门可以会同公安机关交通管理部门批准设置临时停车泊位，并规定停车泊位的使用时间，设置警示标志。","o":["正确","错误"],"a":"A","e":"根据《重庆市道路交通安全条例》第三十一条 在不影响车辆、行人通行与安全的路段，市政等行政主管部门可以会同公安机关交通管理部门批准设置临时停车泊位，并规定停车泊位的使用时间，设置警示标志。","k":"","p":"","j":""},{"i":100749,"c":10,"x":1,"y":1,"q":"住宅区或者单位内部供社会车辆通行的道路，应该设置交通标志、标线及其他交通安全设施，并接受市政等部门指导和监督。","o":["正确","错误"],"a":"B","e":"根据《重庆市道路交通安全条例》规定:住宅区或者单位内部供社会车辆通行的道路，应当设置交通标志、标线及其他交通安全设施，并接受公安机关交通管理部门指导和监督。","k":"","p":"","j":""},{"i":100750,"c":10,"x":1,"y":1,"q":"在城市道路上占用、挖掘道路或者跨越、穿越道路架设、增设管线设施以及在道路上设置机动车出入口等影响道路交通安全、畅通的行为，施工单位或者建设单位应当将施工的具体时间、地点、交通组织方式等报道路主管部门批准，于施工前十日登报公示。","o":["正确","错误"],"a":"B","e":"根据《重庆市道路交通安全条例》第三十三条在城市道路上占用、挖掘道路或者跨越、穿越道路架设增设管线设施以及在道路上设置机动车出入口等影响道路交通安全、畅通的行为，施工单位或者建设单位应当将施工的具体时间、地点、交通组织方式等报道路主管部门批准，于施工前五日登报公示。道路主管部门在审批时，应当征求公安机关交通管理部门的意见，并在受理申请后七日内作出审批决定。工期长、施工量大、社会影响较大的工程，其施工期间交通组织方式应当征得公安机关交通管理部门的同意，并在二十日内作出审批决定。","k":"","p":"","j":""},{"i":100751,"c":10,"x":1,"y":1,"q":"公安机关交通管理部门及其交通警察接到交通事故报警后，应当在三分钟内出警。对在主城区城市主干道上发生的交通事故，应当在接到报警后十五分钟内到达现场。","o":["正确","错误"],"a":"B","e":"根据《重庆市道路交通安全条例》第六十一条:公安机关交通管理部门应当向社会公布交通事故报警电话，方便群众报警。公安机关交通管理部门及其交通警察接到交通事故报警后，应当在三分钟内出警并立即赶赴现场。","k":"","p":"","j":""},{"i":100752,"c":10,"x":1,"y":1,"q":"上道路行驶的重型、中型载货汽车应当按规定安装侧、后防护装置。","o":["正确","错误"],"a":"A","e":"根据《重庆市道路交通安全条例》第十三条上道路行驶的汽车应当符合下列规定:(一)载货汽车与大:中型载客汽车和出租汽车车身应当喷涂车辆所有人名称或者所在地区，载货汽车与大、中型载客汽车还应当分别喷涂核定载质量、核定载客人数、放大的本车牌号等;(二)配备有效的灭火器具、急救包，故障车警告标志等;(三)重型、中型载货汽车应当按规定安装侧、后防护装置;(四)车身两侧的车窗和前后窗不得放置、粘贴、喷涂妨碍安全驾驶的物品文字、图案，不得使用镜面反光遮阳膜;(五)道路施工养护、环卫清扫、设施维修及绿化等道路作业车辆，应当符合国家有关技术标准规定;(六)用于公路营运的载客汽车、重型载货汽车、半挂牵引车以及危险品运输车辆应当安装、使用符合国家标准的行驶记录仪;(七)危险品运输车辆车身前后及两侧应当喷涂或者悬挂醒目的危险品警告标志","k":"","p":"","j":""},{"i":100753,"c":10,"x":1,"y":1,"q":"驾驶自行车，搭载十二周岁以下儿童应该设置固定座椅。","o":["正确","错误"],"a":"B","e":"根据《重庆市道路交通安全条例》第五十四条:自行车在各区县(自治县)政府所在地的城市建成区行驶，不得载人;其他地区驾驶自行车可以搭载。","k":"","p":"","j":""},{"i":100754,"c":10,"x":1,"y":1,"q":"道路交通事故分为车损事故、伤人\n事故和死亡事故。","o":["正确","错误"],"a":"B","e":"道路交通事故分为财产损失事故、伤人事故和死亡事故。","k":"","p":"","j":""},{"i":100755,"c":10,"x":1,"y":1,"q":"交通、建设、市政、农机等部门依据各自职责，负责有关的道路交通安全管理工作。","o":["正确","错误"],"a":"B","e":"根据《重庆市道路交通安全条例》第五条 市人民政府公安部门是本市道路交通安全管理工作的主管机关各级公安机关交通管理部门负责本行政区域内的道路交通安全管理工作。交通、建设、市政、农机等部门，依据各自职责，负责有关的道路交通安全工作。","k":"","p":"","j":""},{"i":100756,"c":10,"x":1,"y":1,"q":"临时通行牌证有效期不得超过十五日。","o":["正确","错误"],"a":"B","e":"机动车所有人申领临时行驶车号牌应当提交以下证明、凭证:(一)机动车所有人的身份证明;(二)机动车交通事故责任强制保险凭证;(三)属于本规定第四十五条第(一)项、第(四)项规定情形的，还应当提交机动车整车出厂合格证明或者进口机动车进口凭证;(四)属于本规定第四十五条第(二)项规定情形的，还应当提交机动车来历证明，以及机动车整车出厂合格证明或者进口机动车进口凭证:(五)属于本规定第四十五条第(三)项规定情形的还应当提交书面申请和机动车安全技术检验合格证明。车辆管理所应当自受理之日起一日内，审查提交的证明、凭证，属于本规定第四十五条第(一)项第(二)项规定情形，需要在本行政辖区内临时行驶的，核发有效期不超过十五日的临时行驶车号牌;需要跨行政辖区临时行驶的，核发有效期不超过三十日的临时行驶车号牌。属于本规定第四十五条第(三)项、第(四)项规定情形的，核发有效期不超过九十日的临时行驶车号牌。因号牌制作的原因，无法在规定时限内核发号牌的，车辆管理所应当核发有效期不超过十五日的临时行驶车号牌。对具有本规定第四十五条第(一)项、第(二)项规定情形之一机动车所有人需要多次申领临时行驶车号牌的，车辆管理所核发临时行驶车号牌不得超过三次。","k":"","p":"","j":""},{"i":100757,"c":10,"x":1,"y":1,"q":"机动车在有禁止左转弯标志的地点不得掉头。","o":["正确","错误"],"a":"A","e":"《中华人民共和国道路交通安全法实施条例》第四十九条 机动车在有禁止掉头或者禁止左转弯标志、标线的地点以及在铁路道口、人行横道、桥梁、急弯、陡坡、隧道或者容易发生危险的路段，不得掉头。","k":"","p":"","j":""},{"i":100758,"c":10,"x":1,"y":1,"q":"转弯时速度过快，车辆易冲出弯道或侧滑。","o":["正确","错误"],"a":"A","e":"转弯速度越快，离心力越大，车辆抓地力越小，容易冲出弯道或发生侧滑、倾翻。","k":"","p":"","j":""},{"i":100759,"c":10,"x":1,"y":1,"q":"王某驾驶轿车为朋友接新娘在轿车前后号牌上贴上“百年好合”的红纸这种做法是合情合理的。","o":["正确","错误"],"a":"B","e":"《道路交通安全违法行为记分管理办法》规定:驾驶未悬挂机动车号牌或者故意遮挡、污损机动车号牌的机动车上道路行驶的，一次记9分。","k":"","p":"","j":""},{"i":100760,"c":10,"x":1,"y":1,"q":"对于交通事故当事人对交通事故责任无争议的事故，组织当事人达成自行协商协议，上传交管12123系统后应快速撤离现场。","o":["正确","错误"],"a":"A","e":"对于交通事故当事人对事故责任无争议的事故，组织当事人达成自行协商协议，上传交管12123系统后快速撤离现场;对于当事人在现场未达成协议的及时通过交管12123系统上传事故照片，由后台交巡警在线进行事故认定。","k":"","p":"","j":""},{"i":100761,"c":10,"x":1,"y":1,"q":"叉车、履带式专用机械等不得上道路行驶。","o":["正确","错误"],"a":"A","e":"根据《重庆市道路交通安全条例》第五十二条规定叉车、履带式专用机械等不得上道路行驶。","k":"","p":"","j":""},{"i":100762,"c":10,"x":1,"y":1,"q":"牵引车、轮式专用机械车、拖拉机摩托车只能在最左侧车道行驶。","o":["正确","错误"],"a":"B","e":"根据《重庆市道路交通安全条例》第三十七条规定重型货车、中型货车、低速货车、三轮汽车、牵引车、轮式专用机械车、拖拉机、摩托车，以及实习期驾驶人驾驶的机动车，应当在慢速车道行驶;其中，牵引车、轮式专用机械车、拖拉机、摩托车只能在最右侧车道行驶。","k":"","p":"","j":""},{"i":100763,"c":10,"x":1,"y":1,"q":"道路上同方向左右两侧车道的机动车向同一车道变更车道时，右侧车道的机动车让左侧车道的机动车先行。","o":["正确","错误"],"a":"A","e":"根据《重庆市道路交通安全条例》第四十一条规定:道路上同方向左右两侧车道的机动车向同一车道变更车道时，右侧车道的机动车让左侧车道的机动车先行。","k":"","p":"","j":""},{"i":100764,"c":10,"x":1,"y":1,"q":"小李驾驶摩托车回家时，发现一根直径约2厘米的水管横卧在道路上，已来不及刹车，他应驾驶摩托车从水管呈垂直的方向通过。","o":["正确","错误"],"a":"A","e":"驾驶摩托车在道路上行驶时，发现有管状物品横卧在道路上，应从管状呈垂直的方向安全通过，避免车辆侧滑发生事故。","k":"","p":"","j":""},{"i":100765,"c":10,"x":1,"y":1,"q":"快处道路交通事故，当事人可以采取照相或摄像等方式固定现场证据后及时撤除现场。","o":["正确","错误"],"a":"B","e":"当事人必须是在确保安全的前提下，才可以采取照相或摄像等方式固定现场证据后及时撤除现场，题目未说明，所以选择错误。","k":"","p":"","j":""},{"i":100766,"c":10,"x":1,"y":1,"q":"未造成人身伤亡且车辆能够移动的交通事故，当事人应当先撤离现场，将车辆移至不妨碍交通的地点，再协商处理损害赔偿事宜。","o":["正确","错误"],"a":"A","e":"根据《道路交通事故处理程序规定》的内容:第十三条 机动车与机动车、机动车与非机动车发生财产损失事故，当事人对事实及成因无争议的，可以自行协商处理损害赔偿事宜。车辆可以移动的，当事人应当在确保安全的原则下对现场拍照或者标划事故车辆现场位置后，立即撤离现场，将车辆移至不妨碍交通的地点，再进行协商。","k":"","p":"","j":""},{"i":100767,"c":10,"x":1,"y":1,"q":"对一年内采用互联网在线快处快赔模式处理道路交通事故3起以上，或者一年内特定车辆间发生道路交通事故3次及以上的当事人应当报警等候处理。","o":["正确","错误"],"a":"A","e":"交通事故快处快赔:对对一年内采用互联网在线快处快赔模式处理道路交通事故3起及以上，或者一年内特定车辆间发生道路交通事故3次及以上的，当事人应当报警等候处理。","k":"","p":"","j":""},{"i":100768,"c":10,"x":1,"y":1,"q":"机动车在城市道路允许临时停车的路段临时停车时，应当按逆行方向停留并开启危险报警闪光灯，车身右侧距路缘不得超过三十厘米，驾驶人不得离车。","o":["正确","错误"],"a":"B","e":"机动车在城市道路允许临时停车的路段临时停车时应当按顺行方向停留并开启危险报警闪光灯，车身右侧距路缘不得超过三十厘米，驾驶人不得离车。临时停车不得影响其他车辆或者行人的通行。","k":"","p":"","j":""},{"i":100769,"c":10,"x":1,"y":1,"q":"当人从亮处进入暗处时，在最初几秒内无法看清周边的事物，这就是明适应。","o":["正确","错误"],"a":"B","e":"当人从亮处进入暗处时，在最初几秒内无法看清周边的事物，是暗适应。","k":"","p":"","j":""},{"i":100770,"c":10,"x":1,"y":1,"q":"机动车在道路上发生故障、交通事故、难以移动的，应当按照规定采取安全警示措施。驾驶人、乘车人可以不离开机动车。","o":["正确","错误"],"a":"B","e":"车辆发生故障不能移动时，应首先开启危险报警闪光灯，然后在车后放置警告标志，转移乘车人员至安全处，并迅速报警，等待救援。","k":"","p":"","j":""},{"i":100771,"c":10,"x":1,"y":1,"q":"机动车通过没有交通信号灯控制也没有交通警察指挥的交叉路口，让右方道路的来车先行。","o":["正确","错误"],"a":"A","e":"根据《重庆市道路交通安全条例》第四十一条规定机动车通过没有交通信号灯控制也没有交通警察指挥的交叉路口，应当遵守下列规定:(一)有让行交通标志、标线控制的，让优先通行的一方先行;(二)没有让行交通标志、标线控制的，在进入路口前停车观察，让右方道路的来车先行，但转弯的机动车让直行的车辆先行。","k":"","p":"","j":""},{"i":100772,"c":10,"x":1,"y":1,"q":"机动车载物的载质量、装载长度宽度、高度应当符合法律、行政法规的规定确保附载作业人员安全。在城市道路上，核定质量零点六吨以下的小型货车，附载作业人员不得超过三人。","o":["正确","错误"],"a":"B","e":"根据《重庆市道路交通安全条例》第四十二条规定:机动车载物的载质量、装载长度、宽度、高度应当符合法律、行政法规的规定，确保附载作业人员安全。在城市道路上，核定载质量零点六吨以下的小型货车，附载作业人员不得超过一人;其他小型货车附载作业人员不得超过三人。自卸货车不得附载作业人员。","k":"","p":"","j":""},{"i":100773,"c":10,"x":1,"y":1,"q":"机动车通过没有交通信号灯控制也没有交通警察指挥的交叉路口，右转弯的机动车让左转弯的机动车先行。","o":["正确","错误"],"a":"A","e":"根据《中华人民共和国道路交通安全法实施条例》第五十二条规定:机动车通过没有交通信号灯控制也没有交通警察指挥的交叉路口，除应当遵守第五十一条第(二)项、第(三)项的规定外，还应当遵守下列规定:有交通标志、标线控制的，让优先通行的一方先行;没有交通标志、标线控制的，在进入路口前停车瞭望，让右方道路的来车先行;支路让主路先行，转弯的机动车让直行的车辆先行;相对方向行驶的右转弯的机动车让左转弯的车辆先行。第五十一条第(二)项、第(三)项的规定:在划有导向车道的路口，按所需行进方向驶入导向车道;准备进入环形路口的让已在路口内的机动车先行。","k":"","p":"","j":""},{"i":100774,"c":10,"x":1,"y":1,"q":"机动车在道路上发生故障、交通事故、难以移动的，应当按照规定采取安全警示措施。驾驶人、乘车人应迅速离开车辆转移至安全地点。","o":["正确","错误"],"a":"A","e":"车辆发生故障不能移动时，应首先开启危险报警闪光灯，然后在车后放置警告标志，转移乘车人员至安全处，并迅速报警，等待救援。","k":"","p":"","j":""},{"i":100775,"c":10,"x":1,"y":1,"q":"机动车在城市道路允许临时停车的路段临时停车时，可以随意停放。","o":["正确","错误"],"a":"B","e":"根据《重庆市道路交通安全条例》第四十六条规定:机动车在城市道路允许临时停车的路段临时停车时应当按顺行方向停留并开启危险报警闪光灯，车身右侧距路缘不得超过三十厘米，驾驶人不得离车。临时停车不得影响其他车辆或者行人的通行。","k":"","p":"","j":""},{"i":100776,"c":10,"x":1,"y":1,"q":"公安机关交通管理部门可以委托交通协管组织，对非机动车和行人的道路交通安全违法行为实施警告或者五十元以下的罚款。","o":["正确","错误"],"a":"B","e":"公安机关交通管理部门及其交通警察对道路交通安全违法行为，应当及时纠正并依法予以处罚。对情节轻微、未影响道路通行的，可以指出其违法行为给予口头警告后放行。公安机关交通管理部门可以委托交通协管组织，对乡道和村道上发生的道路交通安全违法行为实施警告或者五十元以下的罚款。公安机关交通管理部门可以委托交通协管组织，对非机动车和行人的道路交通安全违法行为实施警告。受委托执法组织的执法人员应当取得相应的行政执法资格，并持证上岗，依法履行职责。","k":"","p":"","j":""},{"i":100777,"c":10,"x":1,"y":1,"q":"上道路行驶的汽车车身两侧的车窗和前后窗不得放置、粘贴、喷绘妨碍安全驾驶的物品、文字、图案，可以使用镜面反光遮阳膜。","o":["正确","错误"],"a":"B","e":"根据《重庆市道路交通安全条例》第十三条:上道路行驶的汽车应当符合下列规定:(一)载货汽车与大中型载客汽车和出租汽车车身应当喷涂车辆所有人名称或者所在地区，载货汽车与大、中型载客汽车还应当分别喷涂核定载质量、核定载客人数、放大的本车牌号等;(二)配备有效的灭火器具、急救包故障车警告标志等;(三)重型、中型载货汽车应当按规定安装侧、后防护装置;(四)车身两侧的车窗和前后窗不得放置、粘贴、喷涂妨碍安全驾驶的物品文字、图案，不得使用镜面反光遮阳膜;(五)道路施工养护、环卫清扫、设施维修及绿化等道路作业车辆，应当符合国家有关技术标准规定:(六)用于公路营运的载客汽车、重型载货汽车、半挂牵引车以及危险品运输车辆应当安装、使用符合国家标准的行驶记录仪;(七)危险品运输车辆车身前后及两侧应当喷涂或者悬挂醒目的危险品警告标志。","k":"","p":"","j":""},{"i":100778,"c":10,"x":1,"y":1,"q":"同一方向红、黄、绿三色方向指示信号对应为三个几何位置分立单元。","o":["正确","错误"],"a":"A","e":"《道路交通信号灯设置与安装规范》:机动车信号灯由红色、黄色、绿色三个几何位置分立的无图案圆形单元组成的一组信号灯，指导机动车通行。","k":"","p":"","j":""},{"i":100779,"c":10,"x":1,"y":1,"q":"急弯、陡坡、临崖、临水等危险路段以及下边坡高度为六米以上的路段，可以设置交通指示、警告标志和安全防护。","o":["正确","错误"],"a":"B","e":"根据《重庆市道路交通安全条例》第二十九条:急弯、陡坡、临崖、临水等危险路段以及下边坡高度为六米以上的路段，应当设置交通指示、警告标志和安全防护设施。","k":"","p":"","j":""},{"i":100780,"c":10,"x":1,"y":1,"q":"公民对违反道路交通安全法律、法规的行为只有举报的权利。","o":["正确","错误"],"a":"B","e":"根据《重庆市道路交通安全条例》第八条:单位和个人依法参与道路交通活动受法律保护，对违反道路交通安全法律、法规的行为有劝阻、举报的权利。对道路交通安全工作有突出贡献的单位和个人，应当予以表彰、奖励。","k":"","p":"","j":""},{"i":100781,"c":10,"x":1,"y":1,"q":"发生财产损失事故，且驾驶人无有效机动车驾驶证或者驾驶的机动车与驾驶证载明的准驾车型不符的情形，驾驶人可以撤除后报警。","o":["正确","错误"],"a":"B","e":"根据《道路交通事故处理程序规定》第十三条:发生死亡事故、伤人事故的，或者发生财产损失事故且有下列情形之一的，当事人应当保护现场并立即报警:(一)驾驶人无有效机动车驾驶证或者驾驶的机动车与驾驶证载明的准驾车型不符的;(二)驾驶人有饮酒、服用国家管制的精神药品或者麻醉药品嫌疑的;(三)驾驶人有从事校车业务或者旅客运输:严重超过额定乘员载客，或者严重超过规定时速行驶嫌疑的;(四)机动车无号牌或者使用伪造、变造的号牌的;(五)当事人不能自行移动车辆的;(六)一方当事人离开现场的;(七)有证据证明事故是由一方故意造成的。","k":"","p":"","j":""},{"i":100782,"c":10,"x":1,"y":1,"q":"同方向划有两条以上机动车道的道路，城市道路为每小时七十公里。公路和封闭的机动车专用道路为每小时八十公里。","o":["正确","错误"],"a":"A","e":"根据《重庆市道路交通安全条例》第三十九条:机动车在道路上行驶不得超过限速标志、标线标明的速度。机动车在没有限速标志、标线的道路上行驶不得超过下列最高行驶速度:(一)没有道路中心线的道路，城市道路为每小时三十公里，公路为每小时四十公里;(二)同方向只有一条机动车道的道路，城市道路为每小时五十公里，公路和封闭的机动车专用道路为每小时七十公里;(三)同方向划有两条以上机动车道的道路，城市道路为每小时七十公里，公路和封闭的机动车专用道路为每小时八十公里。","k":"","p":"","j":""},{"i":100783,"c":10,"x":1,"y":1,"q":"在有条件的地点，左弯待转区可设置多条待转车道。","o":["正确","错误"],"a":"A","e":"在有条件的地点，左转弯待转区可设置多条待转车道，增加左转弯的通行能力。“左转弯待转区”是专设在路面较为宽阔而又设有多相位交通信号灯的路口，可有效提高路口机动车通过量，减少车辆车辆滞留。","k":"","p":"","j":""},{"i":100784,"c":10,"x":1,"y":1,"q":"夜间驾车应当全程使用远光灯使视影野更开阔。","o":["正确","错误"],"a":"B","e":"《道路交通安全法实施条例》第五十八条 机动车在夜间没有路灯、照明不良或者遇有雾、雨、雪、沙尘、冰雹等低能见度情况下行驶时，应当开启前照灯，示廓灯和后位灯，但同方向行驶的后车与前车近距离行驶时，不得使用远光灯。机动车雾天行驶应当开启雾灯和危险报警闪光灯。题目说全程使用远光灯，错误。","k":"","p":"","j":""},{"i":100785,"c":10,"x":1,"y":1,"q":"城市道路范围内禁止机动车在桥梁或者非指定的城市道路上试刹车。","o":["正确","错误"],"a":"A","e":"《城市道路管理条例》第二十七条，城市道路范围内禁止下列行为:(一)擅自占用或者挖掘城市道路;(二)履带车、铁轮车或者超重、超高、超长车辆擅自在城市道路上行驶:(三)机动车在桥梁或者非指定的城市道路上试刹车;(四)擅自在城市道路上建设建筑物、构筑物;(五)在桥梁上架设压力在4公斤/平方厘米(0.4兆帕)以上的煤气管道、10千伏以上的高压电力线和其他易燃易爆管线;(六)擅自在桥梁或者路灯设施上设置广告牌或者其他挂浮物;(七)其他损害、侵占城市道路的行为。","k":"","p":"","j":""},{"i":100786,"c":10,"x":1,"y":1,"q":"教育行政部门、学校应当将道路交通安全教育纳入法制教育内容。","o":["正确","错误"],"a":"A","e":"《道路交通安全法》第六条 各级人民政府应当经常进行道路交通安全教育，提高公民的道路交通安全意识。公安机关交通管理部门及其交通警察执行职务时，应当加强道路交通安全法律、法规的宣传，并模范遵守道路交通安全法律、法规。机关、部队、企业事业单位、社会团体以及其他组织，应当对本单位的人员进行道路交通安全教育。 教育行政部门学校应当将道路交通安全教育纳入法制教育的内容，新闻、出版、广播、电视等有关单位，有进行道路交通安全教育的义务。","k":"","p":"","j":""},{"i":100787,"c":10,"x":1,"y":1,"q":"在城市道路上占用、挖掘道路或者跨越、穿越道路架设、增设管线设施以及在道路上设置机动车出入口等影响道路交通安全、畅通的行为，应当征得道路主管部门和公安机关交通管理部门的同意。","o":["正确","错误"],"a":"A","e":"《重庆市道路交通安全条例》第三十三条:在城市道路上占用、挖掘道路或者跨越、穿越道路架设、增设管线设施以及在道路上设置机动车出入口等影响道路交通安全、畅通的行为，应当征得道路主管部门和公安机关交通管理部门的同意。","k":"","p":"","j":""},{"i":100788,"c":10,"x":1,"y":1,"q":"移动作业时，应当在道路上设置可移动的作业标志。","o":["正确","错误"],"a":"A","e":"《重庆市道路交通安全条例》第三十四条道路作业应当遵守下列规定:(一)固定作业应当在作业区范围设置符合国家技术规范、标准的安全防护设施、施工标志和变更车道指示标志、注意危险警告标志等，夜间开启示警灯;移动作业时，应当在路段上设置可移动的作业标志。(二)移动作业车辆、机械应当喷涂明显的反光标志图案，作业时开启示警灯和危险报警闪光灯。(三)作业人员应当按照规定穿着反光服饰、佩戴反光安全帽，注意避让过往车辆。过往车辆对作业车辆和人员应当注意避让。","k":"","p":"","j":""},{"i":100789,"c":10,"x":1,"y":1,"q":"机动车行经漫水路或者漫水桥时应当停车察明水情，辨明道路轮廓，确认安全后，快速通过。","o":["正确","错误"],"a":"B","e":"《重庆市道路交通安全条例》第四十七条:机动车行经漫水路或者漫水桥时，应当停车察明水情，辨清道路轮廓，确认安全后，低速通过。","k":"","p":"","j":""},{"i":100790,"c":10,"x":1,"y":1,"q":"挂车、拖拉机、载运危险品的车辆不得牵引车辆。","o":["正确","错误"],"a":"A","e":"《重庆市道路交通安全条例》第四十四条，牵引车辆应当遵守下列规定:(一)使用软连接牵引的，应当设置示警标识:(二)牵引载运危险品的车辆应当由专业人员操作;(三)挂车、拖拉机、载运危险品的车辆不得牵引车辆;(四)不得牵引轮式专用机械车及其他轮式机械。","k":"","p":"","j":""},{"i":100791,"c":10,"x":1,"y":1,"q":"调整区域交通通行线路的，可以公开征求意见。","o":["正确","错误"],"a":"B","e":"《重庆市道路交通安全条例》第三十二条:调整区域交通通行线路的,应当公开征求意见。不是可以征求，是应当必须征求。","k":"","p":"","j":""},{"i":100792,"c":10,"x":1,"y":1,"q":"道路交通事故分为财产损失事故伤人事故和死亡事故。","o":["正确","错误"],"a":"A","e":"根据《道路交通事故处理程序规定》第三条:道路交通事故分为财产损失事故、伤人事故和死亡事故。","k":"","p":"","j":""},{"i":100793,"c":10,"x":1,"y":1,"q":"驾驶机动车从辅路汇入主路车流前，应注意观察左后方车辆的动态。","o":["正确","错误"],"a":"A","e":"行车中从其他道路汇入车流前，应注意观察后方其他车辆的行车动态，确保行车安全。","k":"","p":"","j":""},{"i":100794,"c":10,"x":1,"y":1,"q":"在没有道路中心线的道路上，前车遇后车发出超车信号时，应当在条件允许的情况下，降低速度、靠右让路。","o":["正确","错误"],"a":"A","e":"《道路交通安全法实施条例》第四十七条:机动车超车时，应当提前开启左转向灯、变换使用远、近光灯或者鸣喇叭。在没有道路中心线或者同方向只有1条机动车道的道路上，前车遇后车发出超车信号时，在条件许可的情况下，应当降低速度、靠右让路。后车应当在确认有充足的安全距离后，从前车的左侧超越，在与被超车辆拉开必要的安全距离后，开启右转向灯，驶回原车道。","k":"","p":"","j":""},{"i":100795,"c":10,"x":1,"y":1,"q":"行驶车道绿色箭头灯亮时，但车辆前方人行横道仍有行人行走，应等行人通过后再起步。","o":["正确","错误"],"a":"A","e":"《道路交通安全法》第四十七条:机动车行经人行横道时，应当减速行驶;遇行人正在通过人行横道，应当停车让行。机动车行经没有交通信号的道路时遇行人横过道路，应当避让。","k":"","p":"","j":""},{"i":100796,"c":10,"x":1,"y":1,"q":"按照交通信号灯指示通行，遇行人横穿可不让行。","o":["正确","错误"],"a":"B","e":"《道路交通安全法》第四十七条:机动车行经人行道时，应当减速行驶:遇行人正在通过人行横道应当停车让行。机动车行经没有交通信号的道路时遇行人横过道路，应当避让。","k":"","p":"","j":""},{"i":100797,"c":10,"x":1,"y":1,"q":"驾驶机动车在高速公路行驶，遇意外情况需紧急停车时，可在行车道上停车。","o":["正确","错误"],"a":"B","e":"《道路交通安全法》第五十二条:机动车在道路上发生故障，需要停车排除故障时，驾驶人应当立即开启危险报警闪光灯，将机动车移至不妨碍交通的地方停放;难以移动的，应当持续开启危险报警闪光灯，并在来车方向设置警告标志等措施扩大示警距离，必要时迅速报警。不得随意在行车道上停车。","k":"","p":"","j":""},{"i":100798,"c":10,"x":1,"y":1,"q":"牵引车、轮式专用机械车、拖拉机,摩托车只能在最右侧车道行驶。","o":["正确","错误"],"a":"A","e":"根据《重庆市道路交通安全条例》第三十七条:重型货车、中型货车、低速货车、三轮汽车、牵引车、轮式专用机械车、拖拉机、摩托车，以及实习期驾驶人驾驶的机动车，应当在慢速车道行驶;其中，牵引车、轮式专用机械车、拖拉机、摩托车只能在最右侧车道行驶。","k":"","p":"","j":""},{"i":100799,"c":10,"x":1,"y":1,"q":"校车载人不得超过核定的人数。","o":["正确","错误"],"a":"A","e":"《校车安全管理条例》第三十四条校车载人不得超过核定的人数,不得以任何理由超员。学校和校车服务提供者不得要求校车驾驶人超员、超速驾驶校车。","k":"","p":"","j":""},{"i":100800,"c":10,"x":1,"y":1,"q":"参加道路交通事故调解时，当事人一方不得超过3人。","o":["正确","错误"],"a":"A","e":"参加损害赔偿调解的人员包括以下人员:(1)道路交通事故当事人及其代理人:A.委托代理人应当出具由委托人签名或者盖章的授权委托书(应当载明委托事项和权限);B.参加调解时当事人一方不得超过三人。(2)道路交通事故车辆所有人或者管理人;(3)公安机关交通管理部门认为有必要参加的其他人员如公安机关交通管理部门聘请的专家、学者，以及公安机关交通管理部门认为调解结果可能对其权益产生影响而通知其参加调解的人员等。","k":"","p":"","j":""},{"i":100801,"c":10,"x":1,"y":1,"q":"机动车在冰雪路面行驶时，驾驶人需要降低车速。","o":["正确","错误"],"a":"A","e":"冰雪路面湿滑，轮胎与路面之间的摩擦力减小，车速过快时车轮容易打滑或者空转，应减速慢行，谨慎驾驶。","k":"","p":"","j":""},{"i":100802,"c":10,"x":1,"y":2,"q":"没有道路中心线的道路，城市道路本市考题限速:()公里/小时。","o":["50","20","40","30"],"a":"D","e":"根据《重庆市道路交通安全条例》第三十九条:机动车在没有限速标志、标线的道路上行驶不得超过下列最高行驶速度:没有道路中心线的道路，城市道路为每小时三十公里，公路为每小时四十公里。","k":"","p":"","j":""},{"i":100803,"c":10,"x":1,"y":2,"q":"发生道路交通事故后，当事人应当开启危险报警灯，夜间还应当开启示廓灯在车身后安全位置摆放()。","o":["指示标牌","锥筒","警示标识","轮胎"],"a":"C","e":"根据《中华人民共和国道路交通安全法实施条例》第六十条规定:机动车在道路上发生故障或者发生交通事故，妨碍交通又难以移动的，应当按照规定开启危险报警闪光灯并在车后50米至100米处设置警告标志，夜间还应当同时开启示廓灯和后位灯。","k":"","p":"","j":""},{"i":100804,"c":10,"x":1,"y":2,"q":"危险品运输车辆车身()应当喷涂或者悬挂醒目的危险警告标志。","o":["前后及两侧","前后","不用喷涂","两侧"],"a":"A","e":"上道路行驶的汽车应当符合下列规定:(一)载货汽车与大、中型载客汽车和出租汽车车身应当喷涂车辆所有人名称或者所在地区，载货汽车与大、中型载客汽车还应当分别喷涂核定载质量、核定载客人数、放大的本车牌号等;(二)配备有效的灭火器具，急救包、故障车警告标志等;(三)重型、中型载货汽车应当按规定安装侧、后防护装置;(四)车身两侧的车窗和前后窗不得放置、粘贴、喷涂妨碍安全驾驶的物品、文字、图案，不得使用镜面反光遮阳膜;(五)道路施工养护、环卫清扫、设施维修及绿化等道路作业车辆，应当符合国家有关技术标准规定;(六)用于公路营运的载客汽车、重型载货汽车半挂牵引车以及危险品运输车辆应当安装、使用符合国家标准的行驶记录仪;(七)危险品运输车辆车身前后及两侧应当喷涂或者悬挂醒目的危险品警告标志。","k":"","p":"","j":""},{"i":100805,"c":10,"x":1,"y":2,"q":"行车中遇前方有障碍物，且对向来车已经接近障碍物时，正确的做法是?","o":["降低速度或停车，让对向来车优先","持续鸣喇叭示意让道","迅速占用车道，迫使对向来车停车让道","交替使用远近光灯提前抢过"],"a":"A","e":"行车中需要借道绕过前方障碍物，但对向来车已经接近障碍物时，应降低速度或停车，让对向来车优先。","k":"","p":"","j":""},{"i":100806,"c":10,"x":1,"y":2,"q":"禁止()载客。","o":["货运机动车","小客车","大客车","公交车"],"a":"A","e":"《道路交通安全法》第五十条规定:禁止货运机动车载客;货运机动车需要附载作业人员的，应当设置保护作业人员的安全措施。","k":"","p":"","j":""},{"i":100807,"c":10,"x":1,"y":2,"q":"夜间会车应当在距相对方向来车()米以外改用近光灯，在窄路、窄桥与非机动车会车时应当使用近光灯。","o":["200","180","150","130"],"a":"C","e":"根据《中华人民共和国道路交通安全法实施条例》第四十八条规定:在没有中心隔离设施或者没有中心线的道路上，机动车遇相对方向来车时应当遵守下列规定:夜间会车应当在距相对方向来车150米以外改用近光灯，在窄路、窄桥与非机动车会车时应当使用近光灯。","k":"","p":"","j":""},{"i":100808,"c":10,"x":1,"y":2,"q":"没有道路中心线的道路,公路限速:\n()公里/小时。","o":["50","20","40","30"],"a":"C","e":"根据《中华人民共和国道路交通安全法实施条例》第四十五条:机动车在道路上行驶不得超过限速标志，标线标明的速度。在没有限速标志、标线的道路上，机动车不得超过下列最高行驶速度:没有道路中心线的道路，城市道路为每小时30公里，公路为每小时40公里;同方向只有1条机动车道的道路，城市道路为每小时50公里，公路为每小时70公里。","k":"","p":"","j":""},{"i":100809,"c":10,"x":1,"y":2,"q":"转弯的非机动车通过有信号灯控制的交叉路口时，应当()。","o":["在直行的车辆和行人前通过","让直行的车辆和行人先通过","有优先通行权","加速前行"],"a":"B","e":"根据《中华人民共和国道路交通安全法实施条例》第六十八条规定:非机动车通过有交通信号灯控制的交叉路口，应当按照下列规定通行:转弯的非机动车让直行的车辆、行人优先通行;遇有前方路口交通阻塞时，不得进入路口:向左转弯时，靠路口中心点的右侧转弯;遇有停止信号时，应当依次停在路口停止线以外。没有停止线的，停在路口以外;向右转弯遇有同方向前车正在等候放行信号时，在本车道内能够转弯的，可以通行;不能转弯的，依次等候。","k":"","p":"","j":""},{"i":100810,"c":10,"x":1,"y":2,"q":"行人在横过道路时，应注意观察道路上通行的车辆。您认为在横过道路时，错误的行为是()。","o":["左右观察，确保安全","一站、二看、三通过","既不左看，也不右看","左看、右看、再左看"],"a":"C","e":"根据《中华人民共和国道路交通安全法实施条例》第七十五条规定:行人横过机动车道，应当从行人过街设施通过;没有行人过街设施的，应当从人行横道通过;没有人行横道的，应当观察来往车辆的情况，确认安全后直行通过，不得在车辆临近时突然加速横穿或者中途倒退、折返。","k":"","p":"","j":""},{"i":100811,"c":10,"x":1,"y":2,"q":"行人通过人行横道，要按人行横道灯的指示通行。小明在通过人行横道线前看到人行横道红灯亮时，应该()。","o":["绕开人行横道通过","迅速通过人行横道","在人行横道线前等待","缓慢通过人行横道"],"a":"C","e":"根据《中华人民共和国道路交通安全法实施条例》第三十九条规定:人行横道信号灯表示:绿灯亮时，准许行人通过人行横道;红灯亮时，禁止行人进入人行横道，但是已经进入人行横道的，可以继续通过或者在道路中心线处停留等候。","k":"","p":"","j":""},{"i":100812,"c":10,"x":1,"y":2,"q":"发生轻微财产损失道路交通事故当事人应当自行撤除现场而未自撤，造成交通严重堵塞的，处200元罚款，并处暂扣机动车驾驶证()月处罚。","o":["1","6","3","12"],"a":"A","e":"《重庆市道路交通安全条例》机动车驾驶人因过错导致交通事故，造成人身伤亡或者财产损失尚不够刑事处罚的，可以处暂扣一个月以上六个月以下机动车驾驶证。发生交通事故，当事人未按本条例第六十条第一、二款规定撤离现场或者阻止他方当事人撤离现场的，处一百元以上二百元以下罚款。造成交通堵塞的，可以并处暂扣一个月机动车驾驶证。","k":"","p":"","j":""},{"i":100813,"c":10,"x":1,"y":2,"q":"公路上发生交通事故的，驾驶人必须在确保安全的原则下，立即组织车上人员疏散到()安全地点，避免发生次生事故。","o":["车后","路边","车前","路外"],"a":"D","e":"根据《道路交通事故处理程序规定》第十三条规定:发生死亡事故、伤人事故的，或者发生财产损失事故且有下列情形之一的，当事人应当保护现场并立即报警:(一)驾驶人无有效机动车驾驶证或者驾驶的机动车与驾驶证载明的准驾车型不符的;(二)驾驶人有饮酒、服用国家管制的精神药品或者麻醉药品嫌疑的;(三)驾驶人有从事校车业务或者旅客运输，严重超过额定乘员载客，或者严重超过规定时速行驶嫌疑的;(四)机动车无号牌或者使用伪造变造的号牌的;(五)当事人不能自行移动车辆的:(六)一方当事人离开现场的;(七)有证据证明事故是由一方故意造成的。驾驶人必须在确保安全的原则下，立即组织车上人员疏散到路外安全地点，避免发生次生事故。驾驶人已因道路交通事故死亡或者受伤无法行动的，车上其他人员应当自行组织疏散。","k":"","p":"","j":""},{"i":100814,"c":10,"x":1,"y":2,"q":"机动车驾驶人违反道路交通安全法律、法规，在一个记分周期内累积记分达到十二分的，应当在()日内到机动车驾驶证核发地或者违法行为地公安机关交通管理部门接受为期七天的道路交通安全法律、法规和相关知识的教育培训。","o":["10","5","7","15"],"a":"D","e":"根据《重庆市道路交通安全条例》第二十四条:驾驶营运机动车的驾驶人应当参加交通安全教育培训，每年不少于二十四学时。机动车驾驶人违反道路交通安全法律、法规，在一个记分周期内累积记分达到十二分的，应当在十五日内到机动车驾驶证核发地或者违法行为地公安机关交通管理部门接受为期七天的道路交通安全法律、法规和相关知识的教育培训。教育培训费用由当事人承担。","k":"","p":"","j":""},{"i":100815,"c":10,"x":1,"y":2,"q":"任何单位或者个人不得转借、冒用伪造、变造、骗领机动车()。","o":["发票","交通信息卡","照片","驾驶证"],"a":"D","e":"根据《重庆市道路交通安全条例》第二十二条规定驾驶机动车应当依法向公安机关交通管理部门申请取得机动车驾驶证，并按规定使用、审验。任何单位或者个人不得转借、冒用、伪造、变造、骗领机动车驾驶证。","k":"","p":"","j":""},{"i":100816,"c":10,"x":1,"y":2,"q":"以下关于驾驶拖拉机的说法不正确的是()。","o":["不得在其他禁止拖拉机通行的道路上行驶","只要是道路，都可以行驶","不得在高速公路上行驶","不得在大中城市中心城区内的道路上行驶"],"a":"B","e":"根据《中华人民共和国道路交通安全法》第五十五条规定:高速公路、大中城市中心城区内的道路，禁止拖拉机通行。其他禁止拖拉机通行的道路，由省、自治区、直辖市人民政府根据当地实际情况规定。在允许拖拉机通行的道路上，拖拉机可以从事货运但是不得用于载人。","k":"","p":"","j":""},{"i":100817,"c":10,"x":1,"y":2,"q":"机动车在设有最高限速标志的道路上行驶时，()。","o":["必须按规定的最高车速行驶","允许超过标明最高时速的10%","可以超过车辆最高设计时速","不得超过标明的最高时速"],"a":"D","e":"根据《中华人民共和国道路交通安全法》第四十二条规定:机动车上道路行驶，不得超过限速标志标明的最高时速。在没有限速标志的路段，应当保持安全车速。夜间行驶或者在容易发生危险的路段行驶，以及遇有沙尘、冰雹、雨、雪、雾、结冰等气象条件时，应当降低行驶速度。","k":"","p":"","j":""},{"i":100818,"c":10,"x":1,"y":2,"q":"在山区冰雪道路上行车，遇前车正在爬坡时，后车应怎样做?","o":["迅速超越前车","等前车通过后再爬坡","鸣喇叭催促前车","紧随其后爬坡"],"a":"B","e":"山区冰雪道路上路面车速低，极易熄火，造成堵塞而且冰雪路面很滑，容易往下滑发生事故，应等前车通过后再通过。","k":"","p":"","j":""},{"i":100819,"c":10,"x":1,"y":2,"q":"在车辆未停稳之前()。","o":["不准开门和上下人","在确保安全的情况下，可以开门和上下人","可以开车门，不准上下人","以上都不对"],"a":"A","e":"根据《重庆市道路交通安全条例》第五十六条规定车辆未停稳前，乘车人不得上下车。乘坐机动车时身体和携带物品不得伸出车外，不得向车外抛洒物品。","k":"","p":"","j":""},{"i":100820,"c":10,"x":1,"y":2,"q":"乘车时要系好安全带，您认为下面哪种说法是正确的()。","o":["前排乘车人必须系好安全带","车速低于每小时60公里时可以不系安全带","坐后排没有必要系安全带","在乡村道路乘车时可以不系安全带"],"a":"A","e":"车辆乘车人员，无论是前排还是后排或驾驶人，在行车过程中都要系好安全带。","k":"","p":"","j":""},{"i":100821,"c":10,"x":1,"y":2,"q":"以下说法正确的是()。","o":["可以驾驶滑板车上道路行驶","叉车、履带式专用机械等不得上道路行驶","只要是道路，轮式专用机械车都可以行驶","拖拉机可以在大中城市中心城区的道路上行驶"],"a":"B","e":"根据《重庆市道路交通安全条例》第五十二条规定叉车、履带式专用机械等不得上道路行驶。轮式专用机械车上道路应当按照公安机关交通管理部门指定的时间和路线行驶。","k":"","p":"","j":""},{"i":100822,"c":10,"x":1,"y":2,"q":"在城市道路上，核定载质量零点六吨以下的小型货车,附载作业人员不得超过()人;其他小型货车附载作业人员不得超过()人。","o":["2,3","2,4","1,3","1,4"],"a":"C","e":"根据《重庆市道路交通安全条例》第四十二条规定机动车载物的载质量、装载长度、宽度、高度应当符合法律、行政法规的规定，确保附载作业人员安全。在城市道路上，核定载质量零点六吨以下的小型货车，附载作业人员不得超过一人;其他小型货车附载作业人员不得超过三人。自卸货车不得附载作业人员。","k":"","p":"","j":""},{"i":100823,"c":10,"x":1,"y":2,"q":"在城市道路上，核定载质量零点六吨以下的小型货车,附载作业人员不得超过()\n人。","o":["三","四","一","二"],"a":"C","e":"根据《重庆市道路交通安全条例》第四十二条规定机动车载物的载质量、装载长度、宽度、高度应当符合法律、行政法规的规定，确保附载作业人员安全，在城市道路上，核定载质量零点六吨以下的小型货车，附载作业人员不得超过一人;其他小型货车附载作业人员不得超过三人。自卸货车不得附载作业人员。","k":"","p":"","j":""},{"i":100824,"c":10,"x":1,"y":2,"q":"快处事故中，转弯未让直行车先行的，承担事故()。","o":["全部责任","主要责任","同等责任","次要责任"],"a":"A","e":"《道路交通安全法实施条例》第五十二条:转弯的机动车让直行的车辆先行;《道路交通事故处理程序规定》第六十条:因一方当事人的过错导致道路交通事故的，承担全部责任。所以转弯未让直行车，要负全部责任。","k":"","p":"","j":""},{"i":100825,"c":10,"x":1,"y":2,"q":"会车前选择的交会位置不理想时正确的是()。","o":["加速行驶，强行通过","减速、低速会车或停车让行","开启远光灯提示对方让行","向左占道，让对方减速让行"],"a":"B","e":"发现交会位置不理想时，应减速或停车让行，以寻找下一个理想会车位置。","k":"","p":"","j":""},{"i":100826,"c":10,"x":1,"y":2,"q":"营运载客车辆应当在规定的停靠站(港)内停车上下乘客，并遵守下列哪些规定以下说法错误的是()。","o":["停车时，车身右侧距路缘不得超过五十厘米","依次进出站","不得使用扩音装置揽客","不得在停靠站(港)内待客、滞留"],"a":"A","e":"根据《重庆市道路交通安全条例》第四十九条:营运载客车辆应当在规定的停靠站(港)内停车上下乘客，并遵守下列规定:(一)依次进出站;(二)停车时，车身右侧距路缘不得超过三十厘米;(三)不得在停靠站(港)内待客、滞留;(四)不得使用扩音装置揽客。","k":"","p":"","j":""},{"i":100827,"c":10,"x":1,"y":2,"q":"机动车在没有限速标志、标线的道路上行驶，没有道路中心线的道路，城市道路为每小时限速()公里。","o":["20","10","30","40"],"a":"C","e":"根据《中华人民共和国道路交通安全法实施条例》第四十五条:机动车在道路上行驶不得超过限速标志、标线标明的速度。在没有限速标志、标线的道路上，机动车不得超过下列最高行驶速度:没有道路中心线的道路，城市道路为每小时30公里，公路为每小时40公里;同方向只有1条机动车道的道路，城市道路为每小时50公里，公路为每小时70公里，","k":"","p":"","j":""},{"i":100828,"c":10,"x":1,"y":2,"q":"掉头、转弯、下陡坡时，机动车最高时速不得超过()。","o":["40公里","15公里","20公里","30公里"],"a":"D","e":"根据《中华人民共和国道路交通安全法实施条例》第四十六条规定:机动车行驶中遇有下列情形之一的，最高行驶速度不得超过每小时30公里，其中拖拉机、电瓶车、轮式专用机械车不得超过每小时15公里:进出非机动车道，通过铁路道口、急弯路、窄路、窄桥时;掉头、转弯、下陡坡时;遇雾、雨、雪沙尘、冰雹，能见度在50米以内时;在冰雪、泥泞的道路上行驶时;牵引发生故障的机动车时。","k":"","p":"","j":""},{"i":100829,"c":10,"x":1,"y":2,"q":"高速公路应当标明车道的行驶速度，最高车速不得超过每小时120公里，最低车速不得低于每小时()公里。","o":["60","50","40","70"],"a":"A","e":"《道路交通安全法实施条例》第七十八条 高速公路应当标明车道的行驶速度，最高车速不得超过每小时120公里，最低车速不得低于每小时60公里。在高速公路上行驶的小型载客汽车最高车速不得超过每小时120公里，其他机动车不得超过每小时100公里摩托车不得超过每小时80公里。","k":"","p":"","j":""},{"i":100830,"c":10,"x":1,"y":2,"q":"同方向只有1条机动车道的道路城市道路限速:()公里/每小时。","o":["30","40","20","50"],"a":"D","e":"根据《重庆市道路交通安全条例》第三十九条:机动车在道路上行驶不得超过限速标志、标线标明的速度。机动车在没有限速标志、标线的道路上行驶不得超过下列最高行驶速度:(一)没有道路中心线的道路，城市道路为每小时三十公里，公路为每小时四十公里;(二)同方向只有一条机动车道的道路城市道路为每小时五十公里，公路和封闭的机动车专用道路为每小时七十公里;(三)同方向划有两条以上机动车道的道路，城市道路为每小时七十公里,公路和封闭的机动车专用道路为每小时八十公里。","k":"","p":"","j":""},{"i":100831,"c":10,"x":1,"y":2,"q":"没有非机动车道的，自行车、电动自行车在距道路右侧边缘()米的范围内行驶。","o":["二点二","二","一点五","二点五"],"a":"B","e":"根据《重庆市道路交通安全条例》第五十四条:非机动车在道路上行驶应当遵守下列规定:(一)有非机动车道的,在非机动车道内行驶:没有非机动车道的，自行车、电动自行车在距道路右侧边缘两米的范围内行驶，残疾人机动轮椅车、人力车、三轮车、畜力车在距道路右侧边缘二点五米的范围内行驶。","k":"","p":"","j":""},{"i":100832,"c":10,"x":1,"y":2,"q":"没有人行道的，行人应当在距道路边缘()米的范围内行走。","o":["一点五","一","二","二点五"],"a":"A","e":"根据《重庆市道路交通安全条例》第五十五条:行人应当在人行道上行走;没有人行道的，应当在距道路边缘一点五米的范围内行走。","k":"","p":"","j":""},{"i":100833,"c":10,"x":1,"y":2,"q":"重型、中型载货汽车，半挂车载物高度从地面起不得超过()米。","o":["5","4","6","4.5"],"a":"B","e":"根据《中华人民共和国道路交通安全法实施条例》第五十四条 机动车载物不得超过机动车行驶证上核定的载质量，装载长度、宽度不得超出车厢，并应当遵守下列规定:(一)重型、中型载货汽车，半挂车载物，高度从地面起不得超过4米，载运集装箱的车辆不得超过4.2米;(二)其他载货的机动车载物，高度从地面起不得超过2.5米;(三)摩托车载物，高度从地面起不得超过1.5米，长度不得超出车身0.2米两轮摩托车载物宽度左右各不得超出车把0.15米三轮摩托车载物宽度不得超过车身。载客汽车除车身外部的行李架和内置的行李箱外，不得载货。载客汽车行李架载货，从车顶起高度不得超过0.5米从地面起高度不得超过4米。","k":"","p":"","j":""},{"i":100834,"c":10,"x":1,"y":2,"q":"机动车转弯、变更车道、超车、掉2头、靠路边停车时，应当提前()米开启转向灯。","o":["50","40","70","30"],"a":"D","e":"根据《重庆市道路交通安全条例》第四十条规定:机动车在夜间或者在隧道内行驶时，或者在遇有雾、雨、雪、沙尘、冰雹等低能见度情况下行驶时，应当开启前照灯、示廓灯和后位灯;在雾天行驶时，应当开启雾灯和危险报警闪光灯。机动车转弯、变更车道、超车、掉头、靠路边停车时，应当提前三十米开启转向灯。","k":"","p":"","j":""},{"i":100835,"c":10,"x":1,"y":2,"q":"机动车行经人行横道时，()；遇行\n人正在通过人行横道，()。","o":["应当减速行驶，可以停车让行","可以减速行驶，可以停车让行","应当减速行驶，应当停车让行","可以减速行驶，应当停车让行"],"a":"C","e":"根据《重庆市道路交通安全条例》第四十八条:机动车行经人行横道时，应当减速行驶:遇行人正在通过人行横道，应当停车让行。机动车行经没有交通信号的道路时，遇行人横过道路，应当避让。","k":"","p":"","j":""},{"i":100836,"c":10,"x":1,"y":2,"q":"夜间当路口红灯不停闪烁时，它表示的是什么含义?","o":["车辆不准通行，但行人可以通行","车辆和行人必须让行","信号灯故障","车辆和行人不准通行"],"a":"B","e":"红灯亮表示车辆和行人不准通行，一直闪烁，说明该路口有紧急情况，表示车辆和行人必须让行。","k":"","p":"","j":""},{"i":100837,"c":10,"x":1,"y":2,"q":"下列哪些非机动车上道路行驶可以载人()。","o":["三轮车","未成年人驾驶的自行车","电动自行车","残疾人机动轮椅车"],"a":"A","e":"根据《重庆市道路交通安全条例》第五十四条第(八)款:三轮车、畜力车载人不得超过核定载人数。","k":"","p":"","j":""},{"i":100838,"c":10,"x":1,"y":2,"q":"除以下哪些机动车之外应当在慢速车道行驶()。","o":["低速货车","中型货车","三轮汽车","大型客车"],"a":"D","e":"根据《重庆市道路交通安全条例》第三十七条:重型货车、中型货车、低速货车、三轮汽车、牵引车、轮式专用机械车、拖拉机、摩托车，以及实习期驾驶人驾驶的机动车，应当在慢速车道行驶。","k":"","p":"","j":""},{"i":100839,"c":10,"x":1,"y":2,"q":"下列哪种车辆只能在最右侧车道行驶?","o":["重型货车","小型汽车","摩托车","三轮汽车"],"a":"C","e":"根据《重庆市道路交通安全条例》第三十七条:牵引车、轮式专用机械车、拖拉机、摩托车只能在最右侧车道行驶。","k":"","p":"","j":""},{"i":100840,"c":10,"x":1,"y":2,"q":"在没有划分机动车车道、非机动车道和人行道的道路上，以下应当在道路两侧通行的有()。","o":["普通两轮摩托车","行人","大型客车","大型货车"],"a":"B","e":"《道路交通安全法》第三十六条 根据道路条件和通行需要，道路划分为机动车道、非机动车道和人行道的机动车、非机动车、行人实行分道通行。没有划分机动车道、非机动车道和人行道的，机动车在道路中间通行，非机动车和行人在道路两侧通行。","k":"","p":"","j":""},{"i":100841,"c":10,"x":1,"y":2,"q":"以下说法错误的是()。","o":["电动自行车、残疾人机动轮椅车、未成年人驾驶的自行车不得载人","驾驶非机动车在道路上行驶，行经人行横道时避让行人","自行车在各区县(自治县)政府所在地的城市建成区行驶，可以载人","驾驶非机动车在道路上行驶，不得在车行道上停车滞留"],"a":"C","e":"根据《重庆市道路交通安全条例》第五十四条:非机动车在道路上行驶应当遵守下列规定:(一)有非机动车道的，在非机动车道内行驶:没有非机动车道的，自行车、电动自行车在距道路右侧边缘两米的范围内行驶，残疾人机动轮椅车、人力车、三轮车、畜力车在距道路右侧边缘二点五米的范围内行驶。(二)行经人行横道时避让行人。(三)不得在车行道上停车滞留。(四)设有转向灯的，转弯前开启转向灯:无转向灯的，伸手示意。(五)制动器失效的，不得在道路上行驶。(六)电动自行车、残疾人机动轮椅车、未成年人驾驶的自行车不得载人。(七)自行车在各区县(自治县)政府所在地的城市建成区行驶不得载人:其他地区驾驶自行车可以搭载一人，搭载六周岁以下儿童应当设置固定座椅。(八)三轮车畜力车载人不得超过核定载人数。","k":"","p":"","j":""},{"i":100842,"c":10,"x":1,"y":2,"q":"发生轻微财产损失道路交通事故当事人应当自行撤除现场而未自撤，造成交通严重堵塞的，处()元罚款。","o":["200","300","500","100"],"a":"A","e":"《道路交通事故处理程序规定》第十九条:机动车与机动车、机动车与非机动车发生财产损失事故，当事人应当在确保安全的原则下，采取现场拍照或者标划事故车辆现场位置等方式固定证据后，立即撤离现场，将车辆移至不妨碍交通的地点，再协商处理损害赔偿事宜，但有本规定第十三条第一款情形的除外。非机动车与非机动车或者行人发生财产损失事故，当事人应当先撤离现场，再协商处理损害赔偿事宜。对应当自行撤离现场而未撤离的，交通警察应当责令当事人撤离现场;造成交通堵塞的对驾驶人处以200元罚款。","k":"","p":"","j":""},{"i":100843,"c":10,"x":1,"y":2,"q":"连续驾驶汽车超过4小时后，就必须停车休息一下，休息时间()。","o":["最多10分钟","最多15分钟","最少20分钟","最少15分钟"],"a":"C","e":"《道路交通安全法实施条例》规定:连续驾驶机动车超过4小时未停车休息或者停车休息时间少于20分钟。","k":"","p":"","j":""},{"i":100844,"c":10,"x":1,"y":2,"q":"超车需从前车左侧超越，以下说法正确的是什么?","o":["便于观察，有利于安全","右侧为快速车道","左侧为慢车道","我国实行左侧通行原则"],"a":"A","e":"我国实行右侧通行原则，左侧为快速车道，右侧为慢速车道。选项描述中只有“便于观察，有利于安全”的说法是正确的。","k":"","p":"","j":""},{"i":100845,"c":10,"x":1,"y":2,"q":"右侧行驶、分道行驶属于以下哪种路权范畴?","o":["完全路权","部分路权","空间路权","时间路权"],"a":"C","e":"空间路权包含静态与动态两大类，如在路边合法停车，就是享有静态空间路权。动态空间路权是指在有通行路权的前提下，车辆可以合法行驶的长度(即距离)、宽度与高度。所以右侧行驶、分道行驶属于空间路权。","k":"","p":"","j":""},{"i":100846,"c":10,"x":1,"y":2,"q":"发生道路交通事故后，驾驶人必须在确保安全的原则下，立即()。","o":["组织车上人员疏散到路外安全地点","逃离现场","离开车辆","打电话报警"],"a":"A","e":"发生交通事故后，驾驶人必须在确保安全的原则下立即组织车上人员疏散到路外安全地点，避免发生次生事故。驾驶人已因道路交通事故死亡或者受伤无法行动的，车上其他人员应当自行组织疏散。","k":"","p":"","j":""},{"i":100847,"c":10,"x":1,"y":2,"q":"行人大风天气在农村公路边行走遇到车辆驶来时，为了躲避扬尘，()是最危险的。","o":["尽量靠公路边走","在路边停下来躲避","横过公路","戴眼镜和口罩"],"a":"C","e":"行人在公路行走，尽量靠路边行驶，不得横过公路要注意安全。","k":"","p":"","j":""},{"i":100848,"c":10,"x":1,"y":2,"q":"转弯的机动车让()的车辆先行。","o":["左行","右行","直行","前行"],"a":"C","e":"《道路交通安全法实施条例》第五十二条，机动车通过没有交通信号灯控制也没有交通警察指挥的交叉路口，除应当遵守第五十一条第(二)项、第(三)项的规定外，还应当遵守下列规定:(一)有交通标志、标线控制的，让优先通行的一方先行;(二)没有交通标志、标线控制的，在进入路口前停车瞭望，让右方道路的来车先行;(三)转弯的机动车让直行的车辆先行;(四)相对方向行驶的右转弯的机动车让左转弯的车辆先行。","k":"","p":"","j":""},{"i":100849,"c":10,"x":1,"y":2,"q":"车辆在交叉路口有优先通行权的遇有车辆抢行时，应怎样做?","o":["加速行驶，强行通过","鸣喇叭催促前车让行","按优先权规定正常行驶不予避让","减速避让或者停车让行"],"a":"D","e":"安全驾驶，准礼貌让行。对方非要抢行，为了安全还是要减速避让，必要时停车让行。","k":"","p":"","j":""},{"i":100850,"c":10,"x":1,"y":2,"q":"机动车在以下情况不应当提前开启右转向灯的是()。","o":["驶离停车地点","超车完毕驶回原车道","向右变更车道","向右转弯"],"a":"A","e":"《道路交通安全法实施条例》第五十七条，机动车应当按照下列规定使用转向灯:(一)向左转弯、向左变更车道、准备超车、驶离停车地点或者掉头时，应当提前开启左转向灯;(二)向右转弯、向右变更车道、超车完毕驶回原车道、靠路边停车时，应当提前开启右转向灯。","k":"","p":"","j":""},{"i":100851,"c":10,"x":1,"y":2,"q":"发生轻微财产损失道路交通事故当事人应当自行撤除现场而未自撤，造成道路严重堵塞的，且拒不听从民警劝导撤除现场，依据《治安管理处罚法》第50条第2款规定，处()日拘留?","o":["5到10","5到7","12","1到2"],"a":"A","e":"《治安管理处罚法》第五十条，有下列行为之一的处警告或者二百元以下罚款;情节严重的，处五日以上十日以下拘留，可以并处五百元以下罚款:(一)拒不执行人民政府在紧急状态情况下依法发布的决定、命令的;(二)阻碍国家机关工作人员依法执行职务的;(三)阻碍执行紧急任务的消防车、救护车工程抢险车、警车等车辆通行的;(四)强行冲闯公安机关设置的警戒带、警戒区的。阻碍人民警察依法执行职务的，从重处罚。","k":"","p":"","j":""},{"i":100852,"c":10,"x":1,"y":2,"q":"小芳骑自行车回家，在一个没有信号灯控制的交叉路口由南向东右转弯时，遇小强骑自行车由北向东左转弯，正确的通行顺序是()。","o":["小芳和小强同时通行","小芳让小强先行","谁抢先谁通行","小强让小芳先行"],"a":"B","e":"右转让左转，所以应该是小芳让小强先行。","k":"","p":"","j":""},{"i":100853,"c":10,"x":1,"y":2,"q":"道路上同方向左右两侧的机动车向2同一方向变更车道时，以下说法正确的是()。","o":["互不相让","右侧车道的机动车让左侧车道机动车先行","左侧车道的机动车让右侧车道机动车先行","以上说法都不正确"],"a":"B","e":"《重庆市道路交通安全条例>第四十一条:道路上同方向左右两侧车道的机动车向同一车道变更车道时，右侧车道的机动车让左侧车道的机动车先行。","k":"","p":"","j":""},{"i":100854,"c":10,"x":1,"y":2,"q":"车辆通过凹凸路面时，如何操作?","o":["低速缓慢平稳通过","加速通过","熄火靠惯性通过","保持原速通过"],"a":"A","e":"遇到凹凸不平的路面，要减速缓慢通过，安全第一。","k":"","p":"","j":""},{"i":100855,"c":10,"x":1,"y":1,"q":"在道路同方向划有两条以上机动车道的，左侧为快速车道，右侧为慢速车道。未达到快速车道规定的行驶速度的，应当在慢速车道行驶。","o":["正确","错误"],"a":"A","e":"《道路交通安全法实施条例》规定:在道路同方向划有2条以上机动车道的，左侧为快速车道，右侧为慢速车道。在快速车道行驶的机动车应当按照快速车道规定的速度行驶，未达到快速车道规定的行驶速度的，应当在慢速车道行驶。","k":"","p":"","j":""},{"i":100856,"c":10,"x":1,"y":1,"q":"如图所示，在这种情况下直行车辆应停车等待。","o":["正确","错误"],"a":"A","e":"由图可知，黄灯亮时，已越过停止线的车辆可以继续通行;其它情况需要停车等待，","k":"","p":"43358.jpg","j":""},{"i":100857,"c":10,"x":1,"y":1,"q":"如图所示，驾驶机动车此时应当停车等待。","o":["正确","错误"],"a":"A","e":"图中前方人行道上还有行人通过，此时驾驶人要停车等待，礼让行人，安全驾驶。","k":"","p":"40148.jpg","j":""},{"i":100858,"c":10,"x":1,"y":2,"q":"如图所示，行驶过程中遇前方有障碍物的情况怎么办?","o":["减速，在确认安全的情况下向右变更车道","抢在红车前绕过障碍物","开启左转向灯","借对向车道绕过障碍物"],"a":"A","e":"《道路交通安全法实施条例》第四十八条，在有障碍的路段，无障碍的一方先行;但有障碍的一方已驶入障碍路段而无障碍的一方未驶入时，有障碍的一方先行。","k":"","p":"874.jpg","j":""},{"i":100859,"c":10,"x":1,"y":2,"q":"如图所示，道路上划设这种标线的车道内允许下列哪类车辆通行?","o":["私家车","公交车","出租车","公务用车"],"a":"B","e":"《道路交通安全法》规定:道路划设专用车道的，在专用车道内，只准许规定的车辆通行，其他车辆不得进入专用车道内行驶","k":"","p":"picture_8.jpg","j":""},{"i":100860,"c":10,"x":1,"y":1,"q":"机动车驾驶人应当参加机动车驾驶人组织开展的交通安全教育培训，每年不少于二十四学时。","o":["正确","错误"],"a":"B","e":"《重庆市道路交通安全条例》第二十四条:驾驶营运机动车的驾驶人应当参加交通安全教育培训，每年不少于二十四学时。","k":"","p":"","j":""},{"i":100861,"c":10,"x":1,"y":1,"q":"发生人身伤亡的交通事故，车辆驾驶人应当保护现场，立即抢救受伤人员，并迅速报警等候处理。","o":["正确","错误"],"a":"A","e":"《道路交通安全法》第七十条，在道路上发生交通事故，车辆驾驶人应当立即停车，保护现场;造成人身伤亡的，车辆驾驶人应当立即抢救受伤人员，并迅速报告执勒的交通警察或者公安机关交通管理部门。因抢救受伤人员变动现场的，应当标明位置。乘车人、过往车辆驾驶人、过往行人应当予以协助。","k":"","p":"","j":""},{"i":100862,"c":10,"x":1,"y":1,"q":"牵引车、轮式专用机械车、拖拉机、摩托车可以随意行驶。","o":["正确","错误"],"a":"B","e":"根据《重庆市道路交通安全条例》第三十七条规定重型货车、中型货车、低速货车、三轮汽车、牵引车、轮式专用机械车、拖拉机、摩托车，以及实习期驾驶人驾驶的机动车，应当在慢速车道行驶;其中，牵引车、轮式专用机械车、拖拉机、摩托车只能在最右侧车道行驶。","k":"","p":"","j":""},{"i":100863,"c":10,"x":1,"y":1,"q":"在道路同方向划有两条以上机动车道的，右侧为快速车道，左侧为慢速车道。","o":["正确","错误"],"a":"B","e":"《道路交通安全法实施条例》第四十四条:在道路同方向划有2条以上机动车道的，左侧为快速车道，右侧为慢速车道。","k":"","p":"","j":""},{"i":100864,"c":10,"x":1,"y":1,"q":"发生道路交通事故后，因抢救受伤人员变动现场的，驾驶人可以标明位置。","o":["正确","错误"],"a":"B","e":"《道路交通安全法》第七十条:在道路上发生交通事故，车辆驾驶人应当立即停车，保护现场:造成人身伤亡的，车辆驾驶人应当立即抢救受伤人员，并迅速报告执勤的交通警察或者公安机关交通管理部门。因抢救受伤人员变动现场的，应当标明位置乘车人、过往车辆驾驶人、过往行人应当予以协助。","k":"","p":"","j":""},{"i":100865,"c":10,"x":1,"y":1,"q":"进入导向车道后，可以变更车道。","o":["正确","错误"],"a":"B","e":"《重庆市道路交通安全条例》规定:机动车进入实线标线划分车道的路段后，以及进入导向车道后，不得变更车道。","k":"","p":"","j":""},{"i":100866,"c":10,"x":1,"y":1,"q":"城市道路范围内禁止机动车在桥梁或者非指定道路上试刹车。","o":["正确","错误"],"a":"A","e":"《城市道路管理条例》第二十七条:城市道路范围内禁止机动车在桥梁或者非指定的城市道路上试刹车。","k":"","p":"","j":""},{"i":100867,"c":10,"x":1,"y":1,"q":"驾驭蓄力车，应当使用驯服的牲蓄;驾驭蓄力车横过道路时，驾驭人应当下车牵引牲畜;驾驭人离开车辆时，应当栓系牲畜。","o":["正确","错误"],"a":"A","e":"《道路交通安全法》第六十条:驾驭畜力车，应当使用驯服的牲畜;驾驭畜力车横过道路时，驾驭人应当下车牵引牲畜;驾驭人离开车辆时，应当拴系牲畜。","k":"","p":"","j":""},{"i":100868,"c":10,"x":1,"y":1,"q":"拖拉机封存、报废应到交管部门办理手续。","o":["正确","错误"],"a":"B","e":"《农用拖拉机及驾驶员安全监理规定》第二十三条:拖拉机封存、报废，均应到农机监理机构办理手续，交回行驶证和号牌。","k":"","p":"","j":""},{"i":100869,"c":10,"x":1,"y":1,"q":"新建横跨道路的管线、道路附属设施、交通管理设施等，从地面起净高不得低于五点五米。法律、行政法规或者国家技术规范另有规定的，从其规定。","o":["正确","错误"],"a":"A","e":"新建横跨道路的管线、道路附属设施、交通管理设施等，从地面起净高不得低于五点五米。法律、行政法规或者国家技术规范另有规定的，从其规定。","k":"","p":"","j":""},{"i":100870,"c":10,"x":1,"y":1,"q":"遇高速公路限速标志标明的车速与《道路交通安全法》对车道行驶车速的规定不一致的，应按照车道规定的车速行驶。","o":["正确","错误"],"a":"B","e":"《道路交通安全法实施条例》第七十八条:道路限速标志标明的车速与上述车道行驶车速的规定不一致的，按照道路限速标志标明的车速行驶。","k":"","p":"","j":""},{"i":100871,"c":10,"x":1,"y":1,"q":"拖拉机、电瓶车、轮式专用机械车在进出非机动车道，通过铁路道口急转弯、窄路、窄桥时，应不得超过每小时25公里。","o":["正确","错误"],"a":"B","e":"《道路交通安全法实施条例》第四十六条:机动车行驶中遇有下列情形之一的，最高行驶速度不得超过每小时30公里，其中拖拉机、电瓶车、轮式专用机械车不得超过每小时15公里:(一)进出非机动车道，通过铁路道口、急弯路、窄路、窄桥时;(二)掉头、转弯、下陡坡时。","k":"","p":"","j":""},{"i":100872,"c":10,"x":1,"y":1,"q":"在草场、农田使用的机动车可以不用缴纳交强险。","o":["正确","错误"],"a":"B","e":"《机动车交通事故责任强制保险条例》第二条:在中华人民共和国境内道路上行驶的机动车的所有人或者管理人，应当依照《中华人民共和国道路交通安全法》的规定投保机动车交通事故责任强制保险。","k":"","p":"","j":""},{"i":100873,"c":10,"x":1,"y":1,"q":"驾驶自行车，搭载十二周岁以下儿童应当设置固定座椅。","o":["正确","错误"],"a":"B","e":"驾驶自行车可以搭载六周岁以下儿童应当设置固定座椅。","k":"","p":"","j":""},{"i":100874,"c":10,"x":1,"y":1,"q":"农用车、拉草车在进出非机动车道，通过铁道道口急转弯、窄路、窄桥时，应不得超过每小时35公里。","o":["正确","错误"],"a":"B","e":"农用车、拉草车在进出非机动车道，通过铁道道口急转弯、窄路、窄桥时，应不得超过每小时15公里。","k":"","p":"","j":""},{"i":100875,"c":10,"x":1,"y":1,"q":"车道一般分为机动车道和非机动车道、蓄力车道三种。","o":["正确","错误"],"a":"B","e":"《道路交通安全法》第三十六条:根据道路条件和通行需要，道路划分为机动车道、非机动车道和人行道的，机动车、非机动车、行人实行分道通行。没有划分机动车道、非机动车道和人行道的，机动车在道路中间通行，非机动车和行人在道路两侧通行。","k":"","p":"","j":""},{"i":100876,"c":10,"x":1,"y":1,"q":"叉车、履带式专用机械不得上道路行驶。","o":["正确","错误"],"a":"A","e":"叉车、履带式专用机械不得上道路行驶。","k":"","p":"","j":""},{"i":100879,"c":10,"x":1,"y":1,"q":"农用车、拉草车、拖拉机在道路上行驶遇后方车辆发出超车信号时，在条件许可的情况下应当降低速度，靠右让路。","o":["正确","错误"],"a":"A","e":"《道路交通安全法实施条例》第四十七条:机动车超车时，应当提前开启左转向灯、变换使用远、近光灯或者鸣喇叭。在没有道路中心线或者同方向只有1条机动车道的道路上，前车遇后车发出超车信号时，在条件许可的情况下，应当降低速度、靠右让路。后车应当在确认有充足的安全距离后，从前车的左侧超越，在与被超车辆拉开必要的安全距离后，开启右转向灯，驶回原车道。","k":"","p":"","j":""},{"i":100881,"c":10,"x":1,"y":1,"q":"公安机关交通管理部门负责拖拉机号牌、行驶证、驾驶证核发。","o":["正确","错误"],"a":"B","e":"《拖拉机和联合收割机驾驶证管理规定》第三条县级人民政府农业机械化主管部门负责本行政区域内拖拉机和联合收割机驾驶证的管理，其所属的农机安全监理机构(以下简称农机监理机构)承担驾驶证申请受理、考试、发证等具体工作。县级以上人民政府农业机械化主管部门及其所属的农机监理机构负责驾驶证业务工作的指导、检查和监督。","k":"","p":"","j":""},{"i":100882,"c":10,"x":1,"y":1,"q":"农用车、拉草车在道路上行驶，遇雾、雨、雪、沙尘、冰雹，能见度在50米以内，应不得超过每小时20公里。","o":["正确","错误"],"a":"B","e":"《道路交通安全法实施条例》第四十六条:机动车行驶中遇有下列情形之一的，最高行驶速度不得超过每小时30公里，其中拖拉机、电瓶车、轮式专用机械车不得超过每小时15公里:遇雾、雨、雪、沙尘、冰雹，能见度在50米以内时。","k":"","p":"","j":""},{"i":100883,"c":10,"x":1,"y":1,"q":"拉草车在路边停车时，应靠近路右边缘，打开危险警示灯并在50--150米后摆放危险警示标志。","o":["正确","错误"],"a":"A","e":"拉草车在路边停车时，应靠近路右边缘，打开危险警示灯并在50--150米后摆放危险警示标志。","k":"","p":"","j":""},{"i":100884,"c":10,"x":1,"y":1,"q":"驾驶农用车、拉草车、拖拉机在道路上行驶超越前方同方向车辆时，应当提前开启左转向灯、变换使用远、近光灯或者鸣喇叭。","o":["正确","错误"],"a":"A","e":"《道路交通安全法实施条例》第四十七条:机动车超车时，应当提前开启左转向灯、变换使用远、近光灯或者鸣喇叭。在没有道路中心线或者同方向只有1条机动车道的道路上，前车遇后车发出超车信号时，在条件许可的情况下，应当降低速度、靠右让路。后车应当在确认有充足的安全距离后，从前车的左侧超越，在与被超车辆拉开必要的安全距离后，开启右转向灯，驶回原车道。","k":"","p":"","j":""},{"i":100885,"c":10,"x":1,"y":2,"q":"北方农牧区夏秋季，什么时间段道路易起雾?","o":["早6时--9时","凌晨1时--3时","15时--17时","13时--15时"],"a":"A","e":"北方农牧区夏秋季，早6时---9时道路易起雾。","k":"","p":"","j":""},{"i":100886,"c":10,"x":1,"y":2,"q":"电动自行车国家标准规定时速不超过( )","o":["每小时25公里","每小时35公里","每小时40公里","每小时30公里"],"a":"A","e":"《电动自行车安全技术规范(GB17761-2018)》规定，要求电动车最高设计时速不超过25Km/h。","k":"","p":"","j":""},{"i":100887,"c":10,"x":1,"y":2,"q":"发生轻微财产损失道路交通事故，当事人应当自行撤除现场而未自撤，造成交通严重堵塞的，处(  )元罚款。","o":["300","500","200","100"],"a":"C","e":"《道路交通事故处理程序规定》第十九条:对应当自行撤离现场而未撤离的，交通警察应当责令当事人撤离现场;造成交通堵塞的，对驾驶人处以200元罚款。","k":"","p":"","j":""},{"i":100888,"c":10,"x":1,"y":2,"q":"机动车在没有限速标志、标线的道路上行使，同方向划有两条以上机动车道的道路，城市道路为每小时限速()公里。","o":["80","50","70","60"],"a":"C","e":"内蒙古自治区实施《中华人民共和国道路交通安全法》办法第三十八条:机动车上道路行驶，不得超过限速标志、标线标明的速度。在同方向划有两条以上机动车道且没有限速标志、标线的路段，高速公路最高速度为每小时120公里，普通公路最高速度为每小时90公里，城市道路最高速度为每小时70公里;单位、居民区内，最高速度为每小时15公里。","k":"","p":"","j":""},{"i":100889,"c":10,"x":1,"y":2,"q":"机动车在道路上变更车道需要注意什么?","o":["不能影响其他车辆正常行驶","进入左侧车道时适当减速","开启转向灯迅速向左转向","尽快加速进入左侧车道"],"a":"A","e":"《道路交通安全法实施条例》规定:在道路同方向划有2条以上机动车道的，变更车道的机动车【不得影响相关车道内行驶的机动车的正常行驶】开启转向灯后，应观察情况，确保安全后再转向不能迅速转向。","k":"","p":"","j":""},{"i":100890,"c":10,"x":1,"y":2,"q":"机动车驾驶人违反道路交通安全法律、法规，在一个记分周期内累积分达到十二分的应当在(  )日内到机动车驾驶证核发地或者违法行为地公安机关交通管理部门接受为期七日的道路交通安全法律、法规和相关知识的教育培训。","o":["7","15","5","10"],"a":"B","e":"机动车驾驶人违反道路交通安全法律、法规，在一个记分周期内累积分达到十二分的，应当在15日内到机动车驾驶证核发地或者违法行为地公安机关交通管理部门接受为期七日的道路交通安全法律、法规和相关知识的教育培训。","k":"","p":"","j":""},{"i":100891,"c":10,"x":1,"y":2,"q":"右侧行驶、分道行驶属于以下哪种路权( )范畴?","o":["时间路权","完全路权","部分路权","空间路权"],"a":"D","e":"右侧行驶、分道行驶属于空间路权范畴。","k":"","p":"","j":""},{"i":100892,"c":10,"x":1,"y":2,"q":"以下说法正确的是( )。","o":["又车、履带式专用机械等不得上道路行驶","可以驾驶滑板车上道路行驶","只要是道路，轮式专用机械车都可以行驶","拖拉机可以在大中城市中心城区内的道路上行驶"],"a":"A","e":"又车、履带式专用机械等不得上道路行驶。","k":"","p":"","j":""},{"i":100893,"c":10,"x":1,"y":2,"q":"拖拉机后斗允许载人吗?","o":["改装后允许","不允许","允许","不确定"],"a":"B","e":"《道路交通安全法》第五十五条:在允许拖拉机通行的道路上，拖拉机可以从事货运，但是不得用于载人。","k":"","p":"","j":""},{"i":100894,"c":10,"x":1,"y":2,"q":"设计最高时速低于( )公里的机动车，不得进入高速公路。","o":["80","60","50","70"],"a":"D","e":"《道路交通安全法》第六十七条:行人、非机动车、拖拉机、轮式专用机械车、铰接式客车、全挂拖斗车以及其他设计最高时速低于七十公里的机动车，不得进入高速公路。","k":"","p":"","j":""},{"i":100895,"c":10,"x":1,"y":2,"q":"行人大风天气在农村公路边行走，遇到车辆驶来时，为了躲避扬尘(  )是最危险的。","o":["在路边停下来躲避","横过公路","尽量靠公路边走","戴眼镜和口罩"],"a":"B","e":"行人大风天气在农村公路边行走，遇到车辆驶来时，为了躲避扬尘横过公路是最危险的。","k":"","p":"","j":""},{"i":100896,"c":10,"x":1,"y":2,"q":"在草原、田间等自然路醉酒驾驶机动车的，应受到什么样的处罚?","o":["处2年以下徒刑","处2年以上徒刑","处管制，并处罚金","吊销机动车驾驶证、依法追究刑事责任"],"a":"D","e":"在草原、田间等自然路醉酒驾驶机动车的，应受到吊销机动车驾驶证、依法追究刑事责任的处罚。","k":"","p":"","j":""},{"i":100897,"c":10,"x":1,"y":2,"q":"拖拉机、电瓶车、轮式专用机械车在冰雪、泥泞的道路上行驶时，应不得超过每小时多少公里?","o":["每小时30公里","每小时25公里","每小时20公里","每小时15公里"],"a":"D","e":"《道路交通安全法实施条例》第四十六条:在冰雪、泥泞的道路上行驶时，拖拉机、电瓶车、轮式专用机械车不得超过每小时15公里。","k":"","p":"","j":""},{"i":100898,"c":10,"x":1,"y":2,"q":"小型拖拉的机动力要求应小于多少千瓦?","o":["14.7千瓦","15.7千瓦","19千瓦","20千瓦"],"a":"A","e":"小型拖拉的机动力要求应小于14.7千瓦。","k":"","p":"","j":""},{"i":100899,"c":10,"x":1,"y":2,"q":"上路行驶的农用机械车，发生交通事故后，由什么部门管辖?","o":["农机主管部门","工商行政管理部门","公安交通管理部门","交通行政部门"],"a":"C","e":"上路行驶的农用机械车，发生交通事故后，由公安交通管理部门管辖。","k":"","p":"","j":""},{"i":100900,"c":10,"x":1,"y":2,"q":"申请机动车检验合格标志的，应当2提供机动车安全技术检验合格证明，申领时间超过机动车安全技术检验合格日期()的，应当重新进行安全技术检验。","o":["10日","30日","60日","90日"],"a":"C","e":"《浙江省实施(中华人民共和国道路交通安全法)办法》第六条:申领机动车检验合格标志的，应当提供机动车安全技术检验合格证明，申领时间超过机动车安全技术检验合格日期六十日的，应当重新进行安全技术检验。","k":"","p":"","j":""},{"i":101046,"c":10,"x":1,"y":1,"q":"驾驶人存在无牌、未交保险或者饮酒、吸毒行为的，不可使用“视频快处”。","o":["正确","错误"],"a":"A","e":"下列4种情形不适用“快处易赔”：1、交通事故中有人员伤亡；2、无牌（含临牌）或无证或无本市保单；3、涉酒涉毒；4、车辆无法移动的。","k":"无牌、无险、饮酒、吸毒都不可使用视频快处。","p":"","j":""},{"i":101047,"c":10,"x":1,"y":1,"q":"机动车与非机动车发生仅造成车辆损失和人员轻微伤，且机动车方应承担责任的事故，适用视频快处。","o":["正确","错误"],"a":"A","e":"在驾驶人及车辆证件合法有效，机动车投保交通事故责任强制保险，驾驶人无饮酒、吸毒、逃逸等严重违法行为的情况下，发生下列交通事故：（1）机动车与机动车发生仅造成车辆损失的道路交通事故，且当事人能够自行移动车辆的；（2）机动车与非机动车（行人）发生仅造成车辆损失和人员轻微伤的，机动车方应当承担事故责任的；（3）机动车发生单方事故造成他方财产损失，有物损负责人在现场的。","k":"视频快处：“机动车承担责任”的适用，“非机动车承担责任”的不适用。","p":"","j":""},{"i":101049,"c":10,"x":1,"y":1,"q":"视频快处过程中，当事人故意隐瞒事故关键信息的，将承担法律责任。","o":["正确","错误"],"a":"A","e":"隐瞒事故关键信息，影响调查取证，是要负法律责任的。","k":"题目里有“故意”二字的，直接答正确。","p":"","j":""},{"i":101050,"c":10,"x":1,"y":2,"q":"当事人发起视频快处后，因特殊情况需取消申请，正确做法是（ ）。","o":["直接驶离现场即可","通过原申请渠道提交取消申请","拨打122说明情况","等待系统自动取消"],"a":"B","e":"发起视频快处后，因特殊情况需取消申请的，应通过原申请渠道提交取消申请。","k":"哪里申请哪里取消。","p":"","j":""},{"i":101051,"c":10,"x":1,"y":2,"q":"什么是“轻微道路交通事故视频快处”？","o":["现场交警处理的事故快处方式","仅适用于高速公路的事故处理模式","“交管12123”APP中基于视频通话的远程快处系统","需双方到交警队现场处理的方式"],"a":"C","e":"“轻微道路交通事故视频快处” 是“交管12123”APP事故处理业务单元中新增模块，是基于视频通话服务研发的事故视频远程快处系统。事故任何一方当事人只需一键报警，建立视频“线上见面”配合现场取证即可完成交通事故调查取证定责。","k":"题目看到“视频快处”，答案找“视频通话”。","p":"","j":""},{"i":101053,"c":10,"x":1,"y":1,"q":"安徽省各地视频快处服务时段均为每日7:00—19:00，无地区差异。","o":["正确","错误"],"a":"B","e":"安徽省内视频快处时间一般为每日7:00—19:00。合肥为7:30—19:00，巢湖节假日有午休，存在地区微调。","k":"安徽省一般为每天7：00—19：00。个别区域有微调","p":"","j":""},{"i":101056,"c":10,"x":1,"y":2,"q":"轻微道路交通事故视频快处中当事人需向后台提交的必要信息不包括（ ）。","o":["事故位置定位信息","事故现场照片","双方驾驶证、行驶证照片","车辆保险单原单"],"a":"D","e":"视频快处都是线上上传电子版证据，不需要纸质版或原件。","k":"不需要原件。","p":"","j":""},{"i":101057,"c":10,"x":1,"y":2,"q":"安徽省轻微交通事故视频快处的常规办结时间约为多久？","o":["5分钟","60分钟","10分钟","30分钟"],"a":"A","e":"全省统一基准，多数事故5分钟内完成处置。","k":"视频快处5分钟内办结。","p":"","j":""},{"i":101058,"c":10,"x":1,"y":2,"q":"以下哪种事故不适用轻微交通事故视频快处？","o":["机动车与机动车之间的财产损失事故","机动车与非机动车之前的轻微伤人事故","高速公路上的机动车财产损失事故","县乡公路上的单车辆机动车事故"],"a":"C","e":"安徽省内视频快处使用车辆为：机动车与机动车之间（包含单辆机动车）的事故，机动车与非机动车之间事故；适用区域：市直辖市内的城市公路、国省道路、县乡公路、小区路面、单位内部路面，暂不包括高速公路。符合范围:三车以下的“人无伤、车能动”各方无异议的轻微交通事故，当事人不存在无证、酒驾、逃逸等违法行为，车辆有交强险且状态正常。人员轻微受伤的，当事人需能准确提供身份证号码，现场无需120急救。","k":"“高速公路”不适用视频快处。","p":"","j":""},{"i":101059,"c":10,"x":1,"y":2,"q":"进行轻微交通事故视频快处操作前，当事人应在车后多远处摆放三角警示牌？","o":["20至50米","150米以外","100至150米","50至100米"],"a":"D","e":"安徽省内安全操作规范，视频快处前需开启双闪灯，在车后50至100米处摆放三角警示牌，确保安全状态下再进行操作，事故处理完后立刻撤离现场。","k":"普通道路放置警告标志：车后50—100米。","p":"","j":""},{"i":101060,"c":10,"x":1,"y":2,"q":"当事人开启轻微交通事故视频快处的方式不包括以下哪项？","o":["直接打开“交管12123”APP点击对应功能","拨打122后由接线员转接进入","通过公安交管部门推送的短信链接进入","拨打110后通过短信链接进入"],"a":"B","e":"安徽省视频快处方式包括：直接打开“交管12123”APP点击对应功能模块、过公安交管部门推送的短信链接进入、拨打110后通过短信链接进入。","k":"122用于报警备案，无法转接视频快处。","p":"","j":""},{"i":101061,"c":10,"x":1,"y":2,"q":"人员轻微受伤的事故适用视频快处的前提是什么？","o":["投保交强险","车辆能自行移动","当事人无争议","无需120急救且能提供身份证号码"],"a":"D","e":"视频快处符合范围:三车以下的“人无伤、车能动”各方无异议的轻微交通事故，当事人不存在无证、酒驾、逃逸等违法行为，车辆有交强险且状态正常。人员轻微受伤的，当事人需能准确提供身份证号码，现场无需120急救。","k":"轻微伤用视频快处应正确提供身份证号，无120急救。","p":"","j":""},{"i":101062,"c":10,"x":1,"y":1,"q":"事故视频快处完成后，当事人可以通过“交管12123”APP的“网办进度”查看并下载电子版事故认定书。","o":["正确","错误"],"a":"A","e":"轻微道路交通事故视频快处”操作步骤：（3）如何查看事故处理流程，领取电子责任认定书。当事人可以通过“交管12123”APP【网办进度】查看事故处理进度、事故责任及电子文书。","k":"“交管12123”可查认定书。","p":"","j":""},{"i":101063,"c":10,"x":1,"y":1,"q":"使用视频快处功能时，需要当事人自行拍摄照片并上传至APP。","o":["正确","错误"],"a":"B","e":"在处理过程中，当事人只需手持手机切换前后摄像头，现场配合取证即可，所有取证均由坐席人员操作。","k":"视频快处由当事人持手机配合，后台坐席人员拍照取证上传。","p":"","j":""},{"i":101064,"c":10,"x":1,"y":1,"q":"机动车在小区路面发生的轻微事故，具备网络通讯条件的也可通过视频快处处理。","o":["正确","错误"],"a":"A","e":"适用区域：市直辖市内的城市公路、国省道路、县乡公路、小区路面、单位内部路面，暂不包括高速公路。","k":"安徽省内的小区和单位内路面也适用视频快处。","p":"","j":""},{"i":101065,"c":10,"x":1,"y":1,"q":"在安徽省内发生的非机动车交通事故，受害人可申请道路交通事故社会救助基金垫付抢救费用。","o":["正确","错误"],"a":"B","e":"基金仅适用于机动车交通事故，非机动车事故不在申请范围内。","k":"救助基金仅适用机动车。","p":"","j":""},{"i":101066,"c":10,"x":1,"y":1,"q":"安徽省道路交通事故社会救助基金垫付的费用无需偿还，由基金全额承担。","o":["正确","错误"],"a":"B","e":"救助基金管理机构根据本办法垫付抢救费用和丧葬费用后，应当依法向机动车道路交通事故责任人进行追偿，受害人及近亲属需配合追偿程序。","k":"垫付的救助基金费用应由事故责任人偿还。","p":"","j":""},{"i":101067,"c":10,"x":1,"y":1,"q":"事故救助基金可垫付交通事故中受害人的车辆维修费用。","o":["正确","错误"],"a":"B","e":"道路交通事故社会救助基金,是指依法筹集用于垫付机动车道路交通事故中受害人人身伤亡的丧葬费用、部分或者全部抢救费用的社会专项基金。","k":"救助基金包括抢救费和丧葬费。","p":"","j":""},{"i":101068,"c":10,"x":1,"y":2,"q":"安徽省道路交通事故社会救助基金垫付抢救费用的申请主体不包括（ ）。","o":["受害人近亲属","受害人本人","处理事故的公安机关交通管理部门","医疗机构"],"a":"C","e":"抢救费用由受害人、受害人近亲属或医疗机构向救助基金管理机构申请，丧葬费由受害人近亲属、殡葬机构向救助基金管理机构申请。","k":"抢救费用由受害人、受害人近亲属或医疗机构申请。","p":"","j":""},{"i":101069,"c":10,"x":1,"y":2,"q":"在安徽省内发生机动车交通事故，以下哪种情形可以申请事故救助基金垫付？","o":["受害人家庭经济困难无力承担医疗费用","肇事机动车已投保交强险且抢救费用未超限额","机动车驾驶人肇事后逃逸","仅造成车辆财产损失无人员伤亡"],"a":"C","e":"有下列情形之一时,救助基金垫付道路交通交通事故中受害人人身伤亡的丧葬费用、部分或者全部抢救费用:(一)抢救费用超过交强险责任限额的;(二)肇事机动车未参加交强险的;(三)机动车肇事后逃逸的。","k":"没有交强险、抢救费超过保险额度、肇事司机逃逸的可以申请救助基金。","p":"","j":""},{"i":101070,"c":10,"x":1,"y":2,"q":"安徽省道路交通事故社会救助基金垫付抢救费用的单人最高额度为多少？","o":["1万元","5万元","10万元","8万元"],"a":"D","e":"救助基金管理机构垫付抢救费用单人最高额度8万元，丧葬费用单人最高额度1万元。","k":"单人最高额定：抢救费8万，丧葬费1万。","p":"","j":""},{"i":101071,"c":10,"x":1,"y":2,"q":"安徽省道路交通事故社会救助基金审核通过后，垫付费用如何支付？","o":["直接划入医疗机构或殡葬机构账户","直接划入受害人个人账户","由救助基金管理机构转交给受害人近亲属","由交管部门代领后转交相关机构"],"a":"A","e":"审核通过后的救助基金费用，抢救费直接划入医疗机构账户，丧葬费直接划入殡葬机构账户，不经过受害人或近亲属转交。","k":"垫付费用直接划入医疗机构或殡葬机构。","p":"","j":""},{"i":101072,"c":10,"x":1,"y":1,"q":"救助基金一般垫付受害人自接受抢救之日起7日内的抢救费用。","o":["正确","错误"],"a":"A","e":"救助基金一般垫付受害人自抢救之时起7日内的抢救费用，特殊情况下超过7日内抢救费用，由医疗机构书面说明理由，经审核后最高垫付额度8万元。","k":"垫付抢救7日内费用，超过7日应由医疗机构书面申请。","p":"","j":""},{"i":101073,"c":10,"x":1,"y":2,"q":"道路交通事故救助基金垫付抢救费用的最长时限为7天，若需延长垫付，应提供哪个机构的证明？","o":["公安机关交通管理部门","救助基金管理机构","医疗机构","保险公司"],"a":"C","e":"救助基金一般垫付受害人自抢救之时起7日内的抢救费用，特殊情况下超过7日内抢救费用，由医疗机构书面说明理由，经审核后最高垫付额度8万元。","k":"垫付抢救7日内费用，超过7日应由医疗机构书面申请。","p":"","j":""},{"i":101074,"c":10,"x":1,"y":2,"q":"机动车肇事逃逸，受害人抢救费用应由（ ）先行垫付。","o":["交警部门","受害人亲属","医院","救助基金"],"a":"D","e":"有下列情形之一时,救助基金垫付道路交通交通事故中受害人人身伤亡的丧葬费用、部分或者全部抢救费用:(一)抢救费用超过交强险责任限额的;(二)肇事机动车未参加交强险的;(三)机动车肇事后逃逸的。","k":"抢救费用由“救助基金”垫付。","p":"","j":""},{"i":101075,"c":10,"x":1,"y":1,"q":"道路交通事故救助基金垫付抢救费用的最高限额为8万元，且无需任何证明即可申请。","o":["正确","错误"],"a":"B","e":"救助基金一般垫付受害人自抢救之时起7日内的抢救费用，特殊情况下超过7日内抢救费用，由医疗机构书面说明理由，经审核后最高垫付额度8万元。","k":"垫付抢救7日内费用，超过7日应由医疗机构书面申请。","p":"","j":""},{"i":101076,"c":10,"x":1,"y":2,"q":"道路交通事故救助基金垫付费用的审核与到账时限为多久？","o":["审核通过后1天内","提交材料后7天内","审核通过后3天内","提交材料后15天内"],"a":"C","e":"申请材料提交给救助基金管理机构（当地人保财险）审核通过后，3天内资金到账。","k":"垫付费用审核通过后3日内到账。","p":"","j":""},{"i":101077,"c":10,"x":1,"y":2,"q":"以下哪种情形不能申请道路交通事故救助基金垫付费用？","o":["受害人家庭经济困难无钱救治","肇事车辆未购买交强险","肇事司机逃逸","抢救费用超过交强险限额1.8万元"],"a":"A","e":"有下列情形之一时,救助基金垫付道路交通交通事故中受害人人身伤亡的丧葬费用、部分或者全部抢救费用:(一)抢救费用超过交强险责任限额的;(二)肇事机动车未参加交强险的;(三)机动车肇事后逃逸的。","k":"没有交强险、抢救费超过保险额度、肇事司机逃逸的可以申请救助基金。","p":"","j":""},{"i":101078,"c":10,"x":1,"y":2,"q":"救助基金垫付费用后，有权向谁追偿？","o":["受害人","交通事故责任人","保险公司","医疗机构"],"a":"B","e":"救助基金管理机构根据本办法垫付抢救费用和丧葬费用后，应当依法向机动车道路交通事故责任人进行追偿。","k":"垫付的救助基金费用应由事故责任人偿还。","p":"","j":""},{"i":101079,"c":10,"x":1,"y":1,"q":"现场急救应遵循先止血后包扎、先重后轻、先救后送的原则。","o":["正确","错误"],"a":"A","e":"现场急救应遵循先止后包、先重后轻、先救后送等原则。","k":"常识，记住就好！","p":"","j":""},{"i":101081,"c":10,"x":1,"y":2,"q":"医学上认定的呼吸、心跳骤停后的急救黄金时间为（ ）。","o":["3分钟","4分钟","5分钟","6分钟"],"a":"B","e":"呼吸、心脏骤停后，急救越早，存活率越高，医学上急救黄金时间为4分钟。","k":"心跳骤停急救黄金时间为4分钟。","p":"","j":""},{"i":101084,"c":10,"x":1,"y":1,"q":"成人心肺复苏时，打开气道的最常用方式是仰头举颏法。","o":["正确","错误","低头抬颏法","双手托颌法"],"a":"A","e":"成人心肺复苏时打开气道的最常用方式是仰头举颏法。这种操作方法是抢救者将一手掌小拇指侧置于患者前额，然后下压使其头部后仰，另一手的食指和中指置于靠近颏部的下颌骨下方，将颏部向前抬起，帮助患者头部后仰，将其气道开放。","k":"打开气道用举颏法。","p":"","j":""},{"i":101086,"c":10,"x":1,"y":2,"q":"成人心肺复苏时胸外按压的深度为（）。","o":["至少6厘米","至少3厘米","至少5厘米","至少胸廓厚度得一半"],"a":"C","e":"成人心肺复苏时，胸外心脏按压的正确位置是胸骨中下1/3交界处，按压的深度至少5厘米，按压频率为每分钟100-120次，按压中断时间应尽可能控制在10秒以内。","k":"胸外按压深度：成人至少5厘米；1岁至青春期约5厘米；1岁以下约4厘米。","p":"","j":""},{"i":101088,"c":10,"x":1,"y":2,"q":"对（ ）损伤的伤员，要严禁让其站起、坐立和行走。","o":["头部","脊柱","下肢","腹部"],"a":"B","e":"救治伤员时，对脊柱损伤的伤员，要严禁让其站起、坐立和行走；搬运昏迷伤员时应采取侧卧位，头偏向一侧；搬运昏迷患者时，应采取平卧位头偏向一侧，侧卧位防止误吸。","k":"脊柱损伤不可站起、坐立和行走。","p":"","j":""},{"i":101090,"c":10,"x":1,"y":2,"q":"骨折固定时，若伤病员同时出现心跳、呼吸骤停，应优先采取的措施是（ ）。","o":["先进行心肺复苏术","立即固定骨折部位","同时开展固定与心肺复苏","等待专业医护人员到达"],"a":"A","e":"伤病员心跳、呼吸骤停同时又伴有骨折时，应遵循先救命后治伤的原则，采取先心肺复苏术，后固定骨折的顺序开展施救。","k":"对于没有心跳和呼吸的人，应就地实施心肺复苏。","p":"","j":""},{"i":101092,"c":10,"x":1,"y":2,"q":"对异物插入体内的伤病员，现场如何处置？","o":["立即拔出","固定后送医","不处理","摇晃伤员"],"a":"B","e":"救护员在现场对伤病员进行救护之前，首先要考虑现场环境是否安全。对意识不清的伤病员，检查脉搏常用颈动脉；对伤员鼻出血，应先给与干净布擦血；对疑似颈椎骨折时，尽量不移动伤病员，拨打急救电话；对异物插入体内的，现场不能拔除异物,应采取简单固定包扎措施后送往医院。","k":"异物插入体内应简单包扎后送医。","p":"","j":""},{"i":101093,"c":10,"x":1,"y":2,"q":"加压包扎止血法主要用于什么情况？","o":["动脉喷射性出血","四肢损伤时的较小血管出血或渗血","头部动脉出血","内脏出血"],"a":"B","e":"包扎止血法可以采用绷带、三角巾、止血带等物品，不能使用麻绳包扎。加压包扎止血法，主要用于四肢损伤时的较小血管出血或渗血。","k":"加压包扎止血法适用于四肢较小血管出血。","p":"","j":""},{"i":101094,"c":10,"x":1,"y":2,"q":"止血带的使用范围是（ ）。","o":["仅限四肢","可用于头部","可用于儿童前臂浅表划伤","所有部位均可"],"a":"A","e":"止血带仅限四肢，不能用于头部出血和儿童的前臂浅表划伤出血。救治四肢动脉喷射性出血伤员时，应记录使用时间，每1小时要放松1次。","k":"止血带仅限于四肢使用。","p":"","j":""},{"i":101095,"c":10,"x":1,"y":2,"q":"包扎开放性腹部损伤（脏器外漏）时，以下哪种做法是正确的？","o":["将脏器直接塞回腹腔","不予处理立即送医","用无菌湿纱布覆盖外漏脏器，并用碗状物扣住伤口避免压迫","用干纱布擦拭后包扎"],"a":"C","e":"包扎开放性腹部损伤（脏器外露）伤员时，用无菌湿纱布覆盖外露脏器，并用碗状物扣住伤口避免压迫，包扎后让患者平卧屈膝。","k":"题目看到“脏器外漏”，答案找“无菌”。","p":"","j":""},{"i":101098,"c":10,"x":1,"y":1,"q":"因自愿实施紧急救助行为造成受助人损害的，救助人不承担民事责任。","o":["正确","错误","不承担责任","全部责任"],"a":"A","e":"根据《民法典》第184条，因紧急搬运导致患者颈椎二次损伤，施救者无需担责；施救者因使用止血带导致患者截肢无需担责。","k":"题目里看到“自愿”二字，直接答正确。","p":"","j":""},{"i":101100,"c":10,"x":1,"y":2,"q":"用干净敷料压迫伤口止血时，放置敷料范围要（ ）。","o":["略大于伤口部位","超出伤口5-10厘米","没有特定要求","越大越好"],"a":"B","e":"用干净敷料压迫伤口止血时，放置敷料范围要大，超出伤口5-10厘米。","k":"敷料应超出伤口5-10厘米。","p":"","j":""},{"i":101101,"c":10,"x":1,"y":2,"q":"在直接加压止血时，应做到（ ）。","o":["持续按压10-15分钟后检查是否止血","持续按压到急救车到达现场为止","按压30分钟即可，无需再次检查是否止血","每隔1分钟松开并检查是否止血"],"a":"A","e":"直接加压止血时，应持续按压10-15分钟后检查是否止血，过早松开会再次出血。","k":"加压止血应持续按压10-15分钟后检查是否出血。","p":"","j":""},{"i":101102,"c":10,"x":1,"y":1,"q":"成人心肺复苏时，若施救者因疲劳导致按压深度不足，可通过临时加快按压频率来补偿。","o":["正确","错误"],"a":"A","e":"如施救者疲劳导致按压深度不足时，可临时加快按压频率补偿。","k":"按压深度不足，可加快按压频率补偿。","p":"","j":""},{"i":101104,"c":10,"x":1,"y":2,"q":"固定前臂骨折时，下列操作正确的是什么？","o":["绷带从近心端向远心端缠绕","夹板长度只需超过腕关节","肢体与夹板间隙用软垫填充","夹板只需固定骨折处即可"],"a":"C","e":"固定前臂骨折时，使用绷带从远心端向近心端缠绕，夹板长度需超过腕关节和肘关节，肢体与夹板间隙用软垫填充。","k":"固定前臂骨折应从远心端到近心端，夹板间用软垫填充。","p":"","j":""},{"i":170134,"c":17,"x":1,"y":3,"q":"如图所示，在交叉口通行信号灯为绿灯时，不得超车的原因是什么？","o":["路口设有交通信号灯","路口内交通情况复杂，易发生交通事故","行经人行横道，可能有行人通过","路口有交通监控设备"],"a":"BC","e":"交叉路口车流多，人行道经常有人通过，情况复杂，容易造成拥堵，易发事故，所以不允许超车。","k":"关于“交叉口不得超车的原因”的多选题，答案选两个“事故”和“行人”。","p":"11148.jpg","j":""},{"i":170135,"c":17,"x":1,"y":3,"q":"以下哪项行为可构成交通肇事罪？","o":["违反交通运输管理法规运输危险化学品","违反交通运输管理法规致人死亡","交通运输肇事后逃逸","驾驶校车，严重超过定额乘员载客"],"a":"BC","e":"《刑法》规定：违反交通运输管理法规，因而发生重大事故，致人重伤、死亡或者使用公私财产遭受重大损失的，处三年以下有期徒刑或者拘役；交通运输肇事后逃逸或者有其他特别恶劣情节的，处三年以上七年以下有期徒刑；因逃逸致人死亡的，处七年以上有期徒刑。","k":"关于“肇事罪”的多选题，答案选两个“逃逸”和“死亡”。","p":"","j":""},{"i":170136,"c":17,"x":1,"y":3,"q":"驾驶机动车超越停在车站的公交车时，应注意的是什么？","o":["公交车可能突然起步","可能有非机动车突然出现在盲区内","公交车前突然跑出的乘客","公交车可能突然加速"],"a":"ABCD","e":"驾驶机动车超越停在车站的公交车时，公交车可能突然起步、公交车可能突然加速、公交车前突然跑出的乘客、非机动车突然出现在盲区内、因此应做好随时停车的准备，加大横向间距，减速缓慢超越，超越时要特别留意公交车的动态，避免发生碰撞。","k":"关于“公交车”的多选题，答案不选“尽快超越”、“催促”，其他全选。（错误的除外）","p":"","j":""},{"i":170137,"c":17,"x":1,"y":3,"q":"大中型客车行驶过程中着火时，以下做法正确的是什么？","o":["组织乘客至安全地带","火势较小时使用灭火器设备灭火","尽快减速停车","报警并设置警示标志"],"a":"ABCD","e":"大中型客车着火时，应尽快减速停车，组织乘客撤离到安全地带，及时报警并设置警告标志。火势较小时应使用灭火器灭火。","k":"有利于安全的都是对的，所以四个全选。","p":"","j":""},{"i":170138,"c":17,"x":1,"y":3,"q":"如图所示，驾驶遇桥下积水时，以下做法正确的是什么？","o":["应一次性匀速通过","积水过深时应选择绕行","通过时应挂低速挡","先停车察明水情"],"a":"ABCD","e":"通过这种涉水路段时，应先察明水情，通过时应避免中途停车，以防熄火，最好的方法就是挂低挡，匀速慢行一次性通过。如果积水过深时应选择绕行，","k":"关于“桥下积水”的多选题，答案全选。","p":"4140515.jpg","j":""},{"i":170139,"c":17,"x":1,"y":3,"q":"关于取得大型货车驾驶证后申请增驾重型牵引挂车的要求，以下说法正确的是什么？","o":["取得大型货车驾驶证满2年","取得大型货车驾驶证满3年","本记分周期和最近连续二个记分周期内没有记满12分记录的","本记分周期和最近连续二个记分周期内有记满12分记录，已参加满分教育且考试通过"],"a":"AC","e":"申请增加重型牵引挂车准驾车型的，已取得驾驶中型客车或者大型货车准驾车型资格2年以上，或者取得驾驶大型客车准驾车型资格1年以上，并在申请前最近连续2个记分周期内没有记满12分记录；","k":"大货增重牵：记住两个2。（2年，连续二个记分周期没有记满12分。）","p":"","j":""},{"i":3090121,"c":309,"x":1,"y":2,"q":"成人心肺复苏时胸外按压的深度为（）。","o":["至少6厘米","至少3厘米","至少5厘米","至少胸廓厚度得一半"],"a":"C","e":"成人心肺复苏时，胸外心脏按压的正确位置是胸骨中下1/3交界处，按压的深度至少5厘米，按压频率为每分钟100-120次，按压中断时间应尽可能控制在10秒以内。","k":"胸外按压深度：成人至少5厘米；1岁至青春期约5厘米；1岁以下约4厘米。","p":"","j":""},{"i":100903,"c":10,"x":4,"y":2,"q":"借道通行的机动车或者行人，应当让本车道内的()优先通行。","o":["机动车","非机动车","行人","车辆或者行人"],"a":"D","e":"《浙江省实施(中华人民共和国道路交通安全法)办法》第四十条:借道通行的车辆或者行人，应当让本道内的车辆或者行人优先通行。","k":"","p":"","j":""},{"i":3010007,"c":301,"x":4,"y":3,"q":"驾驶新能源汽车在路口起步时，以下做法正确的是（ ）。","o":["猛踩加速踏板通过路口","缓踩加速踏板","注意观察后视镜及周围交通情况","注意停止车辆造成的视线盲区内是否有行人或车辆准备通过路口"],"a":"BCD","e":"起步前应缓踩加速踏板，注意观察后视镜及周围情况和视线盲区是否有行人通过。","k":"题目问“正确的”，“猛踩”的都错，所以不选，选其他三个。","p":"","j":""},{"i":3010008,"c":301,"x":4,"y":3,"q":"驾驶此前未接触过的车辆前，应熟悉一下哪些方面？","o":["挡位操作方式","辅助驾驶功能","座椅调整方式","加速、制动踏板位置及性能"],"a":"ABCD","e":"驾驶未接触过的车辆，应该全方位的功能和操作都要了解。","k":"多选题目看到“熟悉”，答案全选。","p":"","j":""},{"i":3010009,"c":301,"x":4,"y":1,"q":"新能源汽车扭矩大，车速能够瞬间到达极值，驾驶新能源汽车起步时，要缓踩加速踏板，防止急加速造成事故。","o":["正确","错误"],"a":"A","e":"新能源汽车起步时，提速是很快的，所以要缓踩油门，防止加速过急发生事故。","k":"题目里有“缓踩”、“轻踩”的，直接答正确。","p":"","j":""},{"i":3010010,"c":301,"x":4,"y":1,"q":"驾驶人在驾驶位长时间未操作时，右脚应离开加速踏板。","o":["正确","错误"],"a":"A","e":"驾驶人在驾驶位上长时间没有操作，右脚应离开加速踏板（油门），以免误踩油门导致事故。","k":"科目四题目中看到“加速踏板”，直接答正确。","p":"","j":""},{"i":3010011,"c":301,"x":4,"y":1,"q":"不同品牌新能源汽车的踏板性能、安装位置可能有所差异，驾驶前应熟悉踏板情况。","o":["正确","错误"],"a":"A","e":"新能源汽车品牌之间踏板性能都有差异，所以驾驶前都应熟悉踏板的情况。","k":"判断题中看到“熟悉”，直接答正确。","p":"","j":""},{"i":3010017,"c":301,"x":4,"y":1,"q":"安全跟车距离需随着车辆速度变化而变化。","o":["正确","错误"],"a":"A","e":"安全跟车距离需要随着速度变化而变化，车速越高，跟车的安全距离要随之增大，这样才能保证安全。","k":"常识，车速越快，安全跟车距离应越大。","p":"","j":""},{"i":3010018,"c":301,"x":4,"y":1,"q":"行车中安全跟车距离应随着车速的提高而减小。","o":["正确","错误"],"a":"B","e":"安全跟车距离需要随着速度变化而变化，车速越高，跟车的安全距离要随之增大，这样才能保证安全。","k":"常识，车速越快，安全跟车距离应越大。","p":"","j":""},{"i":3010019,"c":301,"x":4,"y":1,"q":"跟随满载土石的重型货车行驶时，应选择在其侧面并排行车。","o":["正确","错误"],"a":"B","e":"跟随满载土石的重型货车行驶时，为防止货物固定不稳或者车辆颠簸导致货物掉落，可能会被掉落物击中，造成事故。应选择在其侧面并保持一定距离，以确保行车安全。","k":"题目里看到“并排行车”的，直接答错误。","p":"","j":""},{"i":3010020,"c":301,"x":4,"y":1,"q":"在上坡路段遇前车停车时，应适当减小安全距离，防止前车起步时溜车。","o":["正确","错误"],"a":"B","e":"上坡路段，很容易溜车，所以预防前车溜车应该加大安全车距行驶。","k":"题目里看到“适当减小”，直接答错误。","p":"","j":""},{"i":3010021,"c":301,"x":4,"y":2,"q":"驾驶车辆遇图中情形时，以下操作正确的是（ ）。","o":["减速靠右避让","加速直行逼退来车","加速靠左行驶","减速靠左行驶"],"a":"A","e":"在图中这种没有中心线的道路上行驶，遇到对向来车时，应该减速靠右避让。","k":"答案里有“减速靠右”意思的，直接选。","p":"2025081839.jpg","j":""},{"i":3010022,"c":301,"x":4,"y":1,"q":"跟车时，应保持较远的观察距离，避免紧盯前车车尾。","o":["正确","错误"],"a":"A","e":"跟车行驶，应保持较大的安全距离，当遇到突发状况时，有足够的空间可以进行避让或减速，从而降低事故发生的风险。","k":"判断题中出现“避免”一般都是对的。（影响安全的行为除外。）","p":"","j":""},{"i":3010023,"c":301,"x":4,"y":1,"q":"超车前，应先排除与对面来车会车的可能。","o":["正确","错误"],"a":"A","e":"预计在超车过程中与对面来车有会车可能时，应提前减速，主动放弃超车。","k":"科目四题中看到“可能”都是对的。（只有和“加速”、“只要”、“由近及远”同时出现答错。）","p":"","j":""},{"i":3010024,"c":301,"x":4,"y":1,"q":"雪天跟车应降低车速行驶，不用考虑跟车距离。","o":["正确","错误"],"a":"B","e":"雪天车辆容易打滑，所以应该保持安全跟车距离，减速慢行，避免发生追尾事故。","k":"题目看到“不用考虑”，直接答错误。","p":"","j":""},{"i":3010025,"c":301,"x":4,"y":3,"q":"关于跟车行驶，以下做法正确的是（ ）。","o":["与前车保持安全距离","紧跟前车以防加塞","保持轨迹避免轧线","注意察看后视镜"],"a":"ACD","e":"在道路上安全跟车应保持轨迹，避免轧线行驶，注意观察前车动态，并察看后视镜掌握后车动态，保持安全距离，随时做好减速准备，避免交通事故。","k":"关于“跟车”的多选题，答案里不选“左”、“紧跟”，其他全选。","p":"","j":""},{"i":3010026,"c":301,"x":4,"y":1,"q":"在陡坡路段跟车行驶时，应适当减小跟车距离。","o":["正确","错误"],"a":"B","e":"上坡路段，很容易溜车，所以预防前车溜车应该加大安全车距行驶。","k":"题目里看到“适当减小”，直接答错误。","p":"","j":""},{"i":3010027,"c":301,"x":4,"y":3,"q":"关于高速公路驾车，以下说法错误的是（ ）。","o":["不可骑、轧车道分界线行驶","不可在路肩上行驶","可以在匝道、加速车道或者减速车道上超车","可以学习驾驶机动车"],"a":"CD","e":"高速公路行驶不得有倒车、逆行、掉头、停车、压线行驶等行为。匝道、加速车道、减速车道内不可以倒车、逆行、掉头、停车、超车。高速公路内不可以学习驾驶机动车，以免发生危险。","k":"关于“高速公路┉┉错误的”多选题，答案不选“不可”，其他全选。","p":"","j":""},{"i":3010028,"c":301,"x":4,"y":2,"q":"驾车遇此情形时，以下操作正确的是（ ）。","o":["连续鸣喇叭警告","减速让行","向左驶入对向车道","加速直行通过"],"a":"B","e":"图中前车正在超越我方车辆，此时应减速靠右让行。","k":"题目问正确的，“减速让行”都是对的。","p":"2025081843.jpg","j":""},{"i":3010029,"c":301,"x":4,"y":1,"q":"驾驶新能源汽车出行前，应提前熟悉制动踏板位置，避免误操作造成事故。","o":["正确","错误"],"a":"A","e":"新能源汽车品牌之间踏板性能都有差异，所以驾驶前都应熟悉踏板的情况。","k":"判断题中看到“熟悉”，直接答正确。","p":"","j":""},{"i":3010030,"c":301,"x":4,"y":2,"q":"驾驶新能源汽车出行时，以下做法正确的是（ ）。","o":["起步时缓踩加速踏板","开启辅助驾驶功能时可以双手不扶方向盘","开启辅助驾驶功能时无需注意观察路面情况","起步时猛踩加速踏板"],"a":"A","e":"起步前应缓踩加速踏板，注意观察后视镜及周围情况和视线盲区是否有行人通过，开启辅助驾驶仍然需要保持警惕，随时准备接管车辆的控制权。","k":"题目问正确的，“缓踩”都是对的。","p":"","j":""},{"i":3040005,"c":301,"x":4,"y":1,"q":"驾车时吸烟对安全行车无影响。","o":["正确","错误"],"a":"B","e":"一边开车一边吸烟，不仅妨碍安全驾驶，也会分散驾驶人的注意。","k":"判断题看到“无影响”的，直接答错误。","p":"","j":""},{"i":3040006,"c":301,"x":4,"y":1,"q":"驾车遇到图中情形时，应及时避让道路上的牲畜。","o":["正确","错误"],"a":"A","e":"驾车遇路侧有牲畜，应该提前减速慢行，必要时停车让行，不可以鸣喇叭，以免牲畜受惊慌乱，可能会造成更大的交通问题。","k":"判断题出现“及时”二字的都是对的。（影响安全的行为除外。）","p":"43383.jpg","j":""},{"i":3040007,"c":301,"x":4,"y":1,"q":"驾车遇到图中情形时，应鸣喇叭加速通过。","o":["正确","错误"],"a":"B","e":"驾车遇路侧有牲畜，应该提前减速慢行，必要时停车让行，不可以鸣喇叭，以免牲畜受惊慌乱，可能会造成更大的交通问题。","k":"题目中有‘加速通过’的都是错的，只有‘不可加速通过’是对的。","p":"43383.jpg","j":""},{"i":3040008,"c":301,"x":4,"y":3,"q":"关于出车前对轮胎的检查内容，以下说法正确的是（ ）。","o":["轮胎表面有无脱皮","轮胎侧壁有无裂痕、鼓包","轮胎花纹深度是否过浅","胎压是否充足"],"a":"ABCD","e":"出车前应检查轮胎表面有无脱皮、侧壁有无裂痕鼓包、花纹是否过浅，胎压是否充足，以避免爆胎的风险。","k":"多选题目中有“轮胎”二字的，答案全选。","p":"","j":""},{"i":3040009,"c":301,"x":4,"y":3,"q":"驾车驶近停在车站的公交车辆时应（ ）。","o":["减速慢行","留意公交车变道","注意车辆前方有人穿行","鸣喇叭催促"],"a":"ABC","e":"驾车驶近停在车站的公交车时，应减速慢行，注意车前可能会有人横穿，公交车可能变道，加大安全距离，避免发生碰撞。","k":"关于“公交车”的多选题，答案不选“尽快超越”、“催促”，其他全选。（错误的除外）","p":"","j":""},{"i":3040010,"c":301,"x":4,"y":1,"q":"进入驾驶室前应观察车辆周围情况。","o":["正确","错误"],"a":"A","e":"进入驾驶室前观察周围可以了解车辆附近是否有障碍物、行人、其他车辆等，避免在启动车辆或开车门时发生意外碰撞。不观察周围情况是非常危险和不负责任的行为，可能会引发交通事故。","k":"有利于安全的都是对的。","p":"","j":""},{"i":3040011,"c":301,"x":4,"y":1,"q":"夜间驾驶人行车视野受限，难以看到灯光照射范围以外的情况，因此要减速行驶。","o":["正确","错误"],"a":"A","e":"夜间行车时，由于光线不足，驾驶人的视力、视距和视野都会受到影响，这使得驾驶人的观察力和判断力有所降低，从而增加了交通事故的风险，所以应减速行驶。","k":"题目里有“减速行驶”都是对的。（标志题除外）","p":"","j":""},{"i":3040012,"c":301,"x":4,"y":1,"q":"如图所示，驾驶机动车进入居民小区不能超过限速标志限定的速度行驶。","o":["正确","错误"],"a":"A","e":"图中右侧是最高限速标志，表示进入此小区车速不得超过5公里/小时。","k":"图中红色标志表示“最高限速”（不能超过的意思），题目和图片一致答对。","p":"2025080201.jpg","j":""},{"i":3040013,"c":301,"x":4,"y":1,"q":"检查机油时应在怠速状态下检查。","o":["正确","错误"],"a":"B","e":"检查机油时车辆应停在平坦的地方，并且发动机静止的状态下进行检查。","k":"科四题中出现“检查”的都是对的。（只有和“刮水器”、“立即”、“怠速状态”同时出现答错。）","p":"","j":""},{"i":3040014,"c":301,"x":4,"y":1,"q":"驾驶车辆过程中拨打、接听手持电话会妨碍安全驾驶。","o":["正确","错误"],"a":"A","e":"驾驶人边驾车，边打电话，严重分散驾驶人注意力，导致判断不及时，容易发生事故，这种行为违反了法律规定，所以是违法行为。","k":"常识，驾车接打电话妨碍安全驾驶。","p":"","j":""},{"i":3040015,"c":301,"x":4,"y":1,"q":"在图中场景下己车想向左变更车道时，应加速驶入左前方空隙。","o":["正确","错误"],"a":"B","e":"图中左侧有来车，我方向左变更车道，应注意减速让行。","k":"题目中出现“加速”意思的都是错的。","p":"40056.jpg","j":""},{"i":3040016,"c":301,"x":4,"y":1,"q":"驾驶人身体条件发生变化不符合驾驶车辆条件的，应及时申请注销驾驶本。","o":["正确","错误"],"a":"A","e":"当驾驶人身体条件发生这类变化时，应当在30日内到机动车驾驶证核发地车辆管理所申请注销，以避免在不适合驾驶的情况下上路，保障自身和他人的生命财产安全。","k":"判断题里有‘注销’的都是对的，‘不会被注销’的都是错的。","p":"","j":""},{"i":3040017,"c":301,"x":4,"y":1,"q":"不系安全带可能会导致车辆紧急制动或发生碰撞时人员碰撞车内部件或者被甩出车外。","o":["正确","错误"],"a":"A","e":"安全带的主要目的是在遇紧急制动或发生碰撞时，有效保护身体，减少人员伤亡。不系安全带则会可能发生撞击风窗玻璃、被甩出车外、造成胸部损伤等危险状况。","k":"科目四题中有“导致”的都是对的。（只有和“隐患”同时出现答错）","p":"","j":""},{"i":3040018,"c":301,"x":4,"y":1,"q":"汽车座椅安全头枕高度应调整到头枕中心和头部平齐。","o":["正确","错误"],"a":"A","e":"头枕的中心一定要与头齐平,才能有效的保护驾乘人员颈部。头枕调整不到位，如果后方有车辆撞击，头部由于惯性会后冲，没有头枕保护，颈椎有可能折断。","k":"头枕支撑头，保护颈部。","p":"","j":""},{"i":3040019,"c":301,"x":4,"y":1,"q":"检查机油前应将车辆停在平地。","o":["正确","错误"],"a":"A","e":"检查机油时车辆应停在平坦的地方，并且发动机静止的状态下进行检查。","k":"科四题中出现“检查”的都是对的。（只有和“刮水器”、“立即”、“怠速状态”同时出现答错。）","p":"","j":""},{"i":3040020,"c":301,"x":4,"y":3,"q":"长下坡路连续踩刹车踏板，以下说法正确的是（ ）。","o":["使制动器温度升高","使制动器制动效能下降","缩短制动器寿命","致使车辆倾翻"],"a":"ABC","e":"驾驶机动车下长坡时，车子向下的冲力很大，长时间使用行车制动（也就是脚刹），刹车垫与车轮轴摩擦起热磨损严重，会使制动器温度升高,导致制动性能下降，缩短制动器寿命。","k":"关于“连续踩刹车”的多选题，答案不选“倾翻”，选其他三个。","p":"","j":""},{"i":3040021,"c":301,"x":4,"y":1,"q":"遇到图中道路可空挡滑行，降低油耗。","o":["正确","错误"],"a":"B","e":"图中右侧警告标志是：连续下坡。应该提前减挡，保持充足动力，利用发动机制动减速，绝对不能空挡滑行。","k":"题目里有“空挡滑行”，都是错的。","p":"2025080206.jpg","j":""},{"i":3040022,"c":301,"x":4,"y":3,"q":"关于避险车道，以下说法正确的是（ ）。","o":["一般设置在长下坡路","避险车道前设置预告标志","可用于临时停车检修问题","用于刹车失灵车辆紧急停车"],"a":"ABD","e":"避险车道是指在长陡下坡路段行车道外侧增设的供速度失控（刹车失灵）车辆驶离正线安全减速的专用车道。入口前设置有预告标志。在此处休息、检修很容易发生危险。","k":"关于“避险车道”的多选题，答案不选“休息”、“检修”，选其他三个。","p":"","j":""},{"i":3040023,"c":301,"x":4,"y":2,"q":"驾驶机动车在长下坡路段行使时，以下做法错误的是什么？","o":["观察道路交通标志，留意避险车道位置","挂低速挡，利用发动机制动","关闭发动机熄火滑行","开启缓速器"],"a":"C","e":"","k":"","p":"","j":""},{"i":3040024,"c":301,"x":4,"y":3,"q":"长下坡路驾驶车辆，以下说法正确的是（ ）。","o":["打开缓速装置","挂低速挡行驶","持续踩刹车踏板","观察对向来车"],"a":"ABD","e":"在图中这种连续下坡路行驶，应注意观察对向来车。下坡时应挂低速挡，利用发动机制动，不能持续踩刹车，以免引起制动性能下降。车辆有缓速器的，应打开缓速器。","k":"题目让选正确的，“持续踩刹车”是错的，所以不选，选其他三个。","p":"2025080209.jpg","j":""},{"i":3040025,"c":301,"x":4,"y":3,"q":"长下坡路行驶，驾驶车辆速度因重力作用越来越快，以下控制驾驶车辆速度方法正确的是（ ）。","o":["打开缓速装置","减挡，利用发动机制动","踏下离合器踏板滑行","间隙踩踏刹车踏板制动"],"a":"ABD","e":"长下坡前应该提前挂低速挡，利用发动机制动，以保持充足的动力；可间歇性踏制动踏板降低车速；有缓速器的，可以开启缓速器。任何时候都不可以空挡滑行。","k":"多选题看到“越来越快”，答案不选“滑行”，选其他三个。","p":"","j":""},{"i":3010012,"c":302,"x":4,"y":1,"q":"驾车遇图中所示情形时应随时准备停车让行。","o":["正确","错误"],"a":"A","e":"由图可知，在这样交通混乱的情况下要注意减速让行，必要时停车避让。","k":"题目中有“随时”二字的都是对的。","p":"2025081828.jpg","j":""},{"i":3020002,"c":302,"x":4,"y":2,"q":"路口遇转弯车辆抢行时，以下做法正确的是（ ）","o":["停车避让","保持正常车速行驶","提高车速抢先通过","鸣喇叭抢先通过"],"a":"A","e":"行驶在路上，为了安全，不管是车辆还是行人抢行，都应减速或停车避让。","k":"答案中有“减速避让”、“停车避让”的，直接选。","p":"","j":""},{"i":3040026,"c":302,"x":4,"y":1,"q":"驾驶车辆行驶到图片中路口绿灯亮时，不必为行人让行。","o":["正确","错误"],"a":"B","e":"图中路口虽然是绿灯，但人行横道上仍有行人通过，此时应停车等待行人通过后再起步。","k":"题目中有“不必”二字的，直接答错误。","p":"2025080501.jpg","j":""},{"i":3010015,"c":303,"x":4,"y":1,"q":"图中红圈中交通标志表示前方隧道减速慢行。","o":["正确","错误"],"a":"A","e":"红圈内警告标志是：隧道。提醒前方是照明不好的隧道，应注意慢行。","k":"图中标志是“隧道”，减速慢行是对的。","p":"XT2025061101.jpg","j":""},{"i":3030002,"c":303,"x":4,"y":1,"q":"驾驶车辆遇图中右侧交通标志时，应谨慎驾驶，注意非机动车。","o":["正确","错误"],"a":"A","e":"图中右侧标志是：注意非机动车。提醒前方道路经常有非机动车横穿或出入，应注意慢行。","k":"图中有“注意非机动车”标志，题目和图片一致答对。","p":"2025081823.jpg","j":""},{"i":3030003,"c":303,"x":4,"y":1,"q":"驾驶车辆遇图中情形，在确保安全情况下，可越过黄色虚线绕行。","o":["正确","错误"],"a":"A","e":"图中路中心黄线是虚线，在确保安全的情况下，可以越线与非机动车拉开横向安全距离后超车。","k":"虚可实禁。图中是虚线“可跨越”，题目说“可越过”，题目和图片一致答对。","p":"2025081829.jpg","j":""},{"i":3040027,"c":303,"x":4,"y":1,"q":"为预防对向车辆轧道路中心线行驶，应减速靠右、鸣喇叭提醒。","o":["正确","错误"],"a":"A","e":"图中是视线受阻的路段，为预防对向来车占道行驶，应减速、靠右、鸣喇叭，保证安全行车。","k":"判断题有“靠右”的直接答对。","p":"2025080211.jpg","j":""},{"i":3040028,"c":303,"x":4,"y":1,"q":"如图所示，驾驶机动车此时应停车等待。","o":["正确","错误"],"a":"A","e":"图中是一组的圆形信号灯，此时黄灯亮起，车辆还未越过停止线，应停车等待。如果已经越过停止线，在不妨碍其他车辆和行人通行情况下可以直行通过。","k":"科目四题中有“停车等待”的都是对的。（例外：“只有三条”答错。）","p":"43358.jpg","j":""},{"i":3040030,"c":303,"x":4,"y":1,"q":"通过下图路段，要减速行驶。","o":["正确","错误"],"a":"A","e":"山区弯路，应减速、靠右、鸣喇叭行驶，避免对向有来车，发生碰撞。","k":"题目里有“减速行驶”都是对的。（标志题除外）","p":"2025080213.jpg","j":""},{"i":3040031,"c":303,"x":4,"y":1,"q":"通过图中山区弯道可以轧前方道路中心实线行驶。","o":["正确","错误"],"a":"B","e":"三区弯路，应减速、靠右、鸣喇叭行驶，图中虚线处可以临时跨越，实线处禁止跨越。","k":"虚可实禁。图中实线处禁止轧和跨越，题目说“可以轧实线”，题目和图片不一致答错。","p":"2025080214.jpg","j":""},{"i":3040032,"c":303,"x":4,"y":2,"q":"遇图中情况，以下说法正确的是（ ）。","o":["减速慢行、按喇叭示意","临时占对向车道行驶","轧道路中心标线行驶","停车观察"],"a":"A","e":"图中是急弯路，应减速、靠右、鸣喇叭行驶，以防对向有来车。","k":"弯道行驶原则：减速、靠右、鸣喇叭。","p":"2025080215.jpg","j":""},{"i":3040033,"c":303,"x":4,"y":3,"q":"遇图中标志，以下做法错误的是（ ）。","o":["各行其道加速行驶","轧道路中心标线行驶","加速行驶","减速行驶"],"a":"ABC","e":"图中车辆行至急弯处，并且对向有来车，驾驶人应减速靠右行驶。","k":"题目让选错误的，“加速”、“轧中心线”都是错的。","p":"2025080216.jpg","j":""},{"i":3040034,"c":303,"x":4,"y":1,"q":"驾车驶入图中所示位置时，可以掉头。","o":["正确","错误"],"a":"A","e":"图中车辆所在车道上的箭头表示掉头和直行合用车道，地面上中心是黄色虚实线，靠近机动车一侧是虚线，所以车辆在此处是可以掉头的。","k":"图中车道上划有掉头标志，表示“允许掉头”，题目说“可以掉头”，题目和图片一致答正确。","p":"2025080701.jpg","j":""},{"i":3040035,"c":303,"x":4,"y":1,"q":"驾车驶入图中所示路口时，允许掉头行驶。","o":["正确","错误"],"a":"A","e":"图中标志是：允许掉头：表示前方路口可以在虚线处掉头。此标志设在允许掉头的路口前适当位置。","k":"图中标志是“允许掉头”，题目和图片一致答正确。","p":"2025080218.jpg","j":""},{"i":3040036,"c":303,"x":4,"y":1,"q":"驾驶车辆驶入图中所示路口时，禁止掉头。","o":["正确","错误"],"a":"A","e":"图中标志是：禁止掉头。表示前方路口禁止一切车辆掉头。此标志设在禁止掉头的路口前适当位置。","k":"图中标志是“禁止掉头”，题目和图片一致答正确。","p":"2025080219.jpg","j":""},{"i":3040037,"c":303,"x":4,"y":3,"q":"遇图中标志，以下做法错误的是（ ）。","o":["占对向车道行驶","靠右侧减速行驶","轧道路中心标线行驶","加速通过"],"a":"ACD","e":"在图中急弯道行驶，应减速、靠右、鸣喇叭，注意对向来车。","k":"题目问错误的，占、轧、加速都是错的。","p":"2025080221.jpg","j":""},{"i":3040038,"c":303,"x":4,"y":2,"q":"遇图中路段，以下说法正确的是（ ）。","o":["鸣喇叭，加速通过","减速、鸣喇叭、靠右行","借用对向车道行驶","轧道路中心标线行驶"],"a":"B","e":"","k":"","p":"2025080225.jpg","j":""},{"i":3010014,"c":304,"x":4,"y":3,"q":"驾车通过隧道时，禁止（ ）。","o":["超车","停车","掉头","倒车"],"a":"ABCD","e":"在隧道内照明不足，视线不清，难以观察周围安全情况，所以禁止倒车、掉头、停车、超车。","k":"隧道:开近光靠右，注意对向车，保持大间距，倒掉停超都禁止。","p":"","j":""},{"i":3040039,"c":304,"x":4,"y":1,"q":"遇连续降雨天气出行，山区公路可能路肩疏松、堤坡坍塌，要选择道路坚实路面行驶。","o":["正确","错误"],"a":"A","e":"山区公路连续降雨，土质容易疏松、堤坡坍塌，有泥石流的危险，应选择坚实路面行驶，以免掉下悬崖发生危险。","k":"科目四题中看到“可能”都是对的。（只有和“加速”、“只要”、“由近及远”同时出现答错。）","p":"","j":""},{"i":3040040,"c":304,"x":4,"y":2,"q":"如图所示，驾驶机动车在山区冰雪道路上遇前车正在上坡，正确的做法是什么？","o":["连续鸣喇叭催促","连续变换远近光灯催促","前车通过后再上坡","紧随前车上坡"],"a":"C","e":"冰雪道路易滑，前车正在上坡，可能会因路面打滑而产生后溜，跟在后面行驶，可能会发生事故。所以要等前车通过后，再爬坡。","k":"答案里看到“通过后”的，直接选。","p":"2025080226.jpg","j":""},{"i":3040041,"c":304,"x":4,"y":1,"q":"驾驶车辆遇桥下积水较深要绕行。","o":["正确","错误"],"a":"A","e":"桥下积水很深，如果贸然行驶，可能会发生水淹的危险，所以应绕道行驶。","k":"积水深绕行是对的。","p":"","j":""},{"i":3040042,"c":304,"x":4,"y":1,"q":"行驶在湿滑路面紧急制动时易发生侧滑。","o":["正确","错误"],"a":"A","e":"由于湿滑路面很容易打滑，如果采取紧急制动（急踩刹车），容易发生侧滑或横滑，是非常危险的行为。","k":"判断题中有“侧滑”二字都是对的。只有和“动方向”意思同时出现答错。（列车题除外）","p":"","j":""},{"i":3040043,"c":304,"x":4,"y":1,"q":"驾车在图中山区危险路段会车，靠山体一侧车辆应让行。","o":["正确","错误"],"a":"A","e":"在图中傍山险路会车时，应减速靠右，靠山一侧应让不靠山一侧先行。","k":"科目四题中有“让行”的都是对的。（例外：“不让”、“主路让”、“非机动车让”、“加速车道停车让”、“让行线”这五种情况是错的。）","p":"2025080227.jpg","j":""},{"i":3040044,"c":304,"x":4,"y":1,"q":"驾车在湿滑路面急踩制动踏板，易导致侧滑。","o":["正确","错误"],"a":"A","e":"由于湿滑路面很容易打滑，如果采取紧急制动（急踩刹车），容易发生侧滑或横滑，是非常危险的行为。","k":"科目四题中有“导致”的都是对的。（只有和“隐患”同时出现答错）","p":"","j":""},{"i":3040045,"c":304,"x":4,"y":1,"q":"驾车驶出隧道时要控制车速，以适应光线变化。","o":["正确","错误"],"a":"A","e":"进出隧道时，里外的光线差别很大，驾驶人眼睛不能很快适应，应当减速慢行，适应光线的变化。","k":"题目中有“控制车速”的都是对的。（只有和“二级”同时出现答错）","p":"","j":""},{"i":3040046,"c":304,"x":4,"y":1,"q":"通过急弯路段遇前方车辆行驶缓慢，可以加速超车。","o":["正确","错误"],"a":"B","e":"","k":"","p":"","j":""},{"i":3040047,"c":304,"x":4,"y":1,"q":"如图所示，驾驶机动车遇到这种情况要靠右侧停车等待。","o":["正确","错误"],"a":"A","e":"图中前方是隧道，对向有车辆驶出隧道，此时信号灯为红色，应当靠右停车等候。","k":"判断题有“靠右”的直接答对。","p":"2025080231.jpg","j":""},{"i":3040048,"c":304,"x":4,"y":2,"q":"冰雪道路对安全行车的主要影响是（ ）。","o":["制动距离延长，方向易跑偏","行驶阻力增大","能见度降低，视野模糊","电器设备易受潮短路"],"a":"A","e":"下雪路面结冰变滑，阻力减小，这时候刹车可能稳定性不高，容易跑偏。","k":"科目四题中问“主要影响”的，雾天找“见”，雨天找“滑”，其他选字最多的答案。","p":"","j":""},{"i":3040049,"c":304,"x":4,"y":1,"q":"如图所示，驾驶机动车在积雪路段行驶时，可根据路边树木等参照物判断行驶路线。","o":["正确","错误"],"a":"A","e":"下雪天，如果积雪太厚，看不到路面，可以通过参照物判断道路的位置，注意行车安全。","k":"判断题中有“积雪”的，直接答对。","p":"2025080232.jpg","j":""},{"i":3040050,"c":304,"x":4,"y":1,"q":"在长隧道行驶，应在进隧道前打开远光灯。","o":["正确","错误"],"a":"B","e":"因为隧道内光线不足，能见度低，所以驾驶机动车进入长隧道前要提前开启近光灯，提高能见度，便于看清路况。","k":"使用远光灯的都是错的。","p":"","j":""},{"i":3040051,"c":304,"x":4,"y":1,"q":"进隧道前为防止追尾，应降低行车速度，保持足够安全距离。","o":["正确","错误"],"a":"A","e":"进入隧道前光线充足，进入后视线变暗，这时眼睛有个暗适应的过程。所以进入隧道前一定减速慢行，保持充足的安全距离，防止追尾。","k":"题目有‘安全距离’或加大车距意思的都是对的。","p":"","j":""},{"i":3040052,"c":304,"x":4,"y":1,"q":"驶出隧道时为适应光线变化，应减速慢行。","o":["正确","错误"],"a":"A","e":"驶出隧道时，里外光线差别很大，驾驶人眼睛不能很快适应，应当减速慢行，适应光线的变化。","k":"科目四题中有“减速慢行”都是对的。（图中有行人横穿和开车灯标志的除外。）","p":"2025080233.jpg","j":""},{"i":3040053,"c":304,"x":4,"y":3,"q":"夜间对安全行车的影响有（ ）。","o":["能见度低、不利于观察道路情况","车辆较少","驾驶人容易疲劳","驾驶人反应变慢"],"a":"ACD","e":"夜间光线较暗，有些地方照明条件较差，视线容易受阻，不能很好地观察道路情况。夜间驾驶人容易疲劳，反映也容易变慢。车辆少不会影响驾驶安全。","k":"关于“夜间影响”的多选题，答案选三个最长的。","p":"","j":""},{"i":3040054,"c":304,"x":4,"y":1,"q":"图中红圈中交通标志表示应注意适当提高车速。","o":["正确","错误"],"a":"B","e":"红圈内警告标志是：隧道。提醒前方是照明不好的隧道，应注意慢行。","k":"判断题中有“提高车速”的都是错的。","p":"XT2025061101.jpg","j":""},{"i":3040055,"c":304,"x":4,"y":1,"q":"驾车通过山区急弯路段，要减速、鸣喇叭、靠右行。","o":["正确","错误"],"a":"A","e":"弯道行驶原则：减速、靠右、鸣喇叭。靠右行是为了避免与对向来车发生碰撞。","k":"判断题有“靠右”的直接答对。","p":"","j":""},{"i":3040056,"c":304,"x":4,"y":3,"q":"关于驾车雨天路面湿滑不宜超车，以下说法正确的是（ ）。","o":["不易控制方向","能见度降低","车辆易侧滑","制动距离延长"],"a":"ABCD","e":"雨天驾驶路面湿滑，由于雨水的影响能见度会降低，车轮与地面的附着力减小易发生侧滑，不易控制方向。制动距离相对于普通路面会延长，所以应注意保持车距，减速慢行，尽量避免超车，以免发生车辆侧翻等意外事故。","k":"关于“雨天不宜超车”的多选题，答案全选。","p":"","j":""},{"i":3040057,"c":304,"x":4,"y":2,"q":"驾车遇图中标志，下列做法正确的是（ ）。","o":["靠右侧正常通过","开前照灯告知对面车让行","停车让对面车优先通过","鸣喇叭，加速通过隧道"],"a":"C","e":"图上右侧是禁令标志：停车让行。表示如果对向有来车，我方应该停车让对方先行。","k":"谁粗谁先行。图中右侧标志对方箭头粗，答案找“让对面车”。","p":"2025080234.jpg","j":""},{"i":3040058,"c":304,"x":4,"y":2,"q":"驾车通过图中漫水桥，速度不得超过（ ）。","o":["60公里/小时","50公里/小时","40公里/小时","30公里/小时"],"a":"D","e":"机动车行经漫水路或者漫水桥时，应当停车察明水情，确认安全后，低速通过。车速不要超过30公里/小时。","k":"特殊危险路段，车速不得超30公里/小时。","p":"2025080236.jpg","j":""},{"i":3040059,"c":304,"x":4,"y":1,"q":"遇图中情形，应驶入前方再插入左侧车道。","o":["正确","错误"],"a":"B","e":"图中前方有施工路段，驾驶人看到这种情况，应提前在虚线处变更车道行驶。","k":"题目中有“插入”的，直接答错。","p":"2025080237.jpg","j":""},{"i":3040060,"c":304,"x":4,"y":2,"q":"驾驶机动车在高速公路遇到强浓雾天气，能见度过低时，以下做法正确的是什么？","o":["进入应急车道行驶","在行车道加速行驶","尽快驶离高速公路","立即停车"],"a":"C","e":"高速公路遇强浓雾天气,根本看不清任何东西，继续行驶在高速公路非常危险，应开启雾灯、近光灯、示廓灯、前后位灯和危险报警闪光灯，尽快驶离高速公路。","k":"","p":"","j":""},{"i":3040061,"c":304,"x":4,"y":1,"q":"山区连续下坡路段可以超车。","o":["正确","错误"],"a":"B","e":"在图中这种连续下坡路段车辆由于重力作用，车速容易过快，比平路时操控困难，刹车距离变长，转向控制难度加大等，应避免超车。","k":"判断题中“不得超车”的都对；“可以超车”的都错。","p":"2025080240.jpg","j":""},{"i":3040062,"c":304,"x":4,"y":3,"q":"驾车驶入隧道前，以下说法错误的是（ ）。","o":["开启远光灯","可提高车速","开启危险报警闪光灯","降低车速"],"a":"ABC","e":"隧道内视线不好，所以进入隧道前要降低车速，开启近光灯，按照限速规定行驶，行驶过程中要与前车保持足够的安全距离。","k":"关于“隧道前……错误的”多选题，答案不选“降低车速”，选其他三个。","p":"","j":""},{"i":3040063,"c":304,"x":4,"y":2,"q":"夜间行车应在哪种情况下开启远光灯？","o":["无路灯或照明差的道路","会车","超车","近距离跟车"],"a":"A","e":"","k":"","p":"","j":""},{"i":3040064,"c":304,"x":4,"y":1,"q":"夜间通过照明不良路段可开启远光灯，但近距离跟车不得使用远光灯。","o":["正确","错误"],"a":"A","e":"只有在没有路灯或者没有照明的情况下才能用远光灯，一般都用近光灯。夜间会车，近距离跟车若使用远光灯，会让对方完全看不清，进而引发交通事故。","k":"科目四题中有“不得”的都是对的。（只有和“长时”、“离开”、“变换”、“只需”同时出现答错。）","p":"","j":""},{"i":3040065,"c":304,"x":4,"y":1,"q":"夜间在无路灯路段跟车较近时，不得使用远光灯。","o":["正确","错误"],"a":"A","e":"夜间在没有路灯或照明差的道路上行驶可以使用远光灯，近距离跟车、会车都必须使用近光灯。","k":"科目四题中有“不得”的都是对的。（只有和“长时”、“离开”、“变换”、“只需”同时出现答错。）","p":"","j":""},{"i":3040066,"c":304,"x":4,"y":2,"q":"夜间遇图中情形超车时要怎样使用灯光？","o":["开远光灯","交替使用远近光","开近光灯","开危险报警闪光灯"],"a":"B","e":"夜间超车交替使用远近光灯，会使前方驾驶员更容易发现你的超车意图，或者鸣喇叭提醒。","k":"夜间超车应“交替使用远近光灯”提示前车。","p":"2025080241.jpg","j":""},{"i":3040067,"c":304,"x":4,"y":1,"q":"驾车在能见度小于50米的大雾天气行驶，应开启雾灯、示廓灯、前后位灯、近光灯和危险报警闪光灯。","o":["正确","错误"],"a":"A","e":"能见度小于50米时，应开启雾灯、近光灯、示廓灯、前后位灯和危险警报灯，车速不得超过每小时20公里，并从最近的出口尽快驶离高速公路。","k":"题目中有“开启近光灯”、“交替使用远近光灯”都是对的。","p":"","j":""},{"i":3040068,"c":304,"x":4,"y":3,"q":"如图，夜间驾驶车辆在上坡时发生故障，无法继续行驶，做法正确的是（ ）。","o":["开启示廓灯、后位灯、危险报警闪光灯","使用驻车制动器","在车后方正确设置警告标志","驾乘人员在车外安全地点等候救援"],"a":"ABCD","e":"夜间在上坡路故障停车后，应拉紧手刹，绝对不可以空挡，防止溜车。立即开启危险报警闪光灯和相应灯光，在车后方设置警告标志，车上人员转移到安全地点等候救援。","k":"关于“发生故障”的多选题，不选“车内等”、“雾灯”、“不开灯”，其他全选。","p":"2025080242.jpg","j":""},{"i":3040069,"c":304,"x":4,"y":1,"q":"遇图中情形要加速冲过坡顶。","o":["正确","错误"],"a":"B","e":"","k":"","p":"2025080243.jpg","j":""},{"i":3040070,"c":304,"x":4,"y":2,"q":"雾天会车，以下做法错误的是（ ）。","o":["降低行驶速度","增大横向距离","开启远光灯","开启雾灯"],"a":"C","e":"雾天行驶能见度很低，应开启雾灯，降低车速行驶，会车时应保持横向安全距离，避免剐蹭。","k":"题目问错误的，“开启远光灯”都是错的。","p":"","j":""},{"i":3040071,"c":304,"x":4,"y":1,"q":"夜间驾车通过人行横道时，可开启远光灯示意。","o":["正确","错误"],"a":"B","e":"夜间通过人行横道时，应交替使用远、近光灯提醒行人和车辆注意，然后减速通过路口。","k":"开远光灯的都是错的。","p":"","j":""},{"i":3040072,"c":304,"x":4,"y":1,"q":"驾驶车辆在冰雪道路遇紧急情况时，不应紧急制动，但可急转方向避让。","o":["正确","错误"],"a":"B","e":"冰雪道路本身就比较滑，难以控制方向，如果急转方向就更不受控制，从而引发事故。","k":"题目中有“急转向”动作的都是错的，“不急转向”的都是对的。","p":"","j":""},{"i":3040073,"c":304,"x":4,"y":2,"q":"车辆进入山区弯道前，若对向无来车，以下哪种做法正确？","o":["减速、鸣喇叭","靠左行驶","临时借用对向车道","加速紧贴弯道行驶"],"a":"A","e":"山区弯道为避免对面有来车，应当减速、靠右、鸣喇叭。即使对向没有来车，也不可以借对向车道行驶。","k":"弯道行驶原则：减速、靠右、鸣喇叭。","p":"","j":""},{"i":3040074,"c":304,"x":4,"y":3,"q":"夜间驾驶车辆发生故障停车时要开启（ ）。","o":["前后雾灯","危险报警闪光灯","示廓灯","后位灯"],"a":"BCD","e":"夜间发生故障，首先应开启危险报警闪光灯、示廓灯、后位灯，然后减速靠边停车，最后在来车方向设置警告标志。","k":"关于“发生故障”的多选题，不选“车内等”、“雾灯”、“不开灯”，其他全选。","p":"","j":""},{"i":3040075,"c":304,"x":4,"y":2,"q":"夜间超车遇前车低速行驶、不让路，以下做法正确的是（ ）。","o":["连续鸣喇叭催促","开远光灯","放弃超车","近距离跟车行驶"],"a":"C","e":"超车时遇到前车不让路，说明不符合超车条件，应放弃超车，等前车让路后再超，否则容易发生危险。","k":"答案里有“放弃”二字的直接选。","p":"","j":""},{"i":3040076,"c":304,"x":4,"y":3,"q":"夜间驾驶车辆发现灯光照射逐渐离开路面，说明可能行驶至（ ）。","o":["上坡路段","下坡路段","积水处","急转弯、大坑"],"a":"BD","e":"在平直的路面时，灯光距离不变；但是如果前方出现弯道、大坑或下坡时，灯光就会离开路面，照射到比较远的地方。","k":"关于“灯光离开路面”的多选题，答案选两个“下坡”和“大坑”。","p":"","j":""},{"i":3040077,"c":304,"x":4,"y":1,"q":"夜间通过急弯、人行横道时，应交替使用远近光灯示意。","o":["正确","错误"],"a":"A","e":"夜间通过急弯或人行横道时，应交替使用远、近光灯提醒行人和车辆注意，然后减速通过。","k":"题目中有“开启近光灯”、“交替使用远近光灯”都是对的。","p":"","j":""},{"i":3040078,"c":304,"x":4,"y":1,"q":"夜间驾车因车流较少，可适当提高车速。","o":["正确","错误"],"a":"B","e":"夜间光线较暗，有些地方照明条件较差，视线容易受阻，不能很好地观察道路情况，所以应减速慢行。","k":"判断题中有“提高车速”的都是错的。","p":"","j":""},{"i":3040079,"c":304,"x":4,"y":3,"q":"夜间在窄路遇对向非机动车驶来，以下做法正确的是（ ）。","o":["开启近光灯","开启危险报警闪光灯","开启远光灯","减速避让"],"a":"AD","e":"夜间在窄路与非机动车会车应使用近光灯，注意观察非机动车，减速避让。","k":"会车一律近光灯，所以不选“远光灯”、“危险报警闪光灯”，选其他两个。","p":"","j":""},{"i":3040080,"c":304,"x":4,"y":2,"q":"傍山险路行车遇图中弯道，以下哪种做法正确？","o":["加速通过","靠左行驶","在路中间行驶","靠右减速通过"],"a":"D","e":"图中是傍山险路弯道处，应注意对向来车，减速、靠右、鸣喇叭。","k":"答案里有“减速靠右”意思的，直接选。","p":"2025080244.jpg","j":""},{"i":3040081,"c":304,"x":4,"y":3,"q":"通过图中急弯处要怎样行驶？","o":["减速靠右行驶","借用对向车道","注意对向来车","鸣喇叭示意"],"a":"ACD","e":"图中是山区弯道，应注意对向来车，减速、靠右、鸣喇叭行驶。路中心线是实线，禁止借道超车。","k":"关于“急弯路”的多选题，答案不选“远光灯”、“借”，其他全选。","p":"2025080247.jpg","j":""},{"i":3040082,"c":304,"x":4,"y":1,"q":"夜间会车遇对向来车持续变换远近光灯，可能是提醒己车未关闭远光灯。","o":["正确","错误"],"a":"A","e":"遇对向车使用远光灯时，可以交替使用远光灯提示对方，所以遇对方车辆持续变换远近光灯时，也可能是在提醒我方的车没有关闭远光灯。","k":"科目四题中看到“可能”都是对的。（只有和“加速”、“只要”、“由近及远”同时出现答错。）","p":"","j":""},{"i":3040083,"c":304,"x":4,"y":1,"q":"驾车在雨天高速公路行驶，降低车速可避免“水滑”。","o":["正确","错误"],"a":"A","e":"水滑是因为雨天雨水多，使轮胎与路面的摩擦系数变小，容易产生侧滑。因此要降低车速行驶，降低发生侧滑的可能性。","k":"判断题中有引号“”的都对。只有和“高速行驶”同时出现时答错。","p":"","j":""},{"i":3040084,"c":304,"x":4,"y":1,"q":"图中交通标志提示进入隧道应关闭车灯。","o":["正确","错误"],"a":"B","e":"图中标志为：开车灯。表示机动车行驶至该标志处应开启车灯，设在隧道口前等需要开车灯处。","k":"图中标志是“开车灯”，题目说“关闭车灯”，题目和图片不一致答错误。","p":"2020031201.jpg","j":""},{"i":3040085,"c":304,"x":4,"y":1,"q":"驾车在山区道路行驶为确保安全，应在道路中间会车。","o":["正确","错误"],"a":"B","e":"在山区道路遇对向来车时，应选择安全路段减速或停车交会，为临崖车辆（不靠山一侧）留出足够的时间、空间会车。","k":"科目四题中看到“中间”的都是错的。（只有和“避免”同时出现答对。）","p":"","j":""},{"i":3040086,"c":304,"x":4,"y":1,"q":"夜间近距离跟车可开启远光灯。","o":["正确","错误"],"a":"B","e":"夜间在没有路灯或照明差的道路上行驶可以使用远光灯，近距离跟车、会车都必须使用近光灯。","k":"开远光灯的都是错的。","p":"","j":""},{"i":3040087,"c":304,"x":4,"y":3,"q":"隧道内行车，以下做法错误的是（ ）。","o":["会车使用远光灯","压实线变更车道","会车保持安全间距","开启近光灯"],"a":"AB","e":"隧道内光线不好，应开启近光灯，跟车、会车都应保持安全距离行驶，尽量不要变更车道，确需变更车道应在虚线区完成变更。","k":"题目让选错误的，“使用远光灯”、“压实线”都是错的。","p":"","j":""},{"i":3040088,"c":304,"x":4,"y":3,"q":"夜间会车遇对向来车开启远光灯，经提醒仍不关闭，以下哪种做法正确？","o":["开启远光灯","减速，必要时停车","开启危险报警闪光灯","视线稍右移，避免直视"],"a":"BD","e":"会车时，对方一直不关闭远光灯，我方可交替使用远近光灯提示，同时视线向右平移，防止眩目，减速靠右侧行驶或停车避让，以保证安全会车。","k":"科目四关于“远光灯”的多选题，答案不选“远光灯”、“闪光灯”、“迅速”、“不停”，其他全选。","p":"2020031602.jpg","j":""},{"i":3040089,"c":304,"x":4,"y":1,"q":"图中交通标志表示应提前将行车速度调整到80km/h以下，打开车灯。","o":["正确","错误"],"a":"A","e":"图中右侧标志是：限制最高速度80公里/每小时和开车灯，应开启前照灯近光灯，注意行驶。","k":"图中有“开车灯”标志，题目说“开车灯”，题目和图片一致答正确。","p":"2025080249.jpg","j":""},{"i":3040090,"c":304,"x":4,"y":1,"q":"驾车通过图中桥梁，应握紧转向盘，注意横风。","o":["正确","错误"],"a":"A","e":"图中右侧标志是：注意横风。行驶在这种桥梁路段应紧握转向盘，控制好方向，注意横向来风。","k":"图中标志是“注意横风”，题目和图片一致答正确。","p":"2025080250.jpg","j":""},{"i":3040091,"c":304,"x":4,"y":2,"q":"在雨天湿滑路面行驶，以下做法错误的是（ ）。","o":["避免紧急制动、转向","保持足够安全距离","注意非机动车和行人动态","加速超车"],"a":"D","e":"湿滑路面很容易打滑，应避免紧急制动，以免发生侧滑或横滑；行驶中保持足够的安全距离并时刻注意非机动车和行人的行驶方向。","k":"题目问错误的，“加速”都是错的。","p":"","j":""},{"i":3040092,"c":304,"x":4,"y":1,"q":"驾车在下坡路段停车制动需比在平缓路段提前操作。","o":["正确","错误"],"a":"A","e":"下坡行驶时，在重力的作用下速度会逐渐提高，因而下坡路段停车制动距离会比平路时长，所以要比在平路时提前。","k":"题目里有‘提前’的都是对的，只有和“加速’、‘不受’同时出现答错。","p":"","j":""},{"i":3040093,"c":304,"x":4,"y":1,"q":"车辆在隧道内发生故障，如能行驶应慢行驶离隧道，在安全地点停车。","o":["正确","错误"],"a":"A","e":"隧道内出现故障，可以行驶的应尽量驶出隧道，在安全区域停车检查。如果无法移动，应立即开启危险报警闪光灯，保证安全的情况下取出三角警示牌放置在车后，一般要在150m以外，同时车内其他人员尽快远离车辆，转移到安全地点等候救援，并报警。","k":"判断题中有“安全地点”四个字的,直接答正确。","p":"","j":""},{"i":3040094,"c":304,"x":4,"y":1,"q":"雨天高速公路保持高速行驶时，能够提高轮胎排水量，降低出现“水滑”的可能性。","o":["正确","错误"],"a":"B","e":"“水滑”现象是指雨天高速行车，轮胎和路面之间会形成“水膜”，摩擦系数变小，容易侧滑。所以应降低车速行驶，减少发生侧滑的可能性。","k":"判断题中有引号“”的都对。只有和“高速行驶”同时出现时答错。","p":"","j":""},{"i":3040095,"c":304,"x":4,"y":2,"q":"驾车在图中山区窄路遇对向来车，以下做法正确的是（ ）。","o":["减速","在道路中心行驶","加速通过","停车让行"],"a":"D","e":"在图中这种山区道路遇对向有来车，对方在临崖一侧，我方应停车让行，安全会车。","k":"山区窄路会车，靠山一侧应停车让行。","p":"2025080253.jpg","j":""},{"i":3040096,"c":304,"x":4,"y":2,"q":"遇图中隧道对向有车驶来，以下说法正确的是（ ）。","o":["靠右通过","鸣喇叭，加速通过","停车让对向车先行","开启近光灯告知对向车让行"],"a":"C","e":"图中隧道前只有一条车道，且对向有来车，我方车辆应减速靠右停车让行。","k":"答案有“先让”意思的，直接选。","p":"2025080255.jpg","j":""},{"i":3040097,"c":304,"x":4,"y":1,"q":"驾车在山区下坡路段行驶时，受重力影响车辆制动和操控难度变大，因此不能超车。","o":["正确","错误"],"a":"A","e":"驾驶机动车在山区道路下坡路段尽量避免超车，因为下坡路段车辆由于重力作用，车速容易过快，车辆比平路时更难操控，此时超车容易发生危险。","k":"题目中有“不能超车”的都是对的，“可以超车”的都是错的。","p":"","j":""},{"i":3040098,"c":304,"x":4,"y":1,"q":"在隧道内看到此交通标志，表示车辆故障等紧急情况下在该区域可临时停车。","o":["正确","错误"],"a":"A","e":"图中是指路标志：港湾式紧急停车带。指示前方路段设有紧急停车带的位置。车辆故障时可以临时停车。","k":"图中标志是“紧急停车带”，可以临时停车，题目和图片一致答对。","p":"2020031408.jpg","j":""},{"i":3040099,"c":304,"x":4,"y":3,"q":"雨天对安全行车的主要影响是（ ）。","o":["电器设备易受潮短路","路面湿滑","视线受阻","行驶阻力增大"],"a":"BC","e":"雨天路面湿滑，雨水会使视线受阻，所以更要注意行车安全。","k":"关于“雨天主要影响”的多选题，答案找两个最短的。","p":"","j":""},{"i":3040100,"c":304,"x":4,"y":1,"q":"驾车在山区道路跟车要适当增大跟车距离。","o":["正确","错误"],"a":"A","e":"在图中这种山区弯路的上坡路段跟车行驶，应加大跟车距离，以防前车后溜，引发事故。","k":"题目有‘安全距离’或加大车距意思的都是对的。","p":"2025080258.jpg","j":""},{"i":3040101,"c":304,"x":4,"y":1,"q":"驾车在山区弯道行驶遇前车行驶缓慢，可越实线借用对向车道超车。","o":["正确","错误"],"a":"B","e":"在图中这种急弯道行驶，应尽量避免超车，以免发生危险。并且道路中心线是实线，禁止跨越超车。","k":"科目四题中有“借”字的都是错的。（只有一题“借用快速车道”是对的。）","p":"2025080259.jpg","j":""},{"i":3040102,"c":304,"x":4,"y":1,"q":"在山区上坡路段行驶时，减挡操作需及时、准确且迅速。","o":["正确","错误"],"a":"A","e":"在上坡，或者车速较低时需要挂低速挡保持动力，强行采用高挡位会造成拖挡，会增加油耗并损坏发动机和传动系统。","k":"判断题出现“及时”二字的都是对的。（影响安全的行为除外。）","p":"","j":""},{"i":3040103,"c":304,"x":4,"y":2,"q":"如何在图中道路上安全行驶？","o":["减速靠右侧行驶","压中心线行驶","靠右加速通过","借对向车道行驶"],"a":"A","e":"图中是弯道，为了避免与对向车发生碰撞，我方车应该减速靠右侧行驶。","k":"答案里有“减速靠右”意思的，直接选。","p":"2025080263.jpg","j":""},{"i":3040104,"c":304,"x":4,"y":2,"q":"驾驶车辆遇团雾时，以下做法错误的是（ ）。","o":["开启危险报警闪光灯","开启雾灯、示廓灯、后位灯","轻踩制动踏板减速","与前方车辆近距离行驶时开启远光灯"],"a":"D","e":"","k":"","p":"","j":""},{"i":3040105,"c":304,"x":4,"y":3,"q":"驾车在湿滑路面减速，以下做法正确的是（ ）。","o":["迅速踩下制动踏板","控制转向盘","使用驻车制动器减速","缓踩制动踏板"],"a":"BD","e":"湿滑路面，车轮和地面之间摩擦力很小，迅速踏制动踏板容易引起侧翻。所以应该先握紧方向盘，控制住方向，然后缓踩制动踏板或利用低挡位减速，也就是利用发动机制动。","k":"关于“湿滑路面减速”的多选题，答案找两个最短的。","p":"","j":""},{"i":3040106,"c":304,"x":4,"y":1,"q":"驾车遇团雾时，应降低车速，与前车保持安全距离，并观察后方来车，以防追尾。","o":["正确","错误"],"a":"A","e":"团雾一般都是突然发生的，无法预测。遇到团雾时一定减速慢行，开启雾灯，注意观察，保持安全距离行驶。","k":"题目有‘安全距离’或加大车距意思的都是对的。","p":"","j":""},{"i":3040107,"c":304,"x":4,"y":1,"q":"驾驶车辆遇漫水桥，要停车观察水情确保行车安全后，挂低速挡匀速通过。","o":["正确","错误"],"a":"A","e":"遇图中这种漫水桥，应停车察明水情，确认安全后，减速缓慢通过。","k":"判断题里有“挂低速挡”、“用低速挡”的，直接答对。","p":"picture_61.jpg","j":""},{"i":3040108,"c":304,"x":4,"y":3,"q":"驾车在隧道行驶，以下做法正确的是（ ）。","o":["提高车速，尽快驶离","在紧急停车带停车休息","和前车保持安全车距","按照限速行驶"],"a":"CD","e":"隧道内视线不好，所以进入要开启前照近光灯，按照限速规定行驶，行驶过程中要与前车保持足够的安全距离。隧道内的紧急停车带是车辆故障或遇紧急情况停车的，不可停车休息。","k":"题目问正确的，隧道“提高车速”、“停车”都是错的，所以不选，选其他两个。","p":"","j":""},{"i":3040109,"c":304,"x":4,"y":1,"q":"隧道行车发现行驶路线错误时，应驶出隧道在安全地点停车后再查询路线。","o":["正确","错误"],"a":"A","e":"隧道内禁止停车、倒车、超车、掉头。所以发现行驶路线错误时，只能继续向前行驶，驶出隧道后再找合适的路线。","k":"判断题中有“安全地点”四个字的,直接答正确。","p":"","j":""},{"i":3040110,"c":304,"x":4,"y":1,"q":"进出隧道时应注意光线变化，提前降低车速。","o":["正确","错误"],"a":"A","e":"隧道里面光线较暗，进出隧道时眼睛一时无法适应光线变化，所以应与前车保持安全距离，降低行驶车速。","k":"题目里有‘提前’的都是对的，只有和“加速’、‘不受’同时出现答错。","p":"","j":""},{"i":3040111,"c":304,"x":4,"y":3,"q":"驾车通过隧道时，禁止（ ）。","o":["变更车道","停车","掉头","倒车"],"a":"BCD","e":"","k":"技巧得再换","p":"","j":""},{"i":3040112,"c":304,"x":4,"y":1,"q":"遇图中情形，应鸣喇叭提示对向车让行。","o":["正确","错误"],"a":"B","e":"图中右侧标志是：会车让行。所以此时己车应停车让对方先行。","k":"标志里朝上的红箭头代表我方，应是“我方让行”，题目说“对方车让行”，题目和图片不一致答错误。","p":"2025080602.jpg","j":""},{"i":3040113,"c":304,"x":4,"y":1,"q":"驾车通过桥梁路段为避免颠簸，应提前降低车速。","o":["正确","错误"],"a":"A","e":"车辆通过桥梁、弯道、陡坡这种危险路段时，都应该减速慢行，禁止超车、掉头、停车。","k":"题目里有‘提前’的都是对的，只有和“加速’、‘不受’同时出现答错。","p":"","j":""},{"i":3040114,"c":304,"x":4,"y":3,"q":"夜间驾驶车辆发生故障时，以下哪种做法正确？","o":["应在车内等候救援","按规定设置警告标志","为省电不开启任何灯光","驾乘人员迅速转移到安全地带"],"a":"BD","e":"夜间车辆发生故障时，应开启危险报警闪光灯、示廓灯和后位灯，选择安全区域停车后，再按规定设置警告标志。离开车子站在安全地方报警或者打救援电话，等待救援。","k":"关于“发生故障”的多选题，不选“车内等”、“雾灯”、“不开灯”，其他全选。","p":"","j":""},{"i":3040115,"c":304,"x":4,"y":3,"q":"关于设置警告标志，以下哪种做法正确？","o":["应设置在来车方向","普通公路设置在50至100米处","高速公路应设置在150米外","设置完后回车内等待"],"a":"ABC","e":"交通法规定：车辆故障放置警告标志，普通公路是距来车方向50-100米处。高速公路是距来车方向150米以外。","k":"关于“警告标志”的多选题，不选“车内等”，选其他三个。","p":"","j":""},{"i":3040116,"c":304,"x":4,"y":1,"q":"在山区弯道行驶时，严禁跨越道路中心线。","o":["正确","错误"],"a":"A","e":"山区弯道为避免对面有来车，应当减速、靠右、鸣喇叭。禁止跨越中心线行驶。","k":"判断题中看到“严禁”，直接答对。","p":"","j":""},{"i":3040117,"c":304,"x":4,"y":1,"q":"驾车遇图中前车扬灰情形要加速超车。","o":["正确","错误"],"a":"B","e":"驾驶机动车在图中这种弯道行驶，遇前车扬灰的拉土车，应保持安全距离，减速行驶，避免超车。","k":"题目里有“加速超车”的都是错的。","p":"2025080601.jpg","j":""},{"i":3040118,"c":304,"x":4,"y":1,"q":"降低轮胎气压可以避免爆胎。","o":["正确","错误"],"a":"B","e":"","k":"","p":"","j":""},{"i":3040119,"c":304,"x":4,"y":3,"q":"夜间会车遇对向来车开启远光灯，以下做法正确的是（ ）。","o":["变换远近光灯提示","视线右移，避免直视","减速靠右行驶","切换为远光灯"],"a":"ABC","e":"会车时，对向车开启远光灯。我方可交替使用远近光灯提示，视线向右平移，防止眩目，同时减速靠右侧行驶或停车让行。","k":"科目四关于“远光灯”的多选题，答案不选“远光灯”、“闪光灯”、“迅速”、“不停”，其他全选。","p":"","j":""},{"i":3040120,"c":304,"x":4,"y":3,"q":"如图所示，驾驶机动车不能确认路侧是否有障碍物时，以下做法正确的是什么?","o":["交替变换远近光灯查看路况","加速尽快通过","减速","连续鸣喇叭提示，加速通过"],"a":"AC","e":"夜间行驶视线不好，无法确定周围是否有障碍物，应减速慢行，交替变换远近光灯，利用明暗变化观察路况。","k":"题目问正确的，“加速”都是错的，所以不选，选其他两个。","p":"8885.jpg","j":""},{"i":3010013,"c":305,"x":4,"y":1,"q":"遇后轮爆胎时，应握稳转向盘，缓慢减速，通过后视镜关注后方车辆情况，安全驶离行车道，停车后开启危险报警闪光灯，在来车方向设置警告标志，迅速撤离到安全地点报警求助。","o":["正确","错误"],"a":"A","e":"驾驶车辆遇后轮爆胎，应稳握转向盘，缓慢减速，并通过后视镜观察后方的情况，确认安全后驶离行车道，停到安全区域后在来车方向设置警告标志，撤离到安全区域后报警求助。","k":"判断题中有“安全地点”四个字的,直接答正确。","p":"","j":""},{"i":3010016,"c":305,"x":4,"y":2,"q":"驾驶机动车发生爆胎时，首先应该进行的应急操作是什么？","o":["采取紧急制动，尽快减速","握稳转向盘，松抬加速踏板","开启转向灯，迅速停车","松抬加速踏板，迅速踩下离合器，自然减速"],"a":"B","e":"车辆爆胎时，首先应双手紧握方向盘，调整方向，保持直线行驶，然后利用低挡位减速靠边停车，一定不要紧急制动，否则容易造成翻车。","k":"答案里看到“稳握”或“握稳”的，直接选。（错误的不选）","p":"","j":""},{"i":3050004,"c":305,"x":4,"y":1,"q":"驾驶车辆遇电子显示屏故障，应缓慢减速停至安全区域，并尽快报修。","o":["正确","错误"],"a":"A","e":"遇到显示屏故障时，应选择安全区域停车后，尽快联系专业维修店或车辆制造商的技术支持‌。","k":"题目里有“减速停车”都是对的。( 只有和“急踏”同时出现答错。)","p":"","j":""},{"i":3050005,"c":305,"x":4,"y":2,"q":"轮胎胎压过低时高速行驶，轮胎会出现波浪变形，温度升高，导致（ ）。","o":["气压不稳","爆胎","行驶阻力增大","气压更低"],"a":"B","e":"","k":"","p":"","j":""},{"i":3050006,"c":305,"x":4,"y":2,"q":"关于紧急切断阀，以下哪种说法错误？","o":["液体危险货物运输车的紧急切断阀，非装卸时应处于关闭状态","装卸作业完毕后，必须立即按照紧急切断阀使用说明关闭紧急切断阀","运输过程中，及时检查确保紧急切断阀处于关闭状态","紧急切断阀日常使用较少，不列入日常维护范围"],"a":"D","e":"","k":"","p":"","j":""},{"i":3050007,"c":305,"x":4,"y":2,"q":"在车速较高的情况下驾车遇紧急情况，应急操作的原则是（ ）。","o":["先避车后避物","先避人后避物","先避车后避人","先避物后避人"],"a":"B","e":"","k":"","p":"","j":""},{"i":3050008,"c":305,"x":4,"y":1,"q":"在隧道内发生火灾时，应迅速弃车逃生。","o":["正确","错误"],"a":"A","e":"隧道内发生火灾，人命要紧，应尽快弃车逃生。","k":"题目中有“逃生”的都是对的。","p":"","j":""},{"i":3050009,"c":305,"x":4,"y":1,"q":"车辆发生爆胎后，在尚未控制住车速前，不要冒险使用驻车制动器停车，以避免车辆横甩引发生更大的险情。","o":["正确","错误"],"a":"A","e":"","k":"","p":"","j":""},{"i":3050010,"c":305,"x":4,"y":1,"q":"发生爆胎后，不可以长期使用备胎行驶。","o":["正确","错误"],"a":"A","e":"备胎，是用来作为备用轮胎的，大小和花纹一般都和原装的不匹配，因此不能作为正常轮胎长期使用。","k":"科目四题中看到“长期”，答错；“不可以长期”，答对。","p":"","j":""},{"i":3050011,"c":305,"x":4,"y":2,"q":"爆胎时，以下做法错误的是（ ）。","o":["握稳转向盘，控制车辆方向","猛踩制动踏板，尽快停车","松抬加速踏板，轻踩制动踏板","开启右转向灯，逐渐靠路边停车"],"a":"B","e":"车辆爆胎时，首先应双手稳握方向盘，调整方向，保持直线行驶，轻踩制动踏板，然后利用低挡位减速，开启右转向灯，逐渐靠边停车，一定不要紧急制动，否则容易造成翻车。","k":"题目让选错误的，“猛踩”都是错的。","p":"","j":""},{"i":3050012,"c":305,"x":4,"y":2,"q":"驾驶机动车行车制动突然失效时，应如何操作？","o":["不停地连续踩踏制动踏板","逐级减挡，使用驻车制动器，装有缓速器的，使用缓速器","迅速踏下离合器踏板","重启车辆点火开关"],"a":"B","e":"","k":"","p":"","j":""},{"i":3050013,"c":305,"x":4,"y":2,"q":"爆胎时，以下哪种做法正确？","o":["猛踩制动踏板，尽快停车","紧握转向盘，平稳停车","大幅度调整方向","低速行驶，寻找换轮胎地点"],"a":"B","e":"","k":"","p":"","j":""},{"i":3050014,"c":305,"x":4,"y":1,"q":"机动车后车轮抱死时，车辆可能会出现侧滑甩尾。","o":["正确","错误"],"a":"A","e":"前车轮抱死，会丧失转向能力，所以现在小车都有ABS防抱死系统，紧急刹车时不会再抱死出现丧失转向能力的情况。后车轮抱死，车辆会发生甩尾侧滑现象。","k":"判断题看到“抱死”或“ABS”的，有“短”字的答错，没有“短”字的答对。","p":"","j":""},{"i":3050015,"c":305,"x":4,"y":2,"q":"为避免爆胎，日常维护中，以下做法错误的是（ ）。","o":["降低轮胎气压","定期检查轮胎花纹深度","清理轮胎沟槽里的异物","及时更换破损轮胎"],"a":"A","e":"随着胎压的下降，轮胎与地面的摩擦成倍增加，胎温急剧升高，如果车辆高速行驶，就可能导致爆胎。","k":"题目里看到“避免爆胎”，答案找“气压”；多选题不选“气压”，选其它三个。","p":"","j":""},{"i":3050016,"c":305,"x":4,"y":2,"q":"机动车发动机舱着火时，以下灭火方法正确的是什么？","o":["站在发动机舱正面，完全打开舱盖进行灭火","站在发动机舱侧面，完全打开舱盖进行灭火","发动机舱盖打开一定间隙，进行灭火","隔着发动机舱盖，进行灭火"],"a":"C","e":"","k":"","p":"","j":""},{"i":3050017,"c":305,"x":4,"y":3,"q":"驾驶人为保证安全行车要随车携带（ ）。","o":["安全帽","灭火器","安全锤","冷冻液"],"a":"BC","e":"驾车为预防起火、水淹等危险情况的发生，应携带灭火器和安全锤。","k":"应急常识，记住就好！","p":"","j":""},{"i":3050018,"c":305,"x":4,"y":2,"q":"驾驶车辆爆胎时，驾驶人应采取如何的措施降低车速？","o":["采取紧急制动","使用驻车制动","轻踏制动踏板","迅速踏下离合器踏板"],"a":"C","e":"","k":"","p":"","j":""},{"i":3050019,"c":305,"x":4,"y":1,"q":"装卸作业中紧急切断阀处于开启状态，遇紧急情况时，应立即关闭紧急切断阀。","o":["正确","错误"],"a":"A","e":"装卸作业中，如有紧急情况必须立即按照紧急切断阀使用说明书或操作规程关闭紧急切断阀。这样即使输油管道碰撞断裂，罐内液体也不会泄漏。","k":"题目看到“切断阀”，直接答正确。","p":"","j":""},{"i":3050020,"c":305,"x":4,"y":1,"q":"液体危险货物运输车的紧急切断阀，非装卸时应处于关闭状态。","o":["正确","错误"],"a":"A","e":"","k":"","p":"","j":""},{"i":3050021,"c":305,"x":4,"y":1,"q":"车速较高时遇有紧急情况，不减速直接转向避让，容易造成车辆侧滑或翻车。","o":["正确","错误"],"a":"A","e":"车速较高直接转向会影响后车行驶，同时容易引起侧滑和翻车，造成更大事故，所以应该先制动减速，再适当调整方向。","k":"科目四题中有“避让”的都是对的。（只有“不避让”、“避让直行”、动“方向避让”的答错。）","p":"","j":""},{"i":3050022,"c":305,"x":4,"y":1,"q":"驾驶机动车在铁路道口突然熄火，应首先尝试重新启动，无法重新启动时，应立即检修。","o":["正确","错误"],"a":"B","e":"车辆故障原因突然熄火，短时间内发动不着而又无外援时，驾驶人首要的任务不是去打开发动机盖排除故障，而是设法使汽车迅速离开轨道，以免汽车与火车相撞。","k":"科目四题中有“首先”的，都是对的。（只有和“立即”同时出现答错）","p":"","j":""},{"i":3050023,"c":305,"x":4,"y":1,"q":"驾驶车辆发生紧急情况，车门无法开启，可使用安全锤敲击车窗玻璃四角逃生。","o":["正确","错误"],"a":"A","e":"","k":"","p":"","j":""},{"i":3050024,"c":305,"x":4,"y":1,"q":"在隧道内发生交通事故时，使用隧道中紧急电话报警能给救助人员提供准确的位置信息。","o":["正确","错误"],"a":"A","e":"隧道内普通电话一般信号不好，如果发生交通事故是可以通过隧道内的紧急电话报警，以便给救援人员提供准确的事故位置。","k":"题目中有“报警”行为的都对。","p":"","j":""},{"i":3050025,"c":305,"x":4,"y":2,"q":"驾驶机动车制动突然失效，以下做法错误的是什么？","o":["逐级减挡","使用驻车制动器","装有缓速器的，使用缓速器","迅速踏下离合器踏板"],"a":"D","e":"行车制动突然失效，应开启危险报警闪光灯，逐级或越一级减挡，利用发动机制动减速后，使用驻车制动辅助停车。有缓速器的应使用缓速器。迅速踏下离合器是没用的。","k":"题目问错误的，“迅速”的都是错的。","p":"","j":""},{"i":3050026,"c":305,"x":4,"y":1,"q":"雪天跟车行驶应当加大与前车之间的安全距离。","o":["正确","错误"],"a":"A","e":"冰雪路面行驶时，制动距离比平时要大，跟车时应加大两车之间的安全距离。","k":"题目有‘安全距离’或加大车距意思的都是对的。","p":"","j":""},{"i":3050027,"c":305,"x":4,"y":1,"q":"新能源汽车在行驶中起火时，应立即停车，并尽可能迅速地断开车辆电源。","o":["正确","错误"],"a":"A","e":"新能源的电池着火非常危险，如果火势刚起，在能够断电的情况下，应关闭新能源汽车的电源开关，以减少电流供应。火势较大控制时，要立即远离车辆并拨打报警电话。","k":"科目四题中看到“可能”都是对的。（只有和“加速”、“只要”、“由近及远”同时出现答错。）","p":"","j":""},{"i":3070002,"c":307,"x":4,"y":2,"q":"当高速公路上车辆发生故障时，人员应当疏散到图中哪个位置。","o":["位置1","位置3","位置4","位置2"],"a":"C","e":"当高速公路上车辆发生故障时，最右侧的路肩是最安全的，所以人员应当疏散到位置4，车辆停在位置3。","k":"图中位置4是高速公路最右侧的路肩，最安全的地方。","p":"2025080264.jpg","j":""},{"i":3070003,"c":307,"x":4,"y":1,"q":"发生交通事故后，应注意检查是否有燃油泄漏、电池损坏的情况。","o":["正确","错误"],"a":"A","e":"发生事故一定要下车检查，以免留下安全隐患。","k":"科四题中出现“检查”的都是对的。（只有和“刮水器”、“立即”、“怠速状态”同时出现答错。）","p":"","j":""},{"i":3070004,"c":307,"x":4,"y":1,"q":"搬运昏迷失去知觉的伤员要采取侧卧位。","o":["正确","错误"],"a":"A","e":"搬运昏迷的伤员应采用侧卧位，防止伤员误吸入血液、呕吐物或异物导致窒息。仰卧位，会加重阻塞窒息。","k":"搬运昏迷伤员，“侧卧”的对，“仰卧”的错。","p":"","j":""},{"i":3070005,"c":307,"x":4,"y":1,"q":"遇伤者被压在车轮或货物下时，将车轮或货物移开后再将伤者移出。","o":["正确","错误"],"a":"A","e":"被车轮压住的伤者，必须将车轮或货物移开后再将伤者移出。如果硬拖拽的话，会使伤者的伤势加重。","k":"题目中看到，“移出”的答对，“拽出”的答错。","p":"","j":""},{"i":3070006,"c":307,"x":4,"y":1,"q":"冬季隧道出口路面容易结冰，此时应紧急制动停车。","o":["正确","错误"],"a":"B","e":"冬天隧道出口，有可能路面结冰，道路很滑。出隧道之前应该降低车速，不要急刹车，否则容易发生交通事故。","k":"题目中用“紧急制动”的答错。“不紧急制动”、“避免紧急制动”的答对。","p":"","j":""},{"i":3070007,"c":307,"x":4,"y":1,"q":"遇伤者被压在车轮或货物下时，不能立即拉拽伤者的肢体将其拖出。","o":["正确","错误"],"a":"A","e":"被车轮压住的伤者，必须将车轮或货物移开后再将伤者移出。如果硬拖拽的话，会使伤者的伤势加重。","k":"题目中看到，“不能立即”的，直接答正确。","p":"","j":""},{"i":3080001,"c":308,"x":4,"y":1,"q":"同方向有两条机动车道，驾驶摩托车遇校车在道路右侧停车上下学生时，左侧车道后方摩托车可以减速通过。","o":["正确","错误"],"a":"B","e":"校车在路右侧车道上下学生，同向有一条车道或两条车道的，后方的车辆都应该停车等待。同向有三条车道的，中间车道也必须停车等待，只有最左侧车道，利于观察情况，可以减速通过。","k":"校车上下学生，一条或两条车道要停车等待，三条车道的最左侧车道可以减速通过。","p":"2025071706.jpg","j":""},{"i":3080002,"c":308,"x":4,"y":1,"q":"驾驶摩托车不慎落水时，应立即弃车逃生。","o":["正确","错误"],"a":"A","e":"摩托车落水后，人命要紧，应尽快弃车逃生。","k":"题目中有“逃生”的都是对的。","p":"","j":""},{"i":3080003,"c":308,"x":4,"y":2,"q":"雨天驾驶摩托车遇图中场景，应如何礼让？","o":["保持高速行驶","鸣喇叭催促","加速从左侧绕行","提前减速"],"a":"D","e":"图中是雨天积水路段，路侧有行人、非机动车通过，应提前轻按喇叭提示，然后减速慢行通过，防止溅到行人一身水。","k":"答案里有“提前减速”的，直接选。","p":"2025071707.jpg","j":""},{"i":3080004,"c":308,"x":4,"y":1,"q":"驾驶摩托车出行，发现车辆有异响、异味时应停车检查车辆状况。","o":["正确","错误"],"a":"A","e":"驾驶摩托车出行时，如果发现车辆有异响异味，可能是车的某个部位发生故障，应该停车进行检查。","k":"题目看到“停车检查”的，直接答正确。","p":"","j":""},{"i":3080005,"c":308,"x":4,"y":3,"q":"驾驶摩托车在隧道路段通行，禁止的行为有（ ）。","o":["超车","停车","掉头","倒车"],"a":"ABCD","e":"在隧道内照明不足，视线不清，难以观察周围安全情况，所以禁止倒车、掉头、停车、超车。","k":"关于“隧道禁止”的多选题，答案全选。","p":"","j":""},{"i":3080006,"c":308,"x":4,"y":1,"q":"吴某无证驾驶普通二轮摩托车搭载李某（二人均未佩戴安全头盔）行驶途中，摩托车失控发生侧翻，二人当场死亡。未佩戴安全头盔是导致二人死亡的重要原因。","o":["正确","错误"],"a":"A","e":"本题的违法行为有两个：一是吴某无证驾驶；二是未按规定佩戴头盔。但导致二人死亡的重要原因是未按规定佩戴头盔。","k":"案例题目中有“原因”二字的，直接答对。","p":"","j":""},{"i":3080007,"c":308,"x":4,"y":2,"q":"驾驶摩托车驶入图中隧道路段前，应开启的灯光是（ ）。","o":["危险报警闪光灯","远光灯","近光灯","雾灯"],"a":"C","e":"图中右侧有蓝色标志：开车灯。表示机动车行至该标志处应开启车灯，设在隧道口前等需要开车灯处。（开启车道一般指近光灯）","k":"隧道开近光灯。","p":"2025071708.jpg","j":""},{"i":3080008,"c":308,"x":4,"y":2,"q":"如图所示，夜间驾驶摩托车超车遇前方公交车行驶缓慢时，以下做法正确的是（ ）。","o":["连续鸣喇叭催促","开远光灯尾随行驶","确认安全后超车","连续变换远近光灯催促"],"a":"C","e":"图中前方公交车行驶缓慢，路中心线是黄色虚线，此时加大横向间距，确认安全后减速缓慢超越，超越时要特别留意公交车的动态，避免发生碰撞。","k":"答案里有“确认安全”的，直接选。","p":"2025071709.jpg","j":""},{"i":3080009,"c":308,"x":4,"y":1,"q":"驾驶摩托车发生致人死亡的交通事故，应立即抢救伤员并报警。","o":["正确","错误"],"a":"A","e":"发生致人死亡的交通事故，应及时救治伤员，保护现场，立即报警处理。","k":"题目中有“报警”行为的都对。","p":"","j":""},{"i":3080010,"c":308,"x":4,"y":1,"q":"摩托车乘坐人员应按规定戴安全头盔。","o":["正确","错误"],"a":"A","e":"《道路交通安全法》第五十一条规定：“机动车行驶时，驾驶人、乘坐人员应当按规定使用安全带，摩托车驾驶人及乘坐人员应当按规定戴安全头盔。”","k":"题目中有按规定意思的都是对的。","p":"","j":""},{"i":3080011,"c":308,"x":4,"y":1,"q":"驾驶摩托车遇熄火、断电时，应立即减速并靠边停车。","o":["正确","错误"],"a":"A","e":"驾驶摩托车遇熄火、断电时，会影响正常行驶，应立即减速并靠边停车。","k":"判断题有“靠边停车”的，直接答正确。","p":"","j":""},{"i":3080012,"c":308,"x":4,"y":3,"q":"孙某驾驶轻便摩托车（未佩戴安全头盔），在未确认安全的情况下通过村口，与王某驾驶的小客车相撞，孙某当场死亡，驾驶人的不安全驾驶行为有哪些？","o":["通过路口未确认安全","未佩戴安全头盔","超速","违法变更车道"],"a":"AB","e":"根据题目可知：1、孙某未按规定佩戴头盔；2、通过路口未确认安全。","k":"关于“孙某”的多选题，答案找两个“未”字。","p":"","j":""},{"i":3080013,"c":308,"x":4,"y":1,"q":"如图所示，摩托车乘坐人员无安全隐患。","o":["正确","错误"],"a":"B","e":"安全法规定，摩托车驾驶人及乘坐人员应当按规定戴安全头盔。图中乘坐人员未佩戴头盔，存在安全隐患。","k":"图中乘坐人员未佩戴头盔，题目说“无安全隐患”，答错误。","p":"2025071710.jpg","j":""},{"i":3080014,"c":308,"x":4,"y":1,"q":"当身体疲劳时，不应驾驶摩托车。","o":["正确","错误"],"a":"A","e":"疲劳驾驶影响安全，所以不应驾驶摩托车。","k":"题目里看到“不应驾驶”、“不宜驾驶”，直接答正确。","p":"","j":""},{"i":3080015,"c":308,"x":4,"y":3,"q":"驾驶摩托车看到图中信号灯不断闪烁时，以下做法正确的是（ ）。","o":["尽快加速通过","减速慢行","注意观察，安全通过","禁止通行"],"a":"BC","e":"黄灯闪烁，注意瞭望，确认安全后通过。这种灯多出现在夜间或白天路口车流量不大的情况下，起到警示作用。","k":"关于图中黄灯闪烁的多选题，答案不选“加速”和“禁止”，选其他两个。","p":"2025071711.jpg","j":""},{"i":3080016,"c":308,"x":4,"y":3,"q":"有关摩托车出车前检查内容，以下说法正确的是（ ）。","o":["车底有无漏油、漏水现象","灯光、仪表是否正常","轮胎、链条是否正常","油门、刹车是否正常"],"a":"ABCD","e":"摩托车出行前应检查有无漏油、灯光、仪表、轮胎、链条、油门、刹车等安全性能是否正常，确保安全行车。","k":"关于“出车前”的多选题，答案不选“无需”，其他全选。","p":"","j":""},{"i":3080017,"c":308,"x":4,"y":2,"q":"驾驶摩托车遇图中场景时，以下说法正确的是（ ）。","o":["路口无人时加速驶过","停车等待","缓慢驶过路口","注意观察加速驶过"],"a":"B","e":"图中交叉路口的信号是红灯，此时应停车等待，不得越过停止线。","k":"红灯停，绿灯行。","p":"2025071712.jpg","j":""},{"i":3080018,"c":308,"x":4,"y":1,"q":"摩托车胎压过低时，影响安全驾驶。","o":["正确","错误"],"a":"A","e":"胎压不足会降低胎体耐久性，还会提高轮胎的滚动阻力，加剧与地面的摩擦，高速行驶会导致爆胎；","k":"题目中看到“影响安全”，直接答正确。","p":"","j":""},{"i":3080019,"c":308,"x":4,"y":2,"q":"如图所示，驾驶摩托车在隧道行驶遇前方发生火灾时，以下做法错误的是（ ）。","o":["远离危险源","用湿毛巾或衣物等捂住口鼻","按照疏散指示标识指示的方向逃离","原地等待救援"],"a":"D","e":"遇图中隧道发生火灾时，应远离危险源，不要原地等待，不要高声喊叫，以免吸入较多的烟雾和有毒气体。正确的做法是：用水沾湿手巾或衣物捂住口鼻，弯下腰走，因为着火时，刚开始扩散在隧道里的烟雾和毒气，顶部较浓，下部较稀，而且温度分布也是上高下低；隧道出入口和隧道内，大多都标有安全出口的位置，一定按指示标志逃生。","k":"题目让选错误的，“原地等待”都是错的。","p":"2025071713.jpg","j":""},{"i":3080020,"c":308,"x":4,"y":1,"q":"驾驶摩托车驶出隧道时，应预防横风影响，注意保持车身稳定。","o":["正确","错误"],"a":"A","e":"隧道里是密闭的，在刚出隧道口时很可能发生很强的横风，横风会让方向发生偏移，所以遇到横风时，一定握紧方向盘控制好方向。","k":"题目中有“预防”、“预见”的，直接答对。","p":"","j":""},{"i":3080021,"c":308,"x":4,"y":1,"q":"驾驶人服用国家管制的精神药品、麻醉药品后不应驾驶摩托车。","o":["正确","错误"],"a":"A","e":"服用国家管制的精神药品、吸毒、饮酒禁止驾驶机动车。","k":"题目里看到“不应驾驶”、“不宜驾驶”，直接答正确。","p":"","j":""},{"i":3080022,"c":308,"x":4,"y":2,"q":"驾驶摩托车通过图中路口场景时，以下说法正确的是（ ）。","o":["可直行","可右转","可直行或右转","可左转"],"a":"D","e":"图中交叉路口的信号是绿灯，摩托车在左转弯车道，此时只能左转。","k":"图中摩托车所在车道的箭头朝左，答案找“左”。","p":"2025071714.jpg","j":""},{"i":3080023,"c":308,"x":4,"y":1,"q":"驾驶摩托车在隧道行驶遇前方发生火灾时，可以继续前行并绕行通过。","o":["正确","错误"],"a":"B","e":"遇图中隧道发生火灾，火源已占据了车道，此时应远离危险源，按右侧指示标志方向逃生。继续前行或绕行容易发生危险。","k":"题目中看到“继续前行”，直接答错误。","p":"2025071713.jpg","j":""},{"i":3080024,"c":308,"x":4,"y":2,"q":"关于事故伤员的移动，以下说法正确的是（ ）。","o":["伤员被压应立即拖拽将其拖出","搬运昏迷伤员应采取仰卧位","抢救昏迷伤员前要先检查呼吸","用软担架运送脊柱骨折的伤员"],"a":"C","e":"伤员被压应立即拖拽将其拖出会造成二次伤害；搬运昏迷伤员应采取侧卧位；抢救昏迷伤员前要先检查呼吸；用硬担架运送脊柱骨折的伤员。","k":"题目里看到“伤员”，答案找“抢救”。","p":"","j":""},{"i":3080025,"c":308,"x":4,"y":3,"q":"王某（持C1驾驶证）驾驶摩托车，未佩戴安全头盔逆行，与迎面驶来的张某驾驶的摩托车相撞，张某受伤，王某驾驶车辆逃逸。王某的违法行为有哪些？","o":["逆行","肇事逃逸","不按规定佩戴安全头盔","准驾车型不符"],"a":"ABCD","e":"根据题目可知：1、王某（持C1驾驶证）驾驶摩托车，属于准驾车型不符；2、未佩戴安全头盔逆行，属于未按规定佩戴头盔和逆行。3、王某驾驶车辆逃逸，属于肇事逃逸。","k":"多选题，看到“王某（持C1驾驶证）”，答案不选“信号灯”，其他全选。","p":"","j":""},{"i":3080026,"c":308,"x":4,"y":1,"q":"驾驶摩托车要注意与前方大型车辆保持安全距离，预防前车撒落货物。","o":["正确","错误"],"a":"A","e":"图中前方有装满货物的大货车，应与其拉开安全距离行驶，防止货物撒落引发事故。","k":"题目中有“预防”、“预见”的，直接答对。","p":"2025071715.jpg","j":""},{"i":3080027,"c":308,"x":4,"y":1,"q":"驾驶人吸食毒品或毒瘾发作时，可能产生幻觉、神智混乱，严重威胁驾驶安全。","o":["正确","错误"],"a":"A","e":"吸食毒品或毒瘾发作时，可能产生幻觉、神智混乱，会影响驾驶安全，所以不应驾驶车辆。","k":"题目看到“可能会”、“可能产生”的，直接答对。","p":"","j":""},{"i":3080028,"c":308,"x":4,"y":1,"q":"驾驶摩托车通过桥梁前，为避免车辆颠簸，应提前降低行车速度，谨慎骑车。","o":["正确","错误"],"a":"A","e":"车辆通过桥梁、弯道、陡坡这种危险路段时，都应该减速慢行，禁止超车、掉头、停车。","k":"题目中有“谨慎”的都对。","p":"","j":""},{"i":3080029,"c":308,"x":4,"y":1,"q":"正确佩戴安全头盔并穿戴护具，在摩托车侧翻时能减轻驾驶人人身伤害。","o":["正确","错误"],"a":"A","e":"骑摩托车是正确的佩戴安全头盔和护具，在发生倾翻事故时，会有效的保护驾乘人员的安全。","k":"题目中有“减轻”二字的，直接答正确。","p":"","j":""},{"i":3080030,"c":308,"x":4,"y":1,"q":"摩托车应定期进行维护保养，确保车辆的安全性能。","o":["正确","错误"],"a":"A","e":"摩托车的维护保养是非常重要的，它不仅能确保摩托车安全性能，还能延长其使用寿命。","k":"有利于安全的都是对的。","p":"","j":""},{"i":3080031,"c":308,"x":4,"y":1,"q":"驾驶摩托车发生致人死亡的交通事故，应在确保安全的原则下，保护现场并抓紧时间报警。","o":["正确","错误"],"a":"A","e":"发生致人死亡的交通事故，应及时救治伤员，保护现场，立即报警处理。","k":"题目中有“报警”行为的都对。","p":"","j":""},{"i":3080032,"c":308,"x":4,"y":3,"q":"有关出车前检查轮胎，以下说法正确的是（ ）。","o":["轮胎气压是否异常","轮胎沟槽有无异物","轮胎花纹有无异常磨损","无需检查轮胎"],"a":"ABC","e":"出车前应对轮胎的气压、沟槽、花纹做一个全面检查，确认没有异常才可以上路行驶。","k":"关于“出车前”的多选题，答案不选“无需”，其他全选。","p":"","j":""},{"i":3080033,"c":308,"x":4,"y":2,"q":"驾驶摩托车遇图中场景时，下列做法正确的是（ ）。","o":["停车等待","直行通过路口","掉头","向左转弯"],"a":"A","e":"图中交警手势是停止信号：表示交警面向的方向车辆不允许通行。","k":"图中交警手心对着你，你就要“停车”。","p":"2025071716.jpg","j":""},{"i":3080034,"c":308,"x":4,"y":1,"q":"摩托车胎面磨损严重时，容易爆胎。","o":["正确","错误"],"a":"A","e":"引发轮胎爆裂的几种情况：轮胎磨损严重，轮胎气压过高或过低，尖锐物体刺伤轮胎，车辆超载超员","k":"判断题出现“易”字的都对。只有一题里面有“水”的是错的。","p":"","j":""},{"i":3080035,"c":308,"x":4,"y":2,"q":"驾驶摩托车通过图中隧道，以下做法错误的是（ ）。","o":["开启远光灯","保持安全跟车距离","保持横向安全距离","开启近光灯"],"a":"A","e":"图中是双向隧道，应提前开启近光灯。此时对向有来车，应与对向车保持横向安全距离，进入隧道后与前车保持安全跟车距离行驶。","k":"题目让选错误的，使用“远光灯”都是错的。","p":"2025071717.jpg","j":""},{"i":3080036,"c":308,"x":4,"y":1,"q":"酒后驾驶摩托车时，驾驶人认知反应能力降低，容易导致交通事故。","o":["正确","错误"],"a":"A","e":"饮酒后驾驶人的反应力会下降，不能正确的判断紧急情况，容易引发事故。","k":"判断题出现“易”字的都对。只有一题里面有“水”的是错的。","p":"","j":""},{"i":3080037,"c":308,"x":4,"y":1,"q":"驾驶摩托车遇转向失控时，应稳定车身，减速停车。","o":["正确","错误"],"a":"A","e":"摩托车转向失控后，稳住车身，尽快减速靠边停车。","k":"题目里有“减速停车”都是对的，只有和“急踏”同时出现答错。","p":"","j":""},{"i":3080038,"c":308,"x":4,"y":1,"q":"驾驶人服用影响安全驾驶的感冒药、退烧药等药物后不宜驾驶摩托车。","o":["正确","错误"],"a":"A","e":"服用含“敏”或“苯”的感冒药易引起犯困、嗜睡，会影响驾驶安全。","k":"题目里看到“不应驾驶”、“不宜驾驶”，直接答正确。","p":"","j":""},{"i":3080039,"c":308,"x":4,"y":2,"q":"这个标志是何含义？","o":["禁止在路口掉头","禁止向左和向右转弯","禁止车辆直行","禁止向左向右变道"],"a":"B","e":"图中标志为：禁止向左和向右转弯。表示前方路口禁止一切车辆向左向右转弯。","k":"标志里有两个转弯的箭头，答案就找“转弯”。","p":"2023051574010.jpg","j":""},{"i":3080040,"c":308,"x":4,"y":1,"q":"驾驶摩托车遇制动失效时，应降挡减速。","o":["正确","错误"],"a":"A","e":"制动失效后，应迅速逐级或越一级减挡，利用发动机制动作用控制车速。","k":"题目中有“减挡”或“降挡”的，直接答正确。","p":"","j":""},{"i":3080041,"c":308,"x":4,"y":1,"q":"驾驶摩托车遇抢救伤员的救护车从车后驶来，应减速靠右为救护车让行。","o":["正确","错误"],"a":"A","e":"行车中遇到执行任务的消防车、救护车、工程救险车时要及时让行。","k":"判断题有“靠右”的直接答对。","p":"","j":""},{"i":3080042,"c":308,"x":4,"y":1,"q":"驾驶摩托车遇车辆着火时，驾驶人应立即停车，撤离到安全区域并报警。","o":["正确","错误"],"a":"A","e":"车辆着火，应立即停车，远离着火车辆，撤离到安全区域并报警。","k":"题目中有“报警”行为的都对。","p":"","j":""},{"i":3080043,"c":308,"x":4,"y":1,"q":"驾驶摩托车遇图中桥下积水较深时，应绕行。","o":["正确","错误"],"a":"A","e":"图中桥下积水很深，如果冒然行驶，可能会发生水淹的危险，应绕开此路段通过。","k":"积水深绕行是对的。","p":"2025071718.jpg","j":""},{"i":3080044,"c":308,"x":4,"y":1,"q":"驾驶摩托车遇图中漫水桥，要在停车观察水情确保行车安全后，挂低速挡匀速通过。","o":["正确","错误"],"a":"A","e":"遇图中这种漫水桥，应停车察明水情，确认安全后，减速缓慢通过。","k":"判断题里有“挂低速挡”的，直接答对。","p":"2025071719.jpg","j":""},{"i":3080045,"c":308,"x":4,"y":3,"q":"王某（持C1驾驶证）驾驶正三轮载货摩托车乘载11人，行驶至某弯道处以40km/h的速度与中型厢式货车相撞，造成10人死亡、1人受伤。王某的违法行为有哪些？","o":["准驾车型不符","驾驶载货摩托车非法载客","超速行驶","不按信号灯指示行驶"],"a":"ABC","e":"根据题目可知：1、王某（持C1驾驶证）驾驶正三轮载货摩托车乘载11人，属于准驾车型不符和非法载客；2、弯道处以40km/h的速度，弯道不能超30km/h，王某属于超速行驶。","k":"多选题，看到“王某（持C1驾驶证）”，答案不选“信号灯”，其他全选。","p":"","j":""},{"i":3080046,"c":308,"x":4,"y":1,"q":"王某饮酒后驾驶摩托车发生侧翻。鉴定显示，王某血液酒精含量为140mg/100mL。王某的主要违法行为是醉酒后驾驶机动车。","o":["正确","错误"],"a":"A","e":"王某血液酒精含量为140mg/100mL，大于80mg/100ml，属于醉酒驾驶。","k":"判断题中有“违法行为”的都是对的。","p":"","j":""},{"i":3080047,"c":308,"x":4,"y":2,"q":"驾驶摩托车遇图中场景向右转弯时，以下说法正确的是（ ）。","o":["连续鸣喇叭警示","在行人中穿行","加速驶过","注意礼让行人"],"a":"D","e":"图中交叉路口信号为绿灯，此时摩托车可以右转弯，但应注意礼让行人。","k":"题目问正确的，“礼让”的都是对的。","p":"2025071720.jpg","j":""},{"i":3080048,"c":308,"x":4,"y":2,"q":"王某驾驶普通两轮摩托车搭载9岁儿童，以20km/h速度在最右侧道路行驶，儿童跌落受伤。王某有哪些违法行为？","o":["超速","超员","非法搭载未满12周岁未成年人","未按规定车道行驶"],"a":"C","e":"二轮摩托车载人不得载未满12周岁的未成年人，王某驾驶两轮摩托车搭载9岁儿童，属于非法搭载未满12周岁未成年人。","k":"违法案例单选题，看到“9岁”，答案找“12周岁”。","p":"","j":""},{"i":3080049,"c":308,"x":4,"y":2,"q":"如图所示，驾驶摩托车遇行人正在通过人行横道时，以下做法正确的是（ ）。","o":["鸣喇叭催促通过","在行人中穿行","加速通过","停车让行"],"a":"D","e":"图中有行人正在通过人行横道，此时应停车让行，待行人通过后再起步。","k":"遇行人横过马路，直接选“停车”。","p":"2025071721.jpg","j":""},{"i":3080050,"c":308,"x":4,"y":1,"q":"驾驶摩托车遇图中车道时，可以直行通过。","o":["正确","错误"],"a":"B","e":"图中左转信号为绿灯，直行和右转信号为红灯，摩托车此时在左转车道，只能左转弯，不可直行。","k":"图中直行灯为红色，禁止直行，题目说“可以直行”，图片和题目不一致答错误。","p":"2025071722.jpg","j":""},{"i":3080051,"c":308,"x":4,"y":2,"q":"驾驶摩托车在图中隧道遇对向有车驶来，以下做法正确的是（ ）。","o":["靠右侧停车让行","在路中间停车等待","加速通过","开远光灯提示对向来车"],"a":"A","e":"图中隧道前只有一条车道，且对向有来车，我方摩托车应减速靠右停车让行。","k":"答案里看到“靠右”的，直接选。（错误的不选）","p":"2025071723.jpg","j":""},{"i":3080052,"c":308,"x":4,"y":1,"q":"驾驶摩托车不要与大型车辆并行。","o":["正确","错误"],"a":"A","e":"大型车辆盲区较大，摩托车跟大车并行不易被发现，容易发生危险。","k":"判断题中出现“不要”的都是对的。","p":"","j":""},{"i":3090001,"c":309,"x":4,"y":1,"q":"现场急救应遵循先止后包、先重后轻、先救后送等原则。","o":["正确","错误"],"a":"A","e":"现场急救应遵循先止后包、先重后轻、先救后送等原则。","k":"","p":"","j":""},{"i":3090002,"c":309,"x":4,"y":2,"q":"1岁以下婴儿进行心肺复苏时，按压深度应为（ ）。","o":["5厘米","4厘米","3厘米","6厘米"],"a":"B","e":"儿童心肺复苏时，1岁至青春期儿童按压深度为胸廓厚度的1/3（约5厘米），1岁以下婴儿按压深度应为4厘米。","k":"","p":"","j":""},{"i":3090003,"c":309,"x":4,"y":2,"q":"搬运昏迷伤员时，为防止误吸，应采取的体位是（ ）。","o":["平卧位头直立","俯卧位","半坐卧位","侧卧位头偏向一侧"],"a":"D","e":"搬运昏迷伤员时应采取侧卧位，头偏向一侧；搬运昏迷患者时，应采取平卧位头偏向一侧，侧卧位防止误吸。","k":"","p":"","j":""},{"i":3090004,"c":309,"x":4,"y":2,"q":"成人心肺复苏时，打开气道最常用的方式是（ ）。","o":["仰头举颏法","仰头抬颈法","低头抬颏法","双手托颌法"],"a":"A","e":"成人心肺复苏时打开气道的最常用方式是仰头举颏法。这种操作方法是抢救者将一手掌小拇指侧置于患者前额，然后下压使其头部后仰，另一手的食指和中指置于靠近颏部的下颌骨下方，将颏部向前抬起，帮助患者头部后仰，将其气道开放。","k":"","p":"","j":""},{"i":3090005,"c":309,"x":4,"y":1,"q":"成人心肺复苏时，若施救者因疲劳导致按压深度不足，可通过临时加快按压频率来补偿。","o":["正确","错误"],"a":"A","e":"如施救者疲劳导致按压深度不足时，可临时加快按压频率补偿。","k":"","p":"","j":""},{"i":3090006,"c":309,"x":4,"y":2,"q":"成人心肺复苏时，胸外心脏按压的频率应为每分钟多少次？","o":["80—100次","100—120次","60—80次","120—140次"],"a":"B","e":"成人心肺复苏时，胸外心脏按压的正确位置是胸骨中下1/3交界处，按压的深度至少5厘米，按压频率为每分钟100-120次，按压中断时间应尽可能控制在10秒以内。","k":"","p":"","j":""},{"i":3090007,"c":309,"x":4,"y":2,"q":"成人心肺复苏时，胸外心脏按压与人工呼吸的配合比例是（ ）。","o":["15：01","5：01","30：2","20：03"],"a":"C","e":"心脏按压与人工呼吸配合同时进行时，使用的按压与通气的比例为30：2。","k":"","p":"","j":""},{"i":3090008,"c":309,"x":4,"y":2,"q":"处理开放性腹部损伤（脏器外漏）时，正确的包扎方式是？","o":["直接压迫外露脏器后包扎","不做处理直接送医","用无菌湿纱布覆盖，碗状物扣住伤口后包扎","用干纱布覆盖后加压包扎"],"a":"C","e":"包扎开放性腹部损伤（脏器外露）伤员时，用无菌湿纱布覆盖外露脏器，并用碗状物扣住伤口避免压迫，包扎后让患者平卧屈膝。","k":"","p":"","j":""},{"i":3090009,"c":309,"x":4,"y":3,"q":"当发现病人呼吸、心脏骤停时，正确的做法是（ ）。","o":["立即就地实施心肺复苏","判断病人意识是否丧失","先拨打急救电话，再等待救援人员到场施救","确认胸外心脏按压位置后展开施救"],"a":"ABD","e":"对心跳、呼吸停止的伤员，应就地实施心肺复苏。在开始心肺复苏之前，要判断病人意识是否丧失、呼吸是否停止、颈动脉搏动是否消失，在确认胸外心脏按压位置后开展施救工作。","k":"","p":"","j":""},{"i":3090010,"c":309,"x":4,"y":2,"q":"呼吸、心脏骤停后的急救黄金时间是多久？","o":["3分钟","4分钟","5分钟","6分钟"],"a":"B","e":"呼吸、心脏骤停后，急救越早，存活率越高，医学上急救黄金时间为4分钟。","k":"","p":"","j":""},{"i":3090011,"c":309,"x":4,"y":1,"q":"动脉出血时，采用直接加压的方式可以完全止血。","o":["正确","错误"],"a":"B","e":"动脉出血时，血液随脉搏节律间歇状向外喷射，出血颜色鲜红，应采取指压止血法止血，直接加压无法完全止血。指压止血部位包括桡动脉、股动脉和肱动脉。","k":"","p":"","j":""},{"i":3090012,"c":309,"x":4,"y":2,"q":"动脉出血时，其血液颜色通常为（ ）。","o":["淡红色","鲜红色","紫色","暗红色"],"a":"B","e":"动脉出血时，血液随脉搏节律间歇状向外喷射，出血颜色鲜红，应采取指压止血法止血，直接加压无法完全止血。指压止血部位包括桡动脉、股动脉和肱动脉。","k":"","p":"","j":""},{"i":3090013,"c":309,"x":4,"y":2,"q":"止血带的使用范围是？","o":["仅限四肢","仅用于头部","可用于儿童前臂浅表划伤","所有部位均可"],"a":"A","e":"止血带仅限四肢，不能用于头部出血和儿童的前臂浅表划伤出血。救治四肢动脉喷射性出血伤员时，应记录使用时间，每1小时要放松1次。","k":"","p":"","j":""},{"i":3090014,"c":309,"x":4,"y":1,"q":"对脊柱损伤的伤员，在救治过程中可以让其短暂坐立以调整姿势。","o":["正确","错误"],"a":"B","e":"救护员在现场对伤病员进行救护之前，首先要考虑现场环境是否安全。对意识不清的伤病员，检查脉搏常用颈动脉；对伤员鼻出血，应先给与干净布擦血；对疑似颈椎骨折时，尽量不移动伤病员，拨打急救电话；对异物插入体内的，现场不能拔除异物,应采取简单固定包扎措施后送往医院。","k":"","p":"","j":""},{"i":3090015,"c":309,"x":4,"y":1,"q":"对心跳、呼吸停止的伤员，可直接送往医院，无需就地实施心肺复苏。","o":["正确","错误"],"a":"B","e":"对心跳、呼吸停止的伤员，应就地实施心肺复苏。在开始心肺复苏之前，要判断病人意识是否丧失、呼吸是否停止、颈动脉搏动是否消失，在确认胸外心脏按压位置后开展施救工作。","k":"","p":"","j":""},{"i":3090016,"c":309,"x":4,"y":1,"q":"对异物插入体内的伤病员，为避免感染，现场应立即拔除异物后再包扎。","o":["正确","错误"],"a":"B","e":"对异物插入体内的，现场不能拔除异物,应采取简单固定包扎措施后送往医院。","k":"","p":"","j":""},{"i":3090017,"c":309,"x":4,"y":1,"q":"发现多人急需救治时，应立即呼救。","o":["正确","错误"],"a":"A","e":"发现多人急需救治时，或自己无法完成救治时，应立即呼救。","k":"","p":"","j":""},{"i":3090018,"c":309,"x":4,"y":1,"q":"根据《民法典》第184条，因紧急搬运导致患者颈椎二次损伤，施救者需要承担法律责任。","o":["正确","错误"],"a":"B","e":"发现多人急需救治时，或自己无法完成救治时，应立即呼救。对急需救治的患者，应根据现场情况将病人移出危险区，或消除引起危害的因素。根据《民法典》第184条，因紧急搬运导致患者颈椎二次损伤，施救者无需担责；施救者因使用止血带导致患者截肢无需担责。","k":"","p":"","j":""},{"i":3090019,"c":309,"x":4,"y":3,"q":"关于现场救护的操作原则，下列说法正确的是（ ）。","o":["对意识不清的伤病员，检查脉搏常用颈动脉","对伤员鼻出血，应先给予干净布擦血","现场救护时，无需考虑环境安全，直接优先处理伤病员伤情","对疑似颈椎骨折的伤病员，应立即移动至舒适位置后拨打急救电话"],"a":"AB","e":"救护员现场对伤病员进行救护之前，首先要考虑现场环境是否安全。对意识不清的伤病员，检查脉搏常用静动脉；对伤员鼻出血，应先给与干净布擦血；对疑似颈椎骨折时，尽量不移动伤病员，拨打急救电话；对异物插入体内的，现场不能拔除异物，应采取简单固定包扎措施后送往医院。","k":"","p":"","j":""},{"i":3090020,"c":309,"x":4,"y":3,"q":"关于一侧头顶部出血的止血方法，下列说法正确的是（ ）。","o":["压迫的动脉为颞浅动脉","可用拇指进行压迫止血","止血部位在同侧耳前","需对准耳屏上前方1.5厘米处的血管搏动点"],"a":"ABCD","e":"一侧头顶部出血时，在同侧耳前,对准耳屏上前方1.5厘米血管搏动处，用拇指压迫颞浅动脉止血。","k":"","p":"","j":""},{"i":3090021,"c":309,"x":4,"y":1,"q":"呼吸、心脏骤停后，急救越早，存活率越高，医学上急救的黄金时间为5分钟。","o":["正确","错误"],"a":"B","e":"呼吸、心脏骤停后，急救越早，存活率越高，医学上急救黄金时间为4分钟。","k":"","p":"","j":""},{"i":3090022,"c":309,"x":4,"y":3,"q":"如何发起“轻微道路交通事故视频快处”报警？","o":["通过“江苏交警”微信公众号点击“视频快处”","手机下载“交管12123”APP点击“事故视频快处”","直接拨打122等待交警到场","拨打110报警后接收视频报警短信链接"],"a":"ABD","e":"轻微道路交通事故视频快处”操作步骤：（1）如何报警方法一：通过“江苏交警”微信公众号或者各地公安交管部门微信公众号点击“视频快处”；方法二：手机下载“交管12123”APP，点击“事故视频快处”；方法三：拨打110报警后，点击110推送的视频报警短信链接。","k":"","p":"","j":""},{"i":3090023,"c":309,"x":4,"y":1,"q":"视频快处的电子认定书与纸质认定书具有同等法律效力。","o":["正确","错误"],"a":"A","e":"电子认定书经系统签章后，与纸质版具有同等法律效力，可用于保险理赔。","k":"","p":"","j":""},{"i":3090024,"c":309,"x":4,"y":2,"q":"视频快处时，因信号不佳导致通话中断，当事人应怎么做？","o":["无需操作，系统会自动续接","等待24小时后再处理","尝试重新发起视频通话","放弃处理，直接驶离"],"a":"C","e":"“轻微道路交通事故视频快处”报警中断后，应立即重新发起，确保处理流程完整，避免因中断导致认定失败。","k":"","p":"","j":""},{"i":3090025,"c":309,"x":4,"y":2,"q":"视频快处完成后，当事人收到电子责任认定书，发现信息有误，应如何处理？","o":["联系处理坐席申请更正","自行修改后留存","重新发起视频快处","不影响理赔，无需处理"],"a":"A","e":"对认定书有异议的，可在收到后24小时内联系坐席申请复核更正。","k":"","p":"","j":""},{"i":3090026,"c":309,"x":4,"y":2,"q":"四肢骨折固定时，应将趾指末端露出的目的是？","o":["观察肢体血液循环情况","便于搬运","避免压迫神经","方便包扎"],"a":"A","e":"四肢骨折的病人，固定时应将趾指末端露出，通过观察趾指末端的颜色、温度和肿胀情况，及时判断肢体血液循环情况。","k":"","p":"","j":""},{"i":3090027,"c":309,"x":4,"y":3,"q":"现场急救应遵循哪些原则？","o":["先止后包","先重后轻","先送后救","先救后送"],"a":"ABD","e":"现场急救应遵循先止后包、先重后轻、先救后送等原则。","k":"","p":"","j":""},{"i":3090028,"c":309,"x":4,"y":2,"q":"一侧头顶部出血时，应压迫的止血动脉是（ ）。","o":["面动脉","颈总动脉","颞浅动脉","锁骨下动脉"],"a":"C","e":"一侧头顶部出血时，在同侧耳前,对准耳屏上前方1.5厘米血管搏动处，用拇指压迫颞浅动脉止血。","k":"","p":"","j":""},{"i":3090029,"c":309,"x":4,"y":3,"q":"以下哪些指标能简单而迅速地确定心脏骤停？","o":["呼吸停止","瞳孔放大","无大动脉搏动","病人意识丧失"],"a":"CD","e":"简单而迅速地确定心脏骤停的指标是病人意识消失，无大动脉搏动，不能仅凭呼吸停止、瞳孔散大等症状判断。","k":"","p":"","j":""},{"i":3090030,"c":309,"x":4,"y":2,"q":"运送脊椎骨折的病人时，应选用的搬运工具是（ ）。","o":["轮椅","普通床垫","木板","软担架"],"a":"C","e":"搬运脊柱损伤患者时，可采用“轴线翻身”或脊柱板固定；骨盆骨折患者搬运时，可用宽布带固定骨盆减少移位；运送脊椎骨折的病人应选用木板。","k":"","p":"","j":""},{"i":3090031,"c":309,"x":4,"y":1,"q":"驾驶机动车在高速公路遇应急车道封闭施工，切勿在行车道内停车。","o":["正确","错误"],"a":"A","e":"驾驶机动车经过高速公路施工作业路段，应当先降低车速，观察有无限速要求，按限速要求通过。经过改扩建路段时，如应急车道封闭施工，切勿在行车道内停车。如有紧急情况应当驶入临时停车港湾停靠，停靠时部分车体占用行车道的，应当做好安全防护并立即报警求助，","k":"","p":"","j":""},{"i":3090032,"c":309,"x":4,"y":2,"q":"驾驶机动车在高速公路发生故障时，车辆无法继续行驶的，应当尽可能将车停入应急车道内，开启危险报警闪光灯，夜间开启示廓灯和后位灯，在车后多少米外设置警告标志后再检修?","o":["50","100","150","200"],"a":"C","e":"机动车遇前方车辆停车排队等候或者缓慢行驶时不得占用应急车道或者右侧路肩超车、停车，本车道最末车辆应当开启危险报警闪光灯。发生交通事故后，警告标志应当设置在事故车辆来车方向一百五十米以外","k":"","p":"","j":""},{"i":3090033,"c":309,"x":4,"y":1,"q":"机动车在高速公路高架桥或隧道内发生轻微事故且车辆可以移动的，应当继续驾驶至高速公路服务区或出口再协商处理。","o":["正确","错误"],"a":"A","e":"机动车在高速公路高架桥或隧道内遇轻微事故，若车辆仍具行驶能力，应继续驶至服务区或出口处理，可以减少因停车协商而可能引发的交通拥堵和二次事故风险，确保道路畅通和行车安全。在服务区或出口处，车辆可安全停放，便于事故双方冷静协商，有效处理事故后续事宜。","k":"","p":"","j":""},{"i":3090034,"c":309,"x":4,"y":1,"q":"在高速公路上发生事故后车上人员不及时撤离，或不及时做好安全防护的，一旦发生二次事故要承担相应责任。","o":["正确","错误"],"a":"A","e":"在高速公路上发生事故后，若车上人员不及时撤离现场或不采取安全防护措施，将自身置于危险之中，一旦发生二次事故，这些人员可能因未采取必要的安全措施而遭受额外伤害，并需承担由此产生的相应责任。","k":"","p":"","j":""},{"i":3090035,"c":309,"x":4,"y":1,"q":"高速公路隧道内外光线差异，会对视觉造成干扰。","o":["正确","错误"],"a":"A","e":"高速公路隧道内外光线差异显著，当车辆由明亮的外部环境进入隧道时，光线骤然变暗，会对驾驶员的视觉造成短暂干扰，称为“黑洞效应”。相反，出隧道时则可能出现“白洞效应”，即光线突然增强导致视觉不适。这种光线变化易引发视觉错觉，影响驾驶安全。","k":"","p":"","j":""},{"i":3090036,"c":309,"x":4,"y":1,"q":"匝道一般转弯半径较大，行驶时应严格控制车速，防止失控发生事故。","o":["正确","错误"],"a":"A","e":"匝道一般转弯半径相对较大，但这一特点并不意味着可以忽视车速控制。匝道的设计往往包含弯道且路面可能较为狭窄，这要求驾驶员在行驶时必须严格控制车速。因为车速过快时，在转弯过程中可能因离心力过大而导致车辆失控，进而引发交通事故。因此,驾驶员在匝道行驶时应特别注意减速慢行确保行车安全。","k":"","p":"","j":""},{"i":3090037,"c":309,"x":4,"y":1,"q":"驾驶机动车在高速公路上行驶，能见度不足50米时，应当从最近出口驶离高速公路。","o":["正确","错误"],"a":"A","e":"驾驶机动车在高速公路上行驶，当能见度不足50米时，应当从最近出口驶离高速公路。这是因为能见度极低的情况下，驾驶者的视野严重受限，极易发生追尾等交通事故。为了保障行车安全，降低风险交管部门规定在此类恶劣天气下，驾驶员需减速慢行，并尽快驶离高速公路，选择更安全的路段行驶。因此选择正确。","k":"","p":"","j":""},{"i":3090038,"c":309,"x":4,"y":1,"q":"驾驶机动车在高速公路上遇大雾团雾、强降雨等恶劣天气能见度下降时，应加速通过。","o":["正确","错误"],"a":"B","e":"驾驶机动车在高速公路上遇大雾、团雾、强降雨等恶劣天气，能见度下降时，不应加速通过。加速通过会极大地增加交通事故的风险，因为恶劣天气下视线不清，驾驶员难以准确判断前方路况和车辆动态。因此，在高速公路上遇到恶劣天气时，驾驶员应保持冷静，谨慎驾驶，确保自身和他人的安全。","k":"","p":"","j":""},{"i":3090039,"c":309,"x":4,"y":2,"q":"机动车欲驶离高速公路，进入高速公路匝道前，应当开启什么灯?","o":["左转向灯","右转向灯","危险报警闪光灯","前照灯"],"a":"B","e":"机动车从匝道驶入高速公路，应当开启左转向灯在不妨碍已在高速公路内的机动车正常行驶的情况下驶入车道。机动车驶离高速公路时，应当开启右转向灯，驶入减速车道，降低车速后驶离。","k":"","p":"","j":""},{"i":3090040,"c":309,"x":4,"y":2,"q":"雨天驾驶人在高速公路行车时遇积水路段应怎样做?","o":["减速慢行","原地停车等待","空挡滑行通过","加速通过"],"a":"A","e":"雨天驾驶人在高速公路行车时，遇积水路段应减速慢行。积水路段可能导致路面湿滑，车辆的抓地力降低，制动距离增加，增加了发生侧滑、失控等危险情况的可能性。减速慢行可以让驾驶人有更充足的时间和空间来应对可能发生的紧急情况，确保行车安全。同时，减速慢行还能减少水花飞溅，提高行车视线，进一步降低事故风险。","k":"","p":"","j":""},{"i":3090041,"c":309,"x":4,"y":2,"q":"夜间车辆在高速公路上发生故障除开启危险报警闪光灯以外，还需开启什么灯?","o":["近光灯","远光灯","示廓灯和后位灯","前后雾灯"],"a":"C","e":"夜间车辆在高速公路上发生故障时，除开启危险报警闪光灯以外，还需开启示廓灯和后位灯。危险报警闪光灯(双闪)用于警示其他车辆注意，表明车辆处于非正常状态。示廓灯安装在车前和车后最高处，能显示车辆的轮廓，让其他车辆知晓故障车的大致形状和位置。后位灯则是车后的两个示廓灯，能明确车辆的后端位置，增强后方车辆的辨识度。这三种灯光的联合使用，可以有效避免其他车辆因视线不佳而与故障车发生碰撞，从而最大程度保障道路交通安全。","k":"","p":"","j":""},{"i":3090042,"c":309,"x":4,"y":2,"q":"驾驶机动车在高速公路遇施工路段时，应当()。","o":["原地掉头","加速通过施工路段","在施工路段前紧急制动","降低车速"],"a":"D","e":"驾驶机动车在高速公路上遇到施工路段时，应当降低车速。施工路段可能存在各种不确定因素，如路面变窄、坑洼不平、障碍物等，这些都会增加行车的风险。降低车速有助于驾驶员更好地控制车辆确保安全通过施工区域，同时也有足够的时间来应对突发情况，如紧急制动或避让等","k":"","p":"","j":""},{"i":3090043,"c":309,"x":4,"y":1,"q":"驾驶机动车在高速公路行驶，发现大货车车上货物捆扎不牢时，要尽量远离避让，不得从应急车道超车。","o":["正确","错误"],"a":"A","e":"在高速公路行驶时，若发现大货车货物捆扎不牢固应立即警觉并采取远离措施。不稳定的货物可能随时掉落，对周围车辆构成威胁。应急车道不得占用因此选择正确。","k":"","p":"","j":""},{"i":3090044,"c":309,"x":4,"y":1,"q":"驾驶机动车在高速公路发生故障用时较长或者应急车道宽度不足，导致部分车体占用行车道的，应立即报警求助。","o":["正确","错误"],"a":"A","e":"在高速公路上，若车辆发生故障且修复需时较长或应急车道宽度不足以容纳整车，导致部分车体不得不占用行车道时，应立即报警求助。此种情况下车辆成为道路上的潜在危险源，可能引发交通事故。报警后，交警将及时到达现场，采取必要的交通管制措施，确保道路安全畅通。","k":"","p":"","j":""},{"i":3090045,"c":309,"x":4,"y":1,"q":"驾驶小型车辆在高速公路行驶，遇到前面有大货车时，应注意与大货车保持横向安全距离。","o":["正确","错误"],"a":"A","e":"驾驶小型车辆在高速公路行驶时，遇到前方大货车保持横向安全距离至关重要。大货车体积庞大，存在视线盲区，且由于其重量和速度，一旦发生碰撞后果往往严重。因此，保持足够的横向间距，不仅能减少被大货车盲区覆盖的风险，还能为紧急避让提供空间，确保行车安全。","k":"","p":"","j":""},{"i":3090046,"c":309,"x":4,"y":1,"q":"驾驶机动车在高速公路上发生故障时，在应急车道停车应做好安全防护，人员撤离至护栏外。","o":["正确","错误"],"a":"A","e":"高速公路上车速快，若车辆发生故障停靠在应急车道,车内人员若留在车内或车旁,极易发生二次事故造成更严重的伤害。将人员撤离至护栏外，可以远离危险区域，确保人身安全。同时，开启危险报警闪光灯、设置警告标志等措施也是必不可少的，以提醒其他车辆注意避让，防止发生追尾等事故。","k":"","p":"","j":""},{"i":3090047,"c":309,"x":4,"y":1,"q":"驾驶机动车在高速公路遇应急车道封闭施工时，如有紧急情况应在临时停车港湾停靠。","o":["正确","错误"],"a":"A","e":"高速公路上应急车道封闭施工时，若遇紧急情况应立即寻找并安全驶入临时停车港湾。在应急车道封闭期间，原应急车道无法正常使用，而临时停车港湾为紧急情况提供了安全的停车空间，避免在高速公路主线上随意停车带来的危险，确保人员与车辆的安全。","k":"","p":"","j":""},{"i":3090048,"c":309,"x":4,"y":1,"q":"驾驶小型汽车在高速遇非车辆故障、事故等紧急情况时，可以在应急车道内停车。","o":["正确","错误"],"a":"B","e":"驾驶小型汽车在高速公路上，非车辆故障、事故等紧急情况，不得在应急车道内停车。应急车道是专为处理紧急事务而设，如车辆故障、交通事故、医疗救援等。非紧急情况下占用应急车道，不仅违反了道路交通安全法规，还可能阻碍救援车辆通行，增加道路安全风险。","k":"","p":"","j":""},{"i":3090049,"c":309,"x":4,"y":3,"q":"驾驶车辆在高速公路上行驶，因疏忽驶过了出口时驾驶员做法错误的是?","o":["紧急制动","原地掉头","倒回出口处","从下一个出口驶离"],"a":"ABC","e":"在高速公路上行驶时，若因疏忽驶过了出口，驾驶员采取紧急制动、原地掉头或倒回出口处的做法均属错误。紧急制动可能导致后车追尾,增加事故风险:原地掉头更是极其危险，不仅影响其他车辆正常行驶，还可能导致连环碰撞;而倒回出口处则严重违反交通法规，且同样存在极高的安全隐患。正确做法应是继续前行至下一个出口驶离，确保行车安全，","k":"","p":"","j":""},{"i":3090050,"c":309,"x":4,"y":2,"q":"驾驶机动车进入高速公路隧道时需要注意什么?","o":["严禁超车","在隧道内停车","开启远光灯行驶","加速行驶"],"a":"A","e":"驾驶机动车进入高速公路隧道时，特别需要注意严禁超车。隧道内空间狭窄、视线不佳，超车行为会严重威胁道路交通安全，","k":"","p":"","j":""},{"i":3090051,"c":309,"x":4,"y":2,"q":"在高速公路同方向2-3条以上车道行驶的哪种车型，除因超车需要外，不得驶入左侧车道?","o":["小型汽车","三轮摩托车","小型自动挡汽车","载货汽车"],"a":"D","e":"高速公路同方向有两条车道的，载货汽车除因超车需要外，不得驶入左侧车道;同方向有三条以上车道的，载货汽车不得驶入最左侧车道。载货汽车由于车辆重量大、制动距离长，在高速行驶时若长时间占用左侧车道，不仅会影响其他车辆的通行效率还可能增加交通事故的风险。","k":"","p":"","j":""},{"i":3090052,"c":309,"x":4,"y":1,"q":"在高速公路行车道内紧急制动或者停车查看导航极易引发事故，造成人员伤亡。","o":["正确","错误"],"a":"A","e":"在高速公路行车道内紧急制动或停车查看导航是极其危险的行为。高速公路车速快，紧急制动可能导致后车追尾，而停车查看导航则直接阻挡了其他车辆的正常行驶，两者都极易引发连环事故，造成严重交通拥堵，甚至导致人员伤亡。因此，驾驶员在高速公路上应提前规划好路线，避免此类危险行为。","k":"","p":"","j":""},{"i":3090053,"c":309,"x":4,"y":1,"q":"驾驶机动车在高速公路隧道内行驶时，可以随意变道。","o":["正确","错误"],"a":"B","e":"驾驶机动车在高速公路隧道内行驶时，不可以随意变道。隧道内光线变化大、视野受限，变道行为可能干扰其他车辆，增加交通事故风险。","k":"","p":"","j":""},{"i":3090054,"c":309,"x":4,"y":1,"q":"严禁在高速公路隧道内随意停车超车、变更车道。","o":["正确","错误"],"a":"A","e":"严禁在高速公路隧道内随意停车、超车、变更车道因为这些行为会严重危及行车安全。隧道内视野受限，光线变化大，随意停车会阻碍交通，超车与变更车道可能引发碰撞事故。","k":"","p":"","j":""},{"i":3090055,"c":309,"x":4,"y":2,"q":"高速公路同方向有三条以上车道的，载货汽车除因超车需要外，不得驶入()车道内行驶。","o":["左侧","右侧","中间","随意"],"a":"A","e":"高速公路同方向有两条车道的，载货汽车除因超车需要外，不得驶入左侧车道;同方向有三条以上车道的，载货汽车不得驶入最左侧车道。载货汽车由于车辆重量大、制动距离长，在高速行驶时若长时间占用左侧车道，不仅会影响其他车辆的通行效率还可能增加交通事故的风险。","k":"","p":"","j":""},{"i":3090056,"c":309,"x":4,"y":1,"q":"驾驶机动车在高速公路行驶，发现前方车道上有其他车辆酒落的障碍物，应先采取制动措施减速，确保安全后再变道避让。","o":["正确","错误"],"a":"A","e":"驾驶机动车在高速公路行驶时，发现前方车道有酒落障碍物，应先制动减速，确保行车安全。在速度可控、确认安全后，再平稳变道避让障碍物。此举旨在预防紧急变道导致的失控或碰撞，确保高速公路行车安全。","k":"","p":"","j":""},{"i":3090057,"c":309,"x":4,"y":1,"q":"驾驶机动车在高速公路行驶，突然发现前方车道上有故障车辆或有其他车辆洒落的障碍物，应立即变道行驶。","o":["正确","错误"],"a":"B","e":"驾驶机动车在高速公路行驶，遇前方车道有故障车辆或障碍物时，不应立即变道，而应先减速慢行观察周围交通情况，确认安全后再平稳变道。立即变道可能引发事故，确保安全是首要原则。","k":"","p":"","j":""},{"i":3090058,"c":309,"x":4,"y":2,"q":"高速公路同方向有两条车道的，载货汽车除因超车需要外，不得驶入()车道内行驶。","o":["左侧","右侧","中间","随意"],"a":"A","e":"高速公路同方向有两条车道的，载货汽车除因超车需要外，不得驶入左侧车道;同方向有三条以上车道的，载货汽车不得驶入最左侧车道。载货汽车由于车辆重量大、制动距离长，在高速行驶时若长时间占用左侧车道，不仅会影响其他车辆的通行效率还可能增加交通事故的风险。","k":"","p":"","j":""},{"i":3090059,"c":309,"x":4,"y":1,"q":"在高速公路驾车感觉疲劳时，应当驾驶至下个服务区休息，不得在应急车道停车休息。","o":["正确","错误"],"a":"A","e":"在高速公路上行驶感觉疲困时，应该找到最近的服务区停车休息。因为高速公路不可随便停车，应急车道内只有车辆突发故障或乘客突发疾病才可以停车。","k":"","p":"","j":""},{"i":3090060,"c":309,"x":4,"y":1,"q":"在高速公路行车，突遇险情时，当先避人后避物。","o":["正确","错误"],"a":"A","e":"在高速公路行车时，若突遇险情，应当迅速而冷静地做出反应。遵循“先避人后避物”的原则至关重要因为人的生命安全始终是第一位的。","k":"","p":"","j":""},{"i":3090061,"c":309,"x":4,"y":2,"q":"驾驶机动车在高速公路行驶，突然发现前方车道上有故障车辆或有其他车辆洒落的障碍物，应如何行驶?","o":["急踩刹车","减速，确认安全后变道","连续鸣喇叭","立即停车"],"a":"B","e":"在高速公路驾驶时，若突然发现前方车道有故障车辆或酒落的障碍物，应立即采取正确的应对措施。首先，要果断减速，利用车辆的制动系统平稳降低车速,给自己留出更多的反应时间和安全距离。随后密切观察周围交通状况，特别是后方车辆的行驶状态，确保安全后，再选择合适的时机平稳变道至无障碍的车道继续行驶。","k":"","p":"","j":""},{"i":3090062,"c":309,"x":4,"y":1,"q":"在高速公路驾车行驶，24小时累计驾驶时间不超过8小时。","o":["正确","错误"],"a":"A","e":"驾驶人24小时内累计驾驶时间不超过8小时，日间连续驾驶不超过4小时，夜间连续驾驶不超过2小时，每次停车休息时间不少于20分钟。","k":"","p":"","j":""},{"i":3090063,"c":309,"x":4,"y":1,"q":"驾驶货车在高速公路上行驶时突然发现所载货物出现松动，应将车停在应急车道，重新固定货物后再出发。","o":["正确","错误"],"a":"A","e":"在高速公路上，货车货物松动是安全隐患，需立即处理。选择应急车道停车，能确保安全同时不影响其他车辆。重新固定货物后再出发，预防行驶中货物脱落导致发生交通事故，保障道路通行安全及车辆、人员安全。","k":"","p":"","j":""},{"i":3090064,"c":309,"x":4,"y":3,"q":"高速公路行车中发现前方道路拥堵，应怎样做?","o":["采取制动措施减速","持续鸣喇叭催促","开启危险报警闪光灯提示后车","变道驶入应急车道行驶"],"a":"AC","e":"在高速公路行车中，若发现前方道路拥堵，首先应采取制动措施减速，确保车辆平稳停下或减速行驶避免追尾。同时，开启危险报警闪光灯(双闪)以警示后车，提醒它们前方有紧急情况，需保持安全距离并减速慢行。","k":"","p":"","j":""},{"i":3090065,"c":309,"x":4,"y":1,"q":"在高速公路驾驶机动车时按规定不得接打手机。","o":["正确","错误"],"a":"A","e":"在高速公路驾驶机动车时，按规定不得接打手机。接打手机会分散驾驶员的注意力，降低对路况的警觉性和反应速度，增加发生交通事故的风险。","k":"","p":"","j":""},{"i":3090066,"c":309,"x":4,"y":3,"q":"如计划选择高速公路出行，需提前做好哪些准备?","o":["提前规划好行程","保持充足的睡眠","检查车辆轮胎情况","检查制动等安全状况"],"a":"ABCD","e":"选择高速公路出行前，需提前规划好行程，确保路线清晰;保持充足的睡眠，避免疲劳驾驶;检查车辆轮胎情况，确保胎压正常、无磨损；同时检查制动等安全系统，保障行车安全。","k":"","p":"","j":""},{"i":3090067,"c":309,"x":4,"y":1,"q":"机动车在高速公路行驶，突然遇到前方堵车，车辆行驶缓慢，应当采取制动措施减速并开启危险报警闪光灯，警示后方车辆以防追尾。","o":["正确","错误"],"a":"A","e":"高速遇前方堵车，车辆缓行时，应立即制动减速保持安全距离。同时，开启危险报警闪光灯，有效警示后车，预防追尾碰撞，确保行车安全。","k":"","p":"","j":""},{"i":3090068,"c":309,"x":4,"y":1,"q":"如计划选择高速公路出行，应当提前规划好行程，保持充足的睡眠，并检查车辆轮胎、制动等安全状况。","o":["正确","错误"],"a":"A","e":"选择高速公路出行前，需提前规划好行程，确保路线清晰;保持充足的睡眠，避免疲劳驾驶;检查车辆轮胎情况，确保胎压正常、无磨损;同时检查制动等安全系统，保障行车安全。","k":"","p":"","j":""},{"i":3090069,"c":309,"x":4,"y":1,"q":"驾车准备从高速公路某出口驶出应提前1-2公里变道至右侧车道。","o":["正确","错误"],"a":"A","e":"驾车从高速出口驶出前，应提前1-2公里变道至右侧车道，以确保有足够时间减速并安全汇入出口匝道避免急刹车或强行变道，保障行车安全及道路畅通","k":"","p":"","j":""},{"i":3090070,"c":309,"x":4,"y":2,"q":"车辆落水后，若车门无法打开，最佳破窗时机是?","o":["车辆开始下沉时","车内水位到达腰部时","车内水位接近车顶时","车辆完全淹没后"],"a":"C","e":"本题主要考察车辆落水的应急处置。车内水位接近车顶时:此时车内外水压差最小，车门或车窗的阻力大幅降低，是破窗逃生的最后关键时机。若此前未成功逃生，应抓住此时机，使用安全锤、头枕、尖角等工具猛击侧窗玻璃四角(钢化玻璃最脆弱处)破窗后迅速撤离。因此选择“车内水位接近车顶时”","k":"","p":"","j":""},{"i":3090071,"c":309,"x":4,"y":2,"q":"车辆落水后，正确逃生步骤是?","o":["先破窗→解安全带→>逃生","先解安全带→破窗→逃生","先开门→解安全带→逃生","先取工具→解安全带→破窗"],"a":"B","e":"本题主要考察车辆落水的应急处置。未解除安全带可能导致身体被卡住，无法移动，车辆落水后第一步是先解安全带，再破窗逃生。因此选择“先解安全带→破窗→逃生”。","k":"","p":"","j":""},{"i":3090072,"c":309,"x":4,"y":2,"q":"以下哪种工具最适合用于破窗逃生？","o":["金属钥匙","安全锤","手机","方向盘锁"],"a":"B","e":"本题主要考察车辆落水的应急处置。车辆落水逃生时应使用安全锤破窗逃生，因为安全锤专为破窗设计，尖端可集中冲击力，轻松击碎钢化玻璃。相比之下，钥匙、手机等因受力面积大、硬度不足，破窗效率低;方向盘锁虽有一定重量，但不如安全锤便携和精准。因此选择“安全锤”。","k":"","p":"","j":""},{"i":3090073,"c":309,"x":4,"y":2,"q":"雨天行车时，车辆意外落水的风险\n较高的路段是?","o":["城市主干道","临水临崖路段","高速公路","隧道"],"a":"B","e":"本题主要考察车辆落水的应急处置。雨天行车，临水临崖路段，临水区域防护栏缺失或强度不足易导致车辆落水。城市道路、高速公路、隧道等通常有完善排水系统和护栏，风险较低。因此选择“临水临崖路段”。","k":"","p":"","j":""},{"i":3090074,"c":309,"x":4,"y":2,"q":"机动车落水后，电气开关无法打开车门时，以下说法错误的是什么?","o":["可以尝试应急阀手动开启车门，组织乘客逃生","可以尝试使用安全锤破窗，组织乘客逃生","第一时间组织乘客松开安全带","密封车窗阻挡进水，并及时报警"],"a":"D","e":"本题主要考察车辆落水的应急处置。车辆落水遇电气开关无法打开车门时，可以操纵设置在车门附近的应急阀手动开启车门或使用安全锤破窗，第一时间组织乘客松开安全带逃生。题目问错误的，因此选择“密封车窗阻挡进水，并及时报警”。","k":"","p":"","j":""},{"i":3090075,"c":309,"x":4,"y":2,"q":"机动车落水后，车门车窗无法打开时，以下做法正确的是什么?","o":["使用安全锤、安全头枕等物品尖角处敲碎或者撬碎侧窗玻璃","堵死车窗缝隙，减缓进水速度","打电话报警，等待救援","使用工具撬开车门"],"a":"A","e":"本题主要考察车辆落水的应急处置。车辆落水后若车门无法开启且车窗无法摇下时，驾驶人可以利用车内的安全锤或螺丝刀等坚硬物品敲击车窗四个边角破窗逃生。因此选择“使用安全锤、安全头枕等物品尖角处敲碎或者撬碎侧窗玻璃”。\n相关法规参考:GA/T1773.2-2021《机动车驾驶人安全文明操作规范 第2部分:小型汽车驾驶》，10.6车辆落水，遇车辆落水，宜按以下步骤操作:a)落水后，开启中控锁，解开安全带，迅速打开车门逃生:b)当车门和车窗无法打开时，可采用安全锤、安全头枕等物品的尖角处击碎或撬碎侧窗玻璃逃生。","k":"","p":"","j":""},{"i":3090076,"c":309,"x":4,"y":1,"q":"机动车落水后，只有在水快浸满车厢时，才有可能开启车门或摇下车窗玻璃逃生。","o":["正确","错误"],"a":"A","e":"本题主要考察车辆落水的应急处置。车辆落水后:车内压力低于车外压力，车门因水压太大无法开启时，要等到水快浸满车厢时，再设法开启车门或摇下车窗玻璃逃生。因此选择“正确”。","k":"","p":"","j":""},{"i":3090077,"c":309,"x":4,"y":1,"q":"机动车落水后，要迅速关闭车窗阻挡车内进水，短暂闭绝空气，可打电话告知救援人员失事地点，等待救援。","o":["正确","错误"],"a":"B","e":"车辆落水，遇车辆落水，宜按以下步骤操作:a)落水后，开启中控锁，解开安全带，迅速打开车门逃生;b)当车门和车窗无法打开时，可采用安全锤、安全头枕等物品的尖角处击碎或撬碎侧窗玻璃逃生。","k":"","p":"","j":""},{"i":3090078,"c":309,"x":4,"y":2,"q":"驾驶机动车需要从车窗逃生时，要用安全锤敲击玻璃的哪个部位?","o":["四个角落","中心部位","任意部位","中下部位"],"a":"A","e":"安全玻璃通常是夹层玻璃，中间有一层薄膜使得玻璃碎片不易飞溅，减少伤害。而敲击四角部位可以减小玻璃的整体受力范围，增加局部压力，提高打破玻璃的效率。因此选择“四个角落”。","k":"","p":"","j":""},{"i":3090079,"c":309,"x":4,"y":2,"q":"驾驶机动车时，为了预防车辆落水造成的危险，应随车携带以下哪项物品?","o":["冷冻液","安全帽","危险警告标志","安全锤"],"a":"D","e":"在车辆发生意外情况或进水等紧急情况下，车门可能无法打开或无法快速打开，此时破窗逃生可能是唯一的选择。安全锤通常配备有坚固的金属头部和尖锐的锤子，可以用来敲击车窗玻璃，迅速打碎玻璃以便逃生。","k":"","p":"","j":""},{"i":3090080,"c":309,"x":4,"y":1,"q":"驾驶车辆通过窄桥时，行驶速度必须控制在30km/h以下，如桥上交通情况复杂时，还应降低行驶速度。","o":["正确","错误"],"a":"A","e":"《道路交通安全法实施条例》第四十六条:机动车行驶中遇到进出非机动车道，通过铁路道口、急弯路窄路、窄桥时最高行驶速度不得超过每小时30公里。","k":"","p":"","j":""},{"i":3100001,"c":310,"x":4,"y":1,"q":"防御性驾驶理念要求道路货物运输驾驶人规范操作，避免主动引发事故；宽容礼让，避免卷入被动性事故。","o":["正确","错误"],"a":"A","e":"防御性驾驶理念要求道路货物运输驾驶员在驾驶时规范操作，尽量不犯错误，确保车辆不会主动引发交通事故。同时，在别人犯错误时，驾驶员要及时发现并宽容对待，提前采取措施进行规避，确保不出现被动性的交通事故。","k":"货运资格证试题，题目里有“避免”，直接答正确。","p":"","j":""}]});
